-- ============================================================================;
-- 0001_initial_consolidated_schema.sql
-- The El-Imtiyaz platform — CONSOLIDATED SINGLE-PASS SCHEMA
-- Generated: ' + now + ' (Session 24, the migration-consolidation mandate)
-- ============================================================================;
--
-- WHAT THIS IS: the definitive, latest database state obtained by squashing
-- the complete 152-file historical migration chain (0001..0157, five numbering
-- gaps: 0015/0016/0017/0118/0122 never assigned) into ONE clean schema script.
-- It creates the final schema from scratch on a clean Postgres/Supabase
-- instance in a single pass.
--
-- METHOD: the chain was replayed statement-by-statement on a real Postgres
-- engine (PGlite 0.5.17 / PostgreSQL 18.7 wasm), then the consolidated DDL
-- was generated from the live catalog (pg_dump method: pg_get_functiondef,
-- pg_get_viewdef, pg_get_constraintdef, pg_get_indexdef, pg_get_triggerdef,
-- pg_policies) — guaranteeing the FINAL state, not a concatenation.
--
-- FINAL-STATE GATES (all verified on a clean instance, single pass):
--   tables: 99   (the chain census "100" counts `receipts`, DROPPED by 0079 —
--                  purged here per the consolidation rule; nothing else dropped)
--   views: 14  ·  materialized views: 5  (0049 unique indexes included)
--   storage buckets: 11  (0018 ten + `attendance-justifications` from 0092)
--   functions: 147  ·  triggers: 90  ·  public policies: 242
--   storage.objects policies: 22  ·  sequences: 4
--   seeds: the canonical system seed set (see §14)
--
-- HISTORICAL RECORD: all 152 original migration files are preserved verbatim
-- in supabase/migrations_archive/ (the forensic evidence base, per ADR-001
-- and the ARCH-011 lesson). This file SUPERSEDES the chain for fresh
-- deployments; the archive remains the record of how the schema evolved.
--
-- PLATFORM PRECONDITIONS (Supabase provides these on a managed project):
--   schema `auth` (auth.users + auth.uid()/jwt()/role() — referenced by FKs
--     and RLS policies), schema `storage` (storage.buckets/storage.objects +
--     storage.foldername/filename/extension), roles authenticated/anon/
--     service_role, and the `supabase_realtime` publication.
--   For non-Supabase Postgres, run the local-compat prologue from
--     scripts/schema-test (the T-599/LF-1 `0000_local_compat` discipline).
--
-- EXCLUDED INTERMEDIATE ARTIFACTS (per the consolidation rules):
--   * table `receipts` (created 0007, dropped 0079_drop_orphaned_receipts)
--   * superseded function versions (every CREATE OR REPLACE history step)
--   * migration-internal test/demo data rows (the 0063/0101 Sidi-family
--     fixtures and audit-log rows written during chain replay)
--   * the broken bootstrap 9000 file (supabase/bootstrap/ — syntax errors,
--     superseded; remains in the archive as historical record)
--   * every `alter ... drop ...` / `drop policy` intermediate step
-- ============================================================================;

-- ############################################################################
-- §1. EXTENSIONS
-- ############################################################################
create schema if not exists extensions;
create extension if not exists pgcrypto    with schema extensions;
create extension if not exists pgjwt       with schema extensions;
create extension if not exists "uuid-ossp" with schema extensions;
create extension if not exists pg_trgm     with schema extensions;
create extension if not exists btree_gist  with schema extensions;
do $$ begin
    create extension if not exists pg_stat_statements with schema extensions;
exception when others then
    raise notice 'pg_stat_statements not available; skipping.';
end $$;

create or replace function public.gen_uuid()
returns uuid language sql stable as $$ select extensions.gen_random_uuid() $$;

comment on schema extensions is 'PostgreSQL extensions used by El-Imtiyaz (pgcrypto, pgjwt, pg_trgm, btree_gist).';
comment on function public.gen_uuid is 'Canonical UUID generator wrapper used by every entity table.';

-- pg_dump technique: do not validate function bodies at creation time so the
-- file has no intra-function ordering constraints (bodies reference tables,
-- views and other functions created later in this same file).
set check_function_bodies = off;

-- ############################################################################
-- §2. SEQUENCES
-- ############################################################################
create sequence if not exists public.ledger_seq as bigint start 1 increment 1 maxvalue 9223372036854775807 minvalue 1 cache 1;
create sequence if not exists public.payment_seq as bigint start 1 increment 1 maxvalue 9223372036854775807 minvalue 1 cache 1;
create sequence if not exists public.receipt_seq as bigint start 1 increment 1 maxvalue 9223372036854775807 minvalue 1 cache 1;
create sequence if not exists public.student_seq as bigint start 1 increment 1 maxvalue 9223372036854775807 minvalue 1 cache 1;

-- ############################################################################
-- §3. TABLES (99) — columns, defaults, PK/unique/check constraints inline;
--     foreign keys added in §5 after all tables exist
-- ############################################################################

create table public.academic_history (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  student_id uuid not null,
  academic_year_id uuid not null,
  academic_level_id uuid not null,
  class_id uuid,
  gpa numeric(5,2),
  decision text,
  subject_grades_json jsonb default '{}'::jsonb not null,
  attendance_summary jsonb default '{}'::jsonb not null,
  teacher_observations text,
  archived_at timestamp with time zone default now() not null,
  constraint academic_history_decision_check CHECK (decision = ANY (ARRAY['approved_for_promotion'::text, 'retained_same_year'::text, 'withdrawn'::text, 'graduated'::text])),
  constraint academic_history_academic_level_id_not_null NOT NULL academic_level_id,
  constraint academic_history_academic_year_id_not_null NOT NULL academic_year_id,
  constraint academic_history_archived_at_not_null NOT NULL archived_at,
  constraint academic_history_attendance_summary_not_null NOT NULL attendance_summary,
  constraint academic_history_id_not_null NOT NULL id,
  constraint academic_history_student_id_not_null NOT NULL student_id,
  constraint academic_history_subject_grades_json_not_null NOT NULL subject_grades_json,
  constraint academic_history_tenant_id_not_null NOT NULL tenant_id,
  constraint academic_history_pkey PRIMARY KEY (id),
  constraint academic_history_tenant_id_student_id_academic_year_id_key UNIQUE (tenant_id, student_id, academic_year_id)
);

create table public.academic_levels (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  cycle text not null,
  year_label text not null,
  year_number integer not null,
  grade_code text not null,
  sort_order integer not null,
  is_active boolean default true not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  label_fr text,
  label_ar text,
  constraint academic_levels_cycle_check CHECK (cycle = ANY (ARRAY['primaire'::text, 'cem'::text, 'lycee'::text, 'prescolaire'::text])),
  constraint academic_levels_created_at_not_null NOT NULL created_at,
  constraint academic_levels_cycle_not_null NOT NULL cycle,
  constraint academic_levels_grade_code_not_null NOT NULL grade_code,
  constraint academic_levels_id_not_null NOT NULL id,
  constraint academic_levels_is_active_not_null NOT NULL is_active,
  constraint academic_levels_sort_order_not_null NOT NULL sort_order,
  constraint academic_levels_tenant_id_not_null NOT NULL tenant_id,
  constraint academic_levels_updated_at_not_null NOT NULL updated_at,
  constraint academic_levels_year_label_not_null NOT NULL year_label,
  constraint academic_levels_year_number_not_null NOT NULL year_number,
  constraint academic_levels_pkey PRIMARY KEY (id),
  constraint academic_levels_tenant_id_grade_code_key UNIQUE (tenant_id, grade_code)
);

create table public.academic_years (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  label text not null,
  start_date date not null,
  end_date date not null,
  term_structure text not null,
  is_current boolean default false not null,
  is_archived boolean default false not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  code text,
  constraint academic_years_term_structure_check CHECK (term_structure = ANY (ARRAY['semester'::text, 'trimester'::text, 'quarter'::text])),
  constraint academic_years_created_at_not_null NOT NULL created_at,
  constraint academic_years_end_date_not_null NOT NULL end_date,
  constraint academic_years_id_not_null NOT NULL id,
  constraint academic_years_is_archived_not_null NOT NULL is_archived,
  constraint academic_years_is_current_not_null NOT NULL is_current,
  constraint academic_years_label_not_null NOT NULL label,
  constraint academic_years_start_date_not_null NOT NULL start_date,
  constraint academic_years_tenant_id_not_null NOT NULL tenant_id,
  constraint academic_years_term_structure_not_null NOT NULL term_structure,
  constraint academic_years_updated_at_not_null NOT NULL updated_at,
  constraint academic_years_pkey PRIMARY KEY (id),
  constraint academic_years_tenant_id_label_key UNIQUE (tenant_id, label)
);

create table public.account_adjustments (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  parent_id uuid,
  student_id uuid,
  amount numeric(10,2) not null,
  reason_code text not null,
  admin_note text not null,
  performed_by uuid not null,
  performed_at timestamp with time zone default now() not null,
  before_json jsonb not null,
  after_json jsonb not null,
  created_at timestamp with time zone default now() not null,
  constraint account_adjustments_amount_check CHECK (amount <> 0::numeric),
  constraint account_adjustments_reason_code_check CHECK (reason_code = ANY (ARRAY['sibling_discount'::text, 'staff_family'::text, 'early_payment'::text, 'passage_palier'::text, 'seniority_5y'::text, 'highest_average'::text, 'full_annual'::text, 'scholarship_replacement'::text, 'hardship'::text, 'correction'::text, 'late_fee_waiver'::text, 'other'::text])),
  constraint account_adjustments_admin_note_not_null NOT NULL admin_note,
  constraint account_adjustments_after_json_not_null NOT NULL after_json,
  constraint account_adjustments_amount_not_null NOT NULL amount,
  constraint account_adjustments_before_json_not_null NOT NULL before_json,
  constraint account_adjustments_created_at_not_null NOT NULL created_at,
  constraint account_adjustments_id_not_null NOT NULL id,
  constraint account_adjustments_performed_at_not_null NOT NULL performed_at,
  constraint account_adjustments_performed_by_not_null NOT NULL performed_by,
  constraint account_adjustments_reason_code_not_null NOT NULL reason_code,
  constraint account_adjustments_tenant_id_not_null NOT NULL tenant_id,
  constraint account_adjustments_pkey PRIMARY KEY (id)
);
comment on table public.account_adjustments is 'Replaces deprecated Scholarships (plan §07.04). Every adjustment requires reason_code + admin_note + audit JSON deltas.';

create table public.account_approval_requests (
  id uuid default gen_uuid() not null,
  tenant_id uuid,
  auth_user_id uuid not null,
  email text not null,
  requested_role text default 'parent'::text not null,
  requested_at timestamp with time zone default now() not null,
  activation_code text,
  national_id text,
  phone text,
  full_name text,
  notes_from_user text,
  target_parent_id uuid,
  target_student_id uuid,
  status text default 'pending'::text not null,
  reviewed_by uuid,
  reviewed_at timestamp with time zone,
  decision_note text,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  expires_at timestamp with time zone default (now() + '7 days'::interval) not null,
  student_application jsonb,
  constraint account_approval_requests_requested_role_check CHECK (requested_role = ANY (ARRAY['parent'::text, 'student'::text, 'staff'::text])),
  constraint account_approval_requests_status_check CHECK (status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'expired'::text])),
  constraint account_approval_requests_auth_user_id_not_null NOT NULL auth_user_id,
  constraint account_approval_requests_created_at_not_null NOT NULL created_at,
  constraint account_approval_requests_email_not_null NOT NULL email,
  constraint account_approval_requests_expires_at_not_null NOT NULL expires_at,
  constraint account_approval_requests_id_not_null NOT NULL id,
  constraint account_approval_requests_requested_at_not_null NOT NULL requested_at,
  constraint account_approval_requests_requested_role_not_null NOT NULL requested_role,
  constraint account_approval_requests_status_not_null NOT NULL status,
  constraint account_approval_requests_updated_at_not_null NOT NULL updated_at,
  constraint account_approval_requests_pkey PRIMARY KEY (id),
  constraint account_approval_requests_auth_user_id_key UNIQUE (auth_user_id)
);
comment on table public.account_approval_requests is 'Queue of web-initiated registration requests awaiting admin approval. Approved requests bind auth.users.id to a parent or student profile.';
comment on column public.account_approval_requests.student_application is 'T-413 (STUDENT-102): the structured enrollment application a pending web user attaches — {"student": {first_name, last_name, date_of_birth, gender}, "grade_level_code": "5ap", "note": "…"}. Read by the desktop ApprovalsTab to pre-fill the student-creation form; consumed by approve_student_application when the admin approves.';

create table public.activation_codes (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  code text not null,
  parent_id uuid,
  student_id uuid,
  issued_by uuid,
  issued_at timestamp with time zone default now() not null,
  bound_to_auth_user_id uuid,
  bound_at timestamp with time zone,
  expires_at timestamp with time zone default (now() + '30 days'::interval) not null,
  constraint activation_codes_code_not_null NOT NULL code,
  constraint activation_codes_expires_at_not_null NOT NULL expires_at,
  constraint activation_codes_id_not_null NOT NULL id,
  constraint activation_codes_issued_at_not_null NOT NULL issued_at,
  constraint activation_codes_tenant_id_not_null NOT NULL tenant_id,
  constraint activation_codes_pkey PRIMARY KEY (id),
  constraint activation_codes_tenant_id_code_key UNIQUE (tenant_id, code)
);
comment on table public.activation_codes is '6-7 digit single-use codes that bind a parent''s auth.users.id to their master parent profile + all N students. Plan §06.';

create table public.additional_services (
  id uuid default gen_uuid() not null,
  pricing_config_id uuid not null,
  code text not null,
  label_fr text not null,
  label_ar text,
  amount numeric(10,2) not null,
  billing_model text default 'one_time'::text not null,
  is_active boolean default true not null,
  updated_at timestamp with time zone default now() not null,
  constraint additional_services_amount_check CHECK (amount >= 0::numeric),
  constraint additional_services_billing_model_check CHECK (billing_model = ANY (ARRAY['one_time'::text, 'per_month'::text, 'per_term'::text, 'per_year'::text])),
  constraint additional_services_amount_not_null NOT NULL amount,
  constraint additional_services_billing_model_not_null NOT NULL billing_model,
  constraint additional_services_code_not_null NOT NULL code,
  constraint additional_services_id_not_null NOT NULL id,
  constraint additional_services_is_active_not_null NOT NULL is_active,
  constraint additional_services_label_fr_not_null NOT NULL label_fr,
  constraint additional_services_pricing_config_id_not_null NOT NULL pricing_config_id,
  constraint additional_services_updated_at_not_null NOT NULL updated_at,
  constraint additional_services_pkey PRIMARY KEY (id),
  constraint additional_services_pricing_config_id_code_key UNIQUE (pricing_config_id, code)
);

create table public.ai_provider_configs (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  provider text not null,
  api_key_encrypted text not null,
  default_model text not null,
  fallback_model text,
  is_active boolean default true not null,
  rate_limit_per_minute integer default 60 not null,
  last_used_at timestamp with time zone,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint ai_provider_configs_provider_check CHECK (provider = ANY (ARRAY['groq'::text, 'openrouter'::text])),
  constraint ai_provider_configs_rate_limit_per_minute_check CHECK (rate_limit_per_minute >= 0),
  constraint ai_provider_configs_api_key_encrypted_not_null NOT NULL api_key_encrypted,
  constraint ai_provider_configs_created_at_not_null NOT NULL created_at,
  constraint ai_provider_configs_default_model_not_null NOT NULL default_model,
  constraint ai_provider_configs_id_not_null NOT NULL id,
  constraint ai_provider_configs_is_active_not_null NOT NULL is_active,
  constraint ai_provider_configs_provider_not_null NOT NULL provider,
  constraint ai_provider_configs_rate_limit_per_minute_not_null NOT NULL rate_limit_per_minute,
  constraint ai_provider_configs_tenant_id_not_null NOT NULL tenant_id,
  constraint ai_provider_configs_updated_at_not_null NOT NULL updated_at,
  constraint ai_provider_configs_pkey PRIMARY KEY (id),
  constraint ai_provider_configs_tenant_id_provider_key UNIQUE (tenant_id, provider)
);
comment on table public.ai_provider_configs is 'Encrypted AI provider API keys. AES-256-GCM ciphertext only — never plaintext. Plan §12.06.';
comment on column public.ai_provider_configs.provider is 'Provider discriminator: groq | openrouter.';
comment on column public.ai_provider_configs.api_key_encrypted is 'AES-256-GCM ciphertext blob (base64). Encryption/decryption happens in the Electron main process; the DB never sees the plaintext.';
comment on column public.ai_provider_configs.default_model is 'Primary model ID (e.g. llama-3.3-70b-versatile).';
comment on column public.ai_provider_configs.fallback_model is 'Optional fallback model used when default_model returns 5xx or times out.';
comment on column public.ai_provider_configs.rate_limit_per_minute is 'Tenant-imposed rate cap (independent of provider limits). 0 = no requests allowed.';
comment on column public.ai_provider_configs.created_by is 'user_profiles.id of the admin who entered the key. No FK (convention).';

create table public.ai_request_logs (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  user_id uuid not null,
  feature text not null,
  provider text not null,
  model text not null,
  prompt_token_count integer default 0 not null,
  completion_token_count integer default 0 not null,
  latency_ms integer default 0 not null,
  success boolean not null,
  error_message text,
  requested_at timestamp with time zone default now() not null,
  created_at timestamp with time zone default now() not null,
  constraint ai_request_logs_completion_token_count_check CHECK (completion_token_count >= 0),
  constraint ai_request_logs_feature_check CHECK (feature = ANY (ARRAY['narrative'::text, 'drafting'::text, 'anomaly'::text])),
  constraint ai_request_logs_latency_ms_check CHECK (latency_ms >= 0),
  constraint ai_request_logs_prompt_token_count_check CHECK (prompt_token_count >= 0),
  constraint ai_request_logs_completion_token_count_not_null NOT NULL completion_token_count,
  constraint ai_request_logs_created_at_not_null NOT NULL created_at,
  constraint ai_request_logs_feature_not_null NOT NULL feature,
  constraint ai_request_logs_id_not_null NOT NULL id,
  constraint ai_request_logs_latency_ms_not_null NOT NULL latency_ms,
  constraint ai_request_logs_model_not_null NOT NULL model,
  constraint ai_request_logs_prompt_token_count_not_null NOT NULL prompt_token_count,
  constraint ai_request_logs_provider_not_null NOT NULL provider,
  constraint ai_request_logs_requested_at_not_null NOT NULL requested_at,
  constraint ai_request_logs_success_not_null NOT NULL success,
  constraint ai_request_logs_tenant_id_not_null NOT NULL tenant_id,
  constraint ai_request_logs_user_id_not_null NOT NULL user_id,
  constraint ai_request_logs_pkey PRIMARY KEY (id)
);
comment on table public.ai_request_logs is 'Append-only AI request telemetry. Used for audit, cost tracking, and tenant rate limiting. Plan §12.07.';
comment on column public.ai_request_logs.user_id is 'user_profiles.id of the caller. No FK (convention).';
comment on column public.ai_request_logs.feature is 'AI feature discriminator: narrative=report narratives, drafting=expense/workflow drafts, anomaly=financial anomaly explanation.';
comment on column public.ai_request_logs.latency_ms is 'End-to-end latency including network + provider inference. Used for SLO monitoring.';
comment on column public.ai_request_logs.success is 'TRUE if the provider returned a 2xx response and the app successfully parsed the body. FALSE otherwise (error_message explains).';

create table public.assessments (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  class_subject_id uuid,
  term integer not null,
  kind text,
  label text,
  max_score numeric(5,2) default 20.00 not null,
  weight numeric(5,2) default 1.00 not null,
  scheduled_at date,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  student_id uuid,
  class_id uuid,
  subject_id uuid,
  academic_year text,
  devoir1 numeric(4,2),
  devoir2 numeric(4,2),
  examen numeric(4,2),
  subject_average numeric(4,2),
  coefficient numeric(4,2) default 1.00 not null,
  entered_by uuid,
  entered_at timestamp with time zone default now() not null,
  coefficient_devoir1 numeric(4,2) default 1.00 not null,
  coefficient_devoir2 numeric(4,2) default 1.00 not null,
  coefficient_examen numeric(4,2) default 2.00 not null,
  cc numeric(4,2),
  coefficient_cc numeric(4,2) default 0.00 not null,
  constraint assessments_cc_check CHECK (cc IS NULL OR cc >= 0::numeric AND cc <= 20::numeric),
  constraint assessments_coefficient_cc_check CHECK (coefficient_cc >= 0::numeric),
  constraint assessments_coefficient_check CHECK (coefficient > 0::numeric),
  constraint assessments_coefficient_devoir1_check CHECK (coefficient_devoir1 >= 0::numeric),
  constraint assessments_coefficient_devoir2_check CHECK (coefficient_devoir2 >= 0::numeric),
  constraint assessments_coefficient_examen_check CHECK (coefficient_examen >= 0::numeric),
  constraint assessments_devoir1_check CHECK (devoir1 IS NULL OR devoir1 >= 0::numeric AND devoir1 <= 20::numeric),
  constraint assessments_devoir2_check CHECK (devoir2 IS NULL OR devoir2 >= 0::numeric AND devoir2 <= 20::numeric),
  constraint assessments_examen_check CHECK (examen IS NULL OR examen >= 0::numeric AND examen <= 20::numeric),
  constraint assessments_kind_check CHECK (kind = ANY (ARRAY['devoir_1'::text, 'devoir_2'::text, 'examen'::text])),
  constraint assessments_max_score_check CHECK (max_score > 0::numeric),
  constraint assessments_term_check CHECK (term = ANY (ARRAY[1, 2, 3])),
  constraint assessments_coefficient_cc_not_null NOT NULL coefficient_cc,
  constraint assessments_coefficient_devoir1_not_null NOT NULL coefficient_devoir1,
  constraint assessments_coefficient_devoir2_not_null NOT NULL coefficient_devoir2,
  constraint assessments_coefficient_examen_not_null NOT NULL coefficient_examen,
  constraint assessments_coefficient_not_null NOT NULL coefficient,
  constraint assessments_created_at_not_null NOT NULL created_at,
  constraint assessments_entered_at_not_null NOT NULL entered_at,
  constraint assessments_id_not_null NOT NULL id,
  constraint assessments_max_score_not_null NOT NULL max_score,
  constraint assessments_tenant_id_not_null NOT NULL tenant_id,
  constraint assessments_term_not_null NOT NULL term,
  constraint assessments_updated_at_not_null NOT NULL updated_at,
  constraint assessments_weight_not_null NOT NULL weight,
  constraint assessments_pkey PRIMARY KEY (id),
  constraint assessments_tenant_id_class_subject_id_term_kind_key UNIQUE (tenant_id, class_subject_id, term, kind)
);

create table public.attendance_records (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  student_id uuid not null,
  class_id uuid not null,
  class_subject_id uuid,
  date date not null,
  status text not null,
  arrival_time time without time zone,
  note text,
  recorded_by uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  record_date date,
  session text default 'morning'::text,
  recorded_at timestamp with time zone default now() not null,
  synced_at timestamp with time zone default now(),
  justification_note text,
  justification_path text,
  justification_drive_link text,
  justification_status text default 'none'::text not null,
  justification_reviewed_by uuid,
  justification_reviewed_at timestamp with time zone,
  constraint attendance_records_justification_status_check CHECK (justification_status = ANY (ARRAY['none'::text, 'submitted'::text, 'accepted'::text, 'rejected'::text])),
  constraint attendance_records_session_check CHECK (session = ANY (ARRAY['morning'::text, 'afternoon'::text, 'both'::text])),
  constraint attendance_records_status_check CHECK (status = ANY (ARRAY['present'::text, 'absent_excused'::text, 'absent_unexcused'::text, 'late'::text])),
  constraint attendance_records_class_id_not_null NOT NULL class_id,
  constraint attendance_records_created_at_not_null NOT NULL created_at,
  constraint attendance_records_date_not_null NOT NULL date,
  constraint attendance_records_id_not_null NOT NULL id,
  constraint attendance_records_justification_status_not_null NOT NULL justification_status,
  constraint attendance_records_recorded_at_not_null NOT NULL recorded_at,
  constraint attendance_records_status_not_null NOT NULL status,
  constraint attendance_records_student_id_not_null NOT NULL student_id,
  constraint attendance_records_tenant_id_not_null NOT NULL tenant_id,
  constraint attendance_records_updated_at_not_null NOT NULL updated_at,
  constraint attendance_records_pkey PRIMARY KEY (id)
);
comment on column public.attendance_records.justification_note is 'Parent-submitted justification note (web portal). NULL until the parent submits one.';
comment on column public.attendance_records.justification_path is 'Storage path under bucket "attendance-justifications" for the parent-uploaded file.';
comment on column public.attendance_records.justification_drive_link is 'Optional Google Drive link supplied by the parent as supporting evidence.';
comment on column public.attendance_records.justification_status is 'Workflow state of the parent-submitted justification. Staff flip submitted→accepted/rejected from the desktop app.';
comment on column public.attendance_records.justification_reviewed_by is 'user_profiles.id of the staff member who accepted/rejected the justification.';
comment on column public.attendance_records.justification_reviewed_at is 'Timestamp of the staff review decision.';

create table public.audit_logs (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  action text not null,
  entity_type text not null,
  entity_id uuid,
  actor_id uuid,
  actor_name text,
  actor_role text,
  session_id uuid,
  before_json jsonb,
  after_json jsonb,
  note text,
  ip_address inet,
  user_agent text,
  request_id text,
  supersedes_id uuid,
  occurred_at timestamp with time zone default now() not null,
  created_at timestamp with time zone default now() not null,
  diff jsonb,
  constraint audit_logs_action_not_null NOT NULL action,
  constraint audit_logs_created_at_not_null NOT NULL created_at,
  constraint audit_logs_entity_type_not_null NOT NULL entity_type,
  constraint audit_logs_id_not_null NOT NULL id,
  constraint audit_logs_occurred_at_not_null NOT NULL occurred_at,
  constraint audit_logs_tenant_id_not_null NOT NULL tenant_id,
  constraint audit_logs_pkey PRIMARY KEY (id)
);
comment on table public.audit_logs is 'Append-only audit log. Universal traceability per plan §12. No edits, no deletes (trigger-enforced). before_json/after_json must be COMPLETE, never truncated.';
comment on column public.audit_logs.action is 'Stable action code, e.g. parent.create, payment.collect, expense.approve, auth.login, auth.password_change.';
comment on column public.audit_logs.entity_type is 'Polymorphic discriminator (parent, student, payment, expense_ticket, workflow_run, etc.).';
comment on column public.audit_logs.entity_id is 'UUID of the affected row. NULL for system-wide events (e.g. backup.run).';
comment on column public.audit_logs.actor_id is 'user_profiles.id of the actor. NULL only for true system-initiated events (e.g. scheduled workflow).';
comment on column public.audit_logs.actor_name is 'Denormalized actor display name for fast listing without joins.';
comment on column public.audit_logs.actor_role is 'Role code at time of action (role may change later — this preserves history).';
comment on column public.audit_logs.session_id is 'sessions.id of the actor (NULL for non-interactive events).';
comment on column public.audit_logs.before_json is 'Complete pre-change JSON snapshot. NEVER truncated. NULL for INSERT actions.';
comment on column public.audit_logs.after_json is 'Complete post-change JSON snapshot. NEVER truncated. NULL for DELETE actions.';
comment on column public.audit_logs.supersedes_id is 'Set when this entry corrects a previous one. The superseded entry remains in the log (append-only).';

create table public.backup_archives (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  archive_id_text text not null,
  file_name text not null,
  size_bytes bigint not null,
  checksum_sha256 text not null,
  vault_location text not null,
  status text default 'encrypted'::text not null,
  retention_expires_at timestamp with time zone,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  restored_at timestamp with time zone,
  restored_by uuid,
  purge_at timestamp with time zone,
  metadata jsonb default '{}'::jsonb not null,
  constraint backup_archives_size_bytes_check CHECK (size_bytes >= 0),
  constraint backup_archives_status_check CHECK (status = ANY (ARRAY['encrypted'::text, 'restored'::text, 'corrupted'::text, 'purged'::text])),
  constraint backup_archives_vault_location_check CHECK (vault_location = ANY (ARRAY['indexeddb'::text, 'local_drive'::text, 'offsite_vault'::text])),
  constraint backup_archives_archive_id_text_not_null NOT NULL archive_id_text,
  constraint backup_archives_checksum_sha256_not_null NOT NULL checksum_sha256,
  constraint backup_archives_created_at_not_null NOT NULL created_at,
  constraint backup_archives_file_name_not_null NOT NULL file_name,
  constraint backup_archives_id_not_null NOT NULL id,
  constraint backup_archives_metadata_not_null NOT NULL metadata,
  constraint backup_archives_size_bytes_not_null NOT NULL size_bytes,
  constraint backup_archives_status_not_null NOT NULL status,
  constraint backup_archives_tenant_id_not_null NOT NULL tenant_id,
  constraint backup_archives_updated_at_not_null NOT NULL updated_at,
  constraint backup_archives_vault_location_not_null NOT NULL vault_location,
  constraint backup_archives_pkey PRIMARY KEY (id),
  constraint backup_archives_archive_id_text_key UNIQUE (archive_id_text)
);
comment on table public.backup_archives is 'Metadata for backup archives. Ciphertext stays in IndexedDB per plan §13.03 — Postgres stores ONLY metadata. NEVER store plaintext or ciphertext here.';
comment on column public.backup_archives.archive_id_text is 'Globally-unique archive identifier (matches the IndexedDB key). UNIQUE constraint spans all tenants.';
comment on column public.backup_archives.checksum_sha256 is 'Hex-encoded SHA-256 of the ciphertext blob. Used to detect corruption on restore.';
comment on column public.backup_archives.vault_location is 'Where the ciphertext lives: indexeddb (primary), local_drive (secondary copy), offsite_vault (tertiary).';
comment on column public.backup_archives.status is 'encrypted=at rest, restored=successfully restored, corrupted=checksum mismatch, purged=ciphertext deleted.';
comment on column public.backup_archives.retention_expires_at is 'When the retention period ends. After this date the archive is eligible for purge.';
comment on column public.backup_archives.created_by is 'user_profiles.id of the admin who initiated the backup. No FK (convention).';
comment on column public.backup_archives.restored_by is 'user_profiles.id of the admin who restored from this archive. No FK (convention).';
comment on column public.backup_archives.purge_at is 'Scheduled purge timestamp. Set by the retention scheduler; the purge job picks up rows past this time.';
comment on column public.backup_archives.metadata is 'JSON metadata: {schema_version, encryption_algo, kv_store_ref, source_app_version, ...}. GIN-indexed.';

create table public.calendar_events (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  kind text not null,
  title text not null,
  description text,
  start_at timestamp with time zone not null,
  end_at timestamp with time zone,
  all_day boolean default false not null,
  location text,
  attendee_count integer default 0 not null,
  target_entity_type text,
  target_entity_id uuid,
  target_name text,
  target_phone text,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  is_deleted boolean default false not null,
  priority text default 'medium'::text not null,
  assigned_to_user_id uuid,
  assigned_to_role text,
  constraint calendar_events_attendee_count_check CHECK (attendee_count >= 0),
  constraint calendar_events_check CHECK (end_at IS NULL OR end_at >= start_at),
  constraint calendar_events_kind_check CHECK (kind = ANY (ARRAY['payment_received'::text, 'audit_log'::text, 'expense_event'::text, 'follow_up_call'::text, 'reminder'::text, 'meeting'::text, 'custom'::text])),
  constraint calendar_events_priority_check CHECK (priority = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'urgent'::text])),
  constraint calendar_events_all_day_not_null NOT NULL all_day,
  constraint calendar_events_attendee_count_not_null NOT NULL attendee_count,
  constraint calendar_events_created_at_not_null NOT NULL created_at,
  constraint calendar_events_id_not_null NOT NULL id,
  constraint calendar_events_is_deleted_not_null NOT NULL is_deleted,
  constraint calendar_events_kind_not_null NOT NULL kind,
  constraint calendar_events_priority_not_null NOT NULL priority,
  constraint calendar_events_start_at_not_null NOT NULL start_at,
  constraint calendar_events_tenant_id_not_null NOT NULL tenant_id,
  constraint calendar_events_title_not_null NOT NULL title,
  constraint calendar_events_updated_at_not_null NOT NULL updated_at,
  constraint calendar_events_pkey PRIMARY KEY (id)
);
comment on table public.calendar_events is 'Manual staff-created calendar events. Auto-derived events (payments/audit/expenses) are computed via view, not stored. Plan §13.01.';
comment on column public.calendar_events.kind is 'Event discriminator. payment_received/audit_log/expense_event are typically auto-derived (view); follow_up_call/reminder/meeting/custom are manual.';
comment on column public.calendar_events.start_at is 'Event start (timestamptz). Required. For all-day events, set start_at to midnight and end_at to next midnight.';
comment on column public.calendar_events.all_day is 'TRUE for all-day events (no time component). When TRUE, the UI ignores the time portion of start_at/end_at.';
comment on column public.calendar_events.target_entity_type is 'Polymorphic link discriminator (e.g. parent, student, payment, expense_ticket). target_entity_id is the row UUID.';
comment on column public.calendar_events.target_name is 'Denormalized contact name for follow-up calls — survives even if the linked entity is soft-deleted.';
comment on column public.calendar_events.target_phone is 'Denormalized contact phone for follow-up calls — survives even if the linked entity is soft-deleted.';
comment on column public.calendar_events.created_by is 'user_profiles.id of the staff member who created the event. No FK (convention).';
comment on column public.calendar_events.is_deleted is 'Soft-delete flag. Deleted events are filtered out by default via WHERE is_deleted = false.';
comment on column public.calendar_events.priority is 'Alert-priority enum for color-coding manual events (low/medium/high/urgent). Desktop domain default medium. Added by 0070 (T-175).';
comment on column public.calendar_events.assigned_to_user_id is 'user_profiles.id the event is assigned to (no FK, convention). NULL = unassigned. Added by 0070 (T-175).';
comment on column public.calendar_events.assigned_to_role is 'Role code the event is assigned to (e.g. financial_officer). NULL = unassigned. Added by 0070 (T-175).';

create table public.chat_channels (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  code text not null,
  name text not null,
  channel_type text not null,
  member_ids uuid[] default '{}'::uuid[] not null,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  description text,
  department_id uuid,
  archived_at timestamp with time zone,
  last_message_at timestamp with time zone,
  last_message_preview text,
  scope text default 'internal'::text not null,
  constraint chat_channels_channel_type_check CHECK (channel_type = ANY (ARRAY['direct'::text, 'group'::text, 'department'::text, 'announcement'::text])),
  constraint chat_channels_scope_check CHECK (scope = ANY (ARRAY['internal'::text, 'portal'::text])),
  constraint chat_channels_channel_type_not_null NOT NULL channel_type,
  constraint chat_channels_code_not_null NOT NULL code,
  constraint chat_channels_created_at_not_null NOT NULL created_at,
  constraint chat_channels_id_not_null NOT NULL id,
  constraint chat_channels_member_ids_not_null NOT NULL member_ids,
  constraint chat_channels_name_not_null NOT NULL name,
  constraint chat_channels_scope_not_null NOT NULL scope,
  constraint chat_channels_tenant_id_not_null NOT NULL tenant_id,
  constraint chat_channels_updated_at_not_null NOT NULL updated_at,
  constraint chat_channels_pkey PRIMARY KEY (id),
  constraint chat_channels_tenant_id_code_key UNIQUE (tenant_id, code)
);
comment on table public.chat_channels is 'In-app chat channels. member_ids is a uuid[] of user_profiles.id, GIN-indexed for membership queries. Plan §10.09.';
comment on column public.chat_channels.channel_type is 'direct=1:1, group=ad-hoc multi-user, department=scoped to a department, announcement=read-only broadcast.';
comment on column public.chat_channels.member_ids is 'Array of user_profiles.id. For announcement channels, members are recipients (only channel owners post).';
comment on column public.chat_channels.created_by is 'user_profiles.id of the channel creator. No FK (convention).';
comment on column public.chat_channels.description is 'Optional channel purpose text (desktop domain parity).';
comment on column public.chat_channels.department_id is 'Department scope for department-type channels (no FK by convention).';
comment on column public.chat_channels.archived_at is 'Soft archive timestamp; archived channels are hidden from active lists.';
comment on column public.chat_channels.last_message_at is 'Denormalized sent_at of the most recent message (CHAT-104: ordering by last activity).';
comment on column public.chat_channels.last_message_preview is 'First 120 chars of the most recent message body (CHAT-104: list previews).';
comment on column public.chat_channels.scope is 'CHAT-300 (0135): which chat system this channel belongs to — ''portal'' (at least one member is not an employee-role holder; the ADR-012 portal↔staff communication) or ''internal'' (every member holds an employee role; the ADR-008 workplace messenger). FORCED by the chat_channels_derive_scope trigger from member composition — clients cannot set it.';

create table public.chat_messages (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  channel_id uuid not null,
  author_id uuid not null,
  body text default ''::text not null,
  edited_at timestamp with time zone,
  edited_by uuid,
  deleted_at timestamp with time zone,
  parent_message_id uuid,
  read_by jsonb default '[]'::jsonb not null,
  attachments jsonb default '[]'::jsonb not null,
  sent_at timestamp with time zone default now() not null,
  created_at timestamp with time zone default now() not null,
  constraint chat_messages_attachments_not_null NOT NULL attachments,
  constraint chat_messages_author_id_not_null NOT NULL author_id,
  constraint chat_messages_body_not_null NOT NULL body,
  constraint chat_messages_channel_id_not_null NOT NULL channel_id,
  constraint chat_messages_created_at_not_null NOT NULL created_at,
  constraint chat_messages_id_not_null NOT NULL id,
  constraint chat_messages_read_by_not_null NOT NULL read_by,
  constraint chat_messages_sent_at_not_null NOT NULL sent_at,
  constraint chat_messages_tenant_id_not_null NOT NULL tenant_id,
  constraint chat_messages_pkey PRIMARY KEY (id)
);
comment on table public.chat_messages is 'Messages in a chat channel. Soft-deleted via deleted_at. Threaded via parent_message_id. Plan §10.09.';
comment on column public.chat_messages.author_id is 'user_profiles.id of the sender. No FK (convention).';
comment on column public.chat_messages.edited_by is 'user_profiles.id of the last editor. NULL if never edited.';
comment on column public.chat_messages.parent_message_id is 'Self-FK for threaded replies. SET NULL on parent delete (preserves reply text).';
comment on column public.chat_messages.read_by is 'JSON array of {user_id: uuid, read_at: timestamptz} objects tracking read receipts.';
comment on column public.chat_messages.attachments is 'JSON array of attachment metadata objects referencing Supabase Storage paths.';

create table public.class_subjects (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  class_id uuid not null,
  subject_id uuid not null,
  teacher_id uuid,
  coefficient numeric(4,2) default 1 not null,
  is_active boolean default true not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  teacher_name text,
  weekly_hours numeric(4,1) default 2.0,
  consecutive_periods integer default 1 not null,
  required_room_type text,
  constraint class_subjects_coefficient_check CHECK (coefficient > 0::numeric),
  constraint class_subjects_consecutive_periods_check CHECK (consecutive_periods >= 1 AND consecutive_periods <= 4),
  constraint class_subjects_weekly_hours_check CHECK (weekly_hours > 0::numeric),
  constraint class_subjects_class_id_not_null NOT NULL class_id,
  constraint class_subjects_coefficient_not_null NOT NULL coefficient,
  constraint class_subjects_consecutive_periods_not_null NOT NULL consecutive_periods,
  constraint class_subjects_created_at_not_null NOT NULL created_at,
  constraint class_subjects_id_not_null NOT NULL id,
  constraint class_subjects_is_active_not_null NOT NULL is_active,
  constraint class_subjects_subject_id_not_null NOT NULL subject_id,
  constraint class_subjects_tenant_id_not_null NOT NULL tenant_id,
  constraint class_subjects_updated_at_not_null NOT NULL updated_at,
  constraint class_subjects_pkey PRIMARY KEY (id),
  constraint class_subjects_tenant_id_class_id_subject_id_key UNIQUE (tenant_id, class_id, subject_id)
);

create table public.classes (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  academic_year_id uuid not null,
  academic_level_id uuid not null,
  section text not null,
  code text not null,
  name text,
  capacity integer default 30 not null,
  homeroom_teacher_id uuid,
  room text,
  is_active boolean default true not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  grade_code text,
  homeroom_teacher_name text,
  filiere_code text,
  specialite_code text,
  notes text,
  constraint classes_academic_level_id_not_null NOT NULL academic_level_id,
  constraint classes_academic_year_id_not_null NOT NULL academic_year_id,
  constraint classes_capacity_not_null NOT NULL capacity,
  constraint classes_code_not_null NOT NULL code,
  constraint classes_created_at_not_null NOT NULL created_at,
  constraint classes_id_not_null NOT NULL id,
  constraint classes_is_active_not_null NOT NULL is_active,
  constraint classes_section_not_null NOT NULL section,
  constraint classes_tenant_id_not_null NOT NULL tenant_id,
  constraint classes_updated_at_not_null NOT NULL updated_at,
  constraint classes_pkey PRIMARY KEY (id),
  constraint classes_tenant_id_academic_year_id_code_key UNIQUE (tenant_id, academic_year_id, code)
);
comment on column public.classes.filiere_code is 'T-401: the class''s academic stream (filieres.code). NULL = untagged/general (pre-0107 classes).';
comment on column public.classes.specialite_code is 'T-401: the class''s spécialité (filieres.code with parent_code set). NULL = none.';
comment on column public.classes.notes is 'ACAD-510 (0149): custom notes/observations per class — the persistence target behind AcademicClass.notes (previously dropped silently on both create and update).';

create table public.complementary_services (
  id uuid default gen_uuid() not null,
  pricing_config_id uuid not null,
  code text not null,
  label_fr text not null,
  label_ar text,
  semester_amount numeric(10,2),
  annual_amount numeric(10,2),
  billing_model text default 'per_session'::text not null,
  is_active boolean default true not null,
  updated_at timestamp with time zone default now() not null,
  constraint complementary_services_billing_model_check CHECK (billing_model = ANY (ARRAY['per_session'::text, 'per_semester'::text, 'per_year'::text, 'per_term'::text])),
  constraint complementary_services_billing_model_not_null NOT NULL billing_model,
  constraint complementary_services_code_not_null NOT NULL code,
  constraint complementary_services_id_not_null NOT NULL id,
  constraint complementary_services_is_active_not_null NOT NULL is_active,
  constraint complementary_services_label_fr_not_null NOT NULL label_fr,
  constraint complementary_services_pricing_config_id_not_null NOT NULL pricing_config_id,
  constraint complementary_services_updated_at_not_null NOT NULL updated_at,
  constraint complementary_services_pkey PRIMARY KEY (id),
  constraint complementary_services_pricing_config_id_code_key UNIQUE (pricing_config_id, code)
);

create table public.dashboard_layouts (
  id uuid default gen_random_uuid() not null,
  tenant_id uuid not null,
  user_profile_id uuid not null,
  view_key text not null,
  layout jsonb not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint dashboard_layouts_layout_check CHECK (jsonb_typeof(layout) = 'object'::text),
  constraint dashboard_layouts_view_key_check CHECK (char_length(view_key) >= 1 AND char_length(view_key) <= 128),
  constraint dashboard_layouts_created_at_not_null NOT NULL created_at,
  constraint dashboard_layouts_id_not_null NOT NULL id,
  constraint dashboard_layouts_layout_not_null NOT NULL layout,
  constraint dashboard_layouts_tenant_id_not_null NOT NULL tenant_id,
  constraint dashboard_layouts_updated_at_not_null NOT NULL updated_at,
  constraint dashboard_layouts_user_profile_id_not_null NOT NULL user_profile_id,
  constraint dashboard_layouts_view_key_not_null NOT NULL view_key,
  constraint dashboard_layouts_pkey PRIMARY KEY (id),
  constraint dashboard_layout_identity UNIQUE (tenant_id, user_profile_id, view_key)
);
comment on table public.dashboard_layouts is 'T-448 (UI-326): the DEDICATED dashboard-layout-configuration store — one row per (tenant, user, view key). One clear responsibility: persisting and restoring the user''s dashboard layout. RLS pins every row to its owner (current_user_profile_id); the ONLY write path is the save_dashboard_layout RPC (explicit save — never an implicit update).';
comment on column public.dashboard_layouts.view_key is 'The desktop editor''s storage key (overview / statistics:pilotage / statistics:diagnostic / statistics:charts).';
comment on column public.dashboard_layouts.layout is 'The editor''s StoredLayout verbatim: {"<itemId>": {"x","y","w","h"}, …} — numeric grid coordinates.';

create table public.deliveries (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  delivery_number text not null,
  delivery_type text not null,
  status text default 'assigned'::text not null,
  driver_id uuid,
  vehicle text,
  origin_address text,
  destination_address text,
  scheduled_at timestamp with time zone not null,
  departed_at timestamp with time zone,
  delivered_at timestamp with time zone,
  confirmed_at timestamp with time zone,
  stops jsonb default '[]'::jsonb not null,
  notes text,
  delay_reason text,
  delay_minutes integer default 0 not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  driver_name text,
  new_eta text,
  constraint deliveries_delay_minutes_check CHECK (delay_minutes >= 0),
  constraint deliveries_delivery_type_check CHECK (delivery_type = ANY (ARRAY['inbound'::text, 'outbound'::text, 'internal'::text])),
  constraint deliveries_status_check CHECK (status = ANY (ARRAY['assigned'::text, 'in_transit'::text, 'delivered'::text, 'confirmed'::text, 'failed'::text, 'cancelled'::text])),
  constraint deliveries_created_at_not_null NOT NULL created_at,
  constraint deliveries_delay_minutes_not_null NOT NULL delay_minutes,
  constraint deliveries_delivery_number_not_null NOT NULL delivery_number,
  constraint deliveries_delivery_type_not_null NOT NULL delivery_type,
  constraint deliveries_id_not_null NOT NULL id,
  constraint deliveries_scheduled_at_not_null NOT NULL scheduled_at,
  constraint deliveries_status_not_null NOT NULL status,
  constraint deliveries_stops_not_null NOT NULL stops,
  constraint deliveries_tenant_id_not_null NOT NULL tenant_id,
  constraint deliveries_updated_at_not_null NOT NULL updated_at,
  constraint deliveries_pkey PRIMARY KEY (id),
  constraint deliveries_tenant_id_delivery_number_key UNIQUE (tenant_id, delivery_number)
);
comment on table public.deliveries is 'Multi-stop delivery tracking (inbound/outbound/internal). driver_id → personnel. Plan §11.04.';
comment on column public.deliveries.driver_id is 'personnel.id of the assigned driver. SET NULL if they leave the company.';
comment on column public.deliveries.stops is 'JSON array of stop objects: [{address, lat, lng, contact, window_start, window_end, status}]. GIN-indexed.';
comment on column public.deliveries.delay_minutes is 'Total delay in minutes (>= 0). delay_reason explains the cause.';
comment on column public.deliveries.driver_name is 'Driver display name FROZEN at assignment time (driver_id is ON DELETE SET NULL — post-hoc resolution would degrade).';
comment on column public.deliveries.new_eta is 'Revised arrival estimate (ISO string) reported by the driver on a delay (the domain reportDelay contract).';

create table public.departments (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  code text not null,
  name_fr text not null,
  label_ar text,
  color_hex text,
  head_personnel_id uuid,
  description text,
  sort_order integer default 0 not null,
  is_active boolean default true not null,
  is_archived boolean default false not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint departments_color_hex_check CHECK (color_hex ~ '^#[0-9A-Fa-f]{6}$'::text),
  constraint departments_code_not_null NOT NULL code,
  constraint departments_created_at_not_null NOT NULL created_at,
  constraint departments_id_not_null NOT NULL id,
  constraint departments_is_active_not_null NOT NULL is_active,
  constraint departments_is_archived_not_null NOT NULL is_archived,
  constraint departments_name_fr_not_null NOT NULL name_fr,
  constraint departments_sort_order_not_null NOT NULL sort_order,
  constraint departments_tenant_id_not_null NOT NULL tenant_id,
  constraint departments_updated_at_not_null NOT NULL updated_at,
  constraint departments_pkey PRIMARY KEY (id),
  constraint departments_tenant_id_code_key UNIQUE (tenant_id, code)
);
comment on table public.departments is 'Organizational units grouping personnel (Administration, Teaching, Support, Medical). Plan §10.02.';
comment on column public.departments.code is 'Short stable code (e.g. ADM, TCH, SUP, MED). Unique per tenant.';
comment on column public.departments.color_hex is 'Hex color (#RRGGBB) used in the UI for visual grouping.';
comment on column public.departments.head_personnel_id is 'Personnel responsible for the department. SET NULL if they leave.';
comment on column public.departments.is_archived is 'Soft-archive flag: archived departments are hidden from new assignments but kept for history.';

create table public.device_tokens (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  user_id uuid not null,
  token text not null,
  platform text not null,
  app_version text,
  is_active boolean default true not null,
  last_seen_at timestamp with time zone default now() not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  user_agent text,
  constraint device_tokens_platform_check CHECK (platform = ANY (ARRAY['android'::text, 'ios'::text, 'web'::text])),
  constraint device_tokens_created_at_not_null NOT NULL created_at,
  constraint device_tokens_id_not_null NOT NULL id,
  constraint device_tokens_is_active_not_null NOT NULL is_active,
  constraint device_tokens_last_seen_at_not_null NOT NULL last_seen_at,
  constraint device_tokens_platform_not_null NOT NULL platform,
  constraint device_tokens_tenant_id_not_null NOT NULL tenant_id,
  constraint device_tokens_token_not_null NOT NULL token,
  constraint device_tokens_updated_at_not_null NOT NULL updated_at,
  constraint device_tokens_user_id_not_null NOT NULL user_id,
  constraint device_tokens_pkey PRIMARY KEY (id),
  constraint device_tokens_tenant_id_token_key UNIQUE (tenant_id, token)
);
comment on table public.device_tokens is 'FCM/APNS device-token registry. One user can have multiple active tokens (phone + tablet). The register_fcm_token RPC upserts here on every app launch.';
comment on column public.device_tokens.user_agent is 'Browser user agent for tokens registered by the web portal (NULL for native clients).';

create table public.discount_applications (
