  constraint discount_applications_created_at_not_null NOT NULL created_at,
  constraint discount_applications_discount_id_not_null NOT NULL discount_id,
  constraint discount_applications_id_not_null NOT NULL id,
  constraint discount_applications_student_id_not_null NOT NULL student_id,
  constraint discount_applications_tenant_id_not_null NOT NULL tenant_id,
  constraint discount_applications_pkey PRIMARY KEY (id)
);

create table public.discounts (
  id uuid default gen_uuid() not null,
  pricing_config_id uuid not null,
  code text not null,
  label_fr text not null,
  label_ar text,
  discount_type text not null,
  amount numeric(10,2) not null,
  applies_to text default 'total'::text not null,
  is_active boolean default true not null,
  updated_at timestamp with time zone default now() not null,
  constraint discounts_amount_check CHECK (amount >= 0::numeric),
  constraint discounts_applies_to_check CHECK (applies_to = ANY (ARRAY['tuition'::text, 'transport'::text, 'total'::text, 'per_student'::text])),
  constraint discounts_code_check CHECK (code = ANY (ARRAY['passage_palier'::text, 'seniority_5y'::text, 'full_annual'::text, 'highest_average'::text, 'sibling_fixed'::text, 'sibling_10'::text, 'sibling_15'::text, 'early_bird'::text, 'custom'::text])),
  constraint discounts_discount_type_check CHECK (discount_type = ANY (ARRAY['fixed_amount'::text, 'percentage'::text])),
  constraint discounts_amount_not_null NOT NULL amount,
  constraint discounts_applies_to_not_null NOT NULL applies_to,
  constraint discounts_code_not_null NOT NULL code,
  constraint discounts_discount_type_not_null NOT NULL discount_type,
  constraint discounts_id_not_null NOT NULL id,
  constraint discounts_is_active_not_null NOT NULL is_active,
  constraint discounts_label_fr_not_null NOT NULL label_fr,
  constraint discounts_pricing_config_id_not_null NOT NULL pricing_config_id,
  constraint discounts_updated_at_not_null NOT NULL updated_at,
  constraint discounts_pkey PRIMARY KEY (id),
  constraint discounts_pricing_config_id_code_key UNIQUE (pricing_config_id, code)
);

create table public.er_aggregation_events (
  id uuid default gen_random_uuid() not null,
  tenant_id uuid not null,
  event_type text not null,
  run_id text,
  canonical_id uuid,
  merged_away_id uuid,
  observation_keys text[] default '{}'::text[] not null,
  actor_id uuid,
  actor_name text,
  rationale text,
  payload jsonb default '{}'::jsonb not null,
  created_at timestamp with time zone default now() not null,
  constraint er_aggregation_events_event_type_check CHECK (event_type = ANY (ARRAY['ANALYSIS_RUN'::text, 'PROPOSAL_APPROVED'::text, 'PROPOSAL_REJECTED'::text, 'MERGE_EXECUTED'::text, 'MERGE_UNDONE'::text, 'BINDING_EXECUTED'::text])),
  constraint er_aggregation_events_created_at_not_null NOT NULL created_at,
  constraint er_aggregation_events_event_type_not_null NOT NULL event_type,
  constraint er_aggregation_events_id_not_null NOT NULL id,
  constraint er_aggregation_events_observation_keys_not_null NOT NULL observation_keys,
  constraint er_aggregation_events_payload_not_null NOT NULL payload,
  constraint er_aggregation_events_tenant_id_not_null NOT NULL tenant_id,
  constraint er_aggregation_events_pkey PRIMARY KEY (id)
);
comment on table public.er_aggregation_events is 'T-438 (identity-rules §7.4): the append-only aggregation audit trail. A MERGE_EXECUTED event carries the complete prior row mapping in its payload — the unmerge restores the exact prior state from it (INV-54: ledger rows are re-pointed, never rewritten).';

create table public.er_identity_edges (
  id uuid default gen_random_uuid() not null,
  tenant_id uuid not null,
  a_observation_key text not null,
  b_observation_key text not null,
  confidence numeric(5,4) default 1.0 not null,
  status text default 'active'::text not null,
  evidence jsonb default '[]'::jsonb not null,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  severed_at timestamp with time zone,
  severed_by uuid,
  constraint er_identity_edges_status_check CHECK (status = ANY (ARRAY['active'::text, 'severed'::text, 'negative'::text])),
  constraint er_identity_edges_a_observation_key_not_null NOT NULL a_observation_key,
  constraint er_identity_edges_b_observation_key_not_null NOT NULL b_observation_key,
  constraint er_identity_edges_confidence_not_null NOT NULL confidence,
  constraint er_identity_edges_created_at_not_null NOT NULL created_at,
  constraint er_identity_edges_evidence_not_null NOT NULL evidence,
  constraint er_identity_edges_id_not_null NOT NULL id,
  constraint er_identity_edges_status_not_null NOT NULL status,
  constraint er_identity_edges_tenant_id_not_null NOT NULL tenant_id,
  constraint er_identity_edges_pkey PRIMARY KEY (id),
  constraint er_identity_edge_pair UNIQUE (tenant_id, a_observation_key, b_observation_key)
);
comment on table public.er_identity_edges is 'T-438 (identity-rules §6.1): the identity graph. Active edges = confirmed identity links (the merged clusters); negative edges = review rejections (permanent — never re-proposed); severed edges = undone merges (unmerge provenance).';

create table public.er_match_proposals (
  id text not null,
  tenant_id uuid not null,
  run_id text not null,
  a_observation_key text not null,
  b_observation_key text not null,
  b_canonical_id uuid,
  confidence numeric(5,4) not null,
  band text not null,
  evidence jsonb default '[]'::jsonb not null,
  vetoes text[] default '{}'::text[] not null,
  status text default 'proposed'::text not null,
  decided_by uuid,
  decided_by_name text,
  decided_at timestamp with time zone,
  rationale text,
  created_at timestamp with time zone default now() not null,
  constraint er_match_proposals_band_check CHECK (band = ANY (ARRAY['definite'::text, 'probable'::text, 'review'::text, 'separate'::text])),
  constraint er_match_proposals_confidence_check CHECK (confidence >= 0::numeric AND confidence <= 1::numeric),
  constraint er_match_proposals_status_check CHECK (status = ANY (ARRAY['proposed'::text, 'approved'::text, 'rejected'::text, 'executed'::text, 'superseded'::text])),
  constraint er_match_proposals_a_observation_key_not_null NOT NULL a_observation_key,
  constraint er_match_proposals_b_observation_key_not_null NOT NULL b_observation_key,
  constraint er_match_proposals_band_not_null NOT NULL band,
  constraint er_match_proposals_confidence_not_null NOT NULL confidence,
  constraint er_match_proposals_created_at_not_null NOT NULL created_at,
  constraint er_match_proposals_evidence_not_null NOT NULL evidence,
  constraint er_match_proposals_id_not_null NOT NULL id,
  constraint er_match_proposals_run_id_not_null NOT NULL run_id,
  constraint er_match_proposals_status_not_null NOT NULL status,
  constraint er_match_proposals_tenant_id_not_null NOT NULL tenant_id,
  constraint er_match_proposals_vetoes_not_null NOT NULL vetoes,
  constraint er_match_proposals_pkey PRIMARY KEY (id)
);
comment on table public.er_match_proposals is 'T-438 (identity-rules §7): the engine''s match PROPOSALS with the full evidence vector (INV-51). A proposal NEVER executes on its own (INV-50) — only fn_er_decide_proposal (an explicit human decision) advances its status.';

create table public.er_source_observations (
  id uuid default gen_random_uuid() not null,
  tenant_id uuid not null,
  observation_key text not null,
  source_system text not null,
  source_record_id text not null,
  kind text not null,
  canonical_id uuid,
  payload_hash text not null,
  display_name text,
  phones text[] default '{}'::text[] not null,
  email text,
  grade_level_code text,
  transport_destination text,
  academic_year text,
  tier text default 'import'::text not null,
  analyzed_at timestamp with time zone default now() not null,
  run_id text,
  created_at timestamp with time zone default now() not null,
  constraint er_source_observations_kind_check CHECK (kind = ANY (ARRAY['parent'::text, 'student'::text])),
  constraint er_source_observations_tier_check CHECK (tier = ANY (ARRAY['manual'::text, 'import'::text])),
  constraint er_source_observations_analyzed_at_not_null NOT NULL analyzed_at,
  constraint er_source_observations_created_at_not_null NOT NULL created_at,
  constraint er_source_observations_id_not_null NOT NULL id,
  constraint er_source_observations_kind_not_null NOT NULL kind,
  constraint er_source_observations_observation_key_not_null NOT NULL observation_key,
  constraint er_source_observations_payload_hash_not_null NOT NULL payload_hash,
  constraint er_source_observations_phones_not_null NOT NULL phones,
  constraint er_source_observations_source_record_id_not_null NOT NULL source_record_id,
  constraint er_source_observations_source_system_not_null NOT NULL source_system,
  constraint er_source_observations_tenant_id_not_null NOT NULL tenant_id,
  constraint er_source_observations_tier_not_null NOT NULL tier,
  constraint er_source_observations_pkey PRIMARY KEY (id),
  constraint er_source_observation_identity UNIQUE (tenant_id, observation_key, payload_hash)
);
comment on table public.er_source_observations is 'T-438 (ADR-032 / identity-rules §1): one ANALYZED identity observation — an import row or an existing canonical entity projected for matching. Immutable once written (append-only by convention; the engine never updates a source row). The payload hash keys the idempotency gate (INV-55).';

create table public.exam_sessions (
