create table public.expense_tickets (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  ticket_number text not null,
  title text not null,
  description text not null,
  category_id uuid not null,
  requested_amount numeric(12,2) not null,
  final_spent_amount numeric(12,2),
  justification text not null,
  urgency text not null,
  status text default 'pending_approval'::text not null,
  submitted_by uuid not null,
  submitted_at timestamp with time zone default now() not null,
  approved_by uuid,
  approved_at timestamp with time zone,
  approval_note text,
  rejected_reason text,
  disbursed_at timestamp with time zone,
  settled_by uuid,
  settled_at timestamp with time zone,
  receipt_path text,
  receipt_uploaded_at timestamp with time zone,
  receipt_uploaded_by uuid,
  anomaly_score numeric(5,2),
  anomaly_flags_json jsonb default '[]'::jsonb not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  payee text,
  responsible_profile_id uuid,
  constraint expense_tickets_final_spent_amount_check CHECK (final_spent_amount IS NULL OR final_spent_amount >= 0::numeric),
  constraint expense_tickets_requested_amount_check CHECK (requested_amount > 0::numeric),
  constraint expense_tickets_status_check CHECK (status = ANY (ARRAY['draft'::text, 'pending_approval'::text, 'approved_funds_released'::text, 'rejected'::text, 'disbursed'::text, 'settled_and_closed'::text])),
  constraint expense_tickets_urgency_check CHECK (urgency = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text])),
  constraint expense_tickets_anomaly_flags_json_not_null NOT NULL anomaly_flags_json,
  constraint expense_tickets_category_id_not_null NOT NULL category_id,
  constraint expense_tickets_created_at_not_null NOT NULL created_at,
  constraint expense_tickets_description_not_null NOT NULL description,
  constraint expense_tickets_id_not_null NOT NULL id,
  constraint expense_tickets_justification_not_null NOT NULL justification,
  constraint expense_tickets_requested_amount_not_null NOT NULL requested_amount,
  constraint expense_tickets_status_not_null NOT NULL status,
  constraint expense_tickets_submitted_at_not_null NOT NULL submitted_at,
  constraint expense_tickets_submitted_by_not_null NOT NULL submitted_by,
  constraint expense_tickets_tenant_id_not_null NOT NULL tenant_id,
  constraint expense_tickets_ticket_number_not_null NOT NULL ticket_number,
  constraint expense_tickets_title_not_null NOT NULL title,
  constraint expense_tickets_updated_at_not_null NOT NULL updated_at,
  constraint expense_tickets_urgency_not_null NOT NULL urgency,
  constraint expense_tickets_pkey PRIMARY KEY (id),
  constraint expense_tickets_tenant_id_ticket_number_key UNIQUE (tenant_id, ticket_number)
);
comment on table public.expense_tickets is 'Two-tier expense workflow. State machine enforced at DB layer. No self-approval. Receipt mandatory before settlement (plan §08).';
comment on column public.expense_tickets.responsible_profile_id is 'T-521 (issue #29 / WORKFORCE-520): the staff member accountable for the spend — DISTINCT from submitted_by (requester) and approved_by (decider). NULL on historical rows: flagged for review in the UI, never back-filled (the no-fabrication rule).';

