comment on table public.filieres is 'T-401: the canonical academic classification catalog (filières and their spécialités). Specialities are rows with parent_code set. applicable_grades lists canonical grade_level codes.';

create table public.grade_level_tuition (
  id uuid default gen_uuid() not null,
  pricing_config_id uuid not null,
  academic_level_id uuid not null,
  annual_amount numeric(10,2) not null,
  tranche_1_amount numeric(10,2) not null,
  tranche_2_amount numeric(10,2) not null,
  tranche_3_amount numeric(10,2) not null,
  tranche_1_month integer default 9 not null,
  tranche_2_month integer default 12 not null,
  tranche_3_month integer not null,
  registration_fee numeric(10,2),
  updated_at timestamp with time zone default now() not null,
  constraint grade_level_tuition_annual_amount_check CHECK (annual_amount >= 0::numeric),
  constraint grade_level_tuition_registration_fee_check CHECK (registration_fee IS NULL OR registration_fee >= 0::numeric),
  constraint grade_level_tuition_tranche_1_amount_check CHECK (tranche_1_amount >= 0::numeric),
  constraint grade_level_tuition_tranche_1_month_check CHECK (tranche_1_month >= 1 AND tranche_1_month <= 12),
  constraint grade_level_tuition_tranche_2_amount_check CHECK (tranche_2_amount >= 0::numeric),
  constraint grade_level_tuition_tranche_2_month_check CHECK (tranche_2_month >= 1 AND tranche_2_month <= 12),
  constraint grade_level_tuition_tranche_3_amount_check CHECK (tranche_3_amount >= 0::numeric),
  constraint grade_level_tuition_tranche_3_month_check CHECK (tranche_3_month >= 1 AND tranche_3_month <= 12),
  constraint tranches_sum_check CHECK (abs(tranche_1_amount + tranche_2_amount + tranche_3_amount - annual_amount) < 0.01),
  constraint grade_level_tuition_academic_level_id_not_null NOT NULL academic_level_id,
  constraint grade_level_tuition_annual_amount_not_null NOT NULL annual_amount,
  constraint grade_level_tuition_id_not_null NOT NULL id,
  constraint grade_level_tuition_pricing_config_id_not_null NOT NULL pricing_config_id,
  constraint grade_level_tuition_tranche_1_amount_not_null NOT NULL tranche_1_amount,
  constraint grade_level_tuition_tranche_1_month_not_null NOT NULL tranche_1_month,
  constraint grade_level_tuition_tranche_2_amount_not_null NOT NULL tranche_2_amount,
  constraint grade_level_tuition_tranche_2_month_not_null NOT NULL tranche_2_month,
  constraint grade_level_tuition_tranche_3_amount_not_null NOT NULL tranche_3_amount,
  constraint grade_level_tuition_tranche_3_month_not_null NOT NULL tranche_3_month,
  constraint grade_level_tuition_updated_at_not_null NOT NULL updated_at,
  constraint grade_level_tuition_pkey PRIMARY KEY (id),
  constraint grade_level_tuition_pricing_config_id_academic_level_id_key UNIQUE (pricing_config_id, academic_level_id)
);
comment on column public.grade_level_tuition.registration_fee is 'CALC-001 (0088): FI (frais d''inscription) charged PER STUDENT at this grade. NULL = fall back to the client-side real matrix default. The flat pricing_configs.registration_fee is the LEGACY family fee (deprecated).';

create table public.grades (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  student_id uuid not null,
  assessment_id uuid not null,
  class_subject_id uuid not null,
  score numeric(5,2) not null,
  subject_average numeric(5,2),
  is_absent boolean default false not null,
  entered_by uuid,
  entered_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint grades_score_check CHECK (score >= 0::numeric AND score <= 20::numeric),
  constraint grades_subject_average_check CHECK (subject_average IS NULL OR subject_average >= 0::numeric AND subject_average <= 20::numeric),
  constraint grades_assessment_id_not_null NOT NULL assessment_id,
  constraint grades_class_subject_id_not_null NOT NULL class_subject_id,
  constraint grades_entered_at_not_null NOT NULL entered_at,
  constraint grades_id_not_null NOT NULL id,
  constraint grades_is_absent_not_null NOT NULL is_absent,
  constraint grades_score_not_null NOT NULL score,
  constraint grades_student_id_not_null NOT NULL student_id,
  constraint grades_tenant_id_not_null NOT NULL tenant_id,
  constraint grades_updated_at_not_null NOT NULL updated_at,
  constraint grades_pkey PRIMARY KEY (id),
  constraint grades_tenant_id_student_id_assessment_id_key UNIQUE (tenant_id, student_id, assessment_id)
);

create table public.homework (
  id uuid default gen_uuid() not null,
