  attachments jsonb default '[]'::jsonb not null,
  academic_year text not null,
  created_at timestamp with time zone default now() not null,
  pushed_at timestamp with time zone,
  acknowledged_count integer default 0 not null,
  constraint homework_academic_year_not_null NOT NULL academic_year,
  constraint homework_acknowledged_count_not_null NOT NULL acknowledged_count,
  constraint homework_attachments_not_null NOT NULL attachments,
  constraint homework_class_id_not_null NOT NULL class_id,
  constraint homework_created_at_not_null NOT NULL created_at,
  constraint homework_description_not_null NOT NULL description,
  constraint homework_due_date_not_null NOT NULL due_date,
  constraint homework_id_not_null NOT NULL id,
  constraint homework_subject_id_not_null NOT NULL subject_id,
  constraint homework_subject_name_not_null NOT NULL subject_name,
  constraint homework_teacher_id_not_null NOT NULL teacher_id,
  constraint homework_teacher_name_not_null NOT NULL teacher_name,
  constraint homework_tenant_id_not_null NOT NULL tenant_id,
  constraint homework_title_not_null NOT NULL title,
