create table public.installments (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  parent_id uuid not null,
  student_id uuid not null,
  service_enrollment_id uuid,
  invoice_id uuid,
  tranche_number integer,
  amount_due numeric(10,2) not null,
  amount_paid numeric(10,2) default 0 not null,
  due_date date not null,
  paid_date date,
  status text default 'unpaid'::text not null,
  academic_cycle text,
  is_custom_schedule boolean default false not null,
  custom_schedule_note text,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  amount_pending numeric(12,2) default 0.00 not null,
  payment_plan text default 'tranches'::text not null,
  label text,
  category text default 'tuition'::text not null,
  source_type text,
  source_id text,
  academic_year_id uuid,
  constraint installments_academic_cycle_check CHECK (academic_cycle = ANY (ARRAY['primaire'::text, 'cem'::text, 'lycee'::text, 'prescolaire'::text])),
  constraint installments_amount_due_check CHECK (amount_due >= 0::numeric),
  constraint installments_amount_paid_check CHECK (amount_paid >= 0::numeric),
  constraint installments_category_check CHECK (category = ANY (ARRAY['tuition'::text, 'transport'::text, 'canteen'::text, 'uniform'::text, 'books'::text, 'extracurricular'::text, 'therapy_psychology'::text, 'therapy_speech'::text, 'second_apron'::text, 'parent_credit'::text, 'other'::text])),
  constraint installments_payment_plan_check CHECK (payment_plan = ANY (ARRAY['full_annual'::text, 'tranches'::text])),
  constraint installments_status_check CHECK (status = ANY (ARRAY['unpaid'::text, 'partial'::text, 'paid'::text, 'overdue'::text, 'pending'::text, 'pending_clearance'::text])),
  constraint installments_tranche_number_check CHECK (tranche_number = ANY (ARRAY[0, 1, 2, 3])),
  constraint installments_amount_due_not_null NOT NULL amount_due,
  constraint installments_amount_paid_not_null NOT NULL amount_paid,
  constraint installments_amount_pending_not_null NOT NULL amount_pending,
  constraint installments_category_not_null NOT NULL category,
  constraint installments_created_at_not_null NOT NULL created_at,
  constraint installments_due_date_not_null NOT NULL due_date,
  constraint installments_id_not_null NOT NULL id,
  constraint installments_is_custom_schedule_not_null NOT NULL is_custom_schedule,
  constraint installments_parent_id_not_null NOT NULL parent_id,
  constraint installments_payment_plan_not_null NOT NULL payment_plan,
  constraint installments_status_not_null NOT NULL status,
  constraint installments_student_id_not_null NOT NULL student_id,
  constraint installments_tenant_id_not_null NOT NULL tenant_id,
  constraint installments_updated_at_not_null NOT NULL updated_at,
  constraint installments_pkey PRIMARY KEY (id)
);
comment on table public.installments is 'Tranche-level billing. 3 tranches per service_enrollment. Status auto-computed via trigger from amount_paid.';
comment on column public.installments.service_enrollment_id is 'Optional FK to service_enrollments. NULL for bulk-imported tranches that are not linked to a specific service enrollment (e.g. Excel import rows).';
comment on column public.installments.tranche_number is 'T-466 (DEBT-102): 0 = the registration fee (FI), 1..3 = the official tranches, NULL = a NON-WAVE row (a manual debt / custom charge that exists outside the tranche workflow) — excluded from every wave everywhere (T-424/DATA-042) and from the 0129 identity index by its own predicate.';
comment on column public.installments.academic_cycle is 'Education cycle (prescolaire/primaire/cem/lycee) — drives schedule template.';
comment on column public.installments.is_custom_schedule is 'True when the due date has been manually overridden per parent.';
comment on column public.installments.amount_pending is 'Uncleared non-cash funds (pending check/transfer) sitting on this tranche. Invariant 4: a tranche is "paid" only when amount_paid >= amount_due.';
comment on column public.installments.payment_plan is 'Whether this installment is a 100% full-annual payment or a single tranche.';
comment on column public.installments.label is 'Human-readable tranche label (e.g. "Tranche 1 - Septembre"). When null, the UI falls back to "Tranche {tranche_number}".';
comment on column public.installments.category is 'Billing category -- drives which account the ledger entry lands on. Mirrors ledger_entries.category and payments.category. Denormalized from service_enrollments.service_kind so bulk-imported rows (which do not have a service_enrollment) can still carry the category.';
comment on column public.installments.source_type is 'Provenance of the row. "bulk_import" = Excel importer; "manual_entry" = interactive UI; NULL = legacy/seed data.';
comment on column public.installments.source_id is 'Stable id within the source. For bulk_import, this is "{studentId}:{field}" (e.g. "abc-123:FI") so re-imports hit the same row.';

create table public.inventory_items (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  sku text not null,
  name text not null,
  description text,
  category text,
  unit text default 'piece'::text not null,
  quantity_on_hand numeric(12,2) default 0 not null,
  quantity_reserved numeric(12,2) default 0 not null,
  reorder_level numeric(12,2) default 0 not null,
  reorder_quantity numeric(12,2) default 0 not null,
  unit_cost numeric(12,2) default 0 not null,
  location text,
  is_active boolean default true not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  deleted_at timestamp with time zone,
  constraint inventory_items_check CHECK (quantity_reserved <= quantity_on_hand),
  constraint inventory_items_quantity_on_hand_check CHECK (quantity_on_hand >= 0::numeric),
  constraint inventory_items_quantity_reserved_check CHECK (quantity_reserved >= 0::numeric),
  constraint inventory_items_reorder_level_check CHECK (reorder_level >= 0::numeric),
  constraint inventory_items_reorder_quantity_check CHECK (reorder_quantity >= 0::numeric),
  constraint inventory_items_unit_cost_check CHECK (unit_cost >= 0::numeric),
  constraint inventory_items_created_at_not_null NOT NULL created_at,
  constraint inventory_items_id_not_null NOT NULL id,
  constraint inventory_items_is_active_not_null NOT NULL is_active,
  constraint inventory_items_name_not_null NOT NULL name,
  constraint inventory_items_quantity_on_hand_not_null NOT NULL quantity_on_hand,
  constraint inventory_items_quantity_reserved_not_null NOT NULL quantity_reserved,
  constraint inventory_items_reorder_level_not_null NOT NULL reorder_level,
  constraint inventory_items_reorder_quantity_not_null NOT NULL reorder_quantity,
  constraint inventory_items_sku_not_null NOT NULL sku,
  constraint inventory_items_tenant_id_not_null NOT NULL tenant_id,
  constraint inventory_items_unit_cost_not_null NOT NULL unit_cost,
  constraint inventory_items_unit_not_null NOT NULL unit,
  constraint inventory_items_updated_at_not_null NOT NULL updated_at,
  constraint inventory_items_pkey PRIMARY KEY (id),
  constraint inventory_items_tenant_id_sku_key UNIQUE (tenant_id, sku)
);
comment on table public.inventory_items is 'Stock-keeping units with on-hand/reserved quantities and reorder thresholds. Plan §11.05.';
comment on column public.inventory_items.sku is 'Unique stock-keeping unit code per tenant.';
comment on column public.inventory_items.quantity_reserved is 'Units committed to outbound orders but not yet dispatched. CHECK: reserved <= on_hand.';
comment on column public.inventory_items.reorder_level is 'Threshold below which a reorder alert fires.';
comment on column public.inventory_items.reorder_quantity is 'Suggested reorder quantity when stock falls below reorder_level.';
comment on column public.inventory_items.unit_cost is 'Latest weighted-average unit cost in DZD (numeric(12,2)).';

create table public.inventory_transactions (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  item_id uuid not null,
  transaction_type text not null,
  quantity numeric(12,2) not null,
  unit_cost numeric(12,2) default 0 not null,
  total_cost numeric(12,2) default 0 not null,
  reference_type text,
  reference_id uuid,
  performed_by uuid,
  note text,
  transaction_at timestamp with time zone default now() not null,
  created_at timestamp with time zone default now() not null,
  quantity_before numeric(12,2),
  quantity_after numeric(12,2),
  performed_by_name text,
  constraint inventory_transactions_quantity_check CHECK (quantity <> 0::numeric),
  constraint inventory_transactions_total_cost_check CHECK (total_cost >= 0::numeric),
  constraint inventory_transactions_transaction_type_check CHECK (transaction_type = ANY (ARRAY['receive'::text, 'dispatch'::text, 'scan'::text, 'damage'::text, 'adjust'::text, 'return'::text])),
  constraint inventory_transactions_unit_cost_check CHECK (unit_cost >= 0::numeric),
  constraint inventory_transactions_created_at_not_null NOT NULL created_at,
  constraint inventory_transactions_id_not_null NOT NULL id,
  constraint inventory_transactions_item_id_not_null NOT NULL item_id,
  constraint inventory_transactions_quantity_not_null NOT NULL quantity,
  constraint inventory_transactions_tenant_id_not_null NOT NULL tenant_id,
  constraint inventory_transactions_total_cost_not_null NOT NULL total_cost,
  constraint inventory_transactions_transaction_at_not_null NOT NULL transaction_at,
  constraint inventory_transactions_transaction_type_not_null NOT NULL transaction_type,
  constraint inventory_transactions_unit_cost_not_null NOT NULL unit_cost,
  constraint inventory_transactions_pkey PRIMARY KEY (id)
);
comment on table public.inventory_transactions is 'Append-only stock movement ledger. quantity is signed (+inbound / -outbound). Polymorphic reference via reference_type/reference_id. Plan §11.06.';
comment on column public.inventory_transactions.transaction_type is 'receive=inbound from supplier, dispatch=outbound to consumer, scan=barcoded check, damage=loss/write-off, adjust=manual correction, return=customer return.';
comment on column public.inventory_transactions.quantity is 'Signed quantity: positive for inbound movements (receive/return), negative for outbound (dispatch/damage). Adjust can be either.';
comment on column public.inventory_transactions.reference_type is 'Polymorphic reference discriminator (e.g. purchase_request, delivery, pending_dispatch). reference_id is the row UUID.';
comment on column public.inventory_transactions.performed_by is 'user_profiles.id of the warehouse worker / buyer who recorded the movement. No FK (convention).';
comment on column public.inventory_transactions.quantity_before is 'Item quantity_on_hand BEFORE this transaction (audit-grade ledger display, frozen at write time).';
comment on column public.inventory_transactions.quantity_after is 'Item quantity_on_hand AFTER this transaction (audit-grade ledger display, frozen at write time).';
comment on column public.inventory_transactions.performed_by_name is 'Actor display name FROZEN at write time (performed_by has no FK by convention).';

create table public.invoices (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  parent_id uuid not null,
  student_id uuid,
  service_enrollment_id uuid,
  invoice_number text not null,
  issue_date date default CURRENT_DATE not null,
  due_date date not null,
  amount numeric(10,2) not null,
  status text default 'unpaid'::text not null,
  paid_amount numeric(10,2) default 0 not null,
  notes text,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint invoices_amount_check CHECK (amount >= 0::numeric),
  constraint invoices_status_check CHECK (status = ANY (ARRAY['unpaid'::text, 'paid'::text, 'partial'::text, 'cancelled'::text, 'overdue'::text])),
  constraint invoices_amount_not_null NOT NULL amount,
  constraint invoices_created_at_not_null NOT NULL created_at,
  constraint invoices_due_date_not_null NOT NULL due_date,
  constraint invoices_id_not_null NOT NULL id,
  constraint invoices_invoice_number_not_null NOT NULL invoice_number,
  constraint invoices_issue_date_not_null NOT NULL issue_date,
  constraint invoices_paid_amount_not_null NOT NULL paid_amount,
  constraint invoices_parent_id_not_null NOT NULL parent_id,
  constraint invoices_status_not_null NOT NULL status,
  constraint invoices_tenant_id_not_null NOT NULL tenant_id,
  constraint invoices_updated_at_not_null NOT NULL updated_at,
  constraint invoices_pkey PRIMARY KEY (id),
  constraint invoices_tenant_id_invoice_number_key UNIQUE (tenant_id, invoice_number)
);

create table public.leave_requests (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  personnel_id uuid not null,
  leave_type text not null,
  start_date date not null,
  end_date date not null,
  reason text,
  status text default 'pending'::text not null,
  reviewed_by uuid,
  reviewed_at timestamp with time zone,
  decision_note text,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  reviewed_by_name text,
  amount_requested numeric(12,2),
  clarification_request text,
  clarification_response text,
  constraint leave_requests_amount_requested_check CHECK (amount_requested IS NULL OR amount_requested >= 0::numeric),
  constraint leave_requests_check CHECK (end_date >= start_date),
  constraint leave_requests_leave_type_kind_check CHECK (leave_type = ANY (ARRAY['annual'::text, 'sick'::text, 'personal'::text, 'unpaid'::text, 'maternity'::text, 'paternity'::text, 'leave'::text, 'absence'::text, 'overtime'::text, 'shift_swap'::text, 'remote'::text, 'spending_reimbursement'::text])),
  constraint leave_requests_status_kind_check CHECK (status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'clarification_requested'::text, 'cancelled'::text])),
  constraint leave_requests_created_at_not_null NOT NULL created_at,
  constraint leave_requests_end_date_not_null NOT NULL end_date,
  constraint leave_requests_id_not_null NOT NULL id,
  constraint leave_requests_leave_type_not_null NOT NULL leave_type,
  constraint leave_requests_personnel_id_not_null NOT NULL personnel_id,
  constraint leave_requests_start_date_not_null NOT NULL start_date,
  constraint leave_requests_status_not_null NOT NULL status,
  constraint leave_requests_tenant_id_not_null NOT NULL tenant_id,
  constraint leave_requests_updated_at_not_null NOT NULL updated_at,
  constraint leave_requests_pkey PRIMARY KEY (id)
);
comment on table public.leave_requests is 'Leave request workflow: pending → approved/rejected/cancelled. Plan §10.07.';
comment on column public.leave_requests.leave_type is 'Leave category. Algerian labor law categories: annual, sick, personal, unpaid, maternity, paternity.';
comment on column public.leave_requests.reviewed_by is 'user_profiles.id of the manager/admin who reviewed. No FK (convention).';
comment on column public.leave_requests.decision_note is 'Mandatory when status = rejected (enforced by app layer).';
comment on column public.leave_requests.reviewed_by_name is 'Display name of the manager/admin who reviewed (decidedByName in the desktop domain contract). Stored at decision time because reviewed_by has no FK to user_profiles. Added by 0072 (T-178).';

create table public.ledger_entries (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  entry_number text not null,
  parent_id uuid not null,
  student_id uuid,
  service_enrollment_id uuid,
  payment_id uuid,
  adjustment_id uuid,
  reverses_entry_id uuid,
  account_id text not null,
  entry_type text not null,
  amount numeric(12,2) not null,
  category text,
  description text,
  entry_date timestamp with time zone default now() not null,
  created_at timestamp with time zone default now() not null,
  source_type text,
  source_id text,
  method text,
  receipt_number text,
  payment_status text,
  reverses_id text,
  actor_id text,
  actor_name text,
  at timestamp with time zone,
  metadata jsonb,
  updated_at timestamp with time zone default now() not null,
  constraint ledger_entries_adjustment_description_guard CHECK ((entry_type <> ALL (ARRAY['adjustment'::text, 'reversal'::text])) OR description IS NOT NULL AND length(btrim(description)) >= 3),
  constraint ledger_entries_amount_check CHECK (amount <> 0::numeric),
  constraint ledger_entries_category_check CHECK (category = ANY (ARRAY['tuition'::text, 'transport'::text, 'canteen'::text, 'uniform'::text, 'books'::text, 'extracurricular'::text, 'therapy_psychology'::text, 'therapy_speech'::text, 'second_apron'::text, 'parent_credit'::text, 'other'::text])),
  constraint ledger_entries_entry_type_check CHECK (entry_type = ANY (ARRAY['charge'::text, 'payment'::text, 'adjustment'::text, 'refund'::text, 'reversal'::text, 'transfer'::text])),
  constraint ledger_entries_method_check CHECK (method IS NULL OR (method = ANY (ARRAY['cash'::text, 'check'::text, 'transfer'::text]))),
  constraint ledger_entries_account_id_not_null NOT NULL account_id,
  constraint ledger_entries_amount_not_null NOT NULL amount,
  constraint ledger_entries_created_at_not_null NOT NULL created_at,
  constraint ledger_entries_entry_date_not_null NOT NULL entry_date,
  constraint ledger_entries_entry_number_not_null NOT NULL entry_number,
  constraint ledger_entries_entry_type_not_null NOT NULL entry_type,
  constraint ledger_entries_id_not_null NOT NULL id,
  constraint ledger_entries_parent_id_not_null NOT NULL parent_id,
  constraint ledger_entries_tenant_id_not_null NOT NULL tenant_id,
  constraint ledger_entries_updated_at_not_null NOT NULL updated_at,
  constraint ledger_entries_pkey PRIMARY KEY (id),
  constraint ledger_entries_tenant_id_entry_number_key UNIQUE (tenant_id, entry_number)
);
comment on table public.ledger_entries is 'IMMUTABLE accounting ledger. Single source of truth for all balances — computed by replay via compute_account_balance(). Never edited or deleted; corrections via reversal entries (plan §07).';

create table public.notification_preferences (
  id uuid default gen_uuid() not null,
  tenant_id uuid,
  user_profile_id uuid not null,
  category text not null,
  push_enabled boolean default true not null,
  in_app_enabled boolean default true not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint notification_preferences_category_check CHECK (category = ANY (ARRAY['payment'::text, 'absence'::text, 'message'::text, 'announcement'::text, 'grade'::text, 'homework'::text, 'calendar'::text, 'account'::text, 'system'::text])),
  constraint notification_preferences_category_not_null NOT NULL category,
  constraint notification_preferences_created_at_not_null NOT NULL created_at,
  constraint notification_preferences_id_not_null NOT NULL id,
  constraint notification_preferences_in_app_enabled_not_null NOT NULL in_app_enabled,
  constraint notification_preferences_push_enabled_not_null NOT NULL push_enabled,
  constraint notification_preferences_updated_at_not_null NOT NULL updated_at,
  constraint notification_preferences_user_profile_id_not_null NOT NULL user_profile_id,
  constraint notification_preferences_pkey PRIMARY KEY (id),
  constraint notification_preferences_user_profile_id_category_key UNIQUE (user_profile_id, category)
);
comment on table public.notification_preferences is 'Per-category notification opt-in/out for each user. Missing rows = both push and in-app enabled (default opt-in).';

create table public.notifications (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  kind text not null,
  title text not null,
  body text,
  priority text default 'medium'::text not null,
  source text default 'system'::text not null,
  source_label text,
  target_user_id uuid,
  target_role text,
  is_read boolean default false not null,
  read_at timestamp with time zone,
  dismissed_at timestamp with time zone,
  triggered_at timestamp with time zone default now() not null,
  expires_at timestamp with time zone,
  link_entity_type text,
  link_entity_id uuid,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint notifications_kind_check CHECK (kind = ANY (ARRAY['alert'::text, 'info'::text, 'warning'::text, 'success'::text, 'error'::text, 'system'::text])),
  constraint notifications_priority_check CHECK (priority = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'urgent'::text])),
  constraint notifications_source_check CHECK (source = ANY (ARRAY['system'::text, 'manual'::text, 'workflow'::text, 'schedule'::text, 'audit'::text])),
  constraint notifications_created_at_not_null NOT NULL created_at,
  constraint notifications_id_not_null NOT NULL id,
  constraint notifications_is_read_not_null NOT NULL is_read,
  constraint notifications_kind_not_null NOT NULL kind,
  constraint notifications_priority_not_null NOT NULL priority,
  constraint notifications_source_not_null NOT NULL source,
  constraint notifications_tenant_id_not_null NOT NULL tenant_id,
  constraint notifications_title_not_null NOT NULL title,
  constraint notifications_triggered_at_not_null NOT NULL triggered_at,
  constraint notifications_updated_at_not_null NOT NULL updated_at,
  constraint notifications_pkey PRIMARY KEY (id)
);
comment on table public.notifications is 'User-facing alerts. target_user_id=NULL means role-broadcast (target_role). Polymorphic link to originating entity. Plan §13.02.';
comment on column public.notifications.kind is 'Visual category: alert/info/warning/success/error/system (drives icon + color).';
comment on column public.notifications.priority is 'Urgency: low/medium/high/urgent. Urgent triggers desktop notification + sound.';
comment on column public.notifications.source is 'Origin: system (auto), manual (admin-created), workflow (workflow_run), schedule (cron), audit (audit log).';
comment on column public.notifications.source_label is 'Human-readable source (e.g. "Workflow: Overdue Alert") shown in the notification UI.';
comment on column public.notifications.target_user_id is 'user_profiles.id of the recipient. NULL = broadcast to all users with target_role. No FK (convention).';
comment on column public.notifications.target_role is 'Role name for role-targeted notifications. NULL = all tenant users. Used when target_user_id is NULL.';
comment on column public.notifications.is_read is 'TRUE once the user has opened the notification (read_at is set).';
comment on column public.notifications.dismissed_at is 'Set when the user explicitly dismisses the notification (separate from read — dismissed hides it permanently).';
comment on column public.notifications.triggered_at is 'When the underlying event occurred (may differ from created_at for replayed/backfilled notifications).';
comment on column public.notifications.expires_at is 'Optional TTL — notification is hidden from active lists after this timestamp. NULL = never expires.';
comment on column public.notifications.link_entity_type is 'Polymorphic link discriminator (payment, expense_ticket, workflow_run, etc.). link_entity_id is the row UUID.';
comment on column public.notifications.created_by is 'user_profiles.id of the creator (NULL for system-generated notifications). No FK (convention).';

create table public.onboarding_states (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  personnel_id uuid,
  current_step integer default 0 not null,
  completed_steps integer[] default '{}'::integer[] not null,
  started_at timestamp with time zone default now() not null,
  completed_at timestamp with time zone,
  data_json jsonb default '{}'::jsonb not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint onboarding_states_current_step_check CHECK (current_step >= 0),
  constraint onboarding_states_completed_steps_not_null NOT NULL completed_steps,
  constraint onboarding_states_created_at_not_null NOT NULL created_at,
  constraint onboarding_states_current_step_not_null NOT NULL current_step,
  constraint onboarding_states_data_json_not_null NOT NULL data_json,
  constraint onboarding_states_id_not_null NOT NULL id,
  constraint onboarding_states_started_at_not_null NOT NULL started_at,
  constraint onboarding_states_tenant_id_not_null NOT NULL tenant_id,
  constraint onboarding_states_updated_at_not_null NOT NULL updated_at,
  constraint onboarding_states_pkey PRIMARY KEY (id),
  constraint onboarding_states_tenant_id_personnel_id_key UNIQUE (tenant_id, personnel_id)
);
comment on table public.onboarding_states is 'Onboarding wizard progress per personnel. One row per personnel (uniqueness enforced). Plan §10.10.';
comment on column public.onboarding_states.personnel_id is 'T-483 (0142): NULL = the TENANT-singleton wizard row (the desktop OnboardingRepository''s storage); non-NULL = the 0010 per-employee onboarding progress (plan §10.10).';
comment on column public.onboarding_states.current_step is 'Zero-based index of the current wizard step.';
comment on column public.onboarding_states.completed_steps is 'Array of step indices the user has completed (allows non-linear navigation).';
comment on column public.onboarding_states.completed_at is 'Set when the user finishes the wizard. NULL means in-progress.';
comment on column public.onboarding_states.data_json is 'Free-form JSON payload capturing partial inputs (e.g. draft profile fields) between wizard steps.';

create table public.parent_student_links (
