  constraint parent_student_links_id_not_null NOT NULL id,
  constraint parent_student_links_is_primary_not_null NOT NULL is_primary,
  constraint parent_student_links_parent_id_not_null NOT NULL parent_id,
  constraint parent_student_links_student_id_not_null NOT NULL student_id,
  constraint parent_student_links_tenant_id_not_null NOT NULL tenant_id,
  constraint parent_student_links_pkey PRIMARY KEY (id),
  constraint parent_student_links_tenant_id_parent_id_student_id_key UNIQUE (tenant_id, parent_id, student_id)
);

create table public.parents (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  parent_code text not null,
  first_name text not null,
  last_name text not null,
  primary_phone text not null,
  secondary_phone text,
  email text,
  national_id text,
  occupation text,
  address text,
  city text,
  postal_code text,
  relationship text,
  notes text,
  is_active boolean default true not null,
  is_financially_restricted boolean default false not null,
  auth_user_id uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  deleted_at timestamp with time zone,
