  transport_destination text,
  city_tier text,
  constraint parents_relationship_check CHECK (relationship = ANY (ARRAY['father'::text, 'mother'::text, 'guardian'::text, 'other'::text])),
  constraint parents_created_at_not_null NOT NULL created_at,
  constraint parents_first_name_not_null NOT NULL first_name,
  constraint parents_id_not_null NOT NULL id,
  constraint parents_is_active_not_null NOT NULL is_active,
  constraint parents_is_financially_restricted_not_null NOT NULL is_financially_restricted,
