  constraint parents_parent_code_not_null NOT NULL parent_code,
  constraint parents_primary_phone_not_null NOT NULL primary_phone,
  constraint parents_tenant_id_not_null NOT NULL tenant_id,
  constraint parents_updated_at_not_null NOT NULL updated_at,
  constraint parents_pkey PRIMARY KEY (id),
  constraint parents_tenant_id_parent_code_key UNIQUE (tenant_id, parent_code)
);
comment on table public.parents is 'Master billing entity. A parent may have N students. Soft-deleted via deleted_at; RLS hides deleted rows.';
comment on column public.parents.display_name is 'Complete display name as imported (e.g. ''BENALI Mohamed''). When non-null, UI MUST show this verbatim instead of first_name/last_name. Preserves the full name even when first_name/last_name are split for indexing.';

create table public.payment_allocations (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  payment_id uuid not null,
  charge_id uuid,
  installment_id uuid,
  category text not null,
  allocated_amount numeric(12,2) not null,
  label text,
  created_at timestamp with time zone default now() not null,
  academic_year_id uuid,
  constraint payment_allocations_allocated_amount_check CHECK (allocated_amount >= 0::numeric),
  constraint payment_allocations_category_check CHECK (category = ANY (ARRAY['tuition'::text, 'transport'::text, 'canteen'::text, 'uniform'::text, 'books'::text, 'extracurricular'::text, 'therapy_psychology'::text, 'therapy_speech'::text, 'second_apron'::text, 'parent_credit'::text, 'other'::text])),
  constraint payment_allocations_allocated_amount_not_null NOT NULL allocated_amount,
  constraint payment_allocations_category_not_null NOT NULL category,
  constraint payment_allocations_created_at_not_null NOT NULL created_at,
  constraint payment_allocations_id_not_null NOT NULL id,
  constraint payment_allocations_payment_id_not_null NOT NULL payment_id,
  constraint payment_allocations_tenant_id_not_null NOT NULL tenant_id,
  constraint payment_allocations_pkey PRIMARY KEY (id)
);
comment on table public.payment_allocations is 'Links a single payment to multiple charges/services. A 300000 payment can be split: 250000 to tuition charge, 50000 to transport charge. Enables the Payment Breakdown UI feature.';

create table public.payments (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  payment_number text not null,
  parent_id uuid not null,
  student_id uuid,
  invoice_id uuid,
  installment_id uuid,
  amount numeric(10,2) not null,
  method text not null,
  check_number text,
  check_bank_name text,
  check_issue_date date,
  check_clearance_date date,
  transfer_reference text,
  transfer_source_bank text,
  proof_path text,
  status text not null,
  collected_at timestamp with time zone default now() not null,
  collected_by uuid,
  notes text,
  reversal_of_payment_id uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  receipt_number text,
  category text default 'other'::text,
  expected_amount numeric(12,2) default 0,
  excess_amount numeric(12,2) default 0,
  excess_remark text,
  academic_year_id uuid,
  constraint payments_amount_check CHECK (amount > 0::numeric),
  constraint payments_category_check CHECK (category = ANY (ARRAY['tuition'::text, 'transport'::text, 'canteen'::text, 'uniform'::text, 'books'::text, 'extracurricular'::text, 'therapy_psychology'::text, 'therapy_speech'::text, 'second_apron'::text, 'parent_credit'::text, 'other'::text])),
  constraint payments_method_check CHECK (method = ANY (ARRAY['cash'::text, 'check'::text, 'transfer'::text])),
  constraint payments_status_check CHECK (status = ANY (ARRAY['paid'::text, 'pending'::text, 'partial'::text, 'overdue'::text, 'refunded'::text, 'cancelled'::text, 'pending_clearance'::text, 'unpaid'::text])),
  constraint payments_amount_not_null NOT NULL amount,
  constraint payments_collected_at_not_null NOT NULL collected_at,
  constraint payments_created_at_not_null NOT NULL created_at,
  constraint payments_id_not_null NOT NULL id,
  constraint payments_method_not_null NOT NULL method,
  constraint payments_parent_id_not_null NOT NULL parent_id,
  constraint payments_payment_number_not_null NOT NULL payment_number,
  constraint payments_status_not_null NOT NULL status,
  constraint payments_tenant_id_not_null NOT NULL tenant_id,
  constraint payments_updated_at_not_null NOT NULL updated_at,
  constraint payments_pkey PRIMARY KEY (id),
  constraint payments_tenant_id_payment_number_key UNIQUE (tenant_id, payment_number)
);
comment on column public.payments.receipt_number is 'Alias for payment_number — kept in sync by trigger. Used by the 0026 atomic RPCs and the desktop domain model.';
comment on column public.payments.category is 'Billing category — drives which account the ledger entry lands on. Mirrors ledger_entries.category for cross-table queries.';
comment on column public.payments.expected_amount is 'The total expected amount for the charges this payment covers. When amount exceeds expected_amount, the difference is excess_amount.';
comment on column public.payments.excess_amount is 'UI-display-only field. Populated by the application layer for the overpayment breakdown display. NOT a source of truth for financial calculations — canonical overpayment tracking is via `parent_credit` ledger adjustment entries (INV-7). Reading this column for balance computation is a bug.';
comment on column public.payments.excess_remark is 'Remark explaining an overpayment. Example: Parent paid 360000 instead of 300000, excess 60000 held as parent credit for next year.';

create table public.pending_dispatches (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  destination text not null,
  items_json jsonb default '[]'::jsonb not null,
  scheduled_at timestamp with time zone not null,
  dispatched_at timestamp with time zone,
  dispatched_by uuid,
  delivery_id uuid,
  status text default 'pending'::text not null,
  note text,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint pending_dispatches_status_check CHECK (status = ANY (ARRAY['pending'::text, 'preparing'::text, 'dispatched'::text, 'delivered'::text, 'cancelled'::text])),
  constraint pending_dispatches_created_at_not_null NOT NULL created_at,
  constraint pending_dispatches_destination_not_null NOT NULL destination,
  constraint pending_dispatches_id_not_null NOT NULL id,
  constraint pending_dispatches_items_json_not_null NOT NULL items_json,
  constraint pending_dispatches_scheduled_at_not_null NOT NULL scheduled_at,
  constraint pending_dispatches_status_not_null NOT NULL status,
  constraint pending_dispatches_tenant_id_not_null NOT NULL tenant_id,
  constraint pending_dispatches_updated_at_not_null NOT NULL updated_at,
  constraint pending_dispatches_pkey PRIMARY KEY (id)
);
comment on table public.pending_dispatches is 'Outbound goods awaiting pickup or delivery. Links to deliveries when assigned to a driver. Plan §11.08.';
comment on column public.pending_dispatches.items_json is 'JSON array of item lines: [{sku, name, quantity, note}]. GIN-indexed.';
comment on column public.pending_dispatches.dispatched_by is 'user_profiles.id of the warehouse worker who released the goods. No FK (convention).';
comment on column public.pending_dispatches.delivery_id is 'FK to deliveries(id) once a driver is assigned. SET NULL if the delivery is cancelled.';
comment on column public.pending_dispatches.status is 'Outbound dispatch lifecycle: pending → preparing (goods being gathered) → dispatched → delivered; cancelled is terminal. 0139 added ''preparing'' (T-479: the domain union''s transient state, previously impossible to persist).';

create table public.pending_receipts (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  purchase_request_id uuid,
  supplier_id uuid,
  expected_at timestamp with time zone,
  received_at timestamp with time zone,
  received_by uuid,
  items_json jsonb default '[]'::jsonb not null,
