  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint pending_receipts_status_check CHECK (status = ANY (ARRAY['pending'::text, 'partial'::text, 'received'::text, 'cancelled'::text])),
  constraint pending_receipts_created_at_not_null NOT NULL created_at,
  constraint pending_receipts_id_not_null NOT NULL id,
  constraint pending_receipts_items_json_not_null NOT NULL items_json,
  constraint pending_receipts_status_not_null NOT NULL status,
  constraint pending_receipts_tenant_id_not_null NOT NULL tenant_id,
  constraint pending_receipts_updated_at_not_null NOT NULL updated_at,
  constraint pending_receipts_pkey PRIMARY KEY (id)
);
comment on table public.pending_receipts is 'Inbound goods awaiting verification. Links to purchase_request (origin) and supplier. Plan §11.07.';
comment on column public.pending_receipts.received_by is 'user_profiles.id of the warehouse worker who confirmed receipt. No FK (convention).';
comment on column public.pending_receipts.items_json is 'JSON array of item lines: [{sku, name, expected_qty, received_qty, condition}]. GIN-indexed.';

create table public.performance_reviews (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  personnel_id uuid not null,
  review_period text not null,
  reviewer_id uuid,
  score numeric(3,2),
  strengths text,
  areas_for_improvement text,
  goals text,
  review_date date default CURRENT_DATE not null,
  status text default 'draft'::text not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint performance_reviews_review_period_check CHECK (review_period = ANY (ARRAY['q1'::text, 'q2'::text, 'q3'::text, 'q4'::text, 'annual'::text])),
  constraint performance_reviews_score_check CHECK (score IS NULL OR score >= 0::numeric AND score <= 10::numeric),
  constraint performance_reviews_status_check CHECK (status = ANY (ARRAY['draft'::text, 'published'::text, 'acknowledged'::text])),
  constraint performance_reviews_created_at_not_null NOT NULL created_at,
  constraint performance_reviews_id_not_null NOT NULL id,
  constraint performance_reviews_personnel_id_not_null NOT NULL personnel_id,
  constraint performance_reviews_review_date_not_null NOT NULL review_date,
  constraint performance_reviews_review_period_not_null NOT NULL review_period,
  constraint performance_reviews_status_not_null NOT NULL status,
  constraint performance_reviews_tenant_id_not_null NOT NULL tenant_id,
  constraint performance_reviews_updated_at_not_null NOT NULL updated_at,
  constraint performance_reviews_pkey PRIMARY KEY (id)
);
comment on table public.performance_reviews is 'Quarterly or annual performance reviews. Score scale 0.00–10.00 (numeric(3,2)). Plan §10.08.';
comment on column public.performance_reviews.review_period is 'q1/q2/q3/q4 for quarterly reviews, annual for year-end.';
comment on column public.performance_reviews.reviewer_id is 'personnel.id of the reviewer (a staff member). SET NULL if they leave.';
comment on column public.performance_reviews.score is 'Numeric score 0.00–10.00 with 2 decimals. NULL until review is finalized.';

create table public.permissions (
