  constraint personnel_first_name_not_null NOT NULL first_name,
  constraint personnel_hire_date_not_null NOT NULL hire_date,
  constraint personnel_id_not_null NOT NULL id,
  constraint personnel_is_active_not_null NOT NULL is_active,
  constraint personnel_last_name_not_null NOT NULL last_name,
  constraint personnel_personnel_code_not_null NOT NULL personnel_code,
  constraint personnel_staff_category_not_null NOT NULL staff_category,
  constraint personnel_tenant_id_not_null NOT NULL tenant_id,
