  is_active boolean default true not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint pricing_configs_early_payment_bonus_pct_check CHECK (early_payment_bonus_pct >= 0::numeric AND early_payment_bonus_pct <= 100::numeric),
  constraint pricing_configs_late_penalty_per_day_check CHECK (late_penalty_per_day >= 0::numeric),
  constraint pricing_configs_registration_fee_check CHECK (registration_fee >= 0::numeric),
  constraint pricing_configs_second_apron_fee_check CHECK (second_apron_fee >= 0::numeric),
  constraint pricing_configs_academic_year_id_not_null NOT NULL academic_year_id,
  constraint pricing_configs_created_at_not_null NOT NULL created_at,
  constraint pricing_configs_early_payment_bonus_pct_not_null NOT NULL early_payment_bonus_pct,
  constraint pricing_configs_id_not_null NOT NULL id,
  constraint pricing_configs_is_active_not_null NOT NULL is_active,
  constraint pricing_configs_label_not_null NOT NULL label,
  constraint pricing_configs_late_penalty_per_day_not_null NOT NULL late_penalty_per_day,
  constraint pricing_configs_registration_fee_not_null NOT NULL registration_fee,
  constraint pricing_configs_second_apron_fee_not_null NOT NULL second_apron_fee,
  constraint pricing_configs_tenant_id_not_null NOT NULL tenant_id,
  constraint pricing_configs_updated_at_not_null NOT NULL updated_at,
  constraint pricing_configs_pkey PRIMARY KEY (id),
  constraint pricing_configs_tenant_id_academic_year_id_key UNIQUE (tenant_id, academic_year_id)
);
comment on table public.pricing_configs is 'Top-level pricing config per tenant per academic year. Single source of truth for all amounts (plan §07).';

create table public.promotion_cycle_classes (
  id uuid default gen_random_uuid() not null,
  tenant_id uuid not null,
  cycle_id uuid not null,
  class_id uuid not null,
  class_code text not null,
  class_name text not null,
  grade_code text not null,
  status text default 'pending'::text not null,
  students_awaiting integer default 0 not null,
  promoted_count integer default 0 not null,
  repeating_count integer default 0 not null,
  deferred_count integer default 0 not null,
  exception_note text,
  processed_by_name text,
  processed_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint promotion_cycle_classes_status_check CHECK (status = ANY (ARRAY['pending'::text, 'in_review'::text, 'processed'::text, 'exception'::text, 'skipped'::text])),
  constraint promotion_cycle_classes_class_code_not_null NOT NULL class_code,
  constraint promotion_cycle_classes_class_id_not_null NOT NULL class_id,
  constraint promotion_cycle_classes_class_name_not_null NOT NULL class_name,
  constraint promotion_cycle_classes_created_at_not_null NOT NULL created_at,
  constraint promotion_cycle_classes_cycle_id_not_null NOT NULL cycle_id,
  constraint promotion_cycle_classes_deferred_count_not_null NOT NULL deferred_count,
  constraint promotion_cycle_classes_grade_code_not_null NOT NULL grade_code,
  constraint promotion_cycle_classes_id_not_null NOT NULL id,
  constraint promotion_cycle_classes_promoted_count_not_null NOT NULL promoted_count,
  constraint promotion_cycle_classes_repeating_count_not_null NOT NULL repeating_count,
  constraint promotion_cycle_classes_status_not_null NOT NULL status,
  constraint promotion_cycle_classes_students_awaiting_not_null NOT NULL students_awaiting,
  constraint promotion_cycle_classes_tenant_id_not_null NOT NULL tenant_id,
  constraint promotion_cycle_classes_updated_at_not_null NOT NULL updated_at,
  constraint promotion_cycle_classes_pkey PRIMARY KEY (id),
  constraint promotion_cycle_classes_unique UNIQUE (cycle_id, class_id)
);
comment on table public.promotion_cycle_classes is 'T-403: the per-class review state inside a promotion cycle. One row per source-year class; processed rows carry the decision tallies and remain auditable/reopenable.';

create table public.promotion_cycles (
  id uuid default gen_random_uuid() not null,
  tenant_id uuid not null,
  source_academic_year text not null,
  target_academic_year text not null,
  status text default 'draft'::text not null,
  notes text,
  created_by_profile_id uuid,
  created_by_name text,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  completed_at timestamp with time zone,
  completed_by_name text,
  constraint promotion_cycles_status_check CHECK (status = ANY (ARRAY['draft'::text, 'in_review'::text, 'partially_processed'::text, 'completed'::text, 'cancelled'::text])),
  constraint promotion_cycles_created_at_not_null NOT NULL created_at,
  constraint promotion_cycles_id_not_null NOT NULL id,
  constraint promotion_cycles_source_academic_year_not_null NOT NULL source_academic_year,
  constraint promotion_cycles_status_not_null NOT NULL status,
  constraint promotion_cycles_target_academic_year_not_null NOT NULL target_academic_year,
  constraint promotion_cycles_tenant_id_not_null NOT NULL tenant_id,
  constraint promotion_cycles_updated_at_not_null NOT NULL updated_at,
  constraint promotion_cycles_pkey PRIMARY KEY (id),
  constraint promotion_cycles_active_source_key UNIQUE (tenant_id, source_academic_year)
);
comment on table public.promotion_cycles is 'T-403: one human-in-the-loop promotion cycle per (tenant, source academic year). The whole year is managed as ONE cycle; each class is reviewed and confirmed one at a time via promotion_cycle_classes.';

create table public.purchase_requests (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  request_number text not null,
  title text not null,
  description text,
  requester_id uuid not null,
  department_id uuid,
  status text default 'draft'::text not null,
  priority text default 'medium'::text not null,
  expected_delivery_date date,
  total_amount numeric(12,2) default 0 not null,
  lines jsonb default '[]'::jsonb not null,
  approved_by uuid,
  approved_at timestamp with time zone,
  rejected_reason text,
  supplier_id uuid,
  ordered_at timestamp with time zone,
  received_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  requested_by_name text,
  approved_by_name text,
  constraint purchase_requests_priority_check CHECK (priority = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'urgent'::text])),
  constraint purchase_requests_status_check CHECK (status = ANY (ARRAY['draft'::text, 'submitted'::text, 'approved'::text, 'rejected'::text, 'ordered'::text, 'received'::text, 'cancelled'::text])),
  constraint purchase_requests_total_amount_check CHECK (total_amount >= 0::numeric),
  constraint purchase_requests_created_at_not_null NOT NULL created_at,
  constraint purchase_requests_id_not_null NOT NULL id,
  constraint purchase_requests_lines_not_null NOT NULL lines,
  constraint purchase_requests_priority_not_null NOT NULL priority,
  constraint purchase_requests_request_number_not_null NOT NULL request_number,
  constraint purchase_requests_requester_id_not_null NOT NULL requester_id,
  constraint purchase_requests_status_not_null NOT NULL status,
  constraint purchase_requests_tenant_id_not_null NOT NULL tenant_id,
  constraint purchase_requests_title_not_null NOT NULL title,
  constraint purchase_requests_total_amount_not_null NOT NULL total_amount,
  constraint purchase_requests_updated_at_not_null NOT NULL updated_at,
  constraint purchase_requests_pkey PRIMARY KEY (id),
  constraint purchase_requests_tenant_id_request_number_key UNIQUE (tenant_id, request_number)
);
comment on table public.purchase_requests is 'Two-tier procurement workflow mirroring expense_tickets (0008). State machine enforced at DB layer. Plan §11.03.';
comment on column public.purchase_requests.requester_id is 'user_profiles.id of the buyer/staff submitting the request. No FK (convention).';
comment on column public.purchase_requests.total_amount is 'Sum of line totals. numeric(12,2) in DZD. App-layer recomputes on save.';
comment on column public.purchase_requests.lines is 'JSON array of line items: [{description, quantity, unit_price, total}]. GIN-indexed.';
comment on column public.purchase_requests.approved_by is 'user_profiles.id of the approver (FinancialOfficer/Manager). No FK (convention).';
comment on column public.purchase_requests.requested_by_name is 'Display name of the requester FROZEN at write time (0074 tasks.created_by_name precedent — requester_id has no FK and profiles can be renamed).';
comment on column public.purchase_requests.approved_by_name is 'Display name of the approver FROZEN at decision time (same precedent).';

create table public.re_enrollments (
  id uuid default gen_random_uuid() not null,
  tenant_id uuid not null,
  student_id uuid not null,
  source_academic_year_id uuid not null,
  target_academic_year_id uuid not null,
  source_grade_level_code text,
  source_class_id uuid,
  source_class_name text,
  final_decision text,
  final_average numeric(4,2),
  expected_grade_level_code text,
  status text default 'waiting'::text not null,
  target_class_id uuid,
  decided_at timestamp with time zone,
  decided_by_profile_id uuid,
  decided_by_name text,
  re_enrolled_at timestamp with time zone,
  installments_written integer,
  notes text,
  frozen_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint re_enrollments_final_decision_check CHECK (final_decision = ANY (ARRAY['promoted'::text, 'repeated'::text, 'graduated'::text, 'transferred'::text])),
  constraint re_enrollments_status_check CHECK (status = ANY (ARRAY['waiting'::text, 'started'::text, 're_enrolled'::text, 'not_continuing'::text])),
  constraint re_enrollments_created_at_not_null NOT NULL created_at,
  constraint re_enrollments_id_not_null NOT NULL id,
  constraint re_enrollments_source_academic_year_id_not_null NOT NULL source_academic_year_id,
  constraint re_enrollments_status_not_null NOT NULL status,
  constraint re_enrollments_student_id_not_null NOT NULL student_id,
  constraint re_enrollments_target_academic_year_id_not_null NOT NULL target_academic_year_id,
  constraint re_enrollments_tenant_id_not_null NOT NULL tenant_id,
  constraint re_enrollments_updated_at_not_null NOT NULL updated_at,
  constraint re_enrollments_pkey PRIMARY KEY (id),
  constraint re_enrollments_student_target_key UNIQUE (tenant_id, student_id, target_academic_year_id)
);
comment on table public.re_enrollments is 'T-437 (ADR-031): the year-transition state for CONTINUING students — one row per (tenant, student, target academic year). Carries the source-year finalized snapshot (from student_academic_histories at generation time), the expected next level, the decision state (waiting/started/re_enrolled/not_continuing), and the freeze. NEVER a duplicate person: the flow operates on the existing students row (INV-21a).';

create table public.releve_entries (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  personnel_id uuid not null,
  activity_type text not null,
  class_id uuid,
  class_subject_id uuid,
  description text,
  clock_in_at timestamp with time zone not null,
  clock_out_at timestamp with time zone,
  duration_minutes integer generated always as (
CASE
    WHEN (clock_out_at IS NOT NULL) THEN ((EXTRACT(epoch FROM (clock_out_at - clock_in_at)))::integer / 60)
    ELSE NULL::integer
END) stored,
  recorded_by uuid not null,
  recorded_at timestamp with time zone default now() not null,
  created_at timestamp with time zone default now() not null,
  entry_source text default 'manual'::text not null,
  auto_kind text,
  constraint releve_entries_activity_type_check CHECK (activity_type = ANY (ARRAY['course'::text, 'meeting'::text, 'surveillance'::text, 'supervision'::text, 'correction'::text, 'task'::text, 'delivery'::text, 'warehouse'::text, 'admin'::text, 'other'::text])),
  constraint releve_entries_auto_kind_check CHECK (auto_kind IS NULL OR (auto_kind = ANY (ARRAY['grade_entry'::text, 'homework_push'::text, 'roll_call'::text]))),
  constraint releve_entries_entry_source_check CHECK (entry_source = ANY (ARRAY['manual'::text, 'auto'::text])),
  constraint releve_entries_source_kind_coupling_check CHECK (entry_source = 'manual'::text AND auto_kind IS NULL OR entry_source = 'auto'::text AND auto_kind IS NOT NULL),
  constraint releve_entries_activity_type_not_null NOT NULL activity_type,
  constraint releve_entries_clock_in_at_not_null NOT NULL clock_in_at,
  constraint releve_entries_created_at_not_null NOT NULL created_at,
  constraint releve_entries_entry_source_not_null NOT NULL entry_source,
  constraint releve_entries_id_not_null NOT NULL id,
  constraint releve_entries_personnel_id_not_null NOT NULL personnel_id,
  constraint releve_entries_recorded_at_not_null NOT NULL recorded_at,
  constraint releve_entries_recorded_by_not_null NOT NULL recorded_by,
  constraint releve_entries_tenant_id_not_null NOT NULL tenant_id,
  constraint releve_entries_pkey PRIMARY KEY (id)
);
comment on table public.releve_entries is 'Append-only teacher/staff activity ledger. Plan §09.05: teachers CANNOT edit their own entries (recorded_by must differ from personnel.user_id).';
comment on column public.releve_entries.entry_source is 'ADR-034 (T-482/0141): manual = the §09.05 admin-recorded path (staff quartet + the self-entry trigger); auto = the §09.06 system side effect written ONLY by record_auto_releve_entry.';
comment on column public.releve_entries.auto_kind is 'ADR-034 (T-482/0141): the classroom operation that generated the auto row (grade_entry / homework_push / roll_call). CHECK-coupled: non-null only when entry_source = ''auto''.';

create table public.role_assignments (
  id uuid default gen_uuid() not null,
  user_profile_id uuid not null,
  tenant_id uuid not null,
  role_id uuid not null,
  assigned_by uuid,
  assigned_at timestamp with time zone default now() not null,
  revoked_at timestamp with time zone,
  constraint role_assignments_assigned_at_not_null NOT NULL assigned_at,
  constraint role_assignments_id_not_null NOT NULL id,
  constraint role_assignments_role_id_not_null NOT NULL role_id,
  constraint role_assignments_tenant_id_not_null NOT NULL tenant_id,
  constraint role_assignments_user_profile_id_not_null NOT NULL user_profile_id,
  constraint role_assignments_pkey PRIMARY KEY (id)
);
comment on table public.role_assignments is 'Effective role per user within a tenant. A user may hold different roles across tenants. RLS uses this to resolve permissions.';

create table public.role_permissions (
  role_id uuid not null,
  permission_id uuid not null,
  constraint role_permissions_permission_id_not_null NOT NULL permission_id,
  constraint role_permissions_role_id_not_null NOT NULL role_id,
  constraint role_permissions_pkey PRIMARY KEY (role_id, permission_id)
);

create table public.roles (
  id uuid default gen_uuid() not null,
  code text not null,
  label_fr text not null,
  label_ar text,
  label_en text,
  description text,
  staff_category text,
  is_staff_role boolean default false not null,
  is_web_role boolean default false not null,
  sort_order integer default 100 not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint roles_staff_category_check CHECK (staff_category = ANY (ARRAY['administration'::text, 'teaching'::text, 'support'::text, 'medical'::text, NULL::text])),
  constraint roles_code_not_null NOT NULL code,
  constraint roles_created_at_not_null NOT NULL created_at,
  constraint roles_id_not_null NOT NULL id,
  constraint roles_is_staff_role_not_null NOT NULL is_staff_role,
  constraint roles_is_web_role_not_null NOT NULL is_web_role,
  constraint roles_label_fr_not_null NOT NULL label_fr,
  constraint roles_sort_order_not_null NOT NULL sort_order,
  constraint roles_updated_at_not_null NOT NULL updated_at,
  constraint roles_pkey PRIMARY KEY (id),
  constraint roles_code_key UNIQUE (code)
);
comment on column public.roles.is_staff_role is 'true for SuperAdmin, FinancialOfficer, Teacher, SupportStaff, Manager, Buyer, Driver, WarehouseWorker, Worker (desktop + mobile access).';
comment on column public.roles.is_web_role is 'true for Parent, Student (web portal access only).';

create table public.rooms (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  code text not null,
  name text not null,
  room_type text default 'classroom'::text not null,
  capacity integer,
  building text,
  floor_label text,
  is_active boolean default true not null,
  notes text,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint rooms_capacity_check CHECK (capacity IS NULL OR capacity > 0),
  constraint rooms_room_type_check CHECK (room_type = ANY (ARRAY['classroom'::text, 'science_lab'::text, 'computer_lab'::text, 'language_lab'::text, 'sports'::text, 'library'::text, 'workshop'::text, 'other'::text])),
  constraint rooms_code_not_null NOT NULL code,
  constraint rooms_created_at_not_null NOT NULL created_at,
  constraint rooms_id_not_null NOT NULL id,
  constraint rooms_is_active_not_null NOT NULL is_active,
  constraint rooms_name_not_null NOT NULL name,
  constraint rooms_room_type_not_null NOT NULL room_type,
  constraint rooms_tenant_id_not_null NOT NULL tenant_id,
  constraint rooms_updated_at_not_null NOT NULL updated_at,
  constraint rooms_pkey PRIMARY KEY (id),
  constraint rooms_tenant_id_code_key UNIQUE (tenant_id, code)
);

create table public.salary_adjustments (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  personnel_id uuid not null,
  type text not null,
  amount_before numeric(12,2) not null,
  amount_after numeric(12,2) not null,
  delta numeric(12,2) not null,
  reason text not null,
  effective_date date default CURRENT_DATE not null,
  approved_by uuid,
  approved_by_name text,
  created_at timestamp with time zone default now() not null,
  constraint salary_adjustments_amount_after_check CHECK (amount_after >= 0::numeric),
  constraint salary_adjustments_amount_before_check CHECK (amount_before >= 0::numeric),
  constraint salary_adjustments_check CHECK ((type = ANY (ARRAY['raise'::text, 'cut'::text])) AND amount_after = (amount_before + delta) OR (type = ANY (ARRAY['bonus'::text, 'deduction'::text])) AND amount_after = amount_before),
  constraint salary_adjustments_reason_check CHECK (length(TRIM(BOTH FROM reason)) >= 5),
  constraint salary_adjustments_type_check CHECK (type = ANY (ARRAY['raise'::text, 'cut'::text, 'bonus'::text, 'deduction'::text])),
  constraint salary_adjustments_amount_after_not_null NOT NULL amount_after,
  constraint salary_adjustments_amount_before_not_null NOT NULL amount_before,
  constraint salary_adjustments_created_at_not_null NOT NULL created_at,
  constraint salary_adjustments_delta_not_null NOT NULL delta,
  constraint salary_adjustments_effective_date_not_null NOT NULL effective_date,
  constraint salary_adjustments_id_not_null NOT NULL id,
  constraint salary_adjustments_personnel_id_not_null NOT NULL personnel_id,
  constraint salary_adjustments_reason_not_null NOT NULL reason,
  constraint salary_adjustments_tenant_id_not_null NOT NULL tenant_id,
  constraint salary_adjustments_type_not_null NOT NULL type,
  constraint salary_adjustments_pkey PRIMARY KEY (id)
);

create table public.salary_payments (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  personnel_id uuid not null,
  period text not null,
  base_salary numeric(12,2) not null,
  bonuses_total numeric(12,2) default 0 not null,
  deductions_total numeric(12,2) default 0 not null,
  net_paid numeric(12,2) not null,
  status text default 'unpaid'::text not null,
  payment_date date,
  method text not null,
  reference_number text,
  notes text,
  paid_by uuid,
  paid_by_name text,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint salary_payments_base_salary_check CHECK (base_salary >= 0::numeric),
  constraint salary_payments_bonuses_total_check CHECK (bonuses_total >= 0::numeric),
  constraint salary_payments_deductions_total_check CHECK (deductions_total >= 0::numeric),
  constraint salary_payments_method_check CHECK (method = ANY (ARRAY['cash'::text, 'bank_transfer'::text, 'check'::text, 'mobile_money'::text])),
  constraint salary_payments_net_paid_check CHECK (net_paid >= 0::numeric),
  constraint salary_payments_period_check CHECK (period ~ '^\d{4}-\d{2}$'::text),
  constraint salary_payments_status_check CHECK (status = ANY (ARRAY['paid'::text, 'unpaid'::text, 'pending'::text])),
  constraint salary_payments_base_salary_not_null NOT NULL base_salary,
  constraint salary_payments_bonuses_total_not_null NOT NULL bonuses_total,
  constraint salary_payments_created_at_not_null NOT NULL created_at,
  constraint salary_payments_deductions_total_not_null NOT NULL deductions_total,
  constraint salary_payments_id_not_null NOT NULL id,
  constraint salary_payments_method_not_null NOT NULL method,
  constraint salary_payments_net_paid_not_null NOT NULL net_paid,
  constraint salary_payments_period_not_null NOT NULL period,
  constraint salary_payments_personnel_id_not_null NOT NULL personnel_id,
  constraint salary_payments_status_not_null NOT NULL status,
  constraint salary_payments_tenant_id_not_null NOT NULL tenant_id,
  constraint salary_payments_updated_at_not_null NOT NULL updated_at,
  constraint salary_payments_pkey PRIMARY KEY (id),
  constraint salary_payments_tenant_id_personnel_id_period_key UNIQUE (tenant_id, personnel_id, period)
);

create table public.schedules (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  personnel_id uuid not null,
  shift_id uuid,
  date date not null,
  start_time time without time zone,
  end_time time without time zone,
  note text,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint schedules_created_at_not_null NOT NULL created_at,
  constraint schedules_date_not_null NOT NULL date,
  constraint schedules_id_not_null NOT NULL id,
  constraint schedules_personnel_id_not_null NOT NULL personnel_id,
  constraint schedules_tenant_id_not_null NOT NULL tenant_id,
  constraint schedules_updated_at_not_null NOT NULL updated_at,
  constraint schedules_pkey PRIMARY KEY (id),
  constraint schedules_tenant_id_personnel_id_date_key UNIQUE (tenant_id, personnel_id, date)
);
comment on table public.schedules is 'Daily shift assignment per personnel. One row per personnel per date (uniqueness enforced). Plan §10.04.';
comment on column public.schedules.start_time is 'Optional override of shift.start_time for this specific day.';
comment on column public.schedules.end_time is 'Optional override of shift.end_time for this specific day.';

create table public.service_enrollments (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
