  tranche_1_amount numeric(10,2) default 0 not null,
  tranche_2_amount numeric(10,2) default 0 not null,
  tranche_3_amount numeric(10,2) default 0 not null,
  tranche_1_due_date date,
  tranche_2_due_date date,
  tranche_3_due_date date,
  is_active boolean default true not null,
  enrolled_at timestamp with time zone default now() not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint service_enrollments_annual_amount_check CHECK (annual_amount >= 0::numeric),
  constraint service_enrollments_service_kind_check CHECK (service_kind = ANY (ARRAY['tuition'::text, 'transport'::text, 'canteen'::text, 'club'::text, 'speech_therapy'::text, 'psychology'::text, 'psychotherapy'::text, 'second_apron'::text, 'rattrapage'::text, 'other'::text])),
  constraint service_enrollments_academic_year_id_not_null NOT NULL academic_year_id,
  constraint service_enrollments_annual_amount_not_null NOT NULL annual_amount,
  constraint service_enrollments_created_at_not_null NOT NULL created_at,
  constraint service_enrollments_enrolled_at_not_null NOT NULL enrolled_at,
  constraint service_enrollments_id_not_null NOT NULL id,
  constraint service_enrollments_is_active_not_null NOT NULL is_active,
  constraint service_enrollments_service_kind_not_null NOT NULL service_kind,
  constraint service_enrollments_student_id_not_null NOT NULL student_id,
  constraint service_enrollments_tenant_id_not_null NOT NULL tenant_id,
  constraint service_enrollments_tranche_1_amount_not_null NOT NULL tranche_1_amount,
  constraint service_enrollments_tranche_2_amount_not_null NOT NULL tranche_2_amount,
  constraint service_enrollments_tranche_3_amount_not_null NOT NULL tranche_3_amount,
  constraint service_enrollments_updated_at_not_null NOT NULL updated_at,
  constraint service_enrollments_pkey PRIMARY KEY (id)
);

create table public.sessions (
  id uuid default gen_uuid() not null,
  user_profile_id uuid not null,
  tenant_id uuid,
  supabase_session_id text,
  refresh_token_jti text,
  ip_address inet,
  user_agent text,
  device_name text,
  started_at timestamp with time zone default now() not null,
  last_activity_at timestamp with time zone default now() not null,
  expires_at timestamp with time zone not null,
  revoked_at timestamp with time zone,
  revoked_reason text,
  constraint sessions_expires_at_not_null NOT NULL expires_at,
  constraint sessions_id_not_null NOT NULL id,
  constraint sessions_last_activity_at_not_null NOT NULL last_activity_at,
  constraint sessions_started_at_not_null NOT NULL started_at,
  constraint sessions_user_profile_id_not_null NOT NULL user_profile_id,
  constraint sessions_pkey PRIMARY KEY (id)
);
comment on table public.sessions is 'Active session telemetry. Used for audit, force-revocation on password change (plan §12.04), and concurrent-session limits.';

create table public.shifts (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  code text not null,
  name text not null,
  start_time time without time zone not null,
  end_time time without time zone not null,
  grace_period_minutes integer default 0 not null,
  color_hex text,
  is_active boolean default true not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint shifts_check CHECK (end_time > start_time),
  constraint shifts_color_hex_check CHECK (color_hex ~ '^#[0-9A-Fa-f]{6}$'::text),
  constraint shifts_grace_period_minutes_check CHECK (grace_period_minutes >= 0),
  constraint shifts_code_not_null NOT NULL code,
  constraint shifts_created_at_not_null NOT NULL created_at,
  constraint shifts_end_time_not_null NOT NULL end_time,
  constraint shifts_grace_period_minutes_not_null NOT NULL grace_period_minutes,
  constraint shifts_id_not_null NOT NULL id,
  constraint shifts_is_active_not_null NOT NULL is_active,
  constraint shifts_name_not_null NOT NULL name,
  constraint shifts_start_time_not_null NOT NULL start_time,
  constraint shifts_tenant_id_not_null NOT NULL tenant_id,
  constraint shifts_updated_at_not_null NOT NULL updated_at,
  constraint shifts_pkey PRIMARY KEY (id),
  constraint shifts_tenant_id_code_key UNIQUE (tenant_id, code)
);
comment on table public.shifts is 'Reusable work-time templates with grace period for late clock-ins. Plan §10.03.';
comment on column public.shifts.start_time is 'Local-time start of shift (no timezone — interpreted in tenant.timezone).';
comment on column public.shifts.end_time is 'Local-time end of shift. Must be later than start_time.';
comment on column public.shifts.grace_period_minutes is 'Tolerance window (minutes) before a clock-in is flagged late.';

create table public.staff_absences (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  personnel_id uuid not null,
  date date not null,
  duration_hours numeric(4,2) not null,
  is_excused boolean default false not null,
