  requested_by uuid,
  worker_explanation text,
  worker_submitted_at timestamp with time zone,
  document_ref text,
  decision_note text,
  decided_at timestamp with time zone,
  decided_by uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint staff_absences_duration_hours_check CHECK (duration_hours > 0::numeric),
  constraint staff_absences_justification_status_check CHECK (justification_status = ANY (ARRAY['none'::text, 'requested'::text, 'submitted'::text, 'accepted'::text, 'rejected'::text])),
  constraint staff_absences_created_at_not_null NOT NULL created_at,
  constraint staff_absences_date_not_null NOT NULL date,
  constraint staff_absences_duration_hours_not_null NOT NULL duration_hours,
  constraint staff_absences_id_not_null NOT NULL id,
  constraint staff_absences_is_excused_not_null NOT NULL is_excused,
  constraint staff_absences_justification_status_not_null NOT NULL justification_status,
  constraint staff_absences_personnel_id_not_null NOT NULL personnel_id,
  constraint staff_absences_tenant_id_not_null NOT NULL tenant_id,
  constraint staff_absences_updated_at_not_null NOT NULL updated_at,
  constraint staff_absences_pkey PRIMARY KEY (id)
);

create table public.student_academic_histories (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  student_id uuid not null,
  academic_year text not null,
  cycle text not null,
  grade_code text not null,
  grade_year integer not null,
  class_id uuid,
  class_name text,
  gpa numeric(4,2) not null,
  rank integer,
  decision text not null,
  narrative text,
  recorded_at timestamp with time zone default now() not null,
  filiere_code text,
  specialite_code text,
  constraint student_academic_histories_cycle_check CHECK (cycle = ANY (ARRAY['prescolaire'::text, 'primaire'::text, 'cem'::text, 'lycee'::text])),
  constraint student_academic_histories_decision_check CHECK (decision = ANY (ARRAY['promoted'::text, 'repeated'::text, 'graduated'::text, 'transferred'::text])),
  constraint student_academic_histories_gpa_check CHECK (gpa >= 0::numeric AND gpa <= 20::numeric),
  constraint student_academic_histories_academic_year_not_null NOT NULL academic_year,
  constraint student_academic_histories_cycle_not_null NOT NULL cycle,
  constraint student_academic_histories_decision_not_null NOT NULL decision,
  constraint student_academic_histories_gpa_not_null NOT NULL gpa,
  constraint student_academic_histories_grade_code_not_null NOT NULL grade_code,
  constraint student_academic_histories_grade_year_not_null NOT NULL grade_year,
  constraint student_academic_histories_id_not_null NOT NULL id,
  constraint student_academic_histories_recorded_at_not_null NOT NULL recorded_at,
  constraint student_academic_histories_student_id_not_null NOT NULL student_id,
  constraint student_academic_histories_tenant_id_not_null NOT NULL tenant_id,
  constraint student_academic_histories_pkey PRIMARY KEY (id),
  constraint uq_academic_history_student_year UNIQUE (student_id, academic_year)
);
comment on column public.student_academic_histories.filiere_code is 'T-401: the classification in force during the archived year (stamped by execute_batch_promotion).';

create table public.student_documents (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  student_id uuid not null,
  kind text not null,
  file_name text not null,
  storage_path text not null,
  mime_type text,
  size_bytes bigint,
  uploaded_by uuid,
  uploaded_at timestamp with time zone default now() not null,
