  constraint student_documents_kind_check CHECK (kind = ANY (ARRAY['birth_certificate'::text, 'medical_certificate'::text, 'contract'::text, 'justification_letter'::text, 'id_photo'::text, 'report_card'::text, 'other'::text])),
  constraint student_documents_file_name_not_null NOT NULL file_name,
  constraint student_documents_id_not_null NOT NULL id,
  constraint student_documents_kind_not_null NOT NULL kind,
  constraint student_documents_storage_path_not_null NOT NULL storage_path,
  constraint student_documents_student_id_not_null NOT NULL student_id,
  constraint student_documents_tenant_id_not_null NOT NULL tenant_id,
  constraint student_documents_uploaded_at_not_null NOT NULL uploaded_at,
  constraint student_documents_pkey PRIMARY KEY (id)
);

create table public.student_narratives (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  student_id uuid not null,
  academic_year text not null,
  narrative text not null,
  approved_by uuid,
  approved_by_name text,
  approved_at timestamp with time zone default now() not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint student_narratives_academic_year_not_null NOT NULL academic_year,
  constraint student_narratives_approved_at_not_null NOT NULL approved_at,
  constraint student_narratives_created_at_not_null NOT NULL created_at,
  constraint student_narratives_id_not_null NOT NULL id,
  constraint student_narratives_narrative_not_null NOT NULL narrative,
  constraint student_narratives_student_id_not_null NOT NULL student_id,
  constraint student_narratives_tenant_id_not_null NOT NULL tenant_id,
  constraint student_narratives_updated_at_not_null NOT NULL updated_at,
  constraint student_narratives_pkey PRIMARY KEY (id),
  constraint uq_student_narrative UNIQUE (tenant_id, student_id, academic_year)
);
comment on table public.student_narratives is 'GRADE-103 (0148): the year-keyed report-card narrative store — one per (tenant, student, academic_year), upserted on re-approval. Dedicated table (NOT student_academic_histories): the promotion record''s NOT NULL decision fields would force a fabricated mid-year decision.';

create table public.students (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  parent_id uuid not null,
  student_code text not null,
  first_name text not null,
  middle_name text,
  last_name text not null,
  date_of_birth date not null,
  gender text,
  grade_level_id uuid,
  class_id uuid,
  enrollment_date date default CURRENT_DATE not null,
  enrollment_status text default 'active'::text not null,
  medical_notes text,
  is_active boolean default true not null,
  auth_user_id uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  deleted_at timestamp with time zone,
  display_name text,
  grade_level_code text,
  transport_tier text,
  payment_plan text default 'tranches'::text not null,
  documents_json jsonb,
  filiere_code text,
  specialite_code text,
  origin_type text,
  previous_school_name text,
  previous_school_level text,
  previous_academic_year text,
  origin_notes text,
  constraint students_enrollment_status_check CHECK (enrollment_status = ANY (ARRAY['inquiry'::text, 'quoted'::text, 'enrolled'::text, 'active'::text, 'suspended'::text, 'transferred'::text, 'withdrawn'::text, 'graduated'::text])),
  constraint students_gender_check CHECK (gender = ANY (ARRAY['male'::text, 'female'::text, 'other'::text])),
  constraint students_origin_type_check CHECK (origin_type = ANY (ARRAY['new_admission'::text, 'transfer'::text, 'continuation'::text, 'other'::text])),
  constraint students_payment_plan_check CHECK (payment_plan = ANY (ARRAY['tranches'::text, 'full_annual'::text])),
  constraint students_created_at_not_null NOT NULL created_at,
  constraint students_date_of_birth_not_null NOT NULL date_of_birth,
  constraint students_enrollment_date_not_null NOT NULL enrollment_date,
  constraint students_enrollment_status_not_null NOT NULL enrollment_status,
  constraint students_first_name_not_null NOT NULL first_name,
  constraint students_id_not_null NOT NULL id,
  constraint students_is_active_not_null NOT NULL is_active,
  constraint students_last_name_not_null NOT NULL last_name,
  constraint students_parent_id_not_null NOT NULL parent_id,
  constraint students_payment_plan_not_null NOT NULL payment_plan,
  constraint students_student_code_not_null NOT NULL student_code,
  constraint students_tenant_id_not_null NOT NULL tenant_id,
  constraint students_updated_at_not_null NOT NULL updated_at,
  constraint students_pkey PRIMARY KEY (id),
  constraint students_tenant_id_student_code_key UNIQUE (tenant_id, student_code)
);
comment on table public.students is 'Child enrolled in academic programs. parent_id is NOT NULL FK (parent-first rule, plan §04.01). Soft-deleted via deleted_at.';
comment on column public.students.display_name is 'Complete display name as imported (e.g. ''BENALI Sara''). When non-null, UI shows this verbatim.';
comment on column public.students.documents_json is 'Descriptive attachment records for the student profile Documents tab (vault §04.06): medical certificates, justification letters, contracts. Array of {id, fileName, category(medical|justification|contract|other), note, uploadedBy, uploadedAt}. NULL = no documents.';
comment on column public.students.filiere_code is 'T-401: the student''s current academic stream (filieres.code). NULL = untagged/general.';
comment on column public.students.specialite_code is 'T-401: the student''s current spécialité. NULL = none.';
comment on column public.students.origin_type is 'T-437 (INV-24a): where the student came from BEFORE joining the school — new_admission | transfer | continuation (came up through El-Imtiyaz itself) | other. NULL = unknown (the pre-0128 corpus). Distinct from student_academic_histories (the AT-school history) by construction.';

create table public.subject_configurations (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  subject_id uuid not null,
  academic_year_id uuid not null,
  academic_level_id uuid not null,
  direction text default 'general'::text not null,
  coefficient numeric(4,2) default 1.00 not null,
  subject_code text,
  passing_grade numeric(4,2) default 10.00 not null,
  is_extracurricular boolean default false not null,
  grading_recipe jsonb default '{"cc": 0, "examen": 2, "devoir1": 1, "devoir2": 1}'::jsonb not null,
  weekly_hours numeric(4,1),
  is_active boolean default true not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint subject_configurations_coefficient_check CHECK (coefficient > 0::numeric),
  constraint subject_configurations_passing_grade_check CHECK (passing_grade >= 0::numeric AND passing_grade <= 20::numeric),
  constraint subject_configurations_recipe_shape CHECK (jsonb_typeof(grading_recipe) = 'object'::text AND grading_recipe ? 'devoir1'::text AND grading_recipe ? 'devoir2'::text AND grading_recipe ? 'examen'::text AND grading_recipe ? 'cc'::text AND (grading_recipe ->> 'devoir1'::text) IS NOT NULL AND (grading_recipe ->> 'devoir2'::text) IS NOT NULL AND (grading_recipe ->> 'examen'::text) IS NOT NULL AND (grading_recipe ->> 'cc'::text) IS NOT NULL AND ((grading_recipe ->> 'devoir1'::text)::numeric) >= 0::numeric AND ((grading_recipe ->> 'devoir2'::text)::numeric) >= 0::numeric AND ((grading_recipe ->> 'examen'::text)::numeric) >= 0::numeric AND ((grading_recipe ->> 'cc'::text)::numeric) >= 0::numeric AND (((grading_recipe ->> 'devoir1'::text)::numeric) + ((grading_recipe ->> 'devoir2'::text)::numeric) + ((grading_recipe ->> 'examen'::text)::numeric) + ((grading_recipe ->> 'cc'::text)::numeric)) > 0::numeric),
  constraint subject_configurations_weekly_hours_check CHECK (weekly_hours IS NULL OR weekly_hours > 0::numeric),
  constraint subject_configurations_academic_level_id_not_null NOT NULL academic_level_id,
  constraint subject_configurations_academic_year_id_not_null NOT NULL academic_year_id,
  constraint subject_configurations_coefficient_not_null NOT NULL coefficient,
  constraint subject_configurations_created_at_not_null NOT NULL created_at,
  constraint subject_configurations_direction_not_null NOT NULL direction,
  constraint subject_configurations_grading_recipe_not_null NOT NULL grading_recipe,
  constraint subject_configurations_id_not_null NOT NULL id,
  constraint subject_configurations_is_active_not_null NOT NULL is_active,
  constraint subject_configurations_is_extracurricular_not_null NOT NULL is_extracurricular,
  constraint subject_configurations_passing_grade_not_null NOT NULL passing_grade,
  constraint subject_configurations_subject_id_not_null NOT NULL subject_id,
  constraint subject_configurations_tenant_id_not_null NOT NULL tenant_id,
  constraint subject_configurations_updated_at_not_null NOT NULL updated_at,
  constraint subject_configurations_pkey PRIMARY KEY (id),
  constraint subject_configurations_tenant_id_subject_id_academic_year_i_key UNIQUE (tenant_id, subject_id, academic_year_id, academic_level_id, direction)
);

create table public.subjects (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  code text not null,
  name_fr text not null,
  name_ar text,
  name_en text,
  domain text default 'scolarite'::text not null,
  default_coefficient numeric(4,2) default 1 not null,
  is_active boolean default true not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  cycle text,
  passing_grade numeric(4,2) default 10.00,
  is_extracurricular boolean default false not null,
  constraint subjects_cycle_check CHECK (cycle IS NULL OR (cycle = ANY (ARRAY['prescolaire'::text, 'primaire'::text, 'cem'::text, 'lycee'::text]))),
  constraint subjects_default_coefficient_check CHECK (default_coefficient > 0::numeric),
  constraint subjects_domain_check CHECK (domain = ANY (ARRAY['scolarite'::text, 'club'::text, 'therapy'::text, 'auxiliary'::text])),
  constraint subjects_passing_grade_check CHECK (passing_grade >= 0::numeric AND passing_grade <= 20::numeric),
  constraint subjects_code_not_null NOT NULL code,
  constraint subjects_created_at_not_null NOT NULL created_at,
  constraint subjects_default_coefficient_not_null NOT NULL default_coefficient,
  constraint subjects_domain_not_null NOT NULL domain,
  constraint subjects_id_not_null NOT NULL id,
  constraint subjects_is_active_not_null NOT NULL is_active,
  constraint subjects_is_extracurricular_not_null NOT NULL is_extracurricular,
  constraint subjects_name_fr_not_null NOT NULL name_fr,
  constraint subjects_tenant_id_not_null NOT NULL tenant_id,
  constraint subjects_updated_at_not_null NOT NULL updated_at,
  constraint subjects_pkey PRIMARY KEY (id),
  constraint subjects_tenant_id_code_key UNIQUE (tenant_id, code)
);

create table public.suppliers (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  code text not null,
  name text not null,
  contact_name text,
  phone text,
  email text,
  address text,
  tax_id text,
  payment_terms text,
  rating numeric(3,1),
  is_active boolean default true not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  deleted_at timestamp with time zone,
  category text,
  constraint suppliers_rating_range_check CHECK (rating IS NULL OR rating >= 0::numeric AND rating <= 5::numeric),
  constraint suppliers_code_not_null NOT NULL code,
  constraint suppliers_created_at_not_null NOT NULL created_at,
  constraint suppliers_id_not_null NOT NULL id,
  constraint suppliers_is_active_not_null NOT NULL is_active,
  constraint suppliers_name_not_null NOT NULL name,
  constraint suppliers_tenant_id_not_null NOT NULL tenant_id,
  constraint suppliers_updated_at_not_null NOT NULL updated_at,
  constraint suppliers_pkey PRIMARY KEY (id),
  constraint suppliers_tenant_id_code_key UNIQUE (tenant_id, code)
);
comment on table public.suppliers is 'Master vendor records. Soft-deleted via deleted_at. Plan §11.02.';
comment on column public.suppliers.code is 'Short stable code unique per tenant (e.g. SUP-0001).';
comment on column public.suppliers.payment_terms is 'Free-text payment terms (Net 30, COD, etc.).';
comment on column public.suppliers.rating is 'Optional 1-5 quality rating (smallint). NULL = unrated.';
comment on column public.suppliers.category is 'Free-text supplier category (Fournitures / Carburant / Manuels / Mobilier …). Added by 0073 (T-179) for the desktop domain contract.';

create table public.sync_queue (
  id text not null,
  tenant_id uuid not null,
  entity text not null,
  operation text not null,
  actor_id text,
  payload jsonb not null,
  source_file text,
  import_run_id text,
  status text default 'pending'::text not null,
  attempts integer default 0 not null,
  last_error text,
  queued_at timestamp with time zone default now() not null,
  last_attempt_at timestamp with time zone,
  pushed_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  constraint sync_queue_operation_check CHECK (operation = ANY (ARRAY['insert'::text, 'update'::text, 'delete'::text])),
  constraint sync_queue_status_check CHECK (status = ANY (ARRAY['pending'::text, 'synced'::text, 'failed'::text, 'skipped_mock'::text])),
  constraint sync_queue_attempts_not_null NOT NULL attempts,
  constraint sync_queue_created_at_not_null NOT NULL created_at,
  constraint sync_queue_entity_not_null NOT NULL entity,
  constraint sync_queue_id_not_null NOT NULL id,
  constraint sync_queue_operation_not_null NOT NULL operation,
  constraint sync_queue_payload_not_null NOT NULL payload,
  constraint sync_queue_queued_at_not_null NOT NULL queued_at,
  constraint sync_queue_status_not_null NOT NULL status,
  constraint sync_queue_tenant_id_not_null NOT NULL tenant_id,
  constraint sync_queue_pkey PRIMARY KEY (id)
);
comment on table public.sync_queue is 'Shared outbound mutation queue. Desktop writes here when Excel rows are imported. Android writes here when offline mutations are made. Both clients drain the queue by calling the upsert_*_from_import / mark_sync_queue_processed RPCs. Idempotent by primary key (id).';

create table public.system_settings (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  category text not null,
  key text not null,
  label_fr text not null,
  label_ar text,
  label_en text,
  description_fr text,
  value_type text not null,
  value jsonb,
  value_encrypted text,
  is_sensitive boolean default false not null,
  is_editable boolean default true not null,
  is_required boolean default false not null,
  sort_order integer default 100 not null,
  validation_pattern text,
  validation_min numeric,
  validation_max numeric,
  options jsonb,
  updated_by uuid,
  updated_at timestamp with time zone default now() not null,
  created_at timestamp with time zone default now() not null,
  constraint system_settings_category_check CHECK (category = ANY (ARRAY['connection'::text, 'ai'::text, 'email'::text, 'push'::text, 'storage'::text, 'backup'::text, 'system'::text, 'feature_flags'::text, 'debt'::text])),
  constraint system_settings_value_type_check CHECK (value_type = ANY (ARRAY['string'::text, 'number'::text, 'boolean'::text, 'json'::text, 'secret'::text])),
  constraint system_settings_category_not_null NOT NULL category,
  constraint system_settings_created_at_not_null NOT NULL created_at,
  constraint system_settings_id_not_null NOT NULL id,
  constraint system_settings_is_editable_not_null NOT NULL is_editable,
  constraint system_settings_is_required_not_null NOT NULL is_required,
  constraint system_settings_is_sensitive_not_null NOT NULL is_sensitive,
  constraint system_settings_key_not_null NOT NULL key,
  constraint system_settings_label_fr_not_null NOT NULL label_fr,
  constraint system_settings_sort_order_not_null NOT NULL sort_order,
  constraint system_settings_tenant_id_not_null NOT NULL tenant_id,
  constraint system_settings_updated_at_not_null NOT NULL updated_at,
  constraint system_settings_value_type_not_null NOT NULL value_type,
  constraint system_settings_pkey PRIMARY KEY (id),
  constraint system_settings_tenant_id_category_key_key UNIQUE (tenant_id, category, key)
);
comment on table public.system_settings is 'Database-backed system configuration. Admins edit these from the desktop Configuration tab. Sensitive values are AES-256-GCM encrypted.';
comment on column public.system_settings.category is 'UI grouping: connection, ai, email, push, storage, backup, system, feature_flags.';
comment on column public.system_settings.key is 'Stable dotted key, e.g. supabase.url, groq.api_key, resend.api_key.';
comment on column public.system_settings.value_type is 'string | number | boolean | json | secret. secret values use value_encrypted instead of value.';
comment on column public.system_settings.value is 'Plaintext value as jsonb. NULL for secrets (use value_encrypted instead).';
comment on column public.system_settings.value_encrypted is 'AES-256-GCM ciphertext (base64). Only set when value_type=secret.';
comment on column public.system_settings.is_sensitive is 'true for API keys/passphrases. UI masks the value. Reads return "********" unless reveal=true.';
comment on column public.system_settings.is_editable is 'false prevents deletion (admins can still update the value).';
comment on column public.system_settings.is_required is 'true marks the setting as required — UI shows a warning if empty.';
comment on column public.system_settings.validation_pattern is 'Regex pattern for string validation (e.g. ^https:// for URLs).';
comment on column public.system_settings.options is 'JSON array of {value, label_fr} for enum-like settings.';

create table public.task_attachments (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  task_id uuid not null,
  file_name text not null,
  storage_path text not null,
  mime_type text,
  size_bytes bigint,
  uploaded_by uuid not null,
  uploaded_at timestamp with time zone default now() not null,
  created_at timestamp with time zone default now() not null,
  constraint task_attachments_size_bytes_check CHECK (size_bytes IS NULL OR size_bytes >= 0),
  constraint task_attachments_created_at_not_null NOT NULL created_at,
  constraint task_attachments_file_name_not_null NOT NULL file_name,
  constraint task_attachments_id_not_null NOT NULL id,
  constraint task_attachments_storage_path_not_null NOT NULL storage_path,
  constraint task_attachments_task_id_not_null NOT NULL task_id,
  constraint task_attachments_tenant_id_not_null NOT NULL tenant_id,
  constraint task_attachments_uploaded_at_not_null NOT NULL uploaded_at,
  constraint task_attachments_uploaded_by_not_null NOT NULL uploaded_by,
  constraint task_attachments_pkey PRIMARY KEY (id)
);
comment on table public.task_attachments is 'Files attached to a task. Blob stored in Supabase Storage; metadata in this table. Plan §10.05.';
comment on column public.task_attachments.storage_path is 'Storage path under the task-attachments bucket. Cascade-deleted with task.';

create table public.task_comments (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  task_id uuid not null,
  author_id uuid not null,
  body text not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  author_name text,
  constraint task_comments_body_check CHECK (length(TRIM(BOTH FROM body)) >= 1),
  constraint task_comments_author_id_not_null NOT NULL author_id,
  constraint task_comments_body_not_null NOT NULL body,
  constraint task_comments_created_at_not_null NOT NULL created_at,
  constraint task_comments_id_not_null NOT NULL id,
  constraint task_comments_task_id_not_null NOT NULL task_id,
  constraint task_comments_tenant_id_not_null NOT NULL tenant_id,
  constraint task_comments_updated_at_not_null NOT NULL updated_at,
  constraint task_comments_pkey PRIMARY KEY (id)
);
comment on table public.task_comments is 'Threaded discussion on a task. Cascade-deleted with the parent task. Plan §10.05.';
comment on column public.task_comments.author_id is 'user_profiles.id of the commenter. No FK (convention).';
comment on column public.task_comments.author_name is 'Display name of the comment author (TaskComment.authorName in the desktop domain contract). author_id has no FK to user_profiles. Added by 0074 (T-180).';

create table public.tasks (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  title text not null,
  description text,
  status text default 'pending'::text not null,
  priority text default 'medium'::text not null,
  department_id uuid,
  assignee_ids jsonb default '[]'::jsonb not null,
  due_date date,
  completed_at timestamp with time zone,
  progress integer default 0 not null,
  tags text[] default '{}'::text[] not null,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  created_by_name text,
  completed_by uuid,
  completion_note text,
  reviewed_by uuid,
  review_note text,
  constraint tasks_priority_check CHECK (priority = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'urgent'::text])),
  constraint tasks_progress_check CHECK (progress >= 0 AND progress <= 100),
  constraint tasks_status_kind_check CHECK (status = ANY (ARRAY['pending'::text, 'assigned'::text, 'in_progress'::text, 'blocked'::text, 'completed'::text, 'cancelled'::text, 'needs_review'::text])),
  constraint tasks_title_check CHECK (length(TRIM(BOTH FROM title)) >= 1),
  constraint tasks_assignee_ids_not_null NOT NULL assignee_ids,
  constraint tasks_created_at_not_null NOT NULL created_at,
  constraint tasks_id_not_null NOT NULL id,
  constraint tasks_priority_not_null NOT NULL priority,
  constraint tasks_progress_not_null NOT NULL progress,
  constraint tasks_status_not_null NOT NULL status,
  constraint tasks_tags_not_null NOT NULL tags,
  constraint tasks_tenant_id_not_null NOT NULL tenant_id,
  constraint tasks_title_not_null NOT NULL title,
  constraint tasks_updated_at_not_null NOT NULL updated_at,
  constraint tasks_pkey PRIMARY KEY (id)
);
comment on table public.tasks is 'Multi-assignee task management. assignee_ids is a jsonb array of user_profiles.id strings. Plan §10.05.';
comment on column public.tasks.assignee_ids is 'JSON array of user_profiles.id UUIDs (as strings). GIN-indexed for membership queries.';
comment on column public.tasks.progress is 'Completion percentage 0-100. CHECK constraint enforces range.';
comment on column public.tasks.tags is 'Free-form tag array for filtering. GIN-indexed.';
comment on column public.tasks.created_by is 'user_profiles.id of the task creator. No FK (convention).';
comment on column public.tasks.created_by_name is 'Display name of the task creator (createdByName in the desktop domain contract). created_by has no FK to user_profiles, so the name cannot be joined. Added by 0074 (T-180).';

create table public.tenant_role_overrides (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  role_id uuid not null,
  permission_id uuid not null,
  action text not null,
  created_by uuid,
  created_at timestamp with time zone default now() not null,
  constraint tenant_role_overrides_action_check CHECK (action = ANY (ARRAY['grant'::text, 'deny'::text])),
  constraint tenant_role_overrides_action_not_null NOT NULL action,
  constraint tenant_role_overrides_created_at_not_null NOT NULL created_at,
  constraint tenant_role_overrides_id_not_null NOT NULL id,
  constraint tenant_role_overrides_permission_id_not_null NOT NULL permission_id,
  constraint tenant_role_overrides_role_id_not_null NOT NULL role_id,
  constraint tenant_role_overrides_tenant_id_not_null NOT NULL tenant_id,
  constraint tenant_role_overrides_pkey PRIMARY KEY (id),
  constraint tenant_role_overrides_tenant_id_role_id_permission_id_key UNIQUE (tenant_id, role_id, permission_id)
);

create table public.tenants (
  id uuid default gen_uuid() not null,
  slug text not null,
  name text not null,
  legal_name text,
  tax_id text,
  address text,
  city text,
  postal_code text,
  country text default 'DZ'::text not null,
  phone text,
  email text,
  website text,
  logo_path text,
  default_locale text default 'fr'::text not null,
  default_currency text default 'DZD'::text not null,
  timezone text default 'Africa/Algiers'::text not null,
  is_active boolean default true not null,
  settings jsonb default '{}'::jsonb not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
