  constraint timetable_configurations_periods_not_null NOT NULL periods,
  constraint timetable_configurations_school_days_not_null NOT NULL school_days,
  constraint timetable_configurations_tenant_id_not_null NOT NULL tenant_id,
  constraint timetable_configurations_updated_at_not_null NOT NULL updated_at,
