);
comment on table public.workflow_audit_links is 'M:N join between workflow_runs and audit_logs. Composite PK prevents duplicate links. Plan §12.04.';
comment on column public.workflow_audit_links.audit_log_id is 'UUID of the audit_logs row. FK constraint added in a later migration once audit_logs is defined.';

create table public.workflow_pending_resumes (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  run_id uuid not null,
  workflow_id uuid not null,
  node_id text not null,
  state jsonb default '{}'::jsonb not null,
  resume_after timestamp with time zone not null,
  status text default 'pending'::text not null,
  claimed_at timestamp with time zone,
  completed_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  constraint workflow_pending_resumes_status_check CHECK (status = ANY (ARRAY['pending'::text, 'claimed'::text, 'completed'::text, 'cancelled'::text])),
  constraint workflow_pending_resumes_created_at_not_null NOT NULL created_at,
  constraint workflow_pending_resumes_id_not_null NOT NULL id,
  constraint workflow_pending_resumes_node_id_not_null NOT NULL node_id,
  constraint workflow_pending_resumes_resume_after_not_null NOT NULL resume_after,
  constraint workflow_pending_resumes_run_id_not_null NOT NULL run_id,
  constraint workflow_pending_resumes_state_not_null NOT NULL state,
  constraint workflow_pending_resumes_status_not_null NOT NULL status,
  constraint workflow_pending_resumes_tenant_id_not_null NOT NULL tenant_id,
  constraint workflow_pending_resumes_updated_at_not_null NOT NULL updated_at,
  constraint workflow_pending_resumes_workflow_id_not_null NOT NULL workflow_id,
  constraint workflow_pending_resumes_pkey PRIMARY KEY (id)
);
comment on table public.workflow_pending_resumes is 'Persistent delay/resume queue for workflow runs parked at a wait_duration node (T-228). Claimed atomically by the workflow-resume-scheduler EF. RLS enabled with NO policies: service-role only — the desktop observes pause state via workflow_runs.node_results. Added by 0081 (T-223).';

create table public.workflow_runs (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  workflow_id uuid not null,
  trigger_type text not null,
  triggered_at timestamp with time zone default now() not null,
  started_at timestamp with time zone,
  completed_at timestamp with time zone,
  status text default 'pending'::text not null,
  actor_id uuid,
  error_message text,
  duration_ms integer,
  node_results jsonb default '[]'::jsonb not null,
  created_at timestamp with time zone default now() not null,
  actor_note text,
  request_id text,
  workflow_version integer,
  resumed_at timestamp with time zone,
  constraint workflow_runs_duration_ms_check CHECK (duration_ms IS NULL OR duration_ms >= 0),
  constraint workflow_runs_status_check CHECK (status = ANY (ARRAY['pending'::text, 'running'::text, 'succeeded'::text, 'failed'::text, 'timeout'::text, 'cancelled'::text])),
  constraint workflow_runs_trigger_type_check CHECK (trigger_type = ANY (ARRAY['payment_overdue'::text, 'student_enrolled'::text, 'payment_recorded'::text, 'schedule'::text, 'absence_limit'::text, 'manual_run'::text, 'debt_over_threshold'::text, 'grade_below_threshold'::text, 'payment_cleared_or_bounced'::text, 'document_expiration'::text, 'calendar_cron_event'::text, 'stock_level_critical'::text])),
  constraint workflow_runs_workflow_version_check CHECK (workflow_version IS NULL OR workflow_version >= 1),
  constraint workflow_runs_created_at_not_null NOT NULL created_at,
  constraint workflow_runs_id_not_null NOT NULL id,
  constraint workflow_runs_node_results_not_null NOT NULL node_results,
  constraint workflow_runs_status_not_null NOT NULL status,
  constraint workflow_runs_tenant_id_not_null NOT NULL tenant_id,
  constraint workflow_runs_trigger_type_not_null NOT NULL trigger_type,
  constraint workflow_runs_triggered_at_not_null NOT NULL triggered_at,
  constraint workflow_runs_workflow_id_not_null NOT NULL workflow_id,
  constraint workflow_runs_pkey PRIMARY KEY (id)
);
comment on table public.workflow_runs is 'Workflow execution history. workflow_id is RESTRICT (cannot delete a workflow with runs — disable instead). Plan §12.03.';
comment on column public.workflow_runs.trigger_type is 'Discriminator enum: payment_overdue/student_enrolled/payment_recorded/schedule/absence_limit/manual_run/debt_over_threshold.';
comment on column public.workflow_runs.status is 'pending=queued, running=executing, succeeded/failed/timeout=terminal, cancelled=interrupted by user.';
comment on column public.workflow_runs.actor_id is 'user_profiles.id of the user who triggered the run (NULL for system/schedule triggers). No FK (convention).';
comment on column public.workflow_runs.duration_ms is 'Wall-clock duration in milliseconds. NULL until the run reaches a terminal state.';
comment on column public.workflow_runs.node_results is 'JSON array of per-node outcomes: [{node_id, status, started_at, completed_at, error}]. GIN-indexed.';
comment on column public.workflow_runs.actor_note is 'Free-text note from the triggering actor (e.g. "Desktop manual run by X"). Written by the workflow-execute EF. Added by 0081 (T-223).';
comment on column public.workflow_runs.request_id is 'Correlation id (x-request-id header or generated) for cross-referencing EF logs + audit entries. Added by 0081 (T-223).';
comment on column public.workflow_runs.workflow_version is 'workflows.version at execution time (publish counter — bumped by the workflows_version_on_publish trigger). Added by 0081 (T-223).';
comment on column public.workflow_runs.resumed_at is 'Set when a parked run (workflow_pending_resumes) is resumed by the scheduler EF. Added by 0081 (T-223).';

create table public.workflows (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  code text not null,
  name text not null,
  description text,
  dag_definition jsonb not null,
  status text default 'draft'::text not null,
  max_daily_executions integer default 100 not null,
  trigger_type text,
  created_by uuid,
  last_executed_at timestamp with time zone,
  total_executions integer default 0 not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  last_deployed_at timestamp with time zone,
  version integer default 0 not null,
  constraint workflows_max_daily_executions_check CHECK (max_daily_executions >= 0),
  constraint workflows_status_check CHECK (status = ANY (ARRAY['draft'::text, 'published'::text, 'disabled'::text])),
  constraint workflows_total_executions_check CHECK (total_executions >= 0),
  constraint workflows_version_check CHECK (version >= 0),
  constraint workflows_code_not_null NOT NULL code,
  constraint workflows_created_at_not_null NOT NULL created_at,
  constraint workflows_dag_definition_not_null NOT NULL dag_definition,
  constraint workflows_id_not_null NOT NULL id,
  constraint workflows_max_daily_executions_not_null NOT NULL max_daily_executions,
  constraint workflows_name_not_null NOT NULL name,
  constraint workflows_status_not_null NOT NULL status,
  constraint workflows_tenant_id_not_null NOT NULL tenant_id,
  constraint workflows_total_executions_not_null NOT NULL total_executions,
  constraint workflows_updated_at_not_null NOT NULL updated_at,
  constraint workflows_version_not_null NOT NULL version,
  constraint workflows_pkey PRIMARY KEY (id),
  constraint workflows_tenant_id_code_key UNIQUE (tenant_id, code)
);
comment on table public.workflows is 'DAG-based workflow definitions. Nodes carry {id, type, subtype, x, y, config}. Plan §12.02.';
comment on column public.workflows.dag_definition is 'JSON array of node objects: [{id, type, subtype, x, y, config}]. x/y are canvas coordinates for the visual editor.';
comment on column public.workflows.status is 'draft=editable, published=eligible to run, disabled=paused (history preserved).';
comment on column public.workflows.max_daily_executions is 'Hard cap per tenant per UTC day. Default 100. 0 = effectively disabled.';
comment on column public.workflows.trigger_type is 'Free-text discriminator (payment_overdue, schedule, etc.). Must match workflow_runs.trigger_type enum when published.';
comment on column public.workflows.created_by is 'user_profiles.id of the workflow author. No FK (convention).';
comment on column public.workflows.total_executions is 'Counter incremented per workflow_run (best-effort; authoritative count comes from workflow_runs).';
comment on column public.workflows.last_deployed_at is 'When the workflow was last published (deployed). Maintained by the desktop deploy() write path. Distinct from last_executed_at (the last RUN — maintained by the workflow-execute EF). Added by 0071 (T-176).';
comment on column public.workflows.version is 'Publish counter: 0 = never published (draft); every transition INTO published bumps it by 1 (first publish = 1). Recorded on each workflow_run (workflow_runs.workflow_version). Added by 0081 (T-223).';

create table public.workforce_attendance_events (
  id uuid default gen_uuid() not null,
  tenant_id uuid not null,
  personnel_id uuid not null,
  event_type text not null,
  event_at timestamp with time zone default now() not null,
  latitude numeric(9,6),
  longitude numeric(9,6),
  note text,
  recorded_by uuid,
  created_at timestamp with time zone default now() not null,
  constraint workforce_attendance_events_event_type_check CHECK (event_type = ANY (ARRAY['clock_in'::text, 'break_start'::text, 'break_end'::text, 'clock_out'::text])),
  constraint workforce_attendance_events_created_at_not_null NOT NULL created_at,
  constraint workforce_attendance_events_event_at_not_null NOT NULL event_at,
  constraint workforce_attendance_events_event_type_not_null NOT NULL event_type,
  constraint workforce_attendance_events_id_not_null NOT NULL id,
  constraint workforce_attendance_events_personnel_id_not_null NOT NULL personnel_id,
  constraint workforce_attendance_events_tenant_id_not_null NOT NULL tenant_id,
  constraint workforce_attendance_events_pkey PRIMARY KEY (id)
);
comment on table public.workforce_attendance_events is 'Append-only clock-in/out event stream. event_at replaces the reserved word "timestamp". Plan §10.06.';
comment on column public.workforce_attendance_events.event_at is 'When the event occurred (renamed from "timestamp" to avoid SQL keyword clash).';
comment on column public.workforce_attendance_events.latitude is 'Optional GPS latitude (numeric(9,6) gives sub-meter precision).';
comment on column public.workforce_attendance_events.recorded_by is 'user_profiles.id of whoever recorded the event (typically the personnel themselves via their account, or an admin override).';

-- ############################################################################
-- §4. FUNCTIONS AND RPCs (147) — final definitions only; every superseded
--     intermediate version from the chain is purged (the last writer wins)
--     incl. collect_and_allocate_payment (0127), revert_payment_allocation
--     (0087), register_family_batch (0128), the fn_* state machines, and the
--     five RLS helpers with SECURITY DEFINER + search_path pinned (0099)
-- ############################################################################

create or replace function public.academic_year_start(p_code text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
    select case
        when split_part(p_code, '-', 1) ~ '^\d+$' then split_part(p_code, '-', 1)::int
        else null
    end
$function$
;
comment on function academic_year_start(text) is 'T-405: numeric start year of a YYYY-YYYY academic-year code (NULL when unparseable).';

create or replace function public.adjust_installment_amount(p_installment_id uuid, p_new_amount_due numeric, p_reason text, p_actor_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text)
 RETURNS TABLE(installment_id uuid, parent_id uuid, previous_amount_due numeric, new_amount_due numeric, delta numeric, previous_status text, new_status text, overcovered boolean, excess numeric, ledger_entry_id text, account_balance_after numeric, installments_due_after numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant       uuid := public.current_tenant_id();
    v_reason       text := nullif(btrim(coalesce(p_reason, '')), '');
    v_ins          record;
    v_delta        numeric;
    v_new_status   text;
    v_ledger_id    text;
    v_account_id   text;
    v_description  text;
    v_overcovered  boolean := false;
    v_excess       numeric := 0;
    v_balance      numeric;
    v_due_after    numeric;
    v_prev_due     numeric;
    v_prev_status  text;
begin
    -- Gate 1 — staff roles (the 0137 audience).
    if not public.has_any_role(array['super_admin', 'financial_officer', 'support_staff']) then
        raise exception 'forbidden: tranche amount adjustment is a staff financial write';
    end if;

    -- Gate 2 — the contract guards (fail closed, before any write).
    if p_new_amount_due is null or p_new_amount_due < 0 then
        raise exception 'adjust_installment_amount: the new amount due must be >= 0';
    end if;
    if v_reason is null or length(v_reason) < 3 then
        raise exception 'adjust_installment_amount: the reason is required (>= 3 chars)';
    end if;

    -- Gate 3 — the row exists, tenant-scoped, LOCKED (concurrent adjustments
    -- on the same tranche serialise here: the second writer computes its
    -- delta against the post-first-write value — no lost update, no
    -- double-application).
    select i.id, i.parent_id, i.student_id, i.category, i.label,
           i.amount_due, i.amount_paid, i.amount_pending,
           i.due_date, i.paid_date, i.status
      into v_ins
      from public.installments i
     where i.id = p_installment_id
       and i.tenant_id = v_tenant
       for update;
    if not found then
        raise exception 'adjust_installment_amount: installment % not found in tenant scope', p_installment_id;
    end if;

    v_prev_due    := v_ins.amount_due;
    v_prev_status := v_ins.status;
    v_delta       := p_new_amount_due - v_ins.amount_due;

    -- Gate 4 — the NO-OP guard (the issue's double-application mandate):
    -- a save of the SAME value is rejected — an applied adjustment can
    -- never be re-applied.
    if v_delta = 0 then
        raise exception 'adjust_installment_amount: the new amount due equals the current amount due (%) — nothing to adjust', v_ins.amount_due;
    end if;

    -- The OVER-COVERED classification (explicit, never silent): the new
    -- due sits below the funds already paid or allocated on this tranche.
    if p_new_amount_due < (v_ins.amount_paid + v_ins.amount_pending) then
        v_overcovered := true;
        v_excess := (v_ins.amount_paid + v_ins.amount_pending) - p_new_amount_due;
    end if;

    -- ------------------------------------------------------------------
    -- The STATUS re-derivation (the 0115 waterfall predicates + ADR-033).
    -- Priority: paid (cleared funds cover the new due — INV-4) >
    -- pending_clearance (uncleared funds in flight — the row's settlement
    -- awaits a clearance, the honest state whenever amount_pending > 0) >
    -- partial (cleared funds present) > the ADR-033 date branch.
    -- ------------------------------------------------------------------
    if v_ins.amount_paid >= p_new_amount_due then
        v_new_status := 'paid';                              -- INV-4: cleared funds cover the (new) due
    elsif v_ins.amount_pending > 0 then
        v_new_status := 'pending_clearance';                 -- uncleared funds keep their state
    elsif v_ins.amount_paid > 0 then
        v_new_status := 'partial';
    elsif v_ins.due_date < current_date then
        v_new_status := 'overdue';                           -- ADR-033: past due + no payment activity
    else
        v_new_status := 'unpaid';                            -- ADR-033: the no-payment-activity state
    end if;

    -- ------------------------------------------------------------------
    -- Write 1/3 — the INSTALLMENTS row (the tranche's OWN row only — the
    -- issue's "only the intended tranche is affected").
    -- ------------------------------------------------------------------
    update public.installments
       set amount_due = p_new_amount_due,
           status     = v_new_status,
           paid_date  = case when v_new_status = 'paid' then coalesce(paid_date, now()) else paid_date end,
           updated_at = now()
     where id = v_ins.id;

    -- ------------------------------------------------------------------
    -- Write 2/3 — the LEDGER adjustment entry (the signed DELTA on the
    -- tranche's OWN account — the live charge convention, probed
    -- 2026-10-13). Append-only: the charge history, every payment entry,
    -- every refund/reversal — untouched.
    -- ------------------------------------------------------------------
    v_ledger_id := 'led-' || to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
                   || '-' || substr(md5(gen_random_uuid()::text), 1, 8);
    v_account_id := 'parent:' || v_ins.parent_id || ':category:' || v_ins.category
                    || ':student:' || v_ins.student_id;
    v_description := 'Ajustement tranche — ' || coalesce(v_ins.label, 'tranche')
                     || ' · ' || to_char(p_new_amount_due, 'FM999999999D99')
                     || ' DZD (ancien ' || to_char(v_ins.amount_due, 'FM999999999D99') || ')'
                     || ' · ' || v_reason;

    insert into public.ledger_entries (
        id, tenant_id, entry_number, parent_id, student_id, account_id,
        entry_type, amount, category, description, entry_date,
        source_type, source_id, method, receipt_number, payment_status,
        reverses_id, actor_id, actor_name, at, metadata
    ) values (
        public.gen_uuid(), v_tenant, v_ledger_id, v_ins.parent_id, v_ins.student_id, v_account_id,
        'adjustment', v_delta, v_ins.category, v_description,
        now(),
        'manual_entry', 'adj-' || v_ins.id::text, null, null, null,
        null, p_actor_id::text, p_actor_name, now(),
        jsonb_build_object(
            'installmentId', v_ins.id,
            'previousAmountDue', v_prev_due,
            'newAmountDue', p_new_amount_due,
            'delta', v_delta,
            'reason', v_reason,
            'overcovered', v_overcovered,
            'excess', v_excess,
            'source', 'adjust_installment_amount'
        )
    );

    -- ------------------------------------------------------------------
    -- Write 3/3 — the AUDIT row (the issue's auditability mandate: the
    -- account, the tranche, the previous and new amounts, the reason,
    -- the acting user, the timestamp, the resulting balances).
    -- ------------------------------------------------------------------
    -- The resulting balances (computed AFTER the writes — the honest
    -- post-state, not a projection).
    select coalesce(sum(l.amount), 0) into v_balance
      from public.ledger_entries l
     where l.tenant_id = v_tenant
       and l.parent_id = v_ins.parent_id
       and l.account_id = v_account_id;

    select coalesce(sum(i.amount_due), 0) into v_due_after
      from public.installments i
     where i.tenant_id = v_tenant
       and i.parent_id = v_ins.parent_id;

    insert into public.audit_logs (
        id, tenant_id, action, entity_type, entity_id, actor_id, actor_name,
        before_json, after_json, diff, note, created_at
    ) values (
        public.gen_uuid(), v_tenant, 'installment.amount_adjusted', 'installment', v_ins.id,
        p_actor_id, p_actor_name,
        jsonb_build_object(
            'installmentId', v_ins.id, 'parentId', v_ins.parent_id, 'studentId', v_ins.student_id,
            'category', v_ins.category, 'label', v_ins.label,
            'amountDue', v_prev_due, 'status', v_prev_status,
            'amountPaid', v_ins.amount_paid, 'amountPending', v_ins.amount_pending,
            'installmentsDueTotal', v_due_after - v_delta
        ),
        jsonb_build_object(
            'installmentId', v_ins.id, 'parentId', v_ins.parent_id, 'studentId', v_ins.student_id,
            'category', v_ins.category, 'label', v_ins.label,
            'amountDue', p_new_amount_due, 'status', v_new_status,
            'amountPaid', v_ins.amount_paid, 'amountPending', v_ins.amount_pending,
            'ledgerEntryId', v_ledger_id,
            'accountBalanceAfter', v_balance, 'installmentsDueTotal', v_due_after,
            'overcovered', v_overcovered, 'excess', v_excess
        ),
        jsonb_build_object(
            'amountDue', jsonb_build_array(v_prev_due, p_new_amount_due),
            'delta', v_delta,
            'status', jsonb_build_array(v_prev_status, v_new_status)
        ),
        'Tranche ajustée via RPC adjust_installment_amount (T-510/DEBT-105 — ' || v_reason || ')',
        now()
    );

    return query select
        v_ins.id, v_ins.parent_id,
        v_prev_due, p_new_amount_due, v_delta,
        v_prev_status, v_new_status,
        v_overcovered, v_excess,
        v_ledger_id, v_balance, v_due_after;
end;
$function$
;
comment on function adjust_installment_amount(uuid,numeric,text,uuid,text) is 'T-510 (DEBT-105, GitHub issue #31): the canonical per-tranche amount write path — the installments row UPDATE (amount_due := the NEW TOTAL, the status re-derived per the 0115 waterfall predicates + ADR-033) + the signed DELTA ledger adjustment on the tranche''s own account (the T-103 invariant: Σ installments due == Σ charges + Σ adjustments) + the audit row (before/after, reason, actor, resulting balances). Payments, allocations and history are NEVER touched; the over-covered case (new < paid + pending) is allowed and flagged explicitly; the no-op delta is rejected (the double-application guard).';

create or replace function public.adjust_personnel_salary(p_personnel_id uuid, p_type text, p_delta numeric, p_reason text, p_effective_date date DEFAULT CURRENT_DATE, p_actor_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_personnel record;
    v_amount_before numeric;
    v_amount_after numeric;
    v_signed_delta numeric;
    v_actor_id uuid := public.current_user_profile_id();
    v_actor_name text;
    v_tenant_id uuid;
    v_adjustment public.salary_adjustments;
    v_caller_is_service_role boolean := coalesce(auth.jwt() ->> 'role', '') = 'service_role';
begin
    -- ── Caller verification (0055 pattern) ─────────────────────────────
    if not v_caller_is_service_role then
        if auth.uid() is null then
            raise exception 'adjust_personnel_salary: an authenticated caller is required';
        end if;
        if not public.has_any_role(array['super_admin', 'financial_officer']) then
            raise exception 'adjust_personnel_salary: only super_admin / financial_officer may adjust salaries';
        end if;
    end if;

    -- ── Input validation (mirrors the desktop UI's mandatory-reason rule) ─
    if p_type not in ('raise', 'cut', 'bonus', 'deduction') then
        raise exception 'adjust_personnel_salary: invalid adjustment type %', p_type;
    end if;
    if p_delta is null or p_delta <= 0 then
        raise exception 'adjust_personnel_salary: the adjustment amount must be positive';
    end if;
    if p_reason is null or length(trim(p_reason)) < 5 then
        raise exception 'adjust_personnel_salary: a formal justification of at least 5 characters is mandatory';
    end if;

    -- ── Lock the personnel row (atomic read-modify-write) ───────────────
    select * into v_personnel
      from public.personnel
     where id = p_personnel_id
     for update;

    if not found then
        raise exception 'adjust_personnel_salary: personnel record % not found', p_personnel_id;
    end if;

    v_tenant_id := v_personnel.tenant_id;

    -- Tenant guard (SEC-112 lesson): the caller's working tenant must own
    -- the personnel row. Global admins (tenant-less profiles) and the
    -- service_role are the 0055-trusted exemptions.
    if not v_caller_is_service_role
       and public.current_tenant_id() is not null
       and public.current_tenant_id() <> v_tenant_id then
        raise exception 'adjust_personnel_salary: cross-tenant adjustment refused (personnel tenant % does not match the caller''s working tenant)', v_tenant_id;
    end if;

    v_amount_before := coalesce(v_personnel.base_salary, 0);

    -- Actor display name: the UI-passed name wins, else the profile's
    -- display_name, else a neutral fallback.
    select coalesce(display_name, '') into v_actor_name
      from public.user_profiles
     where id = v_actor_id
       and v_actor_id is not null;
    v_actor_name := coalesce(nullif(trim(coalesce(p_actor_name, '')), ''), nullif(v_actor_name, ''), 'Admin');

    -- ── The four adjustment semantics (the blueprint's table) ───────────
    -- INVARIANT: delta = amount_after - amount_before on every row (the
    -- table CHECK enforces it for raise/cut). For a FLOORED cut the delta
    -- records the reduction that ACTUALLY happened, not the requested
    -- magnitude — a deviation from the blueprint's "-abs(p_delta)" recorded
    -- here because the blueprint's version violates its own row invariant
    -- (amount_after = amount_before + delta) whenever the floor engages.
    if p_type = 'raise' then
        v_amount_after := v_amount_before + abs(p_delta);
        v_signed_delta := abs(p_delta);
    elsif p_type = 'cut' then
        v_amount_after := greatest(0, v_amount_before - abs(p_delta));
        v_signed_delta := v_amount_after - v_amount_before;
    elsif p_type = 'bonus' then
        v_amount_after := v_amount_before;            -- one-off: base unchanged
        v_signed_delta := abs(p_delta);
    else -- 'deduction'
        v_amount_after := v_amount_before;            -- one-off: base unchanged
        v_signed_delta := -abs(p_delta);
    end if;

    -- ── Update the base salary (raise/cut only) ─────────────────────────
    if p_type in ('raise', 'cut') then
        update public.personnel
           set base_salary = v_amount_after,
               updated_at = now()
         where id = p_personnel_id;
    end if;

    -- ── The immutable adjustment row ─────────────────────────────────────
    insert into public.salary_adjustments (
        tenant_id, personnel_id, type, amount_before, amount_after,
        delta, reason, effective_date, approved_by, approved_by_name
    ) values (
        v_tenant_id, p_personnel_id, p_type, v_amount_before, v_amount_after,
        v_signed_delta, trim(p_reason), coalesce(p_effective_date, current_date), v_actor_id, v_actor_name
    )
    returning * into v_adjustment;

    -- ── Master audit log (0014) ──────────────────────────────────────────
    perform public.write_audit_log(
        p_tenant_id   := v_tenant_id,
        p_action      := 'personnel.salary_adjusted',
        p_entity_type := 'personnel',
        p_entity_id   := p_personnel_id,
        p_actor_id    := v_actor_id,
        p_actor_name  := v_actor_name,
        p_before_json := jsonb_build_object('salary', v_amount_before),
        p_after_json  := jsonb_build_object('salary', v_amount_after, 'type', p_type, 'delta', v_signed_delta, 'reason', trim(p_reason)),
        p_note        := format('Salary adjusted (%s: %s DZD)', p_type, v_signed_delta)
    );

    return jsonb_build_object(
        'adjustment', to_jsonb(v_adjustment),
        'base_salary_after', v_amount_after
    );
end;
$function$
;

create or replace function public.admin_create_user_account(p_auth_user_id uuid, p_role_code text, p_tenant_id uuid, p_reviewer_profile_id uuid, p_decision_note text DEFAULT NULL::text, p_personnel_id uuid DEFAULT NULL::uuid, p_email text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_profile_id  uuid;
    v_role_id     uuid;
    v_request_id  uuid;
    v_personnel_id uuid;
    v_bound_user  uuid;
    v_other_id    uuid;
begin
    -- 1. The auth user must exist and have a trigger-created profile.
    select up.id
      into v_profile_id
      from public.user_profiles up
     where up.auth_user_id = p_auth_user_id
       and up.tenant_id = p_tenant_id
       for update;

    if v_profile_id is null then
        raise exception 'user profile not found for auth user %', p_auth_user_id
          using errcode = 'P0002';
    end if;

    -- 2. The requested role must exist (prevents phantom-role assignment).
    select r.id
      into v_role_id
      from public.roles r
     where r.code = p_role_code;

    if v_role_id is null then
        raise exception 'unknown role code %', p_role_code
          using errcode = '22023';  -- invalid_parameter_value
    end if;

    -- 3. Activate the profile (the admin IS the approval).
    update public.user_profiles
       set status = 'active',
           updated_at = now()
     where id = v_profile_id;

    -- 4. Assign the chosen role (idempotent on conflict).
    insert into public.role_assignments (user_profile_id, tenant_id, role_id, assigned_by)
    values (v_profile_id, p_tenant_id, v_role_id, p_reviewer_profile_id)
    on conflict (user_profile_id, tenant_id, role_id) where revoked_at is null
    do nothing;

    -- 5. Resolve the auto-created approval request so the Inscriptions
    --    queue stays clean — the audit trail records who created the
    --    account and when.
    update public.account_approval_requests
       set status = 'approved',
           reviewed_by = p_reviewer_profile_id,
           reviewed_at = now(),
           decision_note = coalesce(p_decision_note, 'Compte créé directement par un administrateur')
     where auth_user_id = p_auth_user_id
       and status = 'pending'
    returning id into v_request_id;

    -- 6. Link the profile to the approval request (mirrors 0005 behaviour).
    if v_request_id is not null then
        update public.user_profiles
           set approval_request_id = v_request_id
         where id = v_profile_id;
    end if;

    -- 7. T-371 (WORKFORCE-501) — bind the employee record to the account,
    --    in the SAME transaction. Guards BEFORE any write:
    if p_personnel_id is not null then
        select p.id, p.user_id
          into v_personnel_id, v_bound_user
          from public.personnel p
         where p.id = p_personnel_id
           and p.tenant_id = p_tenant_id
           and p.deleted_at is null
           for update;

        if v_personnel_id is null then
            raise exception 'personnel % not found in tenant % (or deleted)', p_personnel_id, p_tenant_id
              using errcode = 'P0002';
        end if;

        if v_bound_user is not null and v_bound_user <> v_profile_id then
            raise exception 'personnel % is already linked to another account (%)', p_personnel_id, v_bound_user
              using errcode = '23505';  -- unique_violation semantics
        end if;

        -- The new profile must not already belong to a DIFFERENT employee.
        if v_bound_user is null then
            select p.id
              into v_other_id
              from public.personnel p
             where p.user_id = v_profile_id
               and p.id <> p_personnel_id
               and p.deleted_at is null
             limit 1;

            if v_other_id is not null then
                raise exception 'profile % is already linked to another personnel (%)', v_profile_id, v_other_id
                  using errcode = '23505';
            end if;
        end if;

        -- Backfill the contact email on the employee record when absent so
        -- the two rows agree with each other going forward.
        update public.personnel
           set user_id = v_profile_id,
               email = coalesce(email, nullif(trim(p_email), '')),
               updated_at = now()
         where id = p_personnel_id
           and (user_id is null or user_id = v_profile_id);
    end if;

    return v_profile_id;
end;
$function$
;
comment on function admin_create_user_account(uuid,text,uuid,uuid,text,uuid,text) is 'T-079/T-371: activates the trigger-created profile of an admin-created auth user, assigns the chosen role, resolves the auto-created approval request, and (T-371) optionally binds the selected employee record via personnel.user_id — one atomic transaction. Server-side only (service_role); the create-user-account Edge Function is the security boundary.';

create or replace function public.approve_account_request(p_request_id uuid, p_reviewer_profile_id uuid, p_target_parent_id uuid DEFAULT NULL::uuid, p_target_student_id uuid DEFAULT NULL::uuid, p_decision_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
    v_request record;
    v_role_id uuid;
    v_role_code text;
    v_existing_parent_auth_user_id uuid;
    v_audit_id uuid;
    v_old_parent_auth_user_id uuid;
begin
    select * into v_request
      from public.account_approval_requests
     where id = p_request_id
       and status = 'pending'
     for update;

    if not found then
        raise exception 'Approval request not found or already processed';
    end if;

    -- Determine role to assign
    v_role_code := case v_request.requested_role
        when 'parent' then 'parent'
        when 'student' then 'student'
        when 'staff' then 'support_staff'  -- admin must refine via RBAC editor
    end;

    select id into v_role_id from public.roles where code = v_role_code;

    -- Update the request
    update public.account_approval_requests
       set status = 'approved',
           reviewed_by = p_reviewer_profile_id,
           reviewed_at = now(),
           decision_note = p_decision_note,
           target_parent_id = coalesce(p_target_parent_id, v_request.target_parent_id),
           target_student_id = coalesce(p_target_student_id, v_request.target_student_id)
     where id = p_request_id;

    -- Activate the user profile
    update public.user_profiles
       set status = 'active',
           approval_request_id = p_request_id
     where auth_user_id = v_request.auth_user_id;

    -- Assign the role
    insert into public.role_assignments (user_profile_id, tenant_id, role_id, assigned_by)
    select up.id, v_request.tenant_id, v_role_id, p_reviewer_profile_id
      from public.user_profiles up
     where up.auth_user_id = v_request.auth_user_id
     on conflict (user_profile_id, tenant_id, role_id) where revoked_at is null do nothing;

    -- Bind to parent profile if requested_role='parent' and target_parent_id provided
    -- T-029 / PARENT-101: REJECT re-binding a parent already bound to a
    -- different user. The admin must unbind first via the standard RBAC
    -- editor (which writes its own audit entry). This block also writes
    -- a `parent.bind` audit entry capturing the OLD auth_user_id (null for
    -- first-time bindings) so the rebinding is auditable when it IS
    -- allowed.
    if v_request.requested_role = 'parent' and p_target_parent_id is not null then
        -- Capture the existing binding for the audit entry + the re-bind check.
        select auth_user_id into v_existing_parent_auth_user_id
          from public.parents
         where id = p_target_parent_id;

        v_old_parent_auth_user_id := coalesce(v_existing_parent_auth_user_id, ('00000000-0000-0000-0000-000000000000')::uuid);

        -- Reject re-binding to a different user.
        if v_existing_parent_auth_user_id is not null
           and v_existing_parent_auth_user_id is distinct from v_request.auth_user_id then
            raise exception
                'Parent % is already bound to a different auth_user_id (%). Unbind the previous account via the RBAC editor before approving this request.',
                p_target_parent_id, v_existing_parent_auth_user_id
                using hint = 'Use the RBAC editor to clear auth_user_id first, then re-approve.';
        end if;

        -- Perform the binding.
        update public.parents
           set auth_user_id = v_request.auth_user_id
         where id = p_target_parent_id;

        -- Audit the binding (including the OLD auth_user_id for forensic trail).
        v_audit_id := public.write_audit_log(
            p_tenant_id => v_request.tenant_id,
            p_action => 'parent.bind',
            p_entity_type => 'parent',
            p_entity_id => p_target_parent_id,
            p_actor_id => p_reviewer_profile_id,
            p_actor_role => v_role_code,
            p_before_json => jsonb_build_object('auth_user_id', v_existing_parent_auth_user_id),
            p_after_json => jsonb_build_object('auth_user_id', v_request.auth_user_id, 'request_id', p_request_id),
            p_note => coalesce(p_decision_note, 'parent account binding approved')
        );
    end if;

    -- Bind to student profile if requested_role='student' and target_student_id provided
    -- T-029 / PARENT-101: same guard pattern for students (silent over-
    -- write was the same defect shape).
    if v_request.requested_role = 'student' and p_target_student_id is not null then
        -- Capture the existing binding.
        select auth_user_id into v_existing_parent_auth_user_id
          from public.students
         where id = p_target_student_id;

        if v_existing_parent_auth_user_id is not null
           and v_existing_parent_auth_user_id is distinct from v_request.auth_user_id then
            raise exception
                'Student % is already bound to a different auth_user_id (%). Unbind the previous account via the RBAC editor before approving this request.',
                p_target_student_id, v_existing_parent_auth_user_id
                using hint = 'Use the RBAC editor to clear auth_user_id first, then re-approve.';
        end if;

        update public.students
           set auth_user_id = v_request.auth_user_id
         where id = p_target_student_id;

        v_audit_id := public.write_audit_log(
            p_tenant_id => v_request.tenant_id,
            p_action => 'student.bind',
            p_entity_type => 'student',
            p_entity_id => p_target_student_id,
            p_actor_id => p_reviewer_profile_id,
            p_actor_role => v_role_code,
            p_before_json => jsonb_build_object('auth_user_id', v_existing_parent_auth_user_id),
            p_after_json => jsonb_build_object('auth_user_id', v_request.auth_user_id, 'request_id', p_request_id),
            p_note => coalesce(p_decision_note, 'student account binding approved')
        );
    end if;

    return v_role_id;
end;
$function$
;
comment on function approve_account_request(uuid,uuid,uuid,uuid,text) is 'Approves a web registration request, activates the user profile, assigns the requested role, and (optionally) binds to an existing parent or student profile. Called from the desktop admin UI.';

create or replace function public.approve_expense(p_tenant_id uuid, p_ticket_id uuid, p_approver_profile_id uuid, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_ticket record;
    v_audit_id uuid;
    v_caller_is_service_role boolean := coalesce(auth.jwt() ->> 'role', '') = 'service_role';
begin
    -- ── Caller verification + actor binding (SEC-118, the 0055 pattern) ──
    if not v_caller_is_service_role then
        if auth.uid() is null then
            raise exception 'approve_expense: an authenticated caller is required';
        end if;
        if not public.has_any_role(array['super_admin', 'financial_officer', 'manager']) then
            raise exception 'approve_expense: only super_admin / financial_officer / manager may approve expenses';
        end if;
        if p_approver_profile_id is distinct from public.current_user_profile_id() then
            raise exception 'approve_expense: p_approver_profile_id must be the caller''s own profile (SEC-118 actor binding) — approvals cannot be recorded in another profile''s name';
        end if;
    end if;

    select * into v_ticket from public.expense_tickets where id = p_ticket_id and tenant_id = p_tenant_id;
    if not found then raise exception 'Expense ticket not found'; end if;

    if v_ticket.submitted_by = p_approver_profile_id then
        raise exception 'Self-approval is forbidden (plan §08)';
    end if;

    if v_ticket.status <> 'pending_approval' then
        raise exception 'Ticket is not pending approval (current: %)', v_ticket.status;
    end if;

    update public.expense_tickets
       set status = 'approved_funds_released',
           approved_by = p_approver_profile_id,
           approved_at = now(),
           approval_note = p_note,
           disbursed_at = now(),
           updated_at = now()
     where id = p_ticket_id;

    v_audit_id := public.write_audit_log(
        p_tenant_id := p_tenant_id,
        p_action := 'expense.approve',
        p_entity_type := 'expense_ticket',
        p_entity_id := p_ticket_id,
        p_actor_id := p_approver_profile_id,
        p_after_json := jsonb_build_object('status', 'approved_funds_released', 'note', p_note)
    );

    return v_audit_id;
end;
$function$
;
comment on function approve_expense(uuid,uuid,uuid,text) is 'Atomic expense approval. WEAK-030 no-self-approval + SEC-118 (0155): 0055 caller verification (service_role OR authenticated reviewer) and actor binding (p_approver_profile_id = the caller''s own profile for non-service callers).';

create or replace function public.approve_student_application(p_request_id uuid, p_reviewer_profile_id uuid, p_decision_note text DEFAULT NULL::text, p_target_student_id uuid DEFAULT NULL::uuid, p_target_parent_id uuid DEFAULT NULL::uuid, p_new_parent jsonb DEFAULT NULL::jsonb, p_new_student jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_request record;
    v_parent_id uuid;
    v_student_id uuid;
    v_student_code text;
    v_class record;
    v_class_id uuid;
    v_class_grade_code text;
    v_grade_level_code text;
    v_level record;
    v_year record;
    v_role_id uuid;
    v_existing_student_auth uuid;
    v_seq integer;
    v_is_new_student boolean := false;
    v_audit_id uuid;
    v_parent_code text;
begin
    -- Lock the request (the 0005/0047 pattern).
    select * into v_request
      from public.account_approval_requests
     where id = p_request_id
       and status = 'pending'
     for update;

    if not found then
        raise exception 'approve_student_application: request not found or already processed'
            using errcode = 'P0001';
    end if;

    if v_request.requested_role not in ('parent', 'student') then
        raise exception 'approve_student_application: this RPC approves parent/student applications (requested_role=%)', v_request.requested_role
            using errcode = 'P0001';
    end if;

    -- STUDENT-101 guard (the PARENT-102 lesson, student edition): a
    -- STUDENT-role approval REQUIRES a student binding — target_student_id
    -- (bind existing) OR new_student (create). Otherwise the user would be
    -- active but unbound — the limbo this migration closes.
    if v_request.requested_role = 'student' then
        if p_target_student_id is null and (p_new_student is null or p_new_student = 'null'::jsonb) then
            raise exception 'approve_student_application: a student approval requires target_student_id or new_student (otherwise the user would be active but unbound to any student profile)'
                using errcode = 'P0001';
        end if;
        if p_target_student_id is not null and p_new_student is not null and p_new_student <> 'null'::jsonb then
            raise exception 'approve_student_application: pass either target_student_id (bind existing) or new_student (create), not both'
                using errcode = 'P0001';
        end if;
        if p_target_student_id is not null and p_new_parent is not null and p_new_parent <> 'null'::jsonb then
            raise exception 'approve_student_application: new_parent is only valid when creating a student (pass target_student_id alone to bind an existing student)'
                using errcode = 'P0001';
        end if;
    else
        -- PARENT-role: this RPC is the "approve the family AND enroll the
        -- child" composite. A parent-role approval with p_target_student_id
        -- is a category error (the account binds the PARENT, not a student),
        -- and calling this RPC at all requires a student to enroll — the
        -- plain bind-only parent approval goes through approve_account_request
        -- directly (the existing EF path, unchanged).
        if p_target_student_id is not null then
            raise exception 'approve_student_application: a parent-role approval cannot bind target_student_id (bind the parent; the student is created under the family)'
                using errcode = 'P0001';
        end if;
        if p_new_student is null or p_new_student = 'null'::jsonb then
            raise exception 'approve_student_application: a parent-role approval through this RPC requires new_student (use the plain parent approval path for bind-only approvals)'
                using errcode = 'P0001';
        end if;
        if p_target_parent_id is null and (p_new_parent is null or p_new_parent = 'null'::jsonb) then
            raise exception 'approve_student_application: a parent-role approval requires target_parent_id or new_parent (PARENT-102, migration 0047)'
                using errcode = 'P0001';
        end if;
    end if;

    if p_target_parent_id is not null and p_new_parent is not null and p_new_parent <> 'null'::jsonb then
        raise exception 'approve_student_application: pass either target_parent_id (existing family) or new_parent (create family), not both'
            using errcode = 'P0001';
    end if;

    -- ------------------------------------------------------------------
    -- Branch A (student-role only): bind an EXISTING student
    -- (the 0047 rebind-guard semantics)
    -- ------------------------------------------------------------------
    if v_request.requested_role = 'student' and p_target_student_id is not null then
        select id, auth_user_id, student_code, parent_id
          into v_student_id, v_existing_student_auth, v_student_code, v_parent_id
          from public.students
         where id = p_target_student_id
           and tenant_id = v_request.tenant_id
           and deleted_at is null;

        if v_student_id is null then
            raise exception 'approve_student_application: target student % not found in tenant (or deleted)', p_target_student_id
                using errcode = 'P0002';
        end if;

        if v_existing_student_auth is not null
           and v_existing_student_auth is distinct from v_request.auth_user_id then
            raise exception
                'approve_student_application: student % is already bound to a different auth_user_id (%). Unbind the previous account via the RBAC editor before approving this request.',
                p_target_student_id, v_existing_student_auth
                using hint = 'Use the RBAC editor to clear students.auth_user_id first, then re-approve.',
                    errcode = 'P0001';
        end if;
    else
        -- ------------------------------------------------------------------
        -- Branch B: CREATE the student (the STUDENT-100 fix) — student-role
        -- requests create the student + family; parent-role requests create
        -- the child under the resolved/created family.
        -- ------------------------------------------------------------------

        -- B.1 resolve the parent (students.parent_id is NOT NULL — plan §04.01)
        if p_new_parent is not null and p_new_parent <> 'null'::jsonb then
            if coalesce(btrim(p_new_parent->>'first_name'), '') = ''
               or coalesce(btrim(p_new_parent->>'last_name'), '') = ''
               or coalesce(btrim(p_new_parent->>'primary_phone'), '') = '' then
                raise exception 'approve_student_application: new_parent requires first_name, last_name and primary_phone (the canonical code generator has no random fallback — DRIFT-001, migration 0065)'
                    using errcode = 'P0001';
            end if;

            v_parent_code := public.fn_deterministic_parent_code(
                extract(year from now())::int,
                btrim(p_new_parent->>'primary_phone'),
                p_new_parent->>'display_name',
                btrim(p_new_parent->>'first_name'),
                btrim(p_new_parent->>'last_name')
            );

            insert into public.parents (
                tenant_id, parent_code, first_name, last_name, primary_phone,
                email, national_id, address, city, relationship,
                is_active, created_at, updated_at
            ) values (
                v_request.tenant_id,
                v_parent_code,
                btrim(p_new_parent->>'first_name'),
                btrim(p_new_parent->>'last_name'),
                btrim(p_new_parent->>'primary_phone'),
                nullif(btrim(coalesce(p_new_parent->>'email', v_request.email)), ''),
                nullif(btrim(p_new_parent->>'national_id'), ''),
                nullif(btrim(p_new_parent->>'address'), ''),
                nullif(btrim(p_new_parent->>'city'), ''),
                coalesce(nullif(btrim(p_new_parent->>'relationship'), ''), 'father'),
                true, now(), now()
            )
            -- The deterministic code makes the re-run converge on the SAME
            -- family instead of duplicating (the 0065 idempotency contract:
            -- "the dedup match IS the code").
            on conflict (tenant_id, parent_code) do update
               set email = coalesce(public.parents.email, excluded.email),
                   updated_at = now()
            returning id into v_parent_id;

            v_audit_id := public.write_audit_log(
                p_tenant_id   := v_request.tenant_id,
                p_action      := 'parent.create',
                p_entity_type := 'parent',
                p_entity_id   := v_parent_id,
                p_actor_id    := p_reviewer_profile_id,
                p_after_json  := jsonb_build_object(
                    'source', 'approve_student_application (migration 0116)',
                    'parent_code', v_parent_code
                ),
                p_note        := 'Created parent profile during student-application approval'
            );
        elsif p_target_parent_id is not null then
            select id into v_parent_id
              from public.parents
             where id = p_target_parent_id
               and tenant_id = v_request.tenant_id
               and deleted_at is null;

            if v_parent_id is null then
                raise exception 'approve_student_application: target parent % not found in tenant (or deleted)', p_target_parent_id
                    using errcode = 'P0002';
            end if;
        else
            raise exception 'approve_student_application: creating a student requires target_parent_id or new_parent (students.parent_id is NOT NULL — plan §04.01)'
                using errcode = 'P0001';
        end if;

        -- B.2 validate the student payload
        if coalesce(btrim(p_new_student->>'first_name'), '') = ''
           or coalesce(btrim(p_new_student->>'last_name'), '') = ''
           or coalesce(p_new_student->>'date_of_birth', '') = '' then
            raise exception 'approve_student_application: new_student requires first_name, last_name and date_of_birth'
                using errcode = 'P0001';
        end if;
        if (p_new_student->>'date_of_birth')::date >= current_date then
            raise exception 'approve_student_application: date_of_birth must be in the past'
                using errcode = '22023';
        end if;

        -- B.3 resolve class + grade level (mutual derivation: an explicit
        -- grade_level_code wins; otherwise the class's own level defines it).
        v_class_id := nullif(btrim(coalesce(p_new_student->>'class_id', '')), '')::uuid;
        v_grade_level_code := nullif(btrim(coalesce(p_new_student->>'grade_level_code', '')), '');

        if v_class_id is not null then
            select c.id, c.name, c.code, l.grade_code as level_grade_code,
                   l.cycle as level_cycle, l.year_number as level_year_number
              into v_class
              from public.classes c
              left join public.academic_levels l on l.id = c.academic_level_id
             where c.id = v_class_id
               and c.tenant_id = v_request.tenant_id;

            if v_class.id is null then
                raise exception 'approve_student_application: class % not found in tenant', v_class_id
                    using errcode = 'P0002';
            end if;

            v_class_grade_code := v_class.level_grade_code;
            if v_grade_level_code is null then
                v_grade_level_code := v_class_grade_code;
            elsif v_class_grade_code is not null and v_class_grade_code <> v_grade_level_code then
                raise exception 'approve_student_application: grade_level_code % does not match class % (whose level is %)', v_grade_level_code, v_class_id, v_class_grade_code
                    using errcode = '22023';
            end if;
        end if;

        -- B.4 create the student — the canonical ELV-{year}-{6-digit} code
        v_seq := nextval('public.student_seq');
        v_student_code := 'ELV-' || extract(year from now())::text || '-' || lpad(v_seq::text, 6, '0');

        insert into public.students (
            tenant_id, parent_id, student_code,
            first_name, middle_name, last_name, display_name,
            date_of_birth, gender,
            grade_level_code, grade_level_id, class_id,
            enrollment_date, enrollment_status,
            medical_notes, is_active,
            created_at, updated_at
        ) values (
            v_request.tenant_id, v_parent_id, v_student_code,
            btrim(p_new_student->>'first_name'),
            nullif(btrim(p_new_student->>'middle_name'), ''),
            btrim(p_new_student->>'last_name'),
            nullif(btrim(coalesce(p_new_student->>'display_name', '')), ''),
            (p_new_student->>'date_of_birth')::date,
            nullif(btrim(p_new_student->>'gender'), ''),
            v_grade_level_code,
            (select l.id from public.academic_levels l
              where l.grade_code = v_grade_level_code
                and l.tenant_id = v_request.tenant_id
              limit 1),
            v_class_id,
            current_date, 'active',
            nullif(btrim(p_new_student->>'medical_notes'), ''),
            true, now(), now()
        )
        returning id into v_student_id;

        v_is_new_student := true;

        -- B.5 the canonical enrollment record: student_academic_histories
        -- (0029) — one entry for the CURRENT academic year so the student is
        -- immediately visible in Pedagogy history/provenance consumers
        -- (the T-402 lesson: Supabase mode reads the table, not the
        -- legacy column). Column shape mirrors 0059's
        -- execute_batch_promotion insert verbatim.
        select * into v_year
          from public.academic_years
         where tenant_id = v_request.tenant_id
           and is_current
           and not is_archived
         order by start_date desc
         limit 1;

        if found and v_grade_level_code is not null then
            select * into v_level
              from public.academic_levels
             where grade_code = v_grade_level_code
               and tenant_id = v_request.tenant_id
             limit 1;

            if v_level.id is not null then
                insert into public.student_academic_histories (
                    tenant_id, student_id, academic_year,
                    cycle, grade_code, grade_year,
                    class_id, class_name,
                    gpa, decision, narrative
                ) values (
                    v_request.tenant_id, v_student_id, v_year.label,
                    v_level.cycle, v_grade_level_code,
                    coalesce(v_level.year_number, 1),
                    v_class_id,
                    (select c.name from public.classes c where c.id = v_class_id),
                    0, 'promoted',
                    'Enrollment record created by the student-application approval (migration 0116, T-413).'
                )
                on conflict (student_id, academic_year) do nothing;
            end if;
        end if;

        v_audit_id := public.write_audit_log(
            p_tenant_id   := v_request.tenant_id,
            p_action      := 'student.create',
            p_entity_type := 'student',
            p_entity_id   := v_student_id,
            p_actor_id    := p_reviewer_profile_id,
            p_after_json  := jsonb_build_object(
                'source', 'approve_student_application (migration 0116)',
                'student_code', v_student_code,
                'parent_id', v_parent_id,
                'class_id', v_class_id,
                'grade_level_code', v_grade_level_code
            ),
            p_note        := 'Created student during student-application approval'
        );
    end if;

    -- ------------------------------------------------------------------
    -- Reuse the canonical approval: role assignment + profile activation +
    -- binding + its own audit entries (0005/0047 — the §6 rule).
    -- A student-role approval binds the STUDENT; a parent-role approval
    -- binds the PARENT (0005 semantics preserved verbatim).
    -- ------------------------------------------------------------------
    if v_request.requested_role = 'student' then
        v_role_id := public.approve_account_request(
            p_request_id,
            p_reviewer_profile_id,
            null,
            v_student_id,
            p_decision_note
        );
    else
        v_role_id := public.approve_account_request(
            p_request_id,
            p_reviewer_profile_id,
            v_parent_id,
            null,
            p_decision_note
        );
    end if;

    return jsonb_build_object(
        'student_id', v_student_id,
        'student_code', v_student_code,
        'parent_id', v_parent_id,
        'role_id', v_role_id,
        'created_student', v_is_new_student
    );
end;
$function$
;
comment on function approve_student_application(uuid,uuid,text,uuid,uuid,jsonb,jsonb) is 'T-413 / STUDENT-100: the ONE composite student-application approval — binds an existing student or creates the canonical student record (deterministic parent code, ELV student code, class enrollment, student_academic_histories entry) and activates the account by REUSING approve_account_request internally. SECURITY DEFINER called by the approve-signup-request EF after caller-role verification.';

create or replace function public.attribute_academic_year(p_date date, p_tenant_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select coalesce(
        -- Known academic_years row containing the date (latest start wins).
        (
            select ay.label
              from public.academic_years ay
             where ay.tenant_id = p_tenant_id
               and p_date between ay.start_date and ay.end_date
             order by ay.start_date desc
             limit 1
        ),
        -- Algerian school-year convention (financial-rules §15, INV-14):
        -- July–December starts the YYYY-(YYYY+1) year; January–June belongs
        -- to (YYYY-1)-YYYY.
        case
            when extract(month from p_date) >= 7 then
                extract(year from p_date)::int::text || '-' || (extract(year from p_date)::int + 1)::text
            else
                (extract(year from p_date)::int - 1)::text || '-' || extract(year from p_date)::int::text
        end
    );
$function$
;
comment on function attribute_academic_year(date,uuid) is 'T-405 / INV-14: attribute a date to an academic year — the tenant academic_years window first, then the Jul1–Jun30 Algerian school-year convention.';

create or replace function public.audit_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_entity   text;
    v_action   text;
    v_entity_id uuid;
    v_tenant   uuid;
    v_actor_id  uuid;
    v_actor_name text;
    v_actor_role text;
    v_before   jsonb;
    v_after    jsonb;
    v_row      jsonb;
begin
    -- Snapshots (updated_at stripped — the touch trigger always rewrites it).
    if TG_OP = 'UPDATE' then
        v_before := to_jsonb(OLD) - 'updated_at';
        v_after  := to_jsonb(NEW) - 'updated_at';
        -- No-op guard: only the touch timestamp changed → not a mutation.
        if v_before is not distinct from v_after then
            return null;
        end if;
    elsif TG_OP = 'INSERT' then
        v_before := null;
        v_after  := to_jsonb(NEW) - 'updated_at';
    else -- DELETE
        v_before := to_jsonb(OLD) - 'updated_at';
        v_after  := null;
    end if;

    v_row := case TG_OP when 'DELETE' then to_jsonb(OLD) else to_jsonb(NEW) end;

    -- Entity + action mapping (AuditActions wire-code style: entity.action).
    v_entity := (case TG_TABLE_NAME
        when 'parents'                   then 'parent'
        when 'students'                  then 'student'
        when 'pricing_configs'           then 'pricing_config'
        when 'grade_level_tuition'       then 'pricing_grade'
        when 'transport_destinations'    then 'pricing_transport'
        when 'complementary_services'    then 'pricing_complementary_service'
        when 'additional_services'       then 'pricing_additional_service'
        when 'discounts'                 then 'pricing_discount'
        else TG_TABLE_NAME
    end);
    v_action := v_entity || '.' ||
        (case TG_OP when 'INSERT' then 'create' when 'UPDATE' then 'update' else 'delete' end);

    v_entity_id := (v_row ->> 'id')::uuid;

    -- Tenant resolution: CRM rows carry tenant_id; pricing children resolve
    -- through their pricing_config.
    if TG_TABLE_NAME in ('parents', 'students', 'pricing_configs') then
        v_tenant := (v_row ->> 'tenant_id')::uuid;
    else
        v_tenant := (select pc.tenant_id
                       from public.pricing_configs pc
                      where pc.id = (v_row ->> 'pricing_config_id')::uuid);
    end if;
    if v_tenant is null then
        v_tenant := public.current_tenant_id();
    end if;
    -- Defensive: an unresolvable tenant must NEVER roll back the business
    -- write — skip the audit row and warn (observable in Postgres logs).
    if v_tenant is null then
        raise warning 'audit_row_change: tenant unresolvable for % %', TG_OP, TG_TABLE_NAME;
        return null;
    end if;

    -- Actor attribution (auth context; NULL under service-role jobs).
    select id into v_actor_id
      from public.user_profiles
     where auth_user_id = auth.uid()
     limit 1;
    if v_actor_id is not null then
        select coalesce(display_name, email) into v_actor_name
          from public.user_profiles
         where id = v_actor_id;
        select r.code into v_actor_role
          from public.role_assignments ra
          join public.roles r on r.id = ra.role_id
         where ra.user_profile_id = v_actor_id
           and ra.revoked_at is null
         order by r.code
         limit 1;
    else
        v_actor_name := 'System';
        v_actor_role := null;
    end if;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := v_action,
        p_entity_type := v_entity,
        p_entity_id   := v_entity_id,
        p_actor_id    := v_actor_id,
        p_actor_name  := v_actor_name,
        p_actor_role  := v_actor_role,
        p_before_json := v_before,
        p_after_json  := v_after,
        p_note        := 'Capture automatique (déclencheur ' || TG_OP || ' sur ' || TG_TABLE_NAME || ')'
    );

    return null;
end;
$function$
;
comment on function audit_row_change() is 'T-306: shared row-level audit trigger — writes a write_audit_log entry (full before/after snapshots + actor attribution) for every real INSERT/UPDATE/DELETE on the CRM + pricing entity tables. No-op updates (touch-only) are skipped.';

create or replace function public.batch_register_family(p_tenant_id uuid, p_parent jsonb, p_students jsonb, p_actor_profile_id uuid, p_activation_code text DEFAULT NULL::text)
 RETURNS TABLE(parent_id uuid, student_ids uuid[])
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_parent_id uuid;
    v_student_ids uuid[] := '{}';
    v_student_id uuid;
    v_student jsonb;
    v_parent_code text;
    v_student_code text;
    v_seq integer;
    v_activation_code text;
    v_audit_id uuid;
begin
    -- DRIFT-001 / T-115 (migration 0065): the parent code is CANONICAL and
    -- DETERMINISTIC — FNV-1a of the identity fields, exactly like the
    -- desktop's SupabaseParentRepository and the approve-signup-request EF.
    -- The unique (tenant_id, parent_code) constraint then refuses duplicate
    -- family registrations for the same identity — that refusal IS the
    -- canonical idempotency contract ("the dedup match IS the code").
    if coalesce(btrim(p_parent->>'primary_phone'), '') = ''
       and coalesce(btrim(p_parent->>'display_name'), '') = ''
       and coalesce(btrim(p_parent->>'first_name'), '') = ''
       and coalesce(btrim(p_parent->>'last_name'), '') = '' then
        raise exception 'batch_register_family: parent identity fields required (primary_phone / display_name / first_name / last_name) — the canonical code generator has no random fallback (DRIFT-001, migration 0065)';
    end if;

    v_parent_code := public.fn_deterministic_parent_code(
        extract(year from now())::int,
        p_parent->>'primary_phone',
        p_parent->>'display_name',
        p_parent->>'first_name',
        p_parent->>'last_name'
    );

    -- Insert parent
    insert into public.parents (
        tenant_id, parent_code, first_name, last_name, primary_phone,
        secondary_phone, email, national_id, occupation, address, city,
        postal_code, relationship, notes, is_active, created_at, updated_at
    ) values (
        p_tenant_id, v_parent_code,
        p_parent->>'first_name', p_parent->>'last_name', p_parent->>'primary_phone',
        p_parent->>'secondary_phone', p_parent->>'email', p_parent->>'national_id',
        p_parent->>'occupation', p_parent->>'address', p_parent->>'city',
        p_parent->>'postal_code', p_parent->>'relationship', p_parent->>'notes',
        true, now(), now()
    )
    returning id into v_parent_id;

    -- Insert students (sequential ELV-{year}-{6-digit} — canonical student
    -- format per core/format/id.ts; DRIFT-001's RPC finding targets the
    -- PARENT code, the deterministic-ELV variant belongs to the
    -- sync/import upsert paths).
    for v_student in select * from jsonb_array_elements(p_students)
    loop
        v_seq := nextval('public.student_seq');
        v_student_code := 'ELV-' || extract(year from now())::text || '-' || lpad(v_seq::text, 6, '0');

        insert into public.students (
            tenant_id, parent_id, student_code, first_name, middle_name, last_name,
            date_of_birth, gender, grade_level_id, class_id, enrollment_date,
            enrollment_status, medical_notes, is_active, created_at, updated_at
        ) values (
            p_tenant_id, v_parent_id, v_student_code,
            v_student->>'first_name', v_student->>'middle_name', v_student->>'last_name',
            (v_student->>'date_of_birth')::date,
            v_student->>'gender',
            nullif(v_student->>'grade_level_id', '')::uuid,
            nullif(v_student->>'class_id', '')::uuid,
            current_date, 'enrolled', v_student->>'medical_notes',
            true, now(), now()
        )
        returning id into v_student_id;
        v_student_ids := array_append(v_student_ids, v_student_id);
    end loop;

    -- Issue activation code (or use provided one).
    -- DRIFT-001 / T-115: the DEFAULT is now the canonical DETERMINISTIC code
    -- (same family -> same activation code on retry). Collision fallback:
    -- the 6-digit space can collide across parents in a tenant (~3.7% at
    -- 259 parents); on a collision with a DIFFERENT parent's unbound code,
    -- fall back to the random-with-uniqueness generator (safety first).
    if p_activation_code is not null then
        v_activation_code := p_activation_code;
    else
        v_activation_code := public.fn_deterministic_activation_code(v_parent_code, p_tenant_id);
        if exists (
            select 1 from public.activation_codes ac
             where ac.tenant_id = p_tenant_id
               and ac.code = v_activation_code
               and ac.bound_to_auth_user_id is null
               and ac.parent_id is distinct from v_parent_id
        ) then
            v_activation_code := public.generate_activation_code(p_tenant_id);
        end if;
    end if;

    insert into public.activation_codes (
        tenant_id, code, parent_id, issued_by, issued_at, expires_at
    ) values (
        p_tenant_id, v_activation_code, v_parent_id, p_actor_profile_id, now(), now() + interval '30 days'
    );

    -- Write audit log
    v_audit_id := public.write_audit_log(
        p_tenant_id := p_tenant_id,
        p_action := 'parent.batch_register',
        p_entity_type := 'parent',
        p_entity_id := v_parent_id,
        p_actor_id := p_actor_profile_id,
        p_before_json := null,
        p_after_json := jsonb_build_object('parent_id', v_parent_id, 'student_ids', v_student_ids, 'activation_code', v_activation_code, 'parent_code', v_parent_code, 'code_rule', 'deterministic_fnv1a_0065'),
        p_note := 'Atomic batch registration: parent + ' || cardinality(v_student_ids) || ' students (canonical deterministic parent code, migration 0065)'
    );

    return query select v_parent_id, v_student_ids;
end;
$function$
;
comment on function batch_register_family(uuid,jsonb,jsonb,uuid,text) is 'T-115 / DRIFT-001 (migration 0065): parent code is the canonical DETERMINISTIC PAR-{year}-{FNV-1a 6-hex} of the identity fields (empty identity REJECTED — no random fallback); default activation code is deterministic with a collision fallback to generate_activation_code; student codes stay sequential ELV-{year}-{6-digit}. The unique (tenant_id, parent_code) constraint is the idempotency gate: re-registering the same identity is refused. Supersedes 0036''s "backend fallback only" guard comment.';

create or replace function public.bind_activation_code(p_tenant_id uuid, p_code text, p_auth_user_id uuid)
 RETURNS TABLE(parent_id uuid, parent_full_name text, student_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
    v_activation record;
    v_parent_id uuid;
    v_existing_auth_user_id uuid;
    v_caller_is_service_role boolean;
begin
    -- ── SEC-110: caller verification ─────────────────────────────────
    -- Direct PostgREST callers (user JWT) must bind THEMSELVES only.
    -- The bind-activation-code Edge Function calls via service_role
    -- after verifying the caller's JWT (ctx.userId = the verified
    -- auth.users.id) — service_role is trusted server-side code.
    -- Anonymous / forged-token callers: auth.uid() IS NULL → rejected.
    v_caller_is_service_role := coalesce(auth.jwt() ->> 'role', '') = 'service_role';

    if p_auth_user_id is null then
        raise exception 'bind_activation_code: p_auth_user_id is required (SEC-110)';
    end if;

    if not v_caller_is_service_role
       and (auth.uid() is null or p_auth_user_id <> auth.uid()) then
        raise exception 'bind_activation_code: p_auth_user_id must match the authenticated caller (SEC-110)';
    end if;

    -- Lock the activation code row
    select * into v_activation
      from public.activation_codes
     where tenant_id = p_tenant_id
       and code = p_code
       and bound_to_auth_user_id is null
     for update;

    if not found then
        raise exception 'Invalid or already-used activation code';
    end if;

    if v_activation.expires_at < now() then
        raise exception 'Activation code has expired';
    end if;

    v_parent_id := v_activation.parent_id;

    -- ── STUDENT-101: silent re-bind guard ────────────────────────────
    -- Refuse to transfer a parent record that is already bound to a
    -- DIFFERENT auth user. Re-binding the SAME user (retry after a
    -- partial failure) stays allowed.
    select auth_user_id into v_existing_auth_user_id
      from public.parents
     where id = v_parent_id
     for update;

    if v_existing_auth_user_id is not null
       and v_existing_auth_user_id <> p_auth_user_id then
        raise exception 'bind_activation_code: parent % is already bound to another account — contact the school office', v_parent_id;
    end if;

    -- Mark the code as bound
    update public.activation_codes
       set bound_to_auth_user_id = p_auth_user_id,
           bound_at = now()
     where id = v_activation.id;

    -- Bind the auth.users.id to the parent record
    update public.parents
       set auth_user_id = p_auth_user_id
     where id = v_parent_id;

    -- ── PARENT-103: audit the direct-RPC path ────────────────────────
    -- The EF path already writes its own richer audit entry
    -- (activation_code.bind, with request id) AFTER this RPC returns;
    -- auditing from here too would duplicate it. Direct PostgREST
    -- callers bypass the EF entirely, so THIS path is audited here.
    if not v_caller_is_service_role then
        insert into public.audit_logs (
            id, tenant_id, action, entity_type, entity_id,
            actor_id, actor_name, after_json, note, occurred_at
        ) values (
            public.gen_uuid(), p_tenant_id, 'activation_code.bind_rpc', 'parent', v_parent_id,
            null, 'direct-rpc-caller',
            jsonb_build_object('activation_code', p_code, 'auth_user_id', p_auth_user_id),
            'bind_activation_code called directly via PostgREST (not via the Edge Function)',
            now()
        );
    end if;

    -- Return parent + student count for the response
    return query
        select p.id as parent_id,
               (p.first_name || ' ' || p.last_name) as parent_full_name,
               count(s.id)::bigint as student_count
          from public.parents p
          left join public.students s on s.parent_id = p.id and s.deleted_at is null
         where p.id = v_parent_id
         group by p.id, p.first_name, p.last_name;
end;
$function$
;
comment on function bind_activation_code(uuid,text,uuid) is 'Atomically binds an activation code to the calling user''s auth.users.id. Marks code as used. Updates parents.auth_user_id. Returns parent info + student count.';

create or replace function public.chat_channels_derive_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
    if exists (
        select 1
          from unnest(new.member_ids) as m
         where not public.profile_has_staff_role_in_tenant(m, new.tenant_id)
    ) then
        new.scope := 'portal';
    else
        new.scope := 'internal';
    end if;
    return new;
end;
$function$
;
comment on function chat_channels_derive_scope() is 'CHAT-300 (0135): forces chat_channels.scope from member composition — any NON-staff member (parent/student, or a profile with no employee roles) makes the channel ''portal''; only all-employee member sets are ''internal''. Runs BEFORE INSERT and before every UPDATE so a client-supplied scope value never survives. Uses the row''s OWN tenant (NEW.tenant_id), not current_tenant_id().';

create or replace function public.collect_and_allocate_payment(p_tenant_id uuid, p_parent_id uuid, p_student_id uuid, p_amount numeric, p_method text, p_category text, p_installment_id uuid, p_proof_path text, p_notes text, p_actor_id uuid, p_actor_name text, p_check_number text DEFAULT NULL::text, p_check_bank_name text DEFAULT NULL::text, p_check_issue_date date DEFAULT NULL::date, p_check_clearance_date date DEFAULT NULL::date, p_transfer_reference text DEFAULT NULL::text, p_transfer_source_bank text DEFAULT NULL::text, p_as_of timestamp with time zone DEFAULT now())
 RETURNS TABLE(payment_id uuid, receipt_number text, payment_status text, total_allocated numeric, unallocated_credit numeric, allocations jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_year INT := EXTRACT(YEAR FROM NOW()); v_seq INT; v_receipt TEXT; v_status TEXT;
  v_payment_id UUID := gen_random_uuid(); v_ledger_id TEXT; v_remaining NUMERIC;
  v_alloc JSONB := '[]'::JSONB; v_alloc_item JSONB; v_ins RECORD; v_unallocated NUMERIC := 0;
  v_account_id TEXT; v_ins_remaining NUMERIC; v_allocate NUMERIC; v_new_paid NUMERIC;
  v_new_pending NUMERIC; v_new_status TEXT; v_fully BOOLEAN;
  -- T-310: the RESOLVED actor (name + role).
  v_actor_name TEXT; v_actor_role TEXT;
  -- T-436: the payment-made year (INV-18) + the allocation target year.
  v_payment_year_id UUID;
BEGIN
  IF p_amount <= 0 THEN RAISE EXCEPTION 'Payment amount must be > 0 (got %)', p_amount; END IF;

  -- T-436 (ADR-030): the payment's academic year — the tenant window
  -- containing the collection date (NULL when outside: the read-side
  -- INV-14 fallback resolves it).
  v_payment_year_id := public.resolve_academic_year_id_for_date(
      (p_as_of AT TIME ZONE 'UTC')::date, p_tenant_id);

  -- T-310 (AUDIT-502): resolve the actor ONCE, up-front.
  IF p_actor_name IS NOT NULL AND p_actor_name <> '' AND p_actor_name <> p_actor_id::TEXT THEN
    v_actor_name := p_actor_name;
  ELSE
    SELECT coalesce(up.display_name, up.email) INTO v_actor_name
      FROM public.user_profiles up
     WHERE up.id = p_actor_id OR up.auth_user_id = p_actor_id
     ORDER BY (up.id = p_actor_id) DESC
     LIMIT 1;
    v_actor_name := coalesce(v_actor_name, 'System');
  END IF;
  SELECT r.code INTO v_actor_role
    FROM public.role_assignments ra
    JOIN public.roles r ON r.id = ra.role_id
   WHERE ra.user_profile_id = (
         SELECT up.id FROM public.user_profiles up
          WHERE up.id = p_actor_id OR up.auth_user_id = p_actor_id
          ORDER BY (up.id = p_actor_id) DESC LIMIT 1)
     AND ra.revoked_at IS NULL
   ORDER BY r.code
   LIMIT 1;

  v_status := CASE WHEN p_method = 'cash' THEN 'paid' ELSE 'pending' END;

  SELECT COALESCE(MAX(CAST(SUBSTRING(pay.receipt_number FROM '\d{6}$') AS INT)), 0) + 1 INTO v_seq
  FROM payments pay
  WHERE pay.tenant_id = p_tenant_id AND pay.receipt_number LIKE 'REC-' || v_year || '-%';
  v_receipt := 'REC-' || v_year || '-' || LPAD(v_seq::TEXT, 6, '0');

  -- ADR-023: p_category NULL = multi-service — stored as NULL (the payments
  -- row renders "Multi-services"; per-service truth lives in
  -- payment_allocations). Concrete categories are stored verbatim (T-060).
  INSERT INTO payments (
    id, tenant_id, payment_number, receipt_number, parent_id, student_id, amount,
    method, status, category, installment_id, proof_path, notes,
    check_number, check_bank_name, check_issue_date, check_clearance_date,
    transfer_reference, transfer_source_bank,
    collected_by, collected_at, created_at, updated_at,
    academic_year_id
  ) VALUES (
    v_payment_id, p_tenant_id, v_receipt, v_receipt, p_parent_id, p_student_id, p_amount,
    p_method, v_status, p_category, p_installment_id, p_proof_path, p_notes,
    p_check_number, p_check_bank_name, p_check_issue_date, p_check_clearance_date,
    p_transfer_reference, p_transfer_source_bank,
    p_actor_id, p_as_of, p_as_of, p_as_of,
    v_payment_year_id
  );

  -- ADR-023: the cross-category payment entry books ONE entry (the revert
  -- RPC reverses a single entry by source_id) on the synthetic account
  -- `parent:{id}:category:all` with a NULL category. Parent-level replay
  -- (Σ signed balances) reduces the outstanding correctly; per-category
  -- views read payment_allocations.
  v_account_id := 'parent:' || p_parent_id || ':category:' || COALESCE(p_category, 'all');
  IF p_student_id IS NOT NULL THEN v_account_id := v_account_id || ':student:' || p_student_id; END IF;
  v_ledger_id := 'led-' || EXTRACT(EPOCH FROM NOW()) || '-' || SUBSTRING(gen_random_uuid()::TEXT, 1, 8);
  INSERT INTO ledger_entries (
    entry_number, tenant_id, account_id, parent_id, student_id, category, amount,
    entry_type, source_type, source_id, method, receipt_number, payment_status,
    reverses_id, description, actor_id, actor_name, at, metadata
  ) VALUES (
    v_ledger_id, p_tenant_id, v_account_id, p_parent_id, p_student_id,
    p_category, -p_amount, 'payment', 'payment', v_payment_id::TEXT,
    p_method, v_receipt, v_status, NULL,
    'Encaissement ' || v_receipt || ' — ' || p_method || ' (' || COALESCE(p_category, 'multi-services') || ')',
    p_actor_id::TEXT, v_actor_name, p_as_of,
    JSONB_BUILD_OBJECT(
      'installmentId', p_installment_id, 'proofUrl', p_proof_path,
      'checkNumber', p_check_number, 'checkBankName', p_check_bank_name,
      'checkIssueDate', p_check_issue_date, 'checkClearanceDate', p_check_clearance_date,
      'transferReference', p_transfer_reference, 'transferSourceBank', p_transfer_source_bank
    )
  );

  v_remaining := p_amount;
  IF v_status = 'paid' THEN
    FOR v_ins IN
      SELECT id, amount_due, amount_paid, amount_pending, due_date, status, category, label,
             academic_year_id
      FROM installments
      WHERE parent_id = p_parent_id AND status <> 'paid'
        AND (p_category IS NULL OR category = p_category)
      ORDER BY due_date ASC, id ASC FOR UPDATE
    LOOP
      EXIT WHEN v_remaining <= 0;
      -- BUSINESS-107 (INV-4): the cleared branch now subtracts
      -- amount_pending too — a cheque pending on the tranche reduces the
      -- capacity for a subsequent CASH payment, so paid + pending can
      -- never exceed due.
      v_ins_remaining := GREATEST(0, v_ins.amount_due - v_ins.amount_paid - v_ins.amount_pending);
      IF v_ins_remaining <= 0 THEN CONTINUE; END IF;
      v_allocate := LEAST(v_remaining, v_ins_remaining);
      v_new_paid := v_ins.amount_paid + v_allocate;
      v_new_pending := v_ins.amount_pending;
      v_fully := v_new_paid >= v_ins.amount_due;
      IF v_fully THEN v_new_status := 'paid';
      ELSIF v_new_paid > 0 THEN v_new_status := 'partial';
      ELSE v_new_status := CASE WHEN v_ins.status = 'overdue' THEN 'overdue' ELSE 'pending' END; END IF;
      UPDATE installments
        SET amount_paid = v_new_paid, amount_pending = v_new_pending,
            status = v_new_status,
            paid_date = CASE WHEN v_new_status = 'paid' THEN COALESCE(paid_date, p_as_of) ELSE paid_date END
        WHERE id = v_ins.id;
      -- DATA-029: the canonical per-payment coverage record (T-330 chain).
      -- Concrete category per row — including for cross-category payments.
      -- T-436: the SETTLEMENT-TARGET year (INV-18c/18d) — the allocated
      -- installment's persisted year, resolved through the INV-14 window
      -- when the row predates the column.
      INSERT INTO payment_allocations (
        id, tenant_id, payment_id, charge_id, installment_id, category,
        allocated_amount, label, created_at, academic_year_id
      ) VALUES (
        gen_random_uuid(), p_tenant_id, v_payment_id, NULL, v_ins.id,
        v_ins.category, v_allocate, v_ins.label, p_as_of,
        COALESCE(v_ins.academic_year_id,
                 public.resolve_academic_year_id_for_date(v_ins.due_date, p_tenant_id))
      );
      v_alloc_item := JSONB_BUILD_OBJECT('installmentId', v_ins.id,
        'allocatedAmount', v_allocate, 'newAmountPaid', v_new_paid,
        'newAmountPending', v_new_pending, 'newStatus', v_new_status,
        'fullySatisfied', v_fully, 'cleared', TRUE, 'category', v_ins.category);
      v_alloc := v_alloc || JSONB_BUILD_ARRAY(v_alloc_item);
      v_remaining := v_remaining - v_allocate;
    END LOOP;
    v_unallocated := GREATEST(0, v_remaining);
    IF v_unallocated > 0 THEN
      INSERT INTO ledger_entries (
        entry_number, tenant_id, account_id, parent_id, student_id, category, amount,
        entry_type, source_type, source_id, method, receipt_number, payment_status,
        reverses_id, description, actor_id, actor_name, at, metadata
      ) VALUES (
        'led-' || EXTRACT(EPOCH FROM NOW()) || '-' || SUBSTRING(gen_random_uuid()::TEXT, 1, 8),
        p_tenant_id, 'parent:' || p_parent_id || ':category:parent_credit',
        p_parent_id, NULL, 'parent_credit', -v_unallocated,
        'adjustment', 'adjustment', 'credit-' || v_payment_id::TEXT,
        NULL, NULL, NULL, NULL,
        'Crédit parent (excédent de paiement reçu ' || v_receipt || ')',
        p_actor_id::TEXT, v_actor_name, p_as_of,
        JSONB_BUILD_OBJECT('sourcePaymentId', v_payment_id, 'unallocatedAmount', v_unallocated)
      );
    END IF;
  ELSE
    FOR v_ins IN
      SELECT id, amount_due, amount_paid, amount_pending, due_date, status, category, label,
             academic_year_id
      FROM installments
      WHERE parent_id = p_parent_id AND status <> 'paid'
        AND (p_category IS NULL OR category = p_category)
      ORDER BY due_date ASC, id ASC FOR UPDATE
    LOOP
      EXIT WHEN v_remaining <= 0;
      v_ins_remaining := GREATEST(0, v_ins.amount_due - v_ins.amount_paid - v_ins.amount_pending);
      IF v_ins_remaining <= 0 THEN CONTINUE; END IF;
      v_allocate := LEAST(v_remaining, v_ins_remaining);
      v_new_paid := v_ins.amount_paid;
      v_new_pending := v_ins.amount_pending + v_allocate;
      v_new_status := 'pending_clearance'; v_fully := FALSE;
      UPDATE installments
        SET amount_paid = v_new_paid, amount_pending = v_new_pending,
            status = v_new_status, paid_date = paid_date
        WHERE id = v_ins.id;
      -- DATA-029: pending allocations are recorded too (cleared = FALSE is
      -- derivable from the payment's status; the amount is the commitment).
      -- T-436: the settlement-target year, same as the cleared branch.
      INSERT INTO payment_allocations (
        id, tenant_id, payment_id, charge_id, installment_id, category,
        allocated_amount, label, created_at, academic_year_id
      ) VALUES (
        gen_random_uuid(), p_tenant_id, v_payment_id, NULL, v_ins.id,
        v_ins.category, v_allocate, v_ins.label, p_as_of,
        COALESCE(v_ins.academic_year_id,
                 public.resolve_academic_year_id_for_date(v_ins.due_date, p_tenant_id))
      );
      v_alloc_item := JSONB_BUILD_OBJECT('installmentId', v_ins.id,
        'allocatedAmount', v_allocate, 'newAmountPaid', v_new_paid,
        'newAmountPending', v_new_pending, 'newStatus', v_new_status,
        'fullySatisfied', FALSE, 'cleared', FALSE, 'category', v_ins.category);
      v_alloc := v_alloc || JSONB_BUILD_ARRAY(v_alloc_item);
      v_remaining := v_remaining - v_allocate;
    END LOOP;
    v_unallocated := GREATEST(0, v_remaining);
    -- No parent_credit insert for pending funds (canonical defers until clearance)
  END IF;

  -- 6. Audit log (T-310 canonical columns preserved verbatim).
  INSERT INTO audit_logs (
    id, tenant_id, action, entity_type, entity_id, actor_id, actor_name, actor_role,
    before_json, after_json, diff, note, created_at
  ) VALUES (
    gen_random_uuid(), p_tenant_id, 'payment.collect', 'payment', v_payment_id,
    p_actor_id, v_actor_name, v_actor_role,
    NULL,
    JSONB_BUILD_OBJECT(
      'amount', p_amount, 'method', p_method, 'receipt', v_receipt,
      'status', v_status, 'allocations', v_alloc,
      'unallocatedCredit', v_unallocated, 'category', p_category,
      'paymentAcademicYearId', v_payment_year_id
    ),
    JSONB_BUILD_OBJECT(
      'amount', p_amount, 'method', p_method, 'receipt', v_receipt,
      'status', v_status, 'allocations', v_alloc,
      'unallocatedCredit', v_unallocated, 'category', p_category,
      'paymentAcademicYearId', v_payment_year_id
    ),
    'Encaissement atomique via RPC collect_and_allocate_payment (canonical 0034 + structured fields; 0115 INV-4/cross-category; 0127 T-436 year stamping)',
    p_as_of
  );

  RETURN QUERY SELECT v_payment_id, v_receipt, v_status,
    p_amount - v_unallocated, v_unallocated, v_alloc;
END;
$function$
;

create or replace function public.compute_account_balance(p_account_id text, p_as_of timestamp with time zone DEFAULT now())
 RETURNS TABLE(account_id text, balance numeric, total_charged numeric, total_paid numeric, total_adjusted numeric, total_refunded numeric, total_cleared numeric, total_pending numeric, unallocated_credit numeric)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  RETURN QUERY
    SELECT
      p_account_id,
      COALESCE(SUM(le.amount) FILTER (WHERE le.at <= p_as_of), 0),
      -- CANONICAL REVERSAL SEMANTICS: an entry is excluded from TYPED totals
      -- when another entry's reverses_id points at it (matches the desktop's
      -- reversedIds set). The previous `reverses_id IS NULL` filter kept the
      -- reversed ORIGINAL in the totals while excluding the reversal rows —
      -- inflating total_paid for every refunded payment.
      COALESCE(SUM(le.amount) FILTER (WHERE le.entry_type = 'charge' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0),
      COALESCE(SUM(ABS(le.amount)) FILTER (WHERE le.entry_type = 'payment' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0),
      COALESCE(SUM(le.amount) FILTER (WHERE le.entry_type = 'adjustment' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0),
      COALESCE(SUM(ABS(le.amount)) FILTER (WHERE le.entry_type = 'refund' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0),
      COALESCE(SUM(ABS(le.amount)) FILTER (WHERE le.entry_type = 'payment' AND le.payment_status = 'paid' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0),
      COALESCE(SUM(ABS(le.amount)) FILTER (WHERE le.entry_type = 'payment' AND le.payment_status = 'pending' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0),
      COALESCE(SUM(le.amount) FILTER (WHERE le.entry_type = 'adjustment' AND le.category = 'parent_credit' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0)
    -- FRESH-DB FIX: `account_id` is an output column of the RETURNS TABLE —
    -- qualify with the table alias to avoid the ambiguity error.
    FROM ledger_entries le
    WHERE le.account_id = p_account_id;
END;
$function$
;
comment on function compute_account_balance(text,timestamp with time zone) is 'Canonical single-account balance replay (migration 0034 + 0035 guard).
This is the ONLY function that may compute a single account balance.';

create or replace function public.compute_assessments_subject_average()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_c1  NUMERIC;
    v_c2  NUMERIC;
    v_c3  NUMERIC;
    v_cc  NUMERIC;
    v_num NUMERIC := 0;
    v_den NUMERIC := 0;
BEGIN
    -- Legacy row with no component marks at all — leave the stored value.
    IF NEW.devoir1 IS NULL AND NEW.devoir2 IS NULL
       AND NEW.examen IS NULL AND NEW.cc IS NULL THEN
        RETURN NEW;
    END IF;

    -- Weight snapshots (the values in force at entry — ADR-018 §3).
    v_c1 := COALESCE(NEW.coefficient_devoir1, 1.00);
    v_c2 := COALESCE(NEW.coefficient_devoir2, 1.00);
    v_c3 := COALESCE(NEW.coefficient_examen, 2.00);
    v_cc := COALESCE(NEW.coefficient_cc, 0.00);

    -- A positive-weight component is REQUIRED: any missing one makes the
    -- average not computable (NULL — the T-336 honesty rule).
    IF v_c1 > 0 AND NEW.devoir1 IS NULL THEN NEW.subject_average := NULL; RETURN NEW; END IF;
    IF v_c2 > 0 AND NEW.devoir2 IS NULL THEN NEW.subject_average := NULL; RETURN NEW; END IF;
    IF v_c3 > 0 AND NEW.examen IS NULL THEN NEW.subject_average := NULL; RETURN NEW; END IF;
    IF v_cc > 0 AND NEW.cc      IS NULL THEN NEW.subject_average := NULL; RETURN NEW; END IF;

    IF v_c1 > 0 THEN v_num := v_num + NEW.devoir1 * v_c1; v_den := v_den + v_c1; END IF;
    IF v_c2 > 0 THEN v_num := v_num + NEW.devoir2 * v_c2; v_den := v_den + v_c2; END IF;
    IF v_c3 > 0 THEN v_num := v_num + NEW.examen * v_c3; v_den := v_den + v_c3; END IF;
    IF v_cc > 0 THEN v_num := v_num + NEW.cc      * v_cc; v_den := v_den + v_cc; END IF;

    IF v_den = 0 THEN
        NEW.subject_average := NULL;
        RETURN NEW;
    END IF;

    NEW.subject_average := ROUND((v_num / v_den)::numeric, 2);
    RETURN NEW;
END;
$function$
;
comment on function compute_assessments_subject_average() is 'Canonical subject average = (D1×c1 + D2×c2 + Ex×c3)/(c1+c2+c3), NULL unless all three marks are present (plan §13.03). Mirrors the grades-table trigger from 0004 and the desktop/Android engines bit-for-bit.';

create or replace function public.compute_debt_aging_rows(p_tenant_id uuid, p_as_of timestamp with time zone)
 RETURNS TABLE(tenant_id uuid, parent_id uuid, parent_name text, parent_phone text, student_ids uuid[], outstanding_amount numeric, oldest_due_date date, debt_age_days integer, origin_academic_year text, last_payment_at timestamp with time zone, days_since_last_payment integer, inactivity_days integer, subsequent_year_payment_count integer, subsequent_year_payment_total numeric, has_subsequent_year_payments boolean, obligations jsonb, status_level text, reason_code text, computed_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
    -- T-432: the tenant's academic-year windows, materialized ONCE. When
    -- p_tenant_id IS NULL (the matview's all-tenants usage) the CTE carries
    -- EVERY tenant's windows and the attribution subqueries correlate on the
    -- row's own tenant_id.
    -- T-436: the CTE additionally carries ay.id — the persisted-column
    -- precedence (INV-18a) resolves through it.
    with ay as (
        select ayw.tenant_id, ayw.id as ay_id, ayw.label, ayw.start_date, ayw.end_date
          from public.academic_years ayw
         where p_tenant_id is null or ayw.tenant_id = p_tenant_id
    ),
    oblig as (
        select i.tenant_id,
               i.parent_id,
               i.id as installment_id,
               i.student_id,
               i.category,
               i.label,
               greatest(0, i.amount_due - i.amount_paid - i.amount_pending) as remaining,
               i.due_date,
               i.academic_year_id
          from public.installments i
         where (p_tenant_id is null or i.tenant_id = p_tenant_id)
           and greatest(0, i.amount_due - i.amount_paid - i.amount_pending) > 0
    ),
    -- T-436: the OLDEST outstanding obligation (min due date, then min
    -- installment id — the §15 ordering) WITH its own attribution inputs,
    -- so the origin year follows the persisted column of THAT obligation.
    oldest_oblig as (
        select distinct on (o.tenant_id, o.parent_id)
               o.tenant_id, o.parent_id, o.due_date, o.academic_year_id
          from oblig o
         order by o.tenant_id, o.parent_id, o.due_date, o.installment_id
    ),
    per_parent as (
        select o.tenant_id,
               o.parent_id,
               sum(o.remaining) as outstanding_amount,
               min(o.due_date) as oldest_due_date
          from oblig o
         group by o.tenant_id, o.parent_id
    ),
    attributed as (
        select pp.tenant_id,
               pp.parent_id,
               pp.outstanding_amount,
               pp.oldest_due_date,
               -- T-436 (INV-18a — the ONE precedence): the oldest
               -- obligation's PERSISTED year first (resolved through the
               -- materialized windows), then the INV-14 convention on its
               -- due date (byte-identical to 0126 when the column is NULL).
               coalesce(
                   (select a.label
                      from ay a
                     where a.tenant_id = oo.tenant_id
                       and a.ay_id = oo.academic_year_id
                     limit 1),
                   (select a.label
                      from ay a
                     where a.tenant_id = oo.tenant_id
                       and oo.due_date between a.start_date and a.end_date
                     order by a.start_date desc
                     limit 1),
                   case
                       when extract(month from oo.due_date) >= 7 then
                           extract(year from oo.due_date)::int::text || '-' || (extract(year from oo.due_date)::int + 1)::text
                       else
                           (extract(year from oo.due_date)::int - 1)::text || '-' || extract(year from oo.due_date)::int::text
                   end
               ) as origin_academic_year
          from per_parent pp
          join oldest_oblig oo
            on oo.tenant_id = pp.tenant_id
           and oo.parent_id = pp.parent_id
    ),
    pay as (
        select e.parent_id, e.entry_date, e.amount, e.source_id
          from public.ledger_entries e
         where e.entry_type = 'payment'
           and (p_tenant_id is null or e.tenant_id = p_tenant_id)
           -- Reversal exclusion mirrors the TS engine (computeAccountBalance's
           -- reversedIds): a payment reversed by ANY entry is not payment behavior.
           and not exists (
               select 1 from public.ledger_entries r
                where r.reverses_entry_id = e.id
           )
    ),
    pay_last as (
        select pl.parent_id, max(pl.entry_date) as last_payment_at
          from pay pl
         group by pl.parent_id
    ),
    pay_sub as (
        select a.parent_id,
               count(ps.entry_date) as subsequent_year_payment_count,
               coalesce(sum(abs(ps.amount)), 0) as subsequent_year_payment_total
          from attributed a
          join pay ps
            on ps.parent_id = a.parent_id
           -- T-436 (INV-18): the payment's year — the PERSISTED
           -- payments.academic_year_id first (joined through the ledger
           -- entry's source_id = the payment id), then the INV-14
           -- attribution of the entry date. The keying on a.tenant_id is
           -- the 0126 parity note, preserved.
           and public.academic_year_start(
                   coalesce(
                       (select ay2.label
                          from ay ay2
                         where ay2.tenant_id = a.tenant_id
                           and ay2.ay_id = (
                               select pr.academic_year_id
                                 from public.payments pr
                                where pr.id::text = ps.source_id
                                  and (p_tenant_id is null or pr.tenant_id = a.tenant_id)
                           )
                         limit 1),
                       (select ay2.label
                          from ay ay2
                         where ay2.tenant_id = a.tenant_id
                           and (ps.entry_date at time zone 'UTC')::date between ay2.start_date and ay2.end_date
                         order by ay2.start_date desc
                         limit 1),
                       case
                           when extract(month from (ps.entry_date at time zone 'UTC')::date) >= 7 then
                               extract(year from (ps.entry_date at time zone 'UTC')::date)::int::text || '-' || (extract(year from (ps.entry_date at time zone 'UTC')::date)::int + 1)::text
                           else
                               (extract(year from (ps.entry_date at time zone 'UTC')::date)::int - 1)::text || '-' || extract(year from (ps.entry_date at time zone 'UTC')::date)::int::text
                       end
                   )
               ) > public.academic_year_start(a.origin_academic_year)
         group by a.parent_id
    ),
    oblig_detail as (
        select o.tenant_id,
               o.parent_id,
               jsonb_agg(
                   jsonb_build_object(
                       'installmentId', o.installment_id::text,
                       'studentId', o.student_id::text,
                       'category', o.category,
                       'label', o.label,
                       'remaining', o.remaining,
                       'dueDate', to_char(o.due_date, 'YYYY-MM-DD'),
                       -- T-436 (INV-18a): the per-obligation year — the
                       -- persisted column first, the INV-14 rule fallback.
                       'academicYear', coalesce(
                           (select ay3.label
                              from ay ay3
                             where ay3.tenant_id = o.tenant_id
                               and ay3.ay_id = o.academic_year_id
                             limit 1),
                           (select ay3.label
                              from ay ay3
                             where ay3.tenant_id = o.tenant_id
                               and o.due_date between ay3.start_date and ay3.end_date
                             order by ay3.start_date desc
                             limit 1),
                           case
                               when extract(month from o.due_date) >= 7 then
                                   extract(year from o.due_date)::int::text || '-' || (extract(year from o.due_date)::int + 1)::text
                               else
                                   (extract(year from o.due_date)::int - 1)::text || '-' || extract(year from o.due_date)::int::text
                           end
                       ),
                       'daysOverdue', greatest(0, floor(extract(epoch from (p_as_of - o.due_date::timestamptz)) / 86400))::int
                   ) order by o.due_date, o.installment_id
               ) as obligations,
               coalesce(
                   array_agg(distinct o.student_id) filter (where o.student_id is not null),
                   array[]::uuid[]
               ) as student_ids
          from oblig o
         group by o.tenant_id, o.parent_id
    ),
    -- The per-parent FACTORS, computed once (the INV-16 evaluation inputs).
    -- NOTE the never-paid semantics: inactivity is CASE-based, NOT
    -- greatest(0, coalesce(...)) — postgres GREATEST IGNORES NULLs, so
    -- `greatest(0, floor(p_as_of - NULL))` collapses to 0 and a never-paid
    -- parent would look perfectly active (the live-caught defect this
    -- restructure fixed; INV-16b demands inactivity = debt age there).
    factors as (
        select
            a.tenant_id,
            a.parent_id,
            a.outstanding_amount,
            a.oldest_due_date,
            a.origin_academic_year,
            greatest(0, floor(extract(epoch from (p_as_of - a.oldest_due_date::timestamptz)) / 86400))::int as debt_age_days,
            plast.last_payment_at,
            case when plast.last_payment_at is null then null
                 else greatest(0, floor(extract(epoch from (p_as_of - plast.last_payment_at)) / 86400))::int
            end as days_since_last_payment,
            -- §15 inactivity: last-payment recency; never-paid → debt age
            -- (INV-16b).
            case when plast.last_payment_at is null
                 then greatest(0, floor(extract(epoch from (p_as_of - a.oldest_due_date::timestamptz)) / 86400))::int
                 else greatest(0, floor(extract(epoch from (p_as_of - plast.last_payment_at)) / 86400))::int
            end as inactivity_days,
            coalesce(psub.subsequent_year_payment_count, 0) as subsequent_year_payment_count,
            coalesce(psub.subsequent_year_payment_total, 0) as subsequent_year_payment_total
          from attributed a
          left join pay_last plast on plast.parent_id = a.parent_id
          left join pay_sub psub on psub.parent_id = a.parent_id
         where a.outstanding_amount > 0.001
    )
    select
        p.tenant_id,
        p.id as parent_id,
        -- Name resolution mirrors the DebtTab's seedSummary convention:
        -- display_name first, falling back to first + last.
        coalesce(
            nullif(trim(p.display_name), ''),
            trim(coalesce(p.first_name, '') || ' ' || coalesce(p.last_name, ''))
        ) as parent_name,
        p.primary_phone as parent_phone,
        od.student_ids,
        f.outstanding_amount,
        f.oldest_due_date,
        f.debt_age_days,
        f.origin_academic_year,
        f.last_payment_at,
        f.days_since_last_payment,
        f.inactivity_days,
        f.subsequent_year_payment_count,
        f.subsequent_year_payment_total,
        f.subsequent_year_payment_count > 0 as has_subsequent_year_payments,
        od.obligations,
        -- ── The ordered INV-16 evaluation (mirrors the TS engine exactly).
        --    Pre-T-429 labels; the 0125 wrapper overrides these two columns
        --    with the configurable 4-tier hierarchy (0111's factors are the
        --    canonical inputs — the wrapper discards these status values). ──
        case
            when f.outstanding_amount <= 0.001 then 'green'
            when f.inactivity_days <= 60 then 'green'
            when f.debt_age_days > 180 and f.inactivity_days > 180 then 'red'
            when f.debt_age_days > 90 and f.inactivity_days > 60 then 'orange'
            else 'yellow'
        end as status_level,
        case
            when f.outstanding_amount <= 0.001 then 'resolved'
            when f.inactivity_days <= 60 then 'active_payer'
            when f.debt_age_days > 180 and f.inactivity_days > 180 then 'critical_delinquency'
            when f.debt_age_days > 90 and f.inactivity_days > 60 then 'sustained_delinquency'
            else 'watch'
        end as reason_code,
        p_as_of as computed_at
    from factors f
    join public.parents p
      on p.id = f.parent_id
     and p.tenant_id = f.tenant_id
     and p.deleted_at is null
    join oblig_detail od on od.tenant_id = f.tenant_id and od.parent_id = f.parent_id
$function$
;
comment on function compute_debt_aging_rows(uuid,timestamp with time zone) is 'T-405 + T-432 + T-436: the single cross-year debt-aging computation — installments (INV-4 remaining) + non-reversed payment ledger entries + academic-year attribution (INV-18a precedence: the persisted installments.academic_year_id first, then the INV-14 window/convention fallback; the payments table supplies the persisted payment-year for subsequent-year attribution) → the ordered INV-16 status. Ungated internal (owner-only); use compute_debt_aging_summary from clients.';

create or replace function public.compute_debt_aging_summary(p_as_of timestamp with time zone DEFAULT now())
 RETURNS TABLE(parent_id uuid, parent_name text, parent_phone text, student_ids uuid[], outstanding_amount numeric, oldest_due_date date, debt_age_days integer, origin_academic_year text, last_payment_at timestamp with time zone, days_since_last_payment integer, inactivity_days integer, subsequent_year_payment_count integer, subsequent_year_payment_total numeric, has_subsequent_year_payments boolean, obligations jsonb, status_level text, reason_code text, applied_thresholds jsonb, computed_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
declare
    v_tenant uuid;
    v_grace integer;
    v_yellow integer;
    v_red integer;
    v_active integer;
begin
    -- Gate 1 — staff roles (the installments_select staff branch).
    if not public.has_any_role(array['super_admin', 'financial_officer', 'support_staff']) then
        raise exception 'forbidden: debt aging is a staff surface';
    end if;

    -- Gate 2 — tenant scope (SECURITY DEFINER bypasses the RLS that would
    -- normally scope reads; current_tenant_id() is the canonical resolver).
    v_tenant := public.current_tenant_id();
    if v_tenant is null then
        raise exception 'forbidden: no tenant context';
    end if;

    -- T-429: the configurable thresholds for THIS tenant (defaults if unseeded).
    select t.grace_period_days, t.yellow_days, t.red_days, t.active_payer_grace_days
      into v_grace, v_yellow, v_red, v_active
      from public.debt_aging_thresholds(v_tenant) t;

    return query
    select r.parent_id,
           r.parent_name,
           r.parent_phone,
           r.student_ids,
           r.outstanding_amount,
           r.oldest_due_date,
           r.debt_age_days,
           r.origin_academic_year,
           r.last_payment_at,
           r.days_since_last_payment,
           r.inactivity_days,
           r.subsequent_year_payment_count,
           r.subsequent_year_payment_total,
           r.has_subsequent_year_payments,
           r.obligations,
           -- ── The T-429 4-tier hierarchy (mirrors the TS engine exactly):
           --    pure due-date aging over the INV-4 remaining; the
           --    active-payer rule is REMOVED from the status inputs. ──
           case
               when r.outstanding_amount <= 0.001 then 'green'
               when r.debt_age_days <= coalesce(v_grace, 5) then 'green'
               when r.debt_age_days <= coalesce(v_yellow, 15) then 'yellow'
               when r.debt_age_days <= coalesce(v_red, 60) then 'orange'
               else 'red'
           end as status_level,
           case
               when r.outstanding_amount <= 0.001 then 'resolved'
               when r.debt_age_days <= coalesce(v_grace, 5) then 'not_due'
               when r.debt_age_days <= coalesce(v_yellow, 15) then 'watch'
               when r.debt_age_days <= coalesce(v_red, 60) then 'sustained_delinquency'
               else 'critical_delinquency'
           end as reason_code,
           -- T-443: the EXACT values that shaped this row's status — the
           -- client renders its explanation/parity from these, so the
           -- displayed numbers can never disagree with the server's verdict.
           jsonb_build_object(
               'gracePeriodDays', coalesce(v_grace, 5),
               'yellowDays', coalesce(v_yellow, 15),
               'redDays', coalesce(v_red, 60),
               'activePayerGraceDays', coalesce(v_active, 15)
           ) as applied_thresholds,
           r.computed_at
      from public.compute_debt_aging_rows(v_tenant, coalesce(p_as_of, now())) r
     order by r.outstanding_amount desc, r.parent_id;
end;
$function$
;
comment on function compute_debt_aging_summary(timestamp with time zone) is 'T-405 + T-429 + T-443: the staff debt-aging query contract — one row per debtor (installment outstanding > 0.001 DZD) with the 4-TIER CONFIGURABLE status (financial-rules §15.1 as amended: the thresholds live in system_settings category `debt`; the active-payer rule is decoupled — an annotation, never a status input) AND the applied_thresholds jsonb (the exact values used, so the client explanation/parity matches the verdict by construction). Gate: super_admin/financial_officer/support_staff + current tenant.';

create or replace function public.compute_gpa(p_student_id uuid, p_term integer DEFAULT NULL::integer)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select
        case
            when sum(coefficient) = 0 then null
            else round((sum(subject_average * coefficient) / sum(coefficient))::numeric, 2)
        end
    from public.grades g
    join public.class_subjects cs on cs.id = g.class_subject_id
    where g.student_id = p_student_id
      and g.subject_average is not null
      and (p_term is null or exists (
          select 1 from public.assessments a where a.id = g.assessment_id and a.term = p_term
      ));
$function$
;
comment on function compute_gpa(uuid,integer) is 'Overall GPA = sum(subject_average * coefficient) / sum(coefficient) per plan §13.03.';

create or replace function public.compute_grade_subject_average()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
    v_term integer;
    v_class_subject_id uuid := new.class_subject_id;
    v_student_id uuid := new.student_id;
    v_d1 numeric;
    v_d2 numeric;
    v_ex numeric;
begin
    -- Determine the term from the assessment
    select term into v_term from public.assessments where id = new.assessment_id;
    if v_term is null then
        return new;
    end if;

    -- Look up D1, D2, Examen scores for this student/subject/term
    select g.score into v_d1
      from public.grades g
      join public.assessments a on a.id = g.assessment_id
     where g.student_id = v_student_id
       and g.class_subject_id = v_class_subject_id
       and a.term = v_term
       and a.kind = 'devoir_1';

    select g.score into v_d2
      from public.grades g
      join public.assessments a on a.id = g.assessment_id
     where g.student_id = v_student_id
       and g.class_subject_id = v_class_subject_id
       and a.term = v_term
       and a.kind = 'devoir_2';

    select g.score into v_ex
      from public.grades g
      join public.assessments a on a.id = g.assessment_id
     where g.student_id = v_student_id
       and g.class_subject_id = v_class_subject_id
       and a.term = v_term
       and a.kind = 'examen';

    -- BUG FIX (TIER 4): the lookups above only see rows ALREADY IN THE TABLE.
    -- When the completing mark (e.g. the examen) is being INSERTED, its own
    -- lookup returned NULL and the average was never computed — the compute
    -- path could only fire on a subsequent UPDATE. NEW's own score is now
    -- substituted for its kind so the average is set on the completing row.
    if new.assessment_id in (
        select id from public.assessments
         where term = v_term and kind = 'devoir_1'
           and class_subject_id = v_class_subject_id
    ) then
        v_d1 := new.score;
    elsif new.assessment_id in (
        select id from public.assessments
         where term = v_term and kind = 'devoir_2'
           and class_subject_id = v_class_subject_id
    ) then
        v_d2 := new.score;
    elsif new.assessment_id in (
        select id from public.assessments
         where term = v_term and kind = 'examen'
           and class_subject_id = v_class_subject_id
    ) then
        v_ex := new.score;
    end if;

    if v_d1 is not null and v_d2 is not null and v_ex is not null then
        new.subject_average := round(((v_d1 + v_d2 + 2 * v_ex) / 4.0)::numeric, 2);
    end if;

    return new;
end;
$function$
;
comment on function compute_grade_subject_average() is 'Auto-computes subject_average = (D1 + D2 + 2*Examen) / 4 per plan §13.03. Triggered on every grade insert/update.';

create or replace function public.compute_parent_summary(p_parent_id uuid, p_as_of timestamp with time zone DEFAULT now())
 RETURNS TABLE(parent_id uuid, total_outstanding numeric, total_overdue numeric, total_charged numeric, total_paid numeric, total_adjusted numeric, total_refunded numeric, total_cleared numeric, total_pending numeric, total_unallocated_credit numeric, account_count integer, accounts jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_accounts JSONB := '[]'::JSONB;
  v_total_outstanding NUMERIC := 0;
  v_total_overdue NUMERIC := 0;
  v_total_charged NUMERIC := 0;
  v_total_paid NUMERIC := 0;
  v_total_adjusted NUMERIC := 0;
  v_total_refunded NUMERIC := 0;
  v_total_cleared NUMERIC := 0;
  v_total_pending NUMERIC := 0;
  v_total_unallocated_credit NUMERIC := 0;
  v_account_count INT := 0;
  v_acc RECORD;
  v_latest_charge_due_date TIMESTAMPTZ;
BEGIN
  FOR v_acc IN
    SELECT
      le.account_id,
      le.category,
      le.student_id,
      SUM(le.amount) FILTER (WHERE le.at <= p_as_of) AS balance,
      COALESCE(SUM(le.amount) FILTER (WHERE le.entry_type = 'charge' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0) AS charged,
      COALESCE(SUM(ABS(le.amount)) FILTER (WHERE le.entry_type = 'payment' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0) AS paid,
      COALESCE(SUM(le.amount) FILTER (WHERE le.entry_type = 'adjustment' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0) AS adjusted,
      COALESCE(SUM(ABS(le.amount)) FILTER (WHERE le.entry_type = 'refund' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0) AS refunded,
      COALESCE(SUM(ABS(le.amount)) FILTER (WHERE le.entry_type = 'payment' AND le.payment_status = 'paid' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0) AS cleared,
      COALESCE(SUM(ABS(le.amount)) FILTER (WHERE le.entry_type = 'payment' AND le.payment_status = 'pending' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0) AS pending,
      COALESCE(SUM(le.amount) FILTER (WHERE le.entry_type = 'adjustment' AND le.category = 'parent_credit' AND le.at <= p_as_of AND NOT EXISTS (SELECT 1 FROM ledger_entries rev WHERE rev.tenant_id = le.tenant_id AND (rev.reverses_id = le.id::text OR rev.reverses_id = le.entry_number))), 0) AS unallocated_credit
    FROM ledger_entries le
    WHERE le.parent_id = p_parent_id
    GROUP BY le.account_id, le.category, le.student_id
  LOOP
    v_account_count := v_account_count + 1;

    -- Determine if the account is overdue — canonical mirror of the desktop
    -- engine's buildOverdueDueDateMap + computeParentSummary (INV-4 + INV-10,
    -- equivalence finding A-0042-OVERDUE):
    --   overdueDueDate[accountId] = MAX(charge.at) over ALL of the account's
    --   charge entries — NO as-of filter, NO reversal filter, and NO
    --   installment due_date JOIN (the app engines classify on the charge
    --   entry's own timestamp). The account is overdue iff
    --   balance > 0.001 DZD AND that latest-charge timestamp < p_as_of.
    SELECT MAX(le.at) INTO v_latest_charge_due_date
      FROM ledger_entries le
      WHERE le.account_id = v_acc.account_id
        AND le.entry_type = 'charge';

    DECLARE
      v_is_overdue BOOLEAN := (v_acc.balance > 0.001 AND v_latest_charge_due_date IS NOT NULL AND v_latest_charge_due_date < p_as_of);
    BEGIN
      v_accounts := v_accounts || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
        'accountId', v_acc.account_id,
        'category', v_acc.category,
        'studentId', v_acc.student_id,
        'balance', COALESCE(v_acc.balance, 0),
        'totalCharged', COALESCE(v_acc.charged, 0),
        'totalPaid', COALESCE(v_acc.paid, 0),
        'totalAdjusted', COALESCE(v_acc.adjusted, 0),
        'totalRefunded', COALESCE(v_acc.refunded, 0),
        'totalCleared', COALESCE(v_acc.cleared, 0),
        'totalPending', COALESCE(v_acc.pending, 0),
        'unallocatedCredit', COALESCE(v_acc.unallocated_credit, 0),
        'isOverdue', v_is_overdue
      ));

      v_total_outstanding := v_total_outstanding + COALESCE(v_acc.balance, 0);
      v_total_charged := v_total_charged + COALESCE(v_acc.charged, 0);
      v_total_paid := v_total_paid + COALESCE(v_acc.paid, 0);
      v_total_adjusted := v_total_adjusted + COALESCE(v_acc.adjusted, 0);
      v_total_refunded := v_total_refunded + COALESCE(v_acc.refunded, 0);
      v_total_cleared := v_total_cleared + COALESCE(v_acc.cleared, 0);
      v_total_pending := v_total_pending + COALESCE(v_acc.pending, 0);
      v_total_unallocated_credit := v_total_unallocated_credit + COALESCE(v_acc.unallocated_credit, 0);

      IF v_is_overdue THEN
        v_total_overdue := v_total_overdue + COALESCE(v_acc.balance, 0);
      END IF;
    END;
  END LOOP;

  RETURN QUERY
    SELECT
      p_parent_id,
      v_total_outstanding,
      v_total_overdue,
      v_total_charged,
      v_total_paid,
      v_total_adjusted,
      v_total_refunded,
      v_total_cleared,
      v_total_pending,
      v_total_unallocated_credit,
      v_account_count,
      v_accounts;
END;
$function$
;

create or replace function public.create_direct_channel(p_other_profile_id uuid, p_name text DEFAULT NULL::text)
 RETURNS chat_channels
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_me     uuid := public.current_user_profile_id();
    v_tenant uuid := public.current_tenant_id();
    v_a      uuid;
    v_b      uuid;
    v_code   text;
    v_ch     public.chat_channels;
begin
    if v_me is null then
        raise exception 'create_direct_channel: no user profile for the caller (auth.uid() has no user_profiles row)'
            using errcode = '42501';
    end if;
    if v_tenant is null then
        raise exception 'create_direct_channel: caller has no tenant (global admins must act inside a tenant context)'
            using errcode = '42501';
    end if;
    -- T-400: the full STAFF role set (0023 census minus parent/student) —
    -- the workforce employee roles are staff; parents stay read+reply by
    -- design (their path is open_parent_admin_channel, 0067).
    if not public.has_any_role(array[
        'super_admin', 'manager', 'support_staff', 'financial_officer', 'teacher',
        'worker', 'buyer', 'driver', 'warehouse_worker'
    ]) then
        raise exception 'create_direct_channel: only staff may create chat channels (parents are read+reply by design)'
            using errcode = '42501';
    end if;
    if p_other_profile_id is null or p_other_profile_id = v_me then
        raise exception 'create_direct_channel: p_other_profile_id must be a different profile from the caller'
            using errcode = '22023';
    end if;
    -- The other member must be a real profile of the same tenant (or a
    -- global-admin profile). Guards against fabricated member ids.
    if not exists (
        select 1 from public.user_profiles up
         where up.id = p_other_profile_id
           and (up.tenant_id = v_tenant or up.tenant_id is null)
    ) then
        raise exception 'create_direct_channel: other profile not found in the caller''s tenant'
            using errcode = '22023';
    end if;

    v_a := least(v_me, p_other_profile_id);
    v_b := greatest(v_me, p_other_profile_id);
    v_code := 'DM-' || v_a || '-' || v_b;

    insert into public.chat_channels (
        tenant_id, code, name, channel_type, member_ids, created_by, description
    ) values (
        v_tenant, v_code, coalesce(nullif(btrim(p_name), ''), 'Direct'), 'direct',
        array[v_a, v_b], v_me, null
    )
    on conflict (tenant_id, code) do nothing
    returning * into v_ch;

    if v_ch is null then
        -- Already exists (idempotent re-open by either member of the pair).
        select * into v_ch
          from public.chat_channels
         where tenant_id = v_tenant and code = v_code;
    end if;

    if v_ch is null then
        raise exception 'create_direct_channel: channel vanished after upsert'
            using errcode = '22023';
    end if;

    -- Audit the creation (mock parity: chat.channel_create; convention 0014).
    if v_ch.created_by = v_me then
        insert into public.audit_logs (
            tenant_id, action, entity_type, entity_id, actor_id, after_json, note
        ) values (
            v_tenant, 'chat.channel_create', 'chat_channel', v_ch.id, v_me,
            to_jsonb(v_ch), 'create_direct_channel (idempotent RPC)'
        );
    end if;

    return v_ch;
end;
$function$
;
comment on function create_direct_channel(uuid,text) is 'CHAT-103 canonical path: idempotent 1:1 direct channel creation, staff-only (T-400: the full employee role set — worker/buyer/driver/warehouse_worker included; parents remain read+reply by design via 0067). Deterministic code from the sorted member pair (same pair always maps to the same channel). SECURITY DEFINER with full caller verification (staff gate + target-exists + fixed direct type) — see migration header; returns only a channel the caller belongs to.';

create or replace function public.create_manual_debt(p_parent_id text, p_student_id text, p_category text, p_label text, p_amount_due numeric, p_due_date date, p_academic_year text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text)
 RETURNS TABLE(installment_id uuid, ledger_entry_id uuid, academic_year_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant      uuid := public.current_tenant_id();
    v_parent      uuid := public.resolve_parent_ref(v_tenant, p_parent_id);
    v_student     uuid := public.resolve_student_ref(v_tenant, p_student_id);
    v_label       text := nullif(btrim(coalesce(p_label, '')), '');
    v_note        text := nullif(btrim(coalesce(p_note, '')), '');
    v_reference   text := nullif(btrim(coalesce(p_reference, '')), '');
    v_year_id     uuid;
    v_ins_id      uuid;
    v_ledger_id   uuid;
    v_entry_no    text;
    v_description text;
    v_account_id  text;
begin
    -- Gate 1 — staff roles (the installments_admin policy's audience).
    if not public.has_any_role(array['super_admin', 'financial_officer', 'support_staff']) then
        raise exception 'forbidden: manual debt creation is a staff financial write';
    end if;

    -- Gate 2 — the refs must resolve (the upsert_installment_from_import errors).
    if v_parent is null then
        raise exception 'create_manual_debt: unresolvable parent ref %', p_parent_id;
    end if;
    if v_student is null then
        raise exception 'create_manual_debt: unresolvable student ref %', p_student_id;
    end if;

    -- Gate 3 — the contract guards (fail closed, before any write).
    if v_label is null or length(v_label) < 3 then
        raise exception 'create_manual_debt: the label (the reason) is required (>= 3 chars)';
    end if;
    if p_amount_due is null or p_amount_due <= 0 then
        raise exception 'create_manual_debt: the amount must be strictly positive';
    end if;
    if p_due_date is null then
        raise exception 'create_manual_debt: the due date is required';
    end if;
    if p_category is null or btrim(p_category) = '' then
        raise exception 'create_manual_debt: the category is required';
    end if;

    -- The academic-year stamp — the SAME precedence the import path applies
    -- (0127/0129): explicit code/label match first, then the INV-14 window
    -- resolver on the due date. Frozen at write time (ADR-030 / INV-18b).
    if p_academic_year is not null and nullif(btrim(p_academic_year), '') is not null then
        select ay.id into v_year_id
          from public.academic_years ay
         where ay.tenant_id = v_tenant
           and (ay.code = btrim(p_academic_year) or ay.label = btrim(p_academic_year))
         order by ay.start_date desc
         limit 1;
    end if;
    if v_year_id is null then
        v_year_id := public.resolve_academic_year_id_for_date(p_due_date, v_tenant);
    end if;

    -- The deterministic ledger identity (the led-{ISO}-{rand} convention).
    v_entry_no := 'led-' || to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
                  || '-' || substr(md5(gen_random_uuid()::text), 1, 8);

    v_description := 'Dette manuelle — ' || v_label
                     || (case when v_note is not null then ' · ' || v_note else '' end)
                     || (case when v_reference is not null then ' · réf. ' || v_reference else '' end);

    -- The charge lands on the student-scoped account when the debt is
    -- student-anchored (the adjust() R1.5 convention), else parent-scoped.
    v_account_id := 'parent:' || v_parent || ':category:' || p_category
                    || ':student:' || v_student;

    -- ------------------------------------------------------------------
    -- Write 1/3 — the INSTALLMENT row (the canonical debt record).
    -- ------------------------------------------------------------------
    v_ins_id := public.gen_uuid();
    insert into public.installments (
        id, tenant_id, parent_id, student_id, category, label,
        tranche_number, amount_due, amount_paid, amount_pending,
        due_date, paid_date, status,
        source_type, source_id,
        created_at, updated_at
    ) values (
        v_ins_id, v_tenant, v_parent, v_student, p_category, v_label,
        null, p_amount_due, 0, 0,
        p_due_date, null, 'unpaid',
        'manual_entry', 'manual-' || v_entry_no,
        now(), now()
    );

    -- ------------------------------------------------------------------
    -- Write 2/3 — the LEDGER charge entry (the billing-wire pattern: every
    -- new obligation is both an installment row and a charge entry).
    -- ------------------------------------------------------------------
    v_ledger_id := public.gen_uuid();
    insert into public.ledger_entries (
        id, tenant_id, entry_number, parent_id, student_id, account_id,
        entry_type, amount, category, description, entry_date,
        source_type, source_id, method, receipt_number, payment_status,
        reverses_id, actor_id, actor_name, at, metadata
    ) values (
        v_ledger_id, v_tenant, v_entry_no, v_parent, v_student, v_account_id,
        'charge', p_amount_due, p_category, v_description,
        (p_due_date::timestamptz at time zone 'UTC'),
        'manual_entry', 'manual-' || v_entry_no, null, null, null,
        null, p_actor_id::text, p_actor_name, now(),
        jsonb_build_object(
            'manual', true,
            'installmentId', v_ins_id,
            'note', v_note,
            'reference', v_reference,
            'reason', v_label,
            'source', 'create_manual_debt'
        )
    );

    -- ------------------------------------------------------------------
    -- Write 3/3 — the AUDIT row (the payment.collect pattern).
    -- ------------------------------------------------------------------
    insert into public.audit_logs (
        id, tenant_id, action, entity_type, entity_id, actor_id, actor_name,
        before_json, after_json, diff, note, created_at
    ) values (
        public.gen_uuid(), v_tenant, 'installment.manual_debt_created', 'installment', v_ins_id,
        p_actor_id, p_actor_name,
        null,
        jsonb_build_object(
            'installmentId', v_ins_id, 'ledgerEntryId', v_ledger_id,
            'parentId', v_parent, 'studentId', v_student,
            'category', p_category, 'label', v_label,
            'amountDue', p_amount_due, 'dueDate', p_due_date,
            'academicYearId', v_year_id, 'reference', v_reference
        ),
        jsonb_build_object(
            'installmentId', v_ins_id, 'ledgerEntryId', v_ledger_id,
            'parentId', v_parent, 'studentId', v_student,
            'category', p_category, 'label', v_label,
            'amountDue', p_amount_due, 'dueDate', p_due_date,
            'academicYearId', v_year_id, 'reference', v_reference
        ),
        'Dette manuelle créée via RPC create_manual_debt (T-466/DEBT-102 — la voie canonique)',
        now()
    );

    return query select v_ins_id, v_ledger_id, v_year_id;
end;
$function$
;
comment on function create_manual_debt(text,text,text,text,numeric,date,text,text,text,uuid,text) is 'T-466 (DEBT-102): the canonical manual-debt write path — one installments row (source_type=manual_entry, tranche_number NULL = non-wave, academic_year_id stamped via the explicit-code-then-INV-14 precedence) + the matching ledger charge entry + the audit row. The created obligation flows into every debt surface (Créances, aging statuses, Year Tracking, Dashboard statistics, CRM échéancier) and allocates through the canonical payment waterfall exactly like a tranche.';

create or replace function public.create_pricing_config_for_year(p_academic_year_id uuid, p_label text, p_clone_from_active boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant uuid;
    v_year public.academic_years%rowtype;
    v_new_id uuid;
    v_source_id uuid;
    v_count integer;
begin
    -- Gate 1 — staff roles (same surface as pricing writes).
    if not public.has_any_role(array['super_admin', 'financial_officer']) then
        raise exception 'forbidden: pricing configuration is a staff surface'
            using errcode = '42501';
    end if;

    -- Gate 2 — tenant scope.
    v_tenant := public.current_tenant_id();
    if v_tenant is null then
        raise exception 'forbidden: no tenant context'
            using errcode = '42501';
    end if;

    -- Gate 3 — the academic year must exist and belong to the tenant.
    select * into v_year
      from public.academic_years
     where id = p_academic_year_id;

    if v_year.id is null then
        raise exception 'academic year not found: %', p_academic_year_id
            using errcode = '22023';
    end if;

    if v_year.tenant_id <> v_tenant then
        raise exception 'forbidden: academic year belongs to another tenant'
            using errcode = '42501';
    end if;

    -- Gate 4 — one config per (tenant, year) — the 0006 unique constraint,
    -- surfaced as a friendly error instead of a raw 23505.
    select count(*) into v_count
      from public.pricing_configs
     where tenant_id = v_tenant
       and academic_year_id = p_academic_year_id;

    if v_count > 0 then
        raise exception 'a pricing configuration already exists for academic year % (%)', v_year.label, v_year.id
            using errcode = '23505';
    end if;

    -- The active config (clone source) — resolved AFTER the uniqueness gate
    -- so the clone is optional even when no active config exists.
    select id into v_source_id
      from public.pricing_configs
     where tenant_id = v_tenant
       and is_active
     order by updated_at desc
     limit 1;

    -- Create the config (INACTIVE — activation is the separate explicit
    -- set_active_pricing_config step, per ADR-025 §3 create-then-activate).
    insert into public.pricing_configs (
        tenant_id, academic_year_id, label,
        registration_fee, late_penalty_per_day, second_apron_fee,
        early_payment_bonus_pct, early_payment_deadline,
        is_active
    )
    values (
        v_tenant, p_academic_year_id,
        coalesce(nullif(btrim(p_label), ''), 'Tarification ' || v_year.label),
        coalesce((select pc.registration_fee
                    from public.pricing_configs pc
                   where pc.id = v_source_id), 5000.00),
        coalesce((select pc.late_penalty_per_day
                    from public.pricing_configs pc
                   where pc.id = v_source_id), 100.00),
        coalesce((select pc.second_apron_fee
                    from public.pricing_configs pc
                   where pc.id = v_source_id), 2000.00),
        coalesce((select pc.early_payment_bonus_pct
                    from public.pricing_configs pc
                   where pc.id = v_source_id), 5.00),
        (select pc.early_payment_deadline
           from public.pricing_configs pc
          where pc.id = v_source_id),
        false
    )
    returning id into v_new_id;

    -- Clone the five child grids from the ACTIVE config (year-over-year
    -- changes become a delta the owner edits before activating).
    if p_clone_from_active and v_source_id is not null then
        insert into public.grade_level_tuition (
            pricing_config_id, academic_level_id, annual_amount,
            tranche_1_amount, tranche_2_amount, tranche_3_amount,
            tranche_1_month, tranche_2_month, tranche_3_month,
            registration_fee
        )
        select v_new_id, t.academic_level_id, t.annual_amount,
               t.tranche_1_amount, t.tranche_2_amount, t.tranche_3_amount,
               t.tranche_1_month, t.tranche_2_month, t.tranche_3_month,
               t.registration_fee
          from public.grade_level_tuition t
         where t.pricing_config_id = v_source_id;

        insert into public.transport_destinations (
            pricing_config_id, code, label_fr, label_ar,
            annual_amount, tranche_1_amount, tranche_2_amount, tranche_3_amount,
            tranche_1_month, tranche_2_month, tranche_3_month
        )
        select v_new_id, t.code, t.label_fr, t.label_ar,
               t.annual_amount, t.tranche_1_amount, t.tranche_2_amount, t.tranche_3_amount,
               t.tranche_1_month, t.tranche_2_month, t.tranche_3_month
          from public.transport_destinations t
         where t.pricing_config_id = v_source_id;

        insert into public.complementary_services (
            pricing_config_id, code, label_fr, label_ar,
            semester_amount, annual_amount, billing_model, is_active
        )
        select v_new_id, t.code, t.label_fr, t.label_ar,
               t.semester_amount, t.annual_amount, t.billing_model, t.is_active
          from public.complementary_services t
         where t.pricing_config_id = v_source_id;

        insert into public.additional_services (
            pricing_config_id, code, label_fr, label_ar,
            amount, billing_model, is_active
        )
        select v_new_id, t.code, t.label_fr, t.label_ar,
               t.amount, t.billing_model, t.is_active
          from public.additional_services t
         where t.pricing_config_id = v_source_id;

        insert into public.discounts (
            pricing_config_id, code, label_fr, discount_type, amount,
            applies_to, is_active
        )
        select v_new_id, t.code, t.label_fr, t.discount_type, t.amount,
               t.applies_to, t.is_active
          from public.discounts t
         where t.pricing_config_id = v_source_id;
    end if;

    -- 0086 pricing mutation triggers audit the config + children inserts.
    return v_new_id;
end;
$function$
;
comment on function create_pricing_config_for_year(uuid,text,boolean) is 'T-414 / PRICING-500 / ADR-025: prepares the pricing configuration for an academic year (optionally cloning the ACTIVE config''s five child grids — tuition, transport, complementary, additional, discounts). The new config is created INACTIVE; activation is the separate explicit set_active_pricing_config step. Gates: super_admin/financial_officer + current tenant + year-in-tenant + one-config-per-year (0006 unique constraint surfaced as a friendly 23505).';

create or replace function public.current_tenant_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    -- Tenant is resolved from the user's profile or from the JWT app metadata.
    select coalesce(
        (select tenant_id from public.user_profiles where auth_user_id = auth.uid() limit 1),
        (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid
    );
$function$
;
comment on function current_tenant_id() is 'Resolve the caller''s tenant_id from their profile or JWT app_metadata. SECURITY DEFINER (owner postgres, BYPASSRLS) so RLS policies can call it without re-entering the user_profiles policy. Stable, RLS-safe.';

create or replace function public.current_user_permissions()
 RETURNS text[]
 LANGUAGE sql
 STABLE
AS $function$
    -- Global admins receive every permission code (matches the prior
    -- service_role-style "all permissions" behavior, but now via the
    -- RBAC resolver so the EF shared-helper `extractAuthContext` path
    -- also works for non-super_admin global admins — SEC-109 partial).
    select case
        when public.is_global_admin()
        then coalesce(array_agg(p.code), '{}')
        else (
            -- Effective permissions = default matrix for current roles
            -- IN THE CURRENT TENANT + tenant overrides (deny wins).
            with role_ids as (
                select role_id from public.role_assignments
                where user_profile_id = public.current_user_profile_id()
                  and tenant_id = public.current_tenant_id()  -- TENANT-SCOPE FIX (TENANT-100)
                  and revoked_at is null
            ),
            default_perms as (
                select p.code, true as granted
                from role_permissions rp
                join permissions p on p.id = rp.permission_id
                where rp.role_id in (select role_id from role_ids)
            ),
            overrides as (
                select p.code, (o.action = 'grant') as granted
                from tenant_role_overrides o
                join permissions p on p.id = o.permission_id
                where o.tenant_id = public.current_tenant_id()
                  and o.role_id in (select role_id from role_ids)
            )
            select coalesce(array_agg(distinct code), '{}')
            from (
                select code from default_perms where code not in (select code from overrides where granted = false)
                union
                select code from overrides where granted = true
            ) effective
        )
    end
    from public.permissions p;
$function$
;
comment on function current_user_permissions() is 'Array of effective permission codes after applying tenant overrides (deny wins).';

create or replace function public.current_user_profile_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select id from public.user_profiles where auth_user_id = auth.uid() limit 1;
$function$
;
comment on function current_user_profile_id() is 'Resolve the caller''s user_profiles.id from auth.uid(). SECURITY DEFINER (owner postgres, BYPASSRLS) so RLS policies can call it without re-entering the user_profiles policy. Stable, RLS-safe.';

create or replace function public.current_user_roles()
 RETURNS text[]
 LANGUAGE sql
 STABLE
AS $function$
    -- Global admins (user_profiles.tenant_id IS NULL) implicitly hold
    -- super_admin — they have no role_assignments rows (role_assignments.
    -- tenant_id is NOT NULL per 0003) so the per-tenant lookup below
    -- would return '{}' for them. Return super_admin directly so the
    -- RBAC resolver treats them as super_admin (TENANT-101 fix).
    select case
        when public.is_global_admin()
        then array['super_admin']::text[]
        else coalesce(array_agg(r.code), '{}')
    end
    from public.role_assignments ra
    join public.roles r on r.id = ra.role_id
    where ra.user_profile_id = public.current_user_profile_id()
      and ra.tenant_id = public.current_tenant_id()  -- TENANT-SCOPE FIX (TENANT-100)
      and ra.revoked_at is null;
$function$
;
comment on function current_user_roles() is 'Array of role codes currently assigned to the caller.';

create or replace function public.deactivate_fcm_tokens(p_user_id uuid, p_platform text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_caller_profile uuid;
    v_is_service_role boolean;
    v_deactivated integer;
BEGIN
    -- Same caller-verification rule as register_fcm_token.
    v_is_service_role := (auth.role() = 'service_role');
    IF NOT v_is_service_role THEN
        SELECT up.id INTO v_caller_profile
          FROM public.user_profiles up
         WHERE up.auth_user_id = auth.uid()
         LIMIT 1;
        IF v_caller_profile IS NULL OR v_caller_profile <> p_user_id THEN
            RAISE EXCEPTION 'deactivate_fcm_tokens: caller does not own user profile %', p_user_id
              USING ERRCODE = '42501';
        END IF;
    END IF;

    UPDATE public.device_tokens
       SET is_active = false,
           updated_at = now()
     WHERE user_id = p_user_id
       AND is_active = true
       AND (p_platform IS NULL OR platform = p_platform);

    GET DIAGNOSTICS v_deactivated = ROW_COUNT;
    RETURN v_deactivated;
END;
$function$
;
comment on function deactivate_fcm_tokens(uuid,text) is 'Canonical FCM sign-out path (SYNC-104/105 fix, 2026-08-30): deactivates the caller''s device_tokens rows — Android passes p_platform=''android'', the web portal passes ''web''. Pass NULL to deactivate every platform. Caller-verified like register_fcm_token.';

create or replace function public.debt_aging_thresholds(p_tenant_id uuid)
 RETURNS TABLE(grace_period_days integer, yellow_days integer, red_days integer, active_payer_grace_days integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_grace integer;
    v_yellow integer;
    v_red integer;
    v_active integer;
begin
    select coalesce(max(case when key = 'debt.grace_period_days' then (value #>> '{}')::int end), 5),
           coalesce(max(case when key = 'debt.threshold_yellow_days' then (value #>> '{}')::int end), 15),
           coalesce(max(case when key = 'debt.threshold_red_days' then (value #>> '{}')::int end), 60),
           coalesce(max(case when key = 'debt.active_payer_grace_days' then (value #>> '{}')::int end), 15)
      into v_grace, v_yellow, v_red, v_active
      from public.system_settings
     where tenant_id = p_tenant_id
       and category = 'debt'
       and key in ('debt.grace_period_days', 'debt.threshold_yellow_days',
                   'debt.threshold_red_days', 'debt.active_payer_grace_days');

    return query
    select coalesce(v_grace, 5)::integer,
           coalesce(v_yellow, 15)::integer,
           coalesce(v_red, 60)::integer,
           coalesce(v_active, 15)::integer;
end;
$function$
;
comment on function debt_aging_thresholds(uuid) is 'T-429 (DEBT-100): the configurable debt-aging thresholds for a tenant (the system_settings category `debt`) — with the documented defaults when rows are missing. Consumed by compute_debt_aging_summary.';

create or replace function public.enforce_application_self_update_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    -- No JWT context at all = a direct DB session (psql / SQL console /
    -- migrations). The postgres role bypasses RLS anyway (RLS's own trust
    -- model); the column guard cannot add security against the DB owner.
    if auth.jwt() is null then
        return new;
    end if;

    -- The EF's service-role client (approve/reject RPC writes) is the
    -- trusted administrative path — auth.uid() is NULL there, so the
    -- self-ownership check below must not run.
    if coalesce(auth.jwt() ->> 'role', '') = 'service_role' then
        return new;
    end if;

    -- Staff (direct PostgREST admin updates) keep the full 0019 policy.
    if public.has_any_role(array['super_admin', 'support_staff']) then
        return new;
    end if;

    -- A self-update must target the caller's own pending request (the §2
    -- policy already enforces this on visibility; the trigger re-asserts on
    -- the value level for defence in depth).
    if old.auth_user_id is distinct from auth.uid() then
        raise exception 'student_application self-update: not the caller''s request'
            using errcode = '42501';
    end if;

    if new.auth_user_id is distinct from old.auth_user_id
       or new.status is distinct from old.status
       or new.requested_role is distinct from old.requested_role
       or new.email is distinct from old.email
       or new.tenant_id is distinct from old.tenant_id
       or new.target_parent_id is distinct from old.target_parent_id
       or new.target_student_id is distinct from old.target_student_id
       or new.reviewed_by is distinct from old.reviewed_by
       or new.reviewed_at is distinct from old.reviewed_at
       or new.decision_note is distinct from old.decision_note
       or new.activation_code is distinct from old.activation_code
       or new.national_id is distinct from old.national_id
       or new.phone is distinct from old.phone
       or new.full_name is distinct from old.full_name
       or new.notes_from_user is distinct from old.notes_from_user then
        raise exception 'student_application self-update may only change the student_application payload (migration 0116 §2)'
            using errcode = '42501';
    end if;

    new.updated_at := now();
    return new;
end;
$function$
;
comment on function enforce_application_self_update_columns() is 'T-413 / STUDENT-102: column gate for the account_approval_requests self-update path — a non-staff caller may only attach their student_application payload to their own pending request.';

create or replace function public.enforce_audit_log_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
    raise exception 'audit_logs is append-only (plan §12). UPDATE and DELETE are forbidden. Use a new entry with supersedes_id for corrections.';
end;
$function$
;

create or replace function public.enforce_chat_read_by_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_profile uuid := public.current_user_profile_id();
    v_old jsonb := coalesce(old.read_by, '[]'::jsonb);
    v_new jsonb := coalesce(new.read_by, '[]'::jsonb);
begin
    -- Authors keep the full-update path governed by chat_messages_update_own
    -- (edit body, edited_at, deleted_at, attachments …). Nothing changes
    -- for them.
    if v_profile is not null and old.author_id = v_profile then
        return new;
    end if;

    -- Non-author (recipient) path: every column except read_by must be
    -- byte-identical. This is what stops a member from editing or deleting
    -- other people's messages through the new permissive policy.
    if new.tenant_id is distinct from old.tenant_id
       or new.channel_id is distinct from old.channel_id
       or new.author_id is distinct from old.author_id
       or new.body is distinct from old.body
       or new.edited_at is distinct from old.edited_at
       or new.edited_by is distinct from old.edited_by
       or new.deleted_at is distinct from old.deleted_at
       or new.parent_message_id is distinct from old.parent_message_id
       or new.attachments is distinct from old.attachments
       or new.sent_at is distinct from old.sent_at then
        raise exception 'chat_messages: non-author updates may only touch read_by (REALTIME-101)';
    end if;

    -- read_by must GROW by exactly one entry…
    if jsonb_array_length(v_new) <> jsonb_array_length(v_old) + 1 then
        raise exception 'chat_messages: read_by must grow by exactly one entry per update (REALTIME-101)';
    end if;

    -- …without removing or mutating any existing entry…
    if not (v_new @> v_old) then
        raise exception 'chat_messages: existing read_by entries may not be removed or modified (REALTIME-101)';
    end if;

    -- …and the appended entry must be the caller's OWN receipt.
    if not exists (
        select 1
        from jsonb_array_elements(v_new) e
        where e ->> 'user_id' = v_profile::text
          and not (v_old @> jsonb_build_array(e))
    ) then
        raise exception 'chat_messages: the appended read_by entry must belong to the caller (REALTIME-101)';
    end if;

    return new;
end;
$function$
;
comment on function enforce_chat_read_by_append_only() is 'T-032 / REALTIME-101: narrows the chat_messages_update_read_by member path to appending the caller''s own read receipt.';

create or replace function public.enforce_expense_workflow_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_caller_is_service_role boolean := coalesce(auth.jwt() ->> 'role', '') = 'service_role';
    v_is_authenticated_caller boolean := auth.uid() is not null and not v_caller_is_service_role;
    v_acting_profile_id uuid := public.current_user_profile_id();
    v_is_reviewer boolean := false;
begin
    -- (a) Legal INITIAL statuses: a ticket is born draft or pending_approval.
    if tg_op = 'INSERT' and new.status not in ('draft', 'pending_approval') then
        raise exception 'Invalid initial expense status: % — a ticket must be created as draft or pending_approval (WEAK-030)', new.status;
    end if;

    -- (b) The transition graph, on every status CHANGE.
    if tg_op = 'UPDATE' and old.status is distinct from new.status then
        if not (
            (old.status = 'draft'                     and new.status in ('pending_approval'))
            or (old.status = 'pending_approval'       and new.status in ('approved_funds_released', 'rejected'))
            or (old.status = 'approved_funds_released' and new.status in ('disbursed', 'settled_and_closed'))
            or (old.status = 'disbursed'              and new.status in ('settled_and_closed'))
        ) then
            -- rejected + settled_and_closed fall through: terminal states.
            raise exception 'Unauthorized expense transition: % → % (WEAK-030 state machine)', old.status, new.status;
        end if;
    end if;

    -- (c) HARD no-self-approval (closes the NULL-approver bypass): a ticket
    --     ENTERING approved_funds_released must name an approver that is set
    --     AND different from the submitter. Scoped to the entering change so
    --     legacy approved rows (pre-0064, approved_by possibly NULL) remain
    --     editable for their other columns.
    if new.status = 'approved_funds_released'
       and (tg_op = 'INSERT' or old.status is distinct from 'approved_funds_released')
       and (new.approved_by is null or new.approved_by = new.submitted_by) then
        raise exception 'Self-approval is forbidden (plan §08 / WEAK-030): an approval must name an approver other than the submitter';
    end if;

    -- (d) SEC-118 (T-527): the APPROVAL-AUTHORITY transitions are
    --     REVIEWER-ONLY for authenticated non-service callers: entering
    --     approved_funds_released (the approval), rejected (the rejection)
    --     and disbursed (the funds release). settled_and_closed is
    --     DELIBERATELY NOT gated — the T-521 Android flow lets the SUBMITTER
    --     settle their own APPROVED ticket with the receipt proof (the
    --     t521-expense-e2e.py F3 contract, live-green 2026-10-13): the state
    --     machine (b) already orders settle AFTER approval, the 0008
    --     invariants below already require the receipt + final amount, and
    --     the RLS UPDATE policy already confines submitters to their OWN
    --     rows — the submitter's settle is the proof-upload step, not an
    --     approval bypass. The reviewer set = the 0019
    --     expense_tickets_select visibility set (super_admin /
    --     financial_officer / manager), identical to the desktop
    --     isReviewer gate — one definition, every layer.
    if v_is_authenticated_caller
       and tg_op = 'UPDATE'
       and old.status is distinct from new.status
       and new.status in ('approved_funds_released', 'rejected', 'disbursed') then
        select public.has_any_role(array['super_admin', 'financial_officer', 'manager'])
          into v_is_reviewer;
        if not v_is_reviewer then
            raise exception
                'Reviewer-only expense transition (SEC-118): only super_admin / financial_officer / manager may move a ticket to % — submitters cannot approve, reject or disburse',
                new.status;
        end if;
    end if;

    -- (e) SEC-118 (T-527): anti-forgery — a ticket ENTERING
    --     approved_funds_released must name the ACTING user as approver
    --     (for authenticated non-service callers). Together with (c) this
    --     makes "approved_by = the profile that actually performed the
    --     approval" a database invariant, closing the forged-third-party-
    --     approver hole the plain 0064 clause left open.
    if v_is_authenticated_caller
       and tg_op = 'UPDATE'
       and new.status = 'approved_funds_released'
       and old.status is distinct from 'approved_funds_released'
       and (new.approved_by is null or new.approved_by is distinct from v_acting_profile_id) then
        raise exception
            'Forged approver (SEC-118): approved_by must be the acting user''s own profile — an approval cannot be recorded in another profile''s name';
    end if;

    -- 0008 invariants, preserved verbatim.
    if new.status = 'settled_and_closed' and new.receipt_path is null then
        raise exception 'Receipt upload is mandatory before settlement (plan §08)';
    end if;
    if new.status = 'settled_and_closed' and new.final_spent_amount is null then
        raise exception 'Final spent amount must be set before settlement';
    end if;
    if new.status = 'rejected' and (new.rejected_reason is null or trim(new.rejected_reason) = '') then
        raise exception 'A rejection reason is required';
    end if;

    return new;
end;
$function$
;
comment on function enforce_expense_workflow_rules() is 'WEAK-030 + SEC-118 (T-527/0155): expense state machine (draft→pending_approval→approved|rejected→disbursed→settled; settle allowed from approved or disbursed per settle_expense) + hard no-self-approval (approver set and ≠ submitter) + reviewer-only terminal transitions for authenticated non-service callers + approved_by=acting-user anti-forgery + the 0008 invariants (receipt, final amount, rejection reason).';

create or replace function public.enforce_parent_attendance_update_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  is_parent boolean;
begin
  select public.has_role('parent') into is_parent;
  if is_parent then
    -- Only allow the parent to touch justification_* columns.
    if new.student_id is distinct from old.student_id
       or new.class_id is distinct from old.class_id
       or new.class_subject_id is distinct from old.class_subject_id
       or new.date is distinct from old.date
       or new.status is distinct from old.status
       or new.arrival_time is distinct from old.arrival_time
       or new.note is distinct from old.note
       or new.recorded_by is distinct from old.recorded_by
       or new.tenant_id is distinct from old.tenant_id then
      raise exception 'Parents can only update justification columns on attendance_records';
    end if;
    -- Auto-set justification_status = 'submitted' the first time a parent
    -- submits a justification, but never override an accepted/rejected one.
    if old.justification_status in ('none', 'rejected') and new.justification_status = old.justification_status then
      new.justification_status = 'submitted';
    end if;
  end if;
  return new;
end;
$function$
;

create or replace function public.enforce_parent_self_update_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- T-031 / SEC-008: gate the restriction on the parent role.
  -- Staff (admin, manager, super_admin, support_staff, finance,
  -- teacher, etc.) can update identity fields — the parent-role
  -- restriction applies ONLY to parent callers. has_role() is itself
  -- SECURITY DEFINER per migration 0034, so it works inside this
  -- trigger even when the caller's JWT role assignments would be
  -- filtered by RLS on role_assignments.
  if public.has_role('parent') then
    -- Parents can only touch contact fields. Anything else is rejected.
    if new.id is distinct from old.id
       or new.tenant_id is distinct from old.tenant_id
       or new.parent_code is distinct from old.parent_code
       or new.first_name is distinct from old.first_name
       or new.last_name is distinct from old.last_name
       or new.national_id is distinct from old.national_id
       or new.relationship is distinct from old.relationship
       or new.notes is distinct from old.notes
       or new.is_active is distinct from old.is_active
       or new.is_financially_restricted is distinct from old.is_financially_restricted
       or new.auth_user_id is distinct from old.auth_user_id
       or new.deleted_at is distinct from old.deleted_at then
      raise exception 'Parents can only update contact fields (phone, email, address, occupation)';
    end if;
  end if;
  return new;
end;
$function$
;

create or replace function public.enforce_payment_proof()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
    -- ----------------------------------------------------------------------
    -- INSERT: strict. New payments MUST satisfy the proof requirement for
    -- their method. Refunds inserted via revert_payment_allocation also
    -- pass through here — they typically have method='cash' (no proof
    -- required) and proof_path IS NULL, so the check passes.
    -- ----------------------------------------------------------------------
    if TG_OP = 'INSERT' then
        if new.method in ('check', 'transfer') and new.proof_path is null then
            raise exception 'Proof upload is mandatory for % payments (plan §13.05)', new.method;
        end if;

        if new.method = 'check' and (new.check_number is null or new.check_bank_name is null) then
            raise exception 'Check number and bank name are required for check payments';
        end if;

        if new.method = 'transfer' and new.transfer_reference is null then
            raise exception 'Transaction reference is required for transfer payments';
        end if;
    -- ----------------------------------------------------------------------
    -- UPDATE: re-validate ONLY when the row is being CHANGED in a way
    -- that would weaken the proof requirement:
    --   - method is being changed to a proof-required method
    --     (check or transfer) without setting proof_path; OR
    --   - on a check/transfer row, proof_path is being explicitly cleared
    --     (NEW.proof_path IS NULL while OLD.proof_path IS NOT NULL); OR
    --   - on a check row, check_number/check_bank_name is being cleared; OR
    --   - on a transfer row, transfer_reference is being cleared.
    --
    -- Status-only updates (method unchanged, proof_path unchanged) skip
    -- the proof requirement entirely — this is the WEAK-200 fix.
    -- ----------------------------------------------------------------------
    elsif TG_OP = 'UPDATE' then
        -- Method change to a proof-required method WITHOUT setting proof_path.
        if new.method in ('check', 'transfer')
           and new.proof_path is null
           and (old.method is distinct from new.method
                or old.proof_path is not null) then
            -- Only raise if this UPDATE is actually trying to land on
            -- a NULL proof_path for a check/transfer method — which means
            -- either a method change to check/transfer without proof, OR
            -- an explicit proof_path clear on a check/transfer row.
            -- (If old.method = new.method AND old.proof_path IS NULL,
            -- the row was already NULL — we are grandfathering it.)
            if old.method is distinct from new.method or old.proof_path is not null then
                raise exception 'Proof upload is mandatory for % payments (plan §13.05)', new.method;
            end if;
        end if;

        -- Check-number / bank-name cleared on a check row.
        if new.method = 'check'
           and (old.check_number is not null or old.check_bank_name is not null)
           and (new.check_number is null or new.check_bank_name is null) then
            raise exception 'Check number and bank name are required for check payments';
        end if;

        -- Transfer reference cleared on a transfer row.
        if new.method = 'transfer'
           and old.transfer_reference is not null
           and new.transfer_reference is null then
            raise exception 'Transaction reference is required for transfer payments';
        end if;
    end if;

    -- Auto-set initial status: cash → paid, check/transfer → pending.
    -- Preserved verbatim from the original trigger. Only fires when the
    -- caller left status NULL (which is the canonical "derive from method"
    -- convention).
    if new.status is null then
        new.status := case new.method when 'cash' then 'paid' else 'pending' end;
    end if;

    return new;
end;
$function$
;

create or replace function public.enforce_salary_adjustment_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    raise exception 'salary_adjustments is append-only: UPDATE and DELETE are forbidden (every correction is a new adjustment row).'
        using errcode = 'P0001';
end;
$function$
;

create or replace function public.enforce_staff_absence_justification_flow()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    -- is_excused may ONLY be set by the accepted decision (an already-excused
    -- absence keeps its flag through an admin re-request — the honest restart
    -- path accepted/rejected -> requested below). This check runs BEFORE the
    -- unchanged-status early return: setting is_excused WITHOUT a status
    -- change must be refused too (caught by the verify suite's 6e leg).
    if new.is_excused
       and old.justification_status <> 'accepted'
       and new.justification_status <> 'accepted' then
        raise exception 'staff_absences: is_excused requires justification_status = accepted';
    end if;

    if new.justification_status = old.justification_status then
        return new; -- unchanged status: field edits (notes) are allowed
    end if;

    if not (
        (old.justification_status = 'none'      and new.justification_status = 'requested')
     or (old.justification_status = 'requested' and new.justification_status = 'submitted')
     or (old.justification_status = 'submitted' and new.justification_status in ('accepted', 'rejected'))
     or (old.justification_status in ('accepted', 'rejected') and new.justification_status = 'requested')
    ) then
        raise exception 'staff_absences: illegal justification transition % -> % (allowed: none->requested->submitted->accepted|rejected)',
            old.justification_status, new.justification_status;
    end if;

    return new;
end;
$function$
;

create or replace function public.execute_batch_promotion(p_decisions jsonb, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_decision jsonb;
    v_student_id uuid;
    v_decision_code text;
    v_next_grade text;
    v_academic_year text;
    v_count integer := 0;
    v_updated_ids uuid[] := '{}';
    v_tenant uuid;
    v_caller_is_service_role boolean;
    v_student_found boolean;
    v_history_row public.student_academic_histories%ROWTYPE;
    v_valid_decisions text[] := ARRAY['promoted', 'repeated', 'graduated', 'transferred'];
    v_filiere_code text;
    v_specialite_code text;
BEGIN
    IF p_decisions IS NULL OR jsonb_typeof(p_decisions) <> 'array' THEN
        RAISE EXCEPTION 'execute_batch_promotion: p_decisions must be a JSON array'
          USING ERRCODE = '22023';
    END IF;

    v_caller_is_service_role := coalesce(auth.jwt() ->> 'role', '') = 'service_role';

    -- Tenant resolution + caller verification (same rule as 0059).
    v_tenant := public.current_tenant_id();
    IF p_tenant_id IS NOT NULL AND (v_tenant IS NULL OR p_tenant_id <> v_tenant) THEN
        IF NOT v_caller_is_service_role AND NOT public.is_global_admin() THEN
            RAISE EXCEPTION 'execute_batch_promotion: caller tenant mismatch (p_tenant_id=%)', p_tenant_id
              USING ERRCODE = '42501';
        END IF;
        v_tenant := p_tenant_id;
    END IF;

    IF v_tenant IS NULL THEN
        RAISE EXCEPTION 'execute_batch_promotion: caller tenant unresolvable'
          USING ERRCODE = '42501';
    END IF;

    FOR v_decision IN SELECT * FROM jsonb_array_elements(p_decisions)
    LOOP
        v_student_id     := (v_decision ->> 'student_id')::uuid;
        v_decision_code  := v_decision ->> 'decision';
        v_next_grade     := NULLIF(v_decision ->> 'next_grade_code', '');
        v_academic_year  := v_decision ->> 'academic_year';

        -- ── validation: fail the WHOLE batch on any bad decision ──
        IF v_student_id IS NULL THEN
            RAISE EXCEPTION 'execute_batch_promotion: decision entry without a valid student_id (%)', v_decision
              USING ERRCODE = '22023';
        END IF;
        IF v_decision_code IS NULL OR NOT (v_decision_code = ANY (v_valid_decisions)) THEN
            RAISE EXCEPTION 'execute_batch_promotion: invalid decision "%" for student %', v_decision_code, v_student_id
              USING ERRCODE = '22023';
        END IF;
        IF v_academic_year IS NULL OR v_academic_year = '' THEN
            RAISE EXCEPTION 'execute_batch_promotion: decision for student % lacks academic_year (the completed year to archive)', v_student_id
              USING ERRCODE = '22023';
        END IF;
        IF v_decision_code = 'promoted' AND v_next_grade IS NULL THEN
            RAISE EXCEPTION 'execute_batch_promotion: promoted decision for student % lacks next_grade_code', v_student_id
              USING ERRCODE = '22023';
        END IF;

        -- Student must exist in the caller's tenant (RLS hides foreign rows
        -- → v_student_found stays false → the batch fails closed). 0107 also
        -- reads the classification in force (stamped into the history row).
        SELECT TRUE, s.filiere_code, s.specialite_code
          INTO v_student_found, v_filiere_code, v_specialite_code
          FROM public.students s
         WHERE s.id = v_student_id
           AND s.tenant_id = v_tenant
           AND s.deleted_at IS NULL;

        IF v_student_found IS NOT TRUE THEN
            RAISE EXCEPTION 'execute_batch_promotion: student % not found in tenant %', v_student_id, v_tenant
              USING ERRCODE = '42501';
        END IF;

        -- ── 1. append-only history upsert (idempotent per student+year) ──
        -- 0107: filière/spécialité stamped from the student row (NOT from
        -- the payload — the server value is authoritative; the payload
        -- carries no classification).
        INSERT INTO public.student_academic_histories (
            tenant_id, student_id, academic_year, cycle, grade_code, grade_year,
            class_id, class_name, gpa, rank, decision, narrative,
            filiere_code, specialite_code
        ) VALUES (
            v_tenant, v_student_id, v_academic_year,
            v_decision ->> 'cycle', v_decision ->> 'grade_code',
            COALESCE((v_decision ->> 'grade_year')::int, 0),
            (v_decision ->> 'class_id')::uuid,
            v_decision ->> 'class_name',
            COALESCE((v_decision ->> 'gpa')::numeric, 0),
            (v_decision ->> 'rank')::int,
            v_decision_code,
            v_decision ->> 'narrative',
            v_filiere_code,
            v_specialite_code
        )
        ON CONFLICT (student_id, academic_year) DO UPDATE SET
            cycle       = EXCLUDED.cycle,
            grade_code  = EXCLUDED.grade_code,
            grade_year  = EXCLUDED.grade_year,
            class_id    = EXCLUDED.class_id,
            class_name  = EXCLUDED.class_name,
            gpa         = EXCLUDED.gpa,
            rank        = EXCLUDED.rank,
            decision    = EXCLUDED.decision,
            narrative   = EXCLUDED.narrative,
            filiere_code = EXCLUDED.filiere_code,
            specialite_code = EXCLUDED.specialite_code,
            recorded_at = now();

        -- ── 2 + 3. student advancement (desktop semantics preserved) ──
        IF v_decision_code = 'promoted' THEN
            UPDATE public.students
               SET grade_level_code = v_next_grade,
                   class_id = NULL,
                   updated_at = now()
             WHERE id = v_student_id
               AND tenant_id = v_tenant;
            v_updated_ids := v_updated_ids || v_student_id;
        ELSIF v_decision_code = 'graduated' THEN
            UPDATE public.students
               SET enrollment_status = 'graduated',
                   class_id = NULL,
                   updated_at = now()
             WHERE id = v_student_id
               AND tenant_id = v_tenant;
            v_updated_ids := v_updated_ids || v_student_id;
        END IF;
        -- 'repeated' / 'transferred': history row only — the student row
        -- is untouched (previous desktop contract preserved). The
        -- classification is likewise preserved (the stream continues into
        -- the repeated year unless the school edits it).

        v_count := v_count + 1;
    END LOOP;

    -- ── 4. one audit entry for the batch (0014 canonical entry point) ──
    PERFORM public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'student.promote',
        p_entity_type := 'student',
        p_entity_id   := NULL,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json  := jsonb_build_object(
                             'count', v_count,
                             'updated_student_ids', to_jsonb(v_updated_ids)
                         ),
        p_note        := 'Promotion de classe exécutée (atomique, RPC 0059/0107)'
    );

    RETURN jsonb_build_object(
        'processed_count', v_count,
        'updated_student_ids', to_jsonb(v_updated_ids)
    );
END;
$function$
;
comment on function execute_batch_promotion(jsonb,uuid,text,uuid) is 'T-041 (ACAD-100/BUSINESS-004) + T-401: atomic server-side executor for year-end batch promotion. Receives FINAL decisions (GPA/suggestion/override computed client-side by the canonical desktop engine), archives each to student_academic_histories (0107: with the student''s filière/spécialité — the classification in force during the completed year), advances promoted students, graduates 3eme_annee, writes one audit entry — all in ONE transaction. Runs under caller RLS; any invalid or foreign-tenant decision rolls back the whole batch.';

create or replace function public.expire_pending_approvals()
 RETURNS TABLE(tenant_id uuid, expired_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
    -- Expire every stale approval request past its window, grouped per
    -- tenant. TABLE(tenant_id, expired_count) matches the shape the
    -- expire-pending-approvals Edge Function iterates (0036 contract).
    RETURN QUERY
    WITH expired AS (
        UPDATE public.account_approval_requests a
           SET status = 'expired',
               updated_at = now()
         WHERE a.status = 'pending'
           AND a.expires_at < now()
        RETURNING a.tenant_id
    )
    SELECT e.tenant_id, COUNT(*)::integer AS expired_count
      FROM expired e
     GROUP BY e.tenant_id;
END;
$function$
;
comment on function expire_pending_approvals() is 'Auto-expires pending account_approval_requests past their window. Returns per-tenant (tenant_id, expired_count) rows for the expire-pending-approvals Edge Function. BUG-NEW-001/T-083: the 0036 version referenced a non-existent "users" table and failed silently on every cron run.';

create or replace function public.fn_calculate_student_term_gpa(p_student_id uuid, p_term text, p_academic_year text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_weighted_sum NUMERIC(10, 4) := 0;
    v_total_coef NUMERIC(10, 4) := 0;
    v_rec RECORD;
BEGIN
    FOR v_rec IN 
        SELECT 
            a.subject_average,
            a.coefficient
        FROM public.assessments a
        JOIN public.subjects s ON a.subject_id = s.id
        WHERE a.student_id = p_student_id
          AND a.term::text = p_term
          AND a.academic_year = p_academic_year
          AND a.subject_average IS NOT NULL
          AND s.is_extracurricular = FALSE
    LOOP
        v_weighted_sum := v_weighted_sum + (v_rec.subject_average * v_rec.coefficient);
        v_total_coef := v_total_coef + v_rec.coefficient;
    END LOOP;

    IF v_total_coef = 0 THEN
        RETURN NULL;
    END IF;

    RETURN ROUND((v_weighted_sum / v_total_coef)::NUMERIC, 2);
END;
$function$
;

create or replace function public.fn_cancel_promotion_cycle(p_cycle_id uuid, p_reason text DEFAULT NULL::text, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
    v_tenant uuid := public.fn_resolve_cycle_tenant(p_tenant_id);
    v_cycle public.promotion_cycles;
begin
    select * into v_cycle
      from public.promotion_cycles pc
     where pc.id = p_cycle_id and pc.tenant_id = v_tenant
     for update;
    if v_cycle.id is null then
        raise exception 'fn_cancel_promotion_cycle: cycle % not found in tenant', p_cycle_id
          using errcode = '23503';
    end if;
    if v_cycle.status = 'completed' then
        raise exception 'fn_cancel_promotion_cycle: the cycle for % is completed — it cannot be cancelled (its history is immutable)', v_cycle.source_academic_year
          using errcode = '55006';
    end if;
    if v_cycle.status = 'cancelled' then
        raise exception 'fn_cancel_promotion_cycle: the cycle for % is already cancelled', v_cycle.source_academic_year
          using errcode = '55006';
    end if;

    update public.promotion_cycles pc
       set status = 'cancelled',
           notes = coalesce(p_reason, notes),
           updated_at = now()
     where pc.id = p_cycle_id;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'promotion.cycle_cancel',
        p_entity_type := 'promotion_cycle',
        p_entity_id   := p_cycle_id,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json   := jsonb_build_object('reason', p_reason),
        p_note         := format('Cycle de promotion %s → %s ANNULÉ.', v_cycle.source_academic_year, v_cycle.target_academic_year)
    );

    return jsonb_build_object('ok', true, 'cycle_id', p_cycle_id, 'status', 'cancelled');
end;
$function$
;

create or replace function public.fn_complete_promotion_cycle(p_cycle_id uuid, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
    v_tenant uuid := public.fn_resolve_cycle_tenant(p_tenant_id);
    v_cycle public.promotion_cycles;
    v_pending text;
begin
    select * into v_cycle
      from public.promotion_cycles pc
     where pc.id = p_cycle_id and pc.tenant_id = v_tenant
     for update;
    if v_cycle.id is null then
        raise exception 'fn_complete_promotion_cycle: cycle % not found in tenant', p_cycle_id
          using errcode = '23503';
    end if;
    if v_cycle.status = 'completed' then
        raise exception 'fn_complete_promotion_cycle: the cycle for % is already completed', v_cycle.source_academic_year
          using errcode = '55006';
    end if;
    if v_cycle.status = 'cancelled' then
        raise exception 'fn_complete_promotion_cycle: the cycle for % is cancelled — it cannot be completed', v_cycle.source_academic_year
          using errcode = '55006';
    end if;

    -- EVERY class must be processed / exception / skipped.
    select string_agg(pcc.class_name, ', ') into v_pending
      from public.promotion_cycle_classes pcc
     where pcc.cycle_id = p_cycle_id
       and pcc.status not in ('processed', 'exception', 'skipped');
    if v_pending is not null then
        raise exception 'fn_complete_promotion_cycle: le cycle ne peut pas être terminé — classes restant à traiter : %', v_pending
          using errcode = '22023';
    end if;

    update public.promotion_cycles pc
       set status = 'completed',
           completed_at = now(),
           completed_by_name = coalesce(p_actor_name, '—'),
           updated_at = now()
     where pc.id = p_cycle_id
    returning * into v_cycle;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'promotion.cycle_complete',
        p_entity_type := 'promotion_cycle',
        p_entity_id   := p_cycle_id,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json   := (select jsonb_build_object(
                               'source_academic_year', pc.source_academic_year,
                               'target_academic_year', pc.target_academic_year,
                               'classes', (select count(*) from public.promotion_cycle_classes pcc where pcc.cycle_id = pc.id),
                               'promoted', (select coalesce(sum(pcc.promoted_count), 0) from public.promotion_cycle_classes pcc where pcc.cycle_id = pc.id),
                               'repeated', (select coalesce(sum(pcc.repeating_count), 0) from public.promotion_cycle_classes pcc where pcc.cycle_id = pc.id)
                           ) from public.promotion_cycles pc where pc.id = p_cycle_id),
        p_note         := format('Cycle de promotion %s → %s TERMINÉ.', v_cycle.source_academic_year, v_cycle.target_academic_year)
    );

    return jsonb_build_object(
        'ok', true,
        'cycle_id', p_cycle_id,
        'status', 'completed'
    );
end;
$function$
;

create or replace function public.fn_confirm_promotion_cycle_class(p_cycle_id uuid, p_class_id uuid, p_decisions jsonb, p_ack_incomplete_notes boolean DEFAULT false, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
    v_tenant uuid := public.fn_resolve_cycle_tenant(p_tenant_id);
    v_cycle public.promotion_cycles;
    v_class_row public.promotion_cycle_classes;
    v_decision jsonb;
    v_student_id uuid;
    v_declared_ids uuid[] := '{}';
    v_missing_ids uuid[] := '{}';
    v_missing_list text;
    v_incomplete_count integer := 0;
    v_incomplete_names text;
    v_promoted integer := 0;
    v_repeated integer := 0;
    v_deferred integer := 0;
    v_result jsonb;
begin
    if p_decisions is null or jsonb_typeof(p_decisions) <> 'array' then
        raise exception 'fn_confirm_promotion_cycle_class: p_decisions must be a JSON array'
          using errcode = '22023';
    end if;

    -- Lock the cycle row (the human-in-the-loop unit — one year at a time).
    select * into v_cycle
      from public.promotion_cycles pc
     where pc.id = p_cycle_id
       and pc.tenant_id = v_tenant
     for update;
    if v_cycle.id is null then
        raise exception 'fn_confirm_promotion_cycle_class: cycle % not found in tenant', p_cycle_id
          using errcode = '23503';
    end if;
    if v_cycle.status in ('completed', 'cancelled') then
        raise exception 'fn_confirm_promotion_cycle_class: the cycle for % is % — it can no longer be modified', v_cycle.source_academic_year, v_cycle.status
          using errcode = '55006';
    end if;

    -- Lock the class row (the review unit — one class at a time).
    select * into v_class_row
      from public.promotion_cycle_classes pcc
     where pcc.cycle_id = p_cycle_id
       and pcc.class_id = p_class_id
       and pcc.tenant_id = v_tenant
     for update;
    if v_class_row.id is null then
        raise exception 'fn_confirm_promotion_cycle_class: class % is not part of cycle %', p_class_id, p_cycle_id
          using errcode = '23503';
    end if;
    if v_class_row.status in ('processed', 'exception', 'skipped') then
        raise exception 'fn_confirm_promotion_cycle_class: the class % is already % (reopen it first if you need to re-confirm)', v_class_row.class_name, v_class_row.status
          using errcode = '55006';
    end if;

    -- ── Rule: EVERY active student of the class must have a decision ──
    select array_agg(d ->> 'student_id') into v_declared_ids
      from jsonb_array_elements(p_decisions) d;
    select array_agg(s.id) into v_missing_ids
      from public.students s
     where s.class_id = p_class_id
       and s.tenant_id = v_tenant
       and s.deleted_at is null
       and s.is_active
       and not (s.id = any (coalesce(v_declared_ids, '{}'::uuid[])));
    if v_missing_ids is not null and array_length(v_missing_ids, 1) > 0 then
        select string_agg(s.first_name || ' ' || s.last_name, ', ')
          into v_missing_list
          from public.students s
         where s.id = any (v_missing_ids);
        raise exception 'fn_confirm_promotion_cycle_class: every élève de la classe doit avoir une décision — manquants : %', coalesce(v_missing_list, array_to_string(v_missing_ids, ', '))
          using errcode = '22023';
    end if;

    -- ── The incomplete-notes warning (the two-phase ack) ──
    -- A student's notes are incomplete when ANY of their assessment rows
    -- for the source year has a missing mark, or when they have NO
    -- assessment rows at all. The T-336 honesty rule: never silently treat
    -- missing grades as zero.
    with class_students as (
        select s.id, s.first_name, s.last_name
          from public.students s
         where s.class_id = p_class_id
           and s.tenant_id = v_tenant
           and s.deleted_at is null
           and s.is_active
    ),
    incomplete as (
        select cs.id, cs.first_name || ' ' || cs.last_name as name
          from class_students cs
         where not exists (
                select 1 from public.assessments a
                 where a.student_id = cs.id
                   and a.devoir1 is not null
                   and a.devoir2 is not null
                   and a.examen is not null
                   and a.academic_year = v_cycle.source_academic_year
              )
    )
    select count(*)::int, coalesce(string_agg(name, ', '), '')
      into v_incomplete_count, v_incomplete_names
      from incomplete;

    if v_incomplete_count > 0 and coalesce(p_ack_incomplete_notes, false) is false then
        raise exception '[NOTES_INCOMPLETES] Les notes ne sont pas encore toutes renseignées (%s élève(s) : %s). Êtes-vous sûr de vouloir continuer ?',
            v_incomplete_count, coalesce(v_incomplete_names, '—')
          using errcode = 'P0001';
    end if;

    -- ── THE canonical execution: the SAME atomic RPC the batch flow uses
    -- (ONE business-logic path — the 0059/0107 contract validates and
    -- applies the decisions, archives the histories with the classification
    -- stamp, advances the grades, writes the student.promote audit). ──
    select public.execute_batch_promotion(
               p_decisions,
               p_actor_profile_id,
               coalesce(p_actor_name, 'Cycle de promotion'),
               v_tenant
           ) into v_result;

    -- ── The tallies + the class-row flip (same transaction) ──
    select
        count(*) filter (where d ->> 'decision' = 'promoted')::int,
        count(*) filter (where d ->> 'decision' = 'repeated')::int,
        count(*) filter (where d ->> 'decision' in ('transferred', 'graduated'))::int
      into v_promoted, v_repeated, v_deferred
      from jsonb_array_elements(p_decisions) d;

    update public.promotion_cycle_classes pcc
       set status = 'processed',
           students_awaiting = 0,
           promoted_count = v_promoted,
           repeating_count = v_repeated,
           deferred_count = v_deferred,
           processed_by_name = coalesce(p_actor_name, '—'),
           processed_at = now(),
           updated_at = now()
     where pcc.id = v_class_row.id;

    -- The cycle graduates draft → (in_review|partially_processed).
    update public.promotion_cycles pc
       set status = case when pc.status in ('draft', 'in_review') then 'partially_processed' else pc.status end,
           updated_at = now()
     where pc.id = p_cycle_id;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'promotion.cycle_class_confirm',
        p_entity_type := 'promotion_cycle',
        p_entity_id   := p_cycle_id,
        p_actor_id     := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json   := jsonb_build_object(
                             'class', v_class_row.class_name,
                             'promoted', v_promoted,
                             'repeated', v_repeated,
                             'deferred', v_deferred,
                             'incomplete_notes_acked', coalesce(p_ack_incomplete_notes, false),
                             'incomplete_notes_count', v_incomplete_count
                         ),
        p_note         := format('Classe %s confirmée dans le cycle %s → %s : %s promu(s), %s redoublant(s), %s dérogation(s).',
                                v_class_row.class_name, v_cycle.source_academic_year, v_cycle.target_academic_year,
                                v_promoted, v_repeated, v_deferred)
    );

    return jsonb_build_object(
        'ok', true,
        'cycle_id', p_cycle_id,
        'class_id', p_class_id,
        'class_name', v_class_row.class_name,
        'promoted', v_promoted,
        'repeated', v_repeated,
        'deferred', v_deferred,
        'incomplete_notes_count', v_incomplete_count,
        'incomplete_notes_acked', coalesce(p_ack_incomplete_notes, false)
    );
end;
$function$
;
comment on function fn_confirm_promotion_cycle_class(uuid,uuid,jsonb,boolean,uuid,text,uuid) is 'T-403: the ONE class-level confirmation of the human-in-the-loop promotion cycle. Requires a decision for EVERY active student of the class; enforces the incomplete-notes warning (two-phase ack — the [NOTES_INCOMPLETES] exception must be re-submitted with p_ack_incomplete_notes=true); executes through the canonical execute_batch_promotion RPC (0059/0107 — ONE business path).';

create or replace function public.fn_create_promotion_cycle(p_source_academic_year text, p_target_academic_year text DEFAULT NULL::text, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
    v_tenant uuid := public.fn_resolve_cycle_tenant(p_tenant_id);
    v_source_year public.academic_years;
    v_target text;
    v_cycle public.promotion_cycles;
    v_count integer;
    v_classes integer;
begin
    if p_source_academic_year is null or btrim(p_source_academic_year) = '' then
        raise exception 'fn_create_promotion_cycle: p_source_academic_year is required'
          using errcode = '22023';
    end if;

    -- The source year must exist in the tenant (by code OR label — the
    -- fn_finalize_class_placements resolution convention).
    select * into v_source_year
      from public.academic_years ay
     where ay.tenant_id = v_tenant
       and (ay.code = p_source_academic_year or ay.label = p_source_academic_year)
     order by ay.is_current desc, ay.start_date desc
     limit 1;
    if v_source_year.id is null then
        raise exception 'fn_create_promotion_cycle: source academic year "%" not found in tenant (create it in Années scolaires first)', p_source_academic_year
          using errcode = '23503';
    end if;

    -- The target year defaults to source + 1 ("2026-2027" → "2027-2028").
    v_target := coalesce(nullif(btrim(p_target_academic_year), ''),
                         (regexp_replace(v_source_year.code, '^\d{4}', (substring(v_source_year.code from 1 for 4)::int + 1)::text)));
    if v_target is null or v_target = v_source_year.code then
        raise exception 'fn_create_promotion_cycle: target year "%" must differ from the source year "%"', coalesce(v_target, '(null)'), v_source_year.code
          using errcode = '22023';
    end if;

    -- ONE active cycle per source year (cancelled ones free the slot).
    select count(*) into v_count
      from public.promotion_cycles pc
     where pc.tenant_id = v_tenant
       and pc.source_academic_year = v_source_year.code
       and pc.status <> 'cancelled';
    if v_count > 0 then
        raise exception 'fn_create_promotion_cycle: an active cycle already exists for the year % (open it instead of creating a second one)', v_source_year.code
          using errcode = '23505';
    end if;

    insert into public.promotion_cycles (
        tenant_id, source_academic_year, target_academic_year, status,
        created_by_profile_id, created_by_name
    ) values (
        v_tenant, v_source_year.code, v_target, 'draft',
        p_actor_profile_id, coalesce(p_actor_name, '—')
    )
    returning * into v_cycle;

    -- Enumerate the source year's classes with their LIVE student counts.
    insert into public.promotion_cycle_classes (
        tenant_id, cycle_id, class_id, class_code, class_name, grade_code,
        status, students_awaiting
    )
    select v_tenant, v_cycle.id, c.id, c.code, coalesce(c.name, c.code),
           coalesce(c.grade_code, '?'), 'pending',
           (select count(*) from public.students s
             where s.class_id = c.id
               and s.tenant_id = v_tenant
               and s.deleted_at is null
               and s.is_active)
      from public.classes c
     where c.tenant_id = v_tenant
       and c.academic_year_id = v_source_year.id
       and c.is_active;

    select count(*) into v_classes
      from public.promotion_cycle_classes pcc
     where pcc.cycle_id = v_cycle.id;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'promotion.cycle_create',
        p_entity_type := 'promotion_cycle',
        p_entity_id   := v_cycle.id,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json   := jsonb_build_object(
                             'source_academic_year', v_cycle.source_academic_year,
                             'target_academic_year', v_cycle.target_academic_year,
                             'classes', v_classes
                         ),
        p_note         := format('Cycle de promotion créé pour %s → %s : %s classe(s) à examiner.', v_cycle.source_academic_year, v_cycle.target_academic_year, v_classes)
    );

    return jsonb_build_object(
        'ok', true,
        'cycle_id', v_cycle.id,
        'source_academic_year', v_cycle.source_academic_year,
        'target_academic_year', v_cycle.target_academic_year,
        'classes_count', v_classes
    );
end;
$function$
;

create or replace function public.fn_deterministic_activation_code(p_parent_code text, p_tenant_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
    identity text := btrim(coalesce(p_tenant_id::text, '') || '|' || coalesce(p_parent_code, ''));
    h bigint;
begin
    if identity = '' then
        return '000000';
    end if;
    h := public.fn_fnv1a(identity);
    return ((h % 900000) + 100000)::text;
end;
$function$
;
comment on function fn_deterministic_activation_code(text,uuid) is 'Canonical deterministic activation code: 6 digits [100000, 999999] from fn_fnv1a(''{tenant_id}|{parent_code}''). Mirrors deterministicActivationCode on both clients. Collisions across parents are handled by the CALLER (batch_register_family falls back to generate_activation_code).';

create or replace function public.fn_deterministic_parent_code(p_year integer, p_phone text DEFAULT NULL::text, p_display_name text DEFAULT NULL::text, p_first_name text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text, p_fallback_seed text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
    parts text[] := array[]::text[];
    identity text;
begin
    -- Canonical rule: per-field trim, DROP empty fields, join with '|'.
    if coalesce(btrim(p_phone), '') <> '' then parts := parts || btrim(p_phone); end if;
    if coalesce(btrim(p_display_name), '') <> '' then parts := parts || btrim(p_display_name); end if;
    if coalesce(btrim(p_first_name), '') <> '' then parts := parts || btrim(p_first_name); end if;
    if coalesce(btrim(p_last_name), '') <> '' then parts := parts || btrim(p_last_name); end if;
    identity := array_to_string(parts, '|');
    -- T-018 rule: NO random fallback — empty identity uses the stable seed.
    if identity = '' then
        identity := coalesce(nullif(btrim(p_fallback_seed), ''), 'orphan-parent');
    end if;
    return 'PAR-' || p_year::text || '-' || public.fn_stable_hash(identity);
end;
$function$
;
comment on function fn_deterministic_parent_code(integer,text,text,text,text,text) is 'Canonical deterministic parent code (ADR-003): PAR-{year}-{fn_stable_hash(identity)}; identity = trimmed non-empty (phone, display_name, first_name, last_name) joined with ''|''; empty identity uses the fallback seed (default ''orphan-parent'') — NEVER random. Mirrors desktop src/core/format/id.ts deterministicParentCode and Android core/IdentityCodes.kt.';

create or replace function public.fn_er_decide_proposal(p_proposal_id text, p_decision text, p_actor_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_rationale text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant    uuid;
    v_proposal  public.er_match_proposals;
    v_event_id  uuid;
    v_edge      public.er_identity_edges;
begin
    -- 0. Tenant + guards (T-439/SEC-115: the 0128 caller-tenant-mismatch
    --    guard — the experimental flag was never an authorization boundary,
    --    and SECURITY DEFINER bypasses the er_* RLS by construction).
    v_tenant := public.fn_er_resolve_tenant(p_tenant_id);
    if p_decision not in ('approve', 'reject') then
        raise exception 'fn_er_decide_proposal: décision invalide (%)', p_decision;
    end if;

    select * into v_proposal
    from public.er_match_proposals
    where id = p_proposal_id and tenant_id = v_tenant
    for update;

    if not found then
        raise exception 'fn_er_decide_proposal: proposition introuvable (%)', p_proposal_id;
    end if;
    if v_proposal.status <> 'proposed' then
        raise exception 'fn_er_decide_proposal: proposition déjà décidée (statut %)', v_proposal.status
            using hint = 'A decided proposal is immutable — the audit trail is the correction path.';
    end if;

    -- 1. The edge: active on approve, negative on reject.
    --    A pre-existing negative edge means the pair was rejected before —
    --    refuse the approval (the review queue never re-proposes it anyway).
    select * into v_edge
    from public.er_identity_edges
    where tenant_id = v_tenant
      and a_observation_key = v_proposal.a_observation_key
      and b_observation_key = v_proposal.b_observation_key;

    if p_decision = 'reject' then
        insert into public.er_identity_edges as e (
            tenant_id, a_observation_key, b_observation_key, confidence, status,
            evidence, created_by
        ) values (
            v_tenant, v_proposal.a_observation_key, v_proposal.b_observation_key,
            v_proposal.confidence, 'negative',
            v_proposal.evidence, p_actor_id
        )
        on conflict (tenant_id, a_observation_key, b_observation_key)
        do update set status = 'negative', severed_at = null, severed_by = null;

        update public.er_match_proposals
        set status = 'rejected', decided_by = p_actor_id,
            decided_by_name = p_actor_name, decided_at = now(), rationale = p_rationale
        where id = p_proposal_id and tenant_id = v_tenant;

        insert into public.er_aggregation_events (
            tenant_id, event_type, run_id, canonical_id, observation_keys,
            actor_id, actor_name, rationale, payload
        ) values (
            v_tenant, 'PROPOSAL_REJECTED', v_proposal.run_id, v_proposal.b_canonical_id,
            array[v_proposal.a_observation_key, v_proposal.b_observation_key],
            p_actor_id, p_actor_name, p_rationale,
            jsonb_build_object('proposalId', p_proposal_id, 'confidence', v_proposal.confidence,
                               'band', v_proposal.band)
        ) returning id into v_event_id;

    else
        if v_edge.status = 'negative' then
            raise exception 'fn_er_decide_proposal: paire déjà rejetée (contrainte négative)'
                using hint = 'Un-reject explicitly via the review surface first.';
        end if;

        insert into public.er_identity_edges as e (
            tenant_id, a_observation_key, b_observation_key, confidence, status,
            evidence, created_by
        ) values (
            v_tenant, v_proposal.a_observation_key, v_proposal.b_observation_key,
            v_proposal.confidence, 'active',
            v_proposal.evidence, p_actor_id
        )
        on conflict (tenant_id, a_observation_key, b_observation_key)
        do update set status = 'active', confidence = excluded.confidence,
                      evidence = excluded.evidence, severed_at = null, severed_by = null;

        update public.er_match_proposals
        set status = 'approved', decided_by = p_actor_id,
            decided_by_name = p_actor_name, decided_at = now(), rationale = p_rationale
        where id = p_proposal_id and tenant_id = v_tenant;

        insert into public.er_aggregation_events (
            tenant_id, event_type, run_id, canonical_id, observation_keys,
            actor_id, actor_name, rationale, payload
        ) values (
            v_tenant, 'PROPOSAL_APPROVED', v_proposal.run_id, v_proposal.b_canonical_id,
            array[v_proposal.a_observation_key, v_proposal.b_observation_key],
            p_actor_id, p_actor_name, p_rationale,
            jsonb_build_object('proposalId', p_proposal_id, 'confidence', v_proposal.confidence,
                               'band', v_proposal.band)
        ) returning id into v_event_id;
    end if;

    -- 2. Audit (the canonical trail).
    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'er.decide_proposal',
        p_entity_type := 'er_match_proposal',
        p_entity_id   := null,
        p_actor_id    := p_actor_id,
        p_actor_name  := p_actor_name,
        p_after_json  := jsonb_build_object(
                             'proposalId', p_proposal_id,
                             'decision', p_decision,
                             'confidence', v_proposal.confidence,
                             'band', v_proposal.band
                         ),
        p_note        := format('ER-PMAE : proposition %s — décision %s (confiance %s).',
                                p_proposal_id, p_decision, v_proposal.confidence)
    );

    return jsonb_build_object(
        'eventId', v_event_id,
        'proposalId', p_proposal_id,
        'status', case when p_decision = 'approve' then 'approved' else 'rejected' end
    );
end;
$function$
;

create or replace function public.fn_er_has_aggregation_state(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant uuid;
begin
    -- T-439 (SEC-115): the caller-tenant guard (read-only surface, same
    -- boundary as the mutators).
    v_tenant := public.fn_er_resolve_tenant(p_tenant_id);
    return exists (
        select 1 from public.er_match_proposals
        where tenant_id = v_tenant
          and status <> 'proposed'
    ) or exists (
        select 1 from public.er_identity_edges
        where tenant_id = v_tenant
          and status = 'active'
    );
end;
$function$
;

create or replace function public.fn_er_merge_parents(p_target_parent_id uuid, p_source_parent_id uuid, p_proposal_id text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_rationale text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant       uuid;
    v_target       public.parents;
    v_source       public.parents;
    v_event_id     uuid;
    v_students     jsonb := '{}'::jsonb;
    v_payments     jsonb := '{}'::jsonb;
    v_installments jsonb := '{}'::jsonb;
    v_ledger       jsonb := '{}'::jsonb;
    v_row          record;
begin
    -- 0. Tenant + guards (T-439/SEC-115: the 0128 caller-tenant-mismatch
    --    guard — the experimental flag was never an authorization boundary,
    --    and SECURITY DEFINER bypasses the er_* RLS by construction).
    v_tenant := public.fn_er_resolve_tenant(p_tenant_id);
    if p_target_parent_id is null or p_source_parent_id is null
       or p_target_parent_id = p_source_parent_id then
        raise exception 'fn_er_merge_parents: cible et source requis et distincts';
    end if;

    select * into v_target from public.parents
    where id = p_target_parent_id and tenant_id = v_tenant;
    select * into v_source from public.parents
    where id = p_source_parent_id and tenant_id = v_tenant;

    if v_target.id is null or v_source.id is null then
        raise exception 'fn_er_merge_parents: parent introuvable (cible ou source)';
    end if;
    if v_source.deleted_at is not null then
        raise exception 'fn_er_merge_parents: la source est déjà fusionnée/supprimée (deleted_at non nul)'
            using hint = 'Un-merge the prior merge first.';
    end if;

    -- 1. Capture the COMPLETE prior mapping (the restore contract), then
    --    re-point each relationship table (INV-54: re-point, never rewrite).
    for v_row in
        select id from public.students
        where tenant_id = v_tenant and parent_id = p_source_parent_id
        for update
    loop
        v_students := v_students || jsonb_build_object(v_row.id::text, p_source_parent_id::text);
    end loop;
    update public.students
    set parent_id = p_target_parent_id
    where tenant_id = v_tenant and parent_id = p_source_parent_id;

    for v_row in
        select id from public.payments
        where tenant_id = v_tenant and parent_id = p_source_parent_id
        for update
    loop
        v_payments := v_payments || jsonb_build_object(v_row.id::text, p_source_parent_id::text);
    end loop;
    update public.payments
    set parent_id = p_target_parent_id
    where tenant_id = v_tenant and parent_id = p_source_parent_id;

    for v_row in
        select id from public.installments
        where tenant_id = v_tenant and parent_id = p_source_parent_id
        for update
    loop
        v_installments := v_installments || jsonb_build_object(v_row.id::text, p_source_parent_id::text);
    end loop;
    update public.installments
    set parent_id = p_target_parent_id
    where tenant_id = v_tenant and parent_id = p_source_parent_id;

    for v_row in
        select id from public.ledger_entries
        where tenant_id = v_tenant and parent_id = p_source_parent_id
        for update
    loop
        v_ledger := v_ledger || jsonb_build_object(v_row.id::text, p_source_parent_id::text);
    end loop;
    update public.ledger_entries
    set parent_id = p_target_parent_id
    where tenant_id = v_tenant and parent_id = p_source_parent_id;

    -- 2. Soft-delete the merged-away parent (the T-384 convention).
    update public.parents
    set deleted_at = now()
    where id = p_source_parent_id and tenant_id = v_tenant;

    -- 3. The append-only event carrying the COMPLETE prior mapping.
    insert into public.er_aggregation_events (
        tenant_id, event_type, run_id, canonical_id, merged_away_id,
        observation_keys, actor_id, actor_name, rationale, payload
    ) values (
        v_tenant, 'MERGE_EXECUTED', null, p_target_parent_id, p_source_parent_id,
        '{}', p_actor_id, p_actor_name, p_rationale,
        jsonb_build_object(
            'proposalId', p_proposal_id,
            'restoreMapping', jsonb_build_object(
                'students', v_students,
                'payments', v_payments,
                'installments', v_installments,
                'ledger_entries', v_ledger
            )
        )
    ) returning id into v_event_id;

    -- 4. Audit (the canonical trail).
    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'er.merge_parents',
        p_entity_type := 'parent',
        p_entity_id   := p_target_parent_id,
        p_actor_id    := p_actor_id,
        p_actor_name  := p_actor_name,
        p_before_json := jsonb_build_object(
                             'sourceParentId', p_source_parent_id,
                             'sourceParentCode', v_source.parent_code
                         ),
        p_after_json  := jsonb_build_object(
                             'targetParentId', p_target_parent_id,
                             'targetParentCode', v_target.parent_code,
                             'eventId', v_event_id,
                             'rePointed', jsonb_build_object(
                                 'students', (select count(*) from jsonb_object_keys(v_students)),
                                 'payments', (select count(*) from jsonb_object_keys(v_payments)),
                                 'installments', (select count(*) from jsonb_object_keys(v_installments)),
                                 'ledger_entries', (select count(*) from jsonb_object_keys(v_ledger))
                             )
                         ),
        p_note        := format('ER-PMAE : fusion réversible du parent %s dans %s (%s) — mappage complet enregistré (événement %s).',
                                v_source.parent_code, v_target.parent_code,
                                coalesce(p_rationale, 'décision humaine'), v_event_id)
    );

    return jsonb_build_object(
        'eventId', v_event_id,
        'targetParentId', p_target_parent_id,
        'sourceParentId', p_source_parent_id,
        'rePointed', jsonb_build_object(
            'students', v_students,
            'payments', v_payments,
            'installments', v_installments,
            'ledger_entries', v_ledger
        )
    );
end;
$function$
;

create or replace function public.fn_er_resolve_tenant(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
    v_tenant uuid;
    v_caller_is_service_role boolean := coalesce(auth.jwt() ->> 'role', '') = 'service_role';
begin
    v_tenant := public.current_tenant_id();
    if p_tenant_id is not null and (v_tenant is null or p_tenant_id <> v_tenant) then
        if not v_caller_is_service_role and not public.is_global_admin() then
            raise exception 'er-pmae: caller tenant mismatch (p_tenant_id=%)', p_tenant_id
              using errcode = '42501';
        end if;
        v_tenant := p_tenant_id;
    end if;
    if v_tenant is null then
        raise exception 'er-pmae: caller tenant unresolvable'
          using errcode = '42501';
    end if;
    return v_tenant;
end;
$function$
;

create or replace function public.fn_er_unmerge_parents(p_event_id uuid, p_actor_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_rationale text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant      uuid;
    v_event       public.er_aggregation_events;
    v_restore     jsonb;
    v_row_id      uuid;
    v_prev_parent uuid;
    v_counts      jsonb;
    v_undone_id   uuid;
begin
    -- 0. Tenant + guards (T-439/SEC-115: the 0128 caller-tenant-mismatch
    --    guard — the experimental flag was never an authorization boundary,
    --    and SECURITY DEFINER bypasses the er_* RLS by construction).
    v_tenant := public.fn_er_resolve_tenant(p_tenant_id);

    select * into v_event
    from public.er_aggregation_events
    where id = p_event_id and tenant_id = v_tenant and event_type = 'MERGE_EXECUTED';

    if v_event.id is null then
        raise exception 'fn_er_unmerge_parents: événement de fusion introuvable (%)', p_event_id;
    end if;

    -- One unmerge per merge (idempotence of the reversal).
    if exists (
        select 1 from public.er_aggregation_events
        where tenant_id = v_tenant and event_type = 'MERGE_UNDONE'
          and payload->>'reversesEventId' = p_event_id::text
    ) then
        raise exception 'fn_er_unmerge_parents: cette fusion est déjà annulée';
    end if;

    v_restore := v_event.payload->'restoreMapping';

    -- 1. Replay the prior mapping (only rows that STILL point at the target
    --    from this merge — a row re-parented since is left alone, honestly).
    --    0131 FIX: a direct jsonb→uuid cast raises 42846, and value::text
    --    keeps the JSON quotes — the unquoted extraction is `#>> '{}'`
    --    (the KEY is already unquoted text).
    if v_restore->'students' is not null then
        for v_row_id, v_prev_parent in
            select key::uuid, (value #>> '{}')::uuid
            from jsonb_each(v_restore->'students')
        loop
            update public.students
            set parent_id = v_prev_parent
            where id = v_row_id and tenant_id = v_tenant
              and parent_id = v_event.canonical_id;
        end loop;
    end if;
    if v_restore->'payments' is not null then
        for v_row_id, v_prev_parent in
            select key::uuid, (value #>> '{}')::uuid
            from jsonb_each(v_restore->'payments')
        loop
            update public.payments
            set parent_id = v_prev_parent
            where id = v_row_id and tenant_id = v_tenant
              and parent_id = v_event.canonical_id;
        end loop;
    end if;
    if v_restore->'installments' is not null then
        for v_row_id, v_prev_parent in
            select key::uuid, (value #>> '{}')::uuid
            from jsonb_each(v_restore->'installments')
        loop
            update public.installments
            set parent_id = v_prev_parent
            where id = v_row_id and tenant_id = v_tenant
              and parent_id = v_event.canonical_id;
        end loop;
    end if;
    if v_restore->'ledger_entries' is not null then
        for v_row_id, v_prev_parent in
            select key::uuid, (value #>> '{}')::uuid
            from jsonb_each(v_restore->'ledger_entries')
        loop
            update public.ledger_entries
            set parent_id = v_prev_parent
            where id = v_row_id and tenant_id = v_tenant
              and parent_id = v_event.canonical_id;
        end loop;
    end if;

    -- 2. Restore the merged-away parent (un-soft-delete).
    update public.parents
    set deleted_at = null
    where id = v_event.merged_away_id and tenant_id = v_tenant;

    -- 3. Sever the identity edges tied to the merged-away canonical entity.
    update public.er_identity_edges
    set status = 'severed', severed_at = now(), severed_by = p_actor_id
    where tenant_id = v_tenant and status = 'active'
      and (a_observation_key = 'canonical:' || v_event.merged_away_id::text
           or b_observation_key = 'canonical:' || v_event.merged_away_id::text);

    -- 4. The MERGE_UNDONE event (referencing the reversed merge).
    insert into public.er_aggregation_events (
        tenant_id, event_type, run_id, canonical_id, merged_away_id,
        observation_keys, actor_id, actor_name, rationale, payload
    ) values (
        v_tenant, 'MERGE_UNDONE', v_event.run_id, v_event.canonical_id, v_event.merged_away_id,
        v_event.observation_keys, p_actor_id, p_actor_name, p_rationale,
        jsonb_build_object('reversesEventId', p_event_id::text)
    ) returning id into v_undone_id;

    -- 5. Audit.
    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'er.unmerge_parents',
        p_entity_type := 'parent',
        p_entity_id   := v_event.merged_away_id,
        p_actor_id    := p_actor_id,
        p_actor_name  := p_actor_name,
        p_before_json := jsonb_build_object('mergeEventId', p_event_id),
        p_after_json  := jsonb_build_object('undoneEventId', v_undone_id,
                                            'restoredParentId', v_event.merged_away_id),
        p_note        := format('ER-PMAE : annulation de la fusion %s — mappage restauré, parent %s rétabli.',
                                p_event_id, v_event.merged_away_id)
    );

    select jsonb_build_object(
        'students', (select count(*) from jsonb_object_keys(coalesce(v_restore->'students', '{}'::jsonb))),
        'payments', (select count(*) from jsonb_object_keys(coalesce(v_restore->'payments', '{}'::jsonb))),
        'installments', (select count(*) from jsonb_object_keys(coalesce(v_restore->'installments', '{}'::jsonb))),
        'ledger_entries', (select count(*) from jsonb_object_keys(coalesce(v_restore->'ledger_entries', '{}'::jsonb)))
    ) into v_counts;

    return jsonb_build_object(
        'eventId', v_undone_id,
        'restoredParentId', v_event.merged_away_id,
        'restored', v_counts
    );
end;
$function$
;

create or replace function public.fn_finalize_class_placements(p_target_year_id uuid DEFAULT NULL::uuid, p_target_year_code text DEFAULT NULL::text, p_new_classes jsonb DEFAULT '[]'::jsonb, p_updated_classes jsonb DEFAULT '[]'::jsonb, p_student_assignments jsonb DEFAULT '[]'::jsonb, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_class_record jsonb;
    v_student_record jsonb;
    v_update_record jsonb;
    v_tenant uuid;
    v_caller_is_service_role boolean;
    v_target_year public.academic_years;
    v_academic_level_id uuid;
    v_created_class_id uuid;
    v_created_classes_map jsonb := '{}'::jsonb;
    v_final_target_class_id uuid;
    v_target_class_grade text;
    v_class_found boolean;
    v_class_filiere text;
    v_class_specialite text;
    v_filiere_code text;
    v_specialite_code text;
    v_student_filiere text;
    v_student_specialite text;
    v_created_classes_count integer := 0;
    v_updated_classes_count integer := 0;
    v_assigned_students_count integer := 0;
    v_draft_id text;
    v_code text;
BEGIN
    IF p_new_classes IS NULL OR jsonb_typeof(p_new_classes) <> 'array' THEN
        RAISE EXCEPTION 'fn_finalize_class_placements: p_new_classes must be a JSON array'
          USING ERRCODE = '22023';
    END IF;
    IF p_updated_classes IS NULL OR jsonb_typeof(p_updated_classes) <> 'array' THEN
        RAISE EXCEPTION 'fn_finalize_class_placements: p_updated_classes must be a JSON array'
          USING ERRCODE = '22023';
    END IF;
    IF p_student_assignments IS NULL OR jsonb_typeof(p_student_assignments) <> 'array' THEN
        RAISE EXCEPTION 'fn_finalize_class_placements: p_student_assignments must be a JSON array'
          USING ERRCODE = '22023';
    END IF;

    v_caller_is_service_role := coalesce(auth.jwt() ->> 'role', '') = 'service_role';

    -- Tenant resolution + caller verification (0055/0059 pattern).
    v_tenant := public.current_tenant_id();
    IF p_tenant_id IS NOT NULL AND (v_tenant IS NULL OR p_tenant_id <> v_tenant) THEN
        IF NOT v_caller_is_service_role AND NOT public.is_global_admin() THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: caller tenant mismatch (p_tenant_id=%)', p_tenant_id
              USING ERRCODE = '42501';
        END IF;
        v_tenant := p_tenant_id;
    END IF;

    IF v_tenant IS NULL THEN
        RAISE EXCEPTION 'fn_finalize_class_placements: caller tenant unresolvable'
          USING ERRCODE = '42501';
    END IF;

    -- ── target academic year: by id when a UUID is supplied, else by code ──
    IF p_target_year_id IS NOT NULL THEN
        SELECT * INTO v_target_year
          FROM public.academic_years ay
         WHERE ay.id = p_target_year_id
           AND ay.tenant_id = v_tenant;
    END IF;
    IF v_target_year.id IS NULL AND p_target_year_code IS NOT NULL AND p_target_year_code <> '' THEN
        SELECT * INTO v_target_year
          FROM public.academic_years ay
         WHERE ay.tenant_id = v_tenant
           AND (ay.code = p_target_year_code OR ay.label = p_target_year_code)
         ORDER BY ay.is_current DESC, ay.start_date DESC
         LIMIT 1;
    END IF;
    IF v_target_year.id IS NULL THEN
        RAISE EXCEPTION 'fn_finalize_class_placements: target academic year "%" not found in tenant (create it in Années scolaires first)', coalesce(p_target_year_code, p_target_year_id::text)
          USING ERRCODE = '23503';
    END IF;

    -- ── Step A: insert the newly drafted classes ──────────────────────────
    FOR v_class_record IN SELECT * FROM jsonb_array_elements(p_new_classes)
    LOOP
        v_draft_id := NULLIF(v_class_record ->> 'clientDraftId', '');
        v_code := NULLIF(v_class_record ->> 'code', '');

        IF NULLIF(v_class_record ->> 'name', '') IS NULL THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: new class draft % lacks a name', v_class_record
              USING ERRCODE = '22023';
        END IF;
        IF NULLIF(v_class_record ->> 'gradeCode', '') IS NULL THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: new class draft "%" lacks a gradeCode', v_class_record ->> 'name'
              USING ERRCODE = '22023';
        END IF;
        IF v_code IS NULL THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: new class draft "%" lacks a code', v_class_record ->> 'name'
              USING ERRCODE = '22023';
        END IF;

        -- academic_level_id RESOLVED from academic_levels.grade_code (the
        -- column is a real UUID FK — never synthesized).
        SELECT al.id INTO v_academic_level_id
          FROM public.academic_levels al
         WHERE al.tenant_id = v_tenant
           AND al.grade_code = v_class_record ->> 'gradeCode';
        IF v_academic_level_id IS NULL THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: no academic_level for grade_code "%" (tenant %)', v_class_record ->> 'gradeCode', v_tenant
              USING ERRCODE = '23503';
        END IF;

        -- T-401: classification codes validated against the tenant catalog
        -- when provided (NULL = untagged, the pre-0107 default).
        v_filiere_code := lower(NULLIF(btrim(v_class_record ->> 'filiereCode'), ''));
        v_specialite_code := lower(NULLIF(btrim(v_class_record ->> 'specialiteCode'), ''));
        IF v_filiere_code IS NOT NULL THEN
            IF NOT EXISTS (SELECT 1 FROM public.filieres f
                            WHERE f.tenant_id = v_tenant AND f.code = v_filiere_code
                              AND f.parent_code IS NULL AND f.is_active) THEN
                RAISE EXCEPTION 'fn_finalize_class_placements: unknown filiere_code "%" for tenant (draft "%")', v_filiere_code, v_class_record ->> 'name'
                  USING ERRCODE = '23503';
            END IF;
            IF v_filiere_code = 'general' AND v_specialite_code IS NOT NULL THEN
                RAISE EXCEPTION 'fn_finalize_class_placements: a general class cannot carry a specialite (draft "%")', v_class_record ->> 'name'
                  USING ERRCODE = '22023';
            END IF;
            IF v_specialite_code IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.filieres f
                                                              WHERE f.tenant_id = v_tenant AND f.code = v_specialite_code
                                                                AND f.parent_code = v_filiere_code AND f.is_active) THEN
                RAISE EXCEPTION 'fn_finalize_class_placements: specialite_code "%" is not a spécialité of filière "%" (draft "%")', v_specialite_code, v_filiere_code, v_class_record ->> 'name'
                  USING ERRCODE = '23503';
            END IF;
        END IF;

        -- The unique constraint is (tenant_id, academic_year_id, code).
        SELECT TRUE INTO v_class_found
          FROM public.classes c
         WHERE c.tenant_id = v_tenant
           AND c.academic_year_id = v_target_year.id
           AND c.code = v_code;
        IF v_class_found THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: class code "%" already exists in year %', v_code, v_target_year.label
              USING ERRCODE = '23505';
        END IF;

        INSERT INTO public.classes (
            tenant_id, academic_year_id, academic_level_id,
            code, name, grade_code, section,
            room, capacity,
            homeroom_teacher_id, homeroom_teacher_name,
            filiere_code, specialite_code,
            is_active
        ) VALUES (
            v_tenant, v_target_year.id, v_academic_level_id,
            v_code, v_class_record ->> 'name', v_class_record ->> 'gradeCode',
            COALESCE(NULLIF(v_class_record ->> 'section', ''), 'A'),
            NULLIF(v_class_record ->> 'room', ''),
            COALESCE(NULLIF(v_class_record ->> 'capacity', '')::int, 30),
            CASE
                WHEN NULLIF(v_class_record ->> 'homeroomTeacherId', '') IS NULL THEN NULL
                ELSE (v_class_record ->> 'homeroomTeacherId')::uuid
            END,
            NULLIF(v_class_record ->> 'homeroomTeacherName', ''),
            CASE WHEN v_filiere_code = 'general' THEN NULL ELSE v_filiere_code END,
            v_specialite_code,
            TRUE
        )
        RETURNING id INTO v_created_class_id;

        IF v_draft_id IS NOT NULL THEN
            v_created_classes_map := jsonb_set(
                v_created_classes_map,
                ARRAY[v_draft_id],
                to_jsonb(v_created_class_id::text)
            );
        END IF;

        v_created_classes_count := v_created_classes_count + 1;
    END LOOP;

    -- ── Step B: apply patches to EXISTING classes of the target year ──────
    -- (room / capacity / homeroom only — classification is set at creation
    --  or via class editing, deliberately not patchable here: changing a
    --  class's stream mid-formation would strand already-assigned students.)
    FOR v_update_record IN SELECT * FROM jsonb_array_elements(p_updated_classes)
    LOOP
        IF (v_update_record ->> 'id')::uuid IS NULL THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: class update entry lacks a valid id (%)', v_update_record
              USING ERRCODE = '22023';
        END IF;

        UPDATE public.classes c
           SET room = CASE WHEN v_update_record ? 'room'
                           THEN NULLIF(v_update_record ->> 'room', '') ELSE c.room END,
               capacity = CASE WHEN v_update_record ? 'capacity'
                               THEN COALESCE(NULLIF(v_update_record ->> 'capacity', '')::int, c.capacity)
                               ELSE c.capacity END,
               homeroom_teacher_id = CASE
                   WHEN v_update_record ? 'homeroomTeacherId' THEN
                       CASE WHEN NULLIF(v_update_record ->> 'homeroomTeacherId', '') IS NULL THEN NULL
                            ELSE (v_update_record ->> 'homeroomTeacherId')::uuid END
                   ELSE c.homeroom_teacher_id END,
               homeroom_teacher_name = CASE WHEN v_update_record ? 'homeroomTeacherName'
                                             THEN NULLIF(v_update_record ->> 'homeroomTeacherName', '')
                                             ELSE c.homeroom_teacher_name END,
               updated_at = now()
         WHERE c.id = (v_update_record ->> 'id')::uuid
           AND c.tenant_id = v_tenant
           AND c.academic_year_id = v_target_year.id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: class % not found in tenant/year % (existing-class patches must target the placement year)', v_update_record ->> 'id', v_target_year.label
              USING ERRCODE = '23503';
        END IF;

        v_updated_classes_count := v_updated_classes_count + 1;
    END LOOP;

    -- ── Step C: assign students to their target sections ──────────────────
    -- Historical records are deliberately NOT touched (INV-1 of the studio
    -- spec): student_academic_histories rows belong to the promotion flow.
    FOR v_student_record IN SELECT * FROM jsonb_array_elements(p_student_assignments)
    LOOP
        -- Resolve the final target class id (draft map first, then UUID).
        IF v_student_record ->> 'targetClassId' IS NOT NULL
           AND v_created_classes_map ? (v_student_record ->> 'targetClassId') THEN
            v_final_target_class_id := (v_created_classes_map ->> (v_student_record ->> 'targetClassId'))::uuid;
        ELSIF NULLIF(v_student_record ->> 'targetClassId', '') IS NOT NULL THEN
            v_final_target_class_id := (v_student_record ->> 'targetClassId')::uuid;
        ELSE
            RAISE EXCEPTION 'fn_finalize_class_placements: assignment for student % lacks a targetClassId', v_student_record ->> 'studentId'
              USING ERRCODE = '22023';
        END IF;

        -- Target class must exist in the tenant (RLS hides foreign rows →
        -- not found → the batch fails closed).
        SELECT c.grade_code, c.filiere_code, c.specialite_code
          INTO v_target_class_grade, v_class_filiere, v_class_specialite
          FROM public.classes c
         WHERE c.id = v_final_target_class_id
           AND c.tenant_id = v_tenant;
        IF v_target_class_grade IS NULL THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: target class % not found in tenant %', v_final_target_class_id, v_tenant
              USING ERRCODE = '23503';
        END IF;

        -- Grade integrity: the assignment's gradeLevel must match the
        -- target section's grade (prevents cross-grade corruption).
        IF NULLIF(v_student_record ->> 'gradeLevel', '') IS NOT NULL
           AND v_student_record ->> 'gradeLevel' <> v_target_class_grade THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: student % assignment grade "%" does not match target class grade "%"', v_student_record ->> 'studentId', v_student_record ->> 'gradeLevel', v_target_class_grade
              USING ERRCODE = '22023';
        END IF;

        -- Student must exist in the caller's tenant (not deleted); fetch
        -- the current classification for the compatibility check. FOUND
        -- distinguishes "row with NULL filière" from "no row".
        SELECT s.filiere_code, s.specialite_code
          INTO v_student_filiere, v_student_specialite
          FROM public.students s
         WHERE s.id = (v_student_record ->> 'studentId')::uuid
           AND s.tenant_id = v_tenant
           AND s.deleted_at IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: student % not found in tenant %', v_student_record ->> 'studentId', v_tenant
              USING ERRCODE = '23503';
        END IF;

        -- T-401: classification compatibility — a conflicting stream is a
        -- hard error (the whole batch rolls back, like the grade check).
        IF NOT public.fn_track_compatible(
                 v_student_filiere, v_student_specialite,
                 v_class_filiere, v_class_specialite,
                 v_target_class_grade, v_tenant) THEN
            RAISE EXCEPTION 'fn_finalize_class_placements: student % classification (filière "%" / spécialité "%") is incompatible with target class % (filière "%" / spécialité "%")',
                v_student_record ->> 'studentId', coalesce(v_student_filiere, '—'), coalesce(v_student_specialite, '—'),
                v_final_target_class_id, coalesce(v_class_filiere, '—'), coalesce(v_class_specialite, '—')
              USING ERRCODE = '22023';
        END IF;

        UPDATE public.students
           SET class_id = v_final_target_class_id,
               grade_level_code = COALESCE(NULLIF(v_student_record ->> 'gradeLevel', ''), grade_level_code),
               -- T-401: a tagged class stamps the student's classification
               -- (the legitimate year-end re-streaming transition). An
               -- untagged class leaves the student's classification intact.
               filiere_code = CASE WHEN v_class_filiere IS NOT NULL THEN v_class_filiere
                                   ELSE filiere_code END,
               specialite_code = CASE WHEN v_class_specialite IS NOT NULL THEN v_class_specialite
                                       ELSE specialite_code END,
               updated_at = now()
         WHERE id = (v_student_record ->> 'studentId')::uuid
           AND tenant_id = v_tenant;

        v_assigned_students_count := v_assigned_students_count + 1;
    END LOOP;

    -- ── Step D: ONE audit entry for the whole batch (0014 entry point) ────
    PERFORM public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'class.placement_finalize',
        p_entity_type := 'class',
        p_entity_id   := NULL,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json  := jsonb_build_object(
                             'target_academic_year', v_target_year.label,
                             'classes_created', v_created_classes_count,
                             'classes_updated', v_updated_classes_count,
                             'students_assigned', v_assigned_students_count
                         ),
        p_note        := format('Constitution des classes effectuée pour %s : %s classe(s) créée(s), %s mise(s) à jour, %s élève(s) affecté(s).',
                                v_target_year.label, v_created_classes_count, v_updated_classes_count, v_assigned_students_count)
    );

    RETURN jsonb_build_object(
        'ok', TRUE,
        'targetYearId', v_target_year.id,
        'createdClassesCount', v_created_classes_count,
        'updatedClassesCount', v_updated_classes_count,
        'assignedStudentsCount', v_assigned_students_count
    );
END;
$function$
;

create or replace function public.fn_fnv1a(s text)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
AS $function$
declare
    h bigint := 2166136261;   -- 0x811C9DC5 (FNV-1a offset basis, unsigned)
    c integer;
    x bigint;
begin
    if s is null then s := ''; end if;
    for i in 1 .. length(s) loop
        c := ascii(substring(s from i for 1));
        -- XOR needs both operands in signed int range: normalize h.
        x := h;
        if x >= 2147483648 then x := x - 4294967296; end if;
        x := (x # c)::bigint;
        if x < 0 then x := x + 4294967296; end if;
        -- JS Math.imul truncates to 32 bits == mod 2^32 (bigint-safe).
        h := (x * 16777619) % 4294967296;
    end loop;
    return h;
end;
$function$
;
comment on function fn_fnv1a(text) is 'FNV-1a 32-bit hash, bit-exact with the JS Math.imul / Kotlin Int-based canonical implementations (signed-XOR normalization + mod 2^32 multiply). BMP characters only (charCodeAt/code-point parity) — an accepted constraint, identity fields are names/phones.';

create or replace function public.fn_freeze_re_enrollments(p_target_academic_year_id uuid, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
    v_tenant uuid := public.fn_resolve_reenrollment_tenant(p_tenant_id);
    v_target public.academic_years;
    v_total integer := 0;
    v_waiting integer := 0;
    v_frozen integer := 0;
begin
    select * into v_target from public.academic_years ay
     where ay.id = p_target_academic_year_id and ay.tenant_id = v_tenant;
    if v_target.id is null then
        raise exception 'fn_freeze_re_enrollments: année cible introuvable dans le tenant'
          using errcode = '23503';
    end if;

    select count(*),
           count(*) filter (where re.status = 'waiting'),
           count(*) filter (where re.frozen_at is not null)
      into v_total, v_waiting, v_frozen
      from public.re_enrollments re
     where re.tenant_id = v_tenant
       and re.target_academic_year_id = p_target_academic_year_id;

    if v_total = 0 then
        raise exception 'fn_freeze_re_enrollments: aucun candidat généré pour % — générez la liste d''abord', v_target.code
          using errcode = '55006';
    end if;

    if v_frozen > 0 then
        raise exception 'fn_freeze_re_enrollments: la liste % est DÉJÀ figée', v_target.code
          using errcode = '55006';
    end if;

    -- INV-23b: the freeze REFUSES while any candidate is still waiting —
    -- "record that decision rather than leaving them unresolved".
    if v_waiting > 0 then
        raise exception 'fn_freeze_re_enrollments: % candidat(s) en attente de décision pour % — décidez chaque élève avant de figer', v_waiting, v_target.code
          using errcode = '55006';
    end if;

    update public.re_enrollments re
       set frozen_at = now(),
           updated_at = now()
     where re.tenant_id = v_tenant
       and re.target_academic_year_id = p_target_academic_year_id
       and re.frozen_at is null;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 're_enrollment.frozen',
        p_entity_type := 're_enrollment',
        p_entity_id   := null,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json  := jsonb_build_object(
                             'target_academic_year', v_target.code,
                             'total', v_total
                         ),
        p_note        := format('Liste de réinscription %s FIGÉE (%s candidat(s)) — la revue est terminée.', v_target.code, v_total)
    );

    return jsonb_build_object(
        'ok', true,
        'target_academic_year', v_target.code,
        'frozen_count', v_total
    );
end;
$function$
;
comment on function fn_freeze_re_enrollments(uuid,uuid,text,uuid) is 'T-437 (INV-23b): freeze the target-year re-enrollment list — refuses while any candidate is still waiting; after the freeze every decision/re-enrollment is refused. The re-enrollment-side counterpart of the promotion-cycle completion.';

create or replace function public.fn_generate_re_enrollment_candidates(p_source_academic_year_id uuid, p_target_academic_year_id uuid, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
    v_tenant uuid := public.fn_resolve_reenrollment_tenant(p_tenant_id);
    v_source public.academic_years;
    v_target public.academic_years;
    v_frozen_count integer;
    v_total integer := 0;
    v_inserted integer := 0;
begin
    if p_source_academic_year_id is null or p_target_academic_year_id is null then
        raise exception 'fn_generate_re_enrollment_candidates: p_source_academic_year_id et p_target_academic_year_id sont requis'
          using errcode = '22023';
    end if;

    select * into v_source from public.academic_years ay
     where ay.id = p_source_academic_year_id and ay.tenant_id = v_tenant;
    if v_source.id is null then
        raise exception 'fn_generate_re_enrollment_candidates: année source introuvable dans le tenant'
          using errcode = '23503';
    end if;

    select * into v_target from public.academic_years ay
     where ay.id = p_target_academic_year_id and ay.tenant_id = v_tenant;
    if v_target.id is null then
        raise exception 'fn_generate_re_enrollment_candidates: année cible introuvable dans le tenant (créez-la dans Années scolaires d''abord)'
          using errcode = '23503';
    end if;

    if v_source.id = v_target.id then
        raise exception 'fn_generate_re_enrollment_candidates: l''année cible doit différer de l''année source (%)', v_source.code
          using errcode = '22023';
    end if;

    -- The freeze guard (INV-23b): a frozen list is FINAL — no new candidates.
    select count(*) into v_frozen_count
      from public.re_enrollments re
     where re.tenant_id = v_tenant
       and re.target_academic_year_id = v_target.id
       and re.frozen_at is not null;
    if v_frozen_count > 0 then
        raise exception 'fn_generate_re_enrollment_candidates: la liste % → % est FIGÉE (%) — aucune génération possible', v_source.code, v_target.code, v_frozen_count
          using errcode = '55006';
    end if;

    select count(*) into v_total
      from public.re_enrollments re
     where re.tenant_id = v_tenant
       and re.target_academic_year_id = v_target.id;

    -- INV-22a: candidates = the active roster + the FINALIZED source-year
    -- results from student_academic_histories (the promotion flow's writer).
    -- INV-22b: history-less candidates surface final_decision = NULL (the
    -- honest « non finalisé » state). INV-22c: expected level — promoted →
    -- the student's CURRENT grade (0059 already advanced it); repeated → the
    -- source grade (0059 left the row untouched); no history → the canonical
    -- academic_levels progression.
    with roster as (
        select s.id as student_id,
               s.grade_level_code,
               s.class_id
          from public.students s
         where s.tenant_id = v_tenant
           and s.deleted_at is null
           and s.is_active
           and s.enrollment_status in ('active', 'enrolled')
    ),
    hist as (
        select h.student_id, h.grade_code, h.class_id as hist_class_id,
               h.class_name as hist_class_name, h.gpa, h.decision
          from public.student_academic_histories h
         where h.tenant_id = v_tenant
           and h.academic_year = v_source.code
    ),
    snap as (
        select r.student_id,
               r.grade_level_code,
               coalesce(hc.grade_code, r.grade_level_code) as source_grade,
               coalesce(hc.hist_class_id, r.class_id)      as source_class_id,
               coalesce(hc.hist_class_name, cc.name, cc.code) as source_class_name,
               hc.decision as final_decision,
               hc.gpa      as final_average,
               case
                 when hc.decision = 'promoted' then r.grade_level_code
                 when hc.decision = 'repeated' then hc.grade_code
                 else coalesce(nx.next_grade, r.grade_level_code)
               end as expected_grade
          from roster r
          left join hist hc on hc.student_id = r.student_id
          left join public.classes cc on cc.id = r.class_id
          left join lateral (
              select al2.grade_code as next_grade
                from public.academic_levels al1
                join lateral (
                    select aln.grade_code
                      from public.academic_levels aln
                     where aln.tenant_id = v_tenant
                       and aln.is_active
                       and aln.sort_order > al1.sort_order
                     order by aln.sort_order
                     limit 1
                ) al2 on true
               where al1.tenant_id = v_tenant
                 and al1.grade_code = r.grade_level_code
               limit 1
          ) nx on true
    )
    insert into public.re_enrollments (
        tenant_id, student_id,
        source_academic_year_id, target_academic_year_id,
        source_grade_level_code, source_class_id, source_class_name,
        final_decision, final_average, expected_grade_level_code,
        status
    )
    select v_tenant, sn.student_id,
           v_source.id, v_target.id,
           sn.source_grade, sn.source_class_id, sn.source_class_name,
           sn.final_decision, sn.final_average, sn.expected_grade,
           'waiting'
      from snap sn
      on conflict (tenant_id, student_id, target_academic_year_id) do update set
           -- Regeneration REFRESHES the finalized snapshot for rows still
           -- WAITING (generate-before-finalize → finalize → regenerate picks
           -- up the results, INV-22b); DECIDED rows are frozen facts (the
           -- decision was taken on the data the school saw at the time).
           source_grade_level_code = excluded.source_grade_level_code,
           source_class_id = excluded.source_class_id,
           source_class_name = excluded.source_class_name,
           final_decision = excluded.final_decision,
           final_average = excluded.final_average,
           expected_grade_level_code = excluded.expected_grade_level_code,
           updated_at = now()
         where public.re_enrollments.status = 'waiting';

    GET DIAGNOSTICS v_inserted = ROW_COUNT;

    -- The AFTER count (rows now materialized for the target year).
    select count(*) into v_total
      from public.re_enrollments re
     where re.tenant_id = v_tenant
       and re.target_academic_year_id = v_target.id;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 're_enrollment.candidates_generated',
        p_entity_type := 're_enrollment',
        p_entity_id   := null,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json  := jsonb_build_object(
                             'source_academic_year', v_source.code,
                             'target_academic_year', v_target.code,
                             'candidates_written', v_inserted,
                             'total_rows', v_total
                         ),
        p_note        := format('Candidats de réinscription générés pour %s → %s : %s écriture(s) (insertions + rafraîchissements en attente), %s au total.',
                                v_source.code, v_target.code, v_inserted, v_total)
    );

    return jsonb_build_object(
        'ok', true,
        'source_academic_year', v_source.code,
        'target_academic_year', v_target.code,
        'candidates_written', v_inserted,
        'total_rows', v_total
    );
end;
$function$
;
comment on function fn_generate_re_enrollment_candidates(uuid,uuid,uuid,text,uuid) is 'T-437 (INV-22): materialize the re-enrollment candidates for a year pair — the active roster enriched from the FINALIZED student_academic_histories rows of the source year (never a second pass/fail engine). Idempotent (ON CONFLICT DO NOTHING — existing decisions survive); freeze-guarded.';

create or replace function public.fn_get_promotion_cycle_classes(p_cycle_id uuid, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, cycle_id uuid, class_id uuid, class_code text, class_name text, grade_code text, status text, students_awaiting integer, promoted_count integer, repeating_count integer, deferred_count integer, exception_note text, processed_by_name text, processed_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
    v_tenant uuid := public.fn_resolve_cycle_tenant(p_tenant_id);
begin
    return query
    select pcc.id, pcc.cycle_id, pcc.class_id, pcc.class_code, pcc.class_name,
           pcc.grade_code, pcc.status, pcc.students_awaiting,
           pcc.promoted_count, pcc.repeating_count, pcc.deferred_count,
           pcc.exception_note, pcc.processed_by_name, pcc.processed_at
      from public.promotion_cycle_classes pcc
     where pcc.tenant_id = v_tenant
       and pcc.cycle_id = p_cycle_id
     order by pcc.grade_code asc, pcc.class_code asc;
end;
$function$
;

create or replace function public.fn_get_promotion_cycles(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, source_academic_year text, target_academic_year text, status text, notes text, created_by_name text, created_at timestamp with time zone, updated_at timestamp with time zone, completed_at timestamp with time zone, completed_by_name text, classes_total integer, classes_processed integer, students_awaiting integer, promoted_count integer, repeating_count integer, deferred_count integer)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
    v_tenant uuid := public.fn_resolve_cycle_tenant(p_tenant_id);
begin
    return query
    select pc.id,
           pc.source_academic_year,
           pc.target_academic_year,
           pc.status,
           pc.notes,
           pc.created_by_name,
           pc.created_at,
           pc.updated_at,
           pc.completed_at,
           pc.completed_by_name,
           (select count(*)::int from public.promotion_cycle_classes pcc where pcc.cycle_id = pc.id),
           (select count(*)::int from public.promotion_cycle_classes pcc where pcc.cycle_id = pc.id and pcc.status = 'processed'),
           (select coalesce(sum(pcc.students_awaiting), 0)::int from public.promotion_cycle_classes pcc where pcc.cycle_id = pc.id and pcc.status not in ('processed', 'skipped')),
           (select coalesce(sum(pcc.promoted_count), 0)::int from public.promotion_cycle_classes pcc where pcc.cycle_id = pc.id),
           (select coalesce(sum(pcc.repeating_count), 0)::int from public.promotion_cycle_classes pcc where pcc.cycle_id = pc.id),
           (select coalesce(sum(pcc.deferred_count), 0)::int from public.promotion_cycle_classes pcc where pcc.cycle_id = pc.id)
      from public.promotion_cycles pc
     where pc.tenant_id = v_tenant
     order by pc.source_academic_year desc, pc.created_at desc;
end;
$function$
;

create or replace function public.fn_get_re_enrollment_candidates(p_target_academic_year_id uuid, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(re_enrollment_id uuid, student_id uuid, student_code text, student_first_name text, student_last_name text, student_grade_level text, student_class_id uuid, parent_id uuid, parent_code text, parent_display_name text, parent_phone text, source_academic_year text, target_academic_year text, source_grade_level_code text, source_class_name text, final_decision text, final_average numeric, expected_grade_level_code text, status text, target_class_id uuid, target_class_name text, decided_at timestamp with time zone, decided_by_name text, re_enrolled_at timestamp with time zone, installments_written integer, notes text, frozen_at timestamp with time zone, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
    v_tenant uuid := public.fn_resolve_reenrollment_tenant(p_tenant_id);
begin
    return query
    select re.id,
           s.id, s.student_code, s.first_name, s.last_name,
           s.grade_level_code, s.class_id,
           p.id, p.parent_code,
           coalesce(p.display_name, (p.first_name || ' ' || p.last_name)),
           p.primary_phone,
           ay_src.code,
           ay_tgt.code,
           re.source_grade_level_code,
           re.source_class_name,
           re.final_decision,
           re.final_average,
           re.expected_grade_level_code,
           re.status,
           re.target_class_id,
           tc.name,
           re.decided_at,
           re.decided_by_name,
           re.re_enrolled_at,
           re.installments_written,
           re.notes,
           re.frozen_at,
           re.created_at
      from public.re_enrollments re
      join public.students s on s.id = re.student_id
      join public.parents p on p.id = s.parent_id
      join public.academic_years ay_src on ay_src.id = re.source_academic_year_id
      join public.academic_years ay_tgt on ay_tgt.id = re.target_academic_year_id
      left join public.classes tc on tc.id = re.target_class_id
     where re.tenant_id = v_tenant
       and re.target_academic_year_id = p_target_academic_year_id
     order by (re.status = 'waiting') desc, s.last_name, s.first_name;
end;
$function$
;

create or replace function public.fn_re_enroll_student(p_re_enrollment_id uuid, p_grade_level_code text, p_class_id uuid DEFAULT NULL::uuid, p_payment_plan text DEFAULT 'tranches'::text, p_transport_tier text DEFAULT NULL::text, p_installments jsonb DEFAULT '[]'::jsonb, p_ledger_entries jsonb DEFAULT '[]'::jsonb, p_notes text DEFAULT NULL::text, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
    v_tenant uuid := public.fn_resolve_reenrollment_tenant(p_tenant_id);
    v_row public.re_enrollments;
    v_student public.students;
    v_target public.academic_years;
    v_plan text := coalesce(nullif(btrim(p_payment_plan), ''), 'tranches');
    v_ledger_written integer := 0;
    v_inst_written integer := 0;
    v_e record;
    v_i record;
begin
    -- -----------------------------------------------------------------
    -- 0. Guards: lock the candidate, tenant match, freeze, state.
    -- -----------------------------------------------------------------
    select * into v_row
      from public.re_enrollments re
     where re.id = p_re_enrollment_id
       and re.tenant_id = v_tenant
     for update;
    if v_row.id is null then
        raise exception 'fn_re_enroll_student: candidat introuvable dans le tenant'
          using errcode = '42501';
    end if;

    if v_row.frozen_at is not null then
        raise exception 'fn_re_enroll_student: la liste est FIGÉE depuis % — aucune réinscription possible', v_row.frozen_at
          using errcode = '55006';
    end if;

    if v_row.status not in ('waiting', 'started') then
        raise exception 'fn_re_enroll_student: statut « % » non réinscriptible (waiting | started requis)', v_row.status
          using errcode = '55006';
    end if;

    if v_plan not in ('tranches', 'full_annual') then
        raise exception 'fn_re_enroll_student: p_payment_plan « % » invalide (tranches | full_annual)', p_payment_plan
          using errcode = '22023';
    end if;

    select * into v_target from public.academic_years ay
     where ay.id = v_row.target_academic_year_id and ay.tenant_id = v_tenant;
    if v_target.id is null then
        raise exception 'fn_re_enroll_student: année cible introuvable'
          using errcode = '23503';
    end if;

    -- INV-21a: the EXISTING student row — never a duplicate person.
    select * into v_student
      from public.students s
     where s.id = v_row.student_id
       and s.tenant_id = v_tenant
       and s.deleted_at is null
     for update;
    if v_student.id is null then
        raise exception 'fn_re_enroll_student: élève introuvable dans le tenant'
          using errcode = '42501';
    end if;

    -- -----------------------------------------------------------------
    -- 1. The new-year placement (INV-21c: identity/parent/history rows
    --    are NEVER touched — grade/class/plan/transport only).
    -- -----------------------------------------------------------------
    update public.students s
       set grade_level_code = coalesce(nullif(btrim(p_grade_level_code), ''), s.grade_level_code),
           class_id = p_class_id,
           payment_plan = v_plan,
           transport_tier = coalesce(nullif(btrim(coalesce(p_transport_tier, '')), ''), s.transport_tier),
           enrollment_status = 'active',
           updated_at = now()
     where s.id = v_student.id;

    -- -----------------------------------------------------------------
    -- 2. The ledger charges (the register_family_batch wire semantics —
    --    the account_id derived HERE with the REAL uuids).
    -- -----------------------------------------------------------------
    if p_ledger_entries is not null and jsonb_array_length(p_ledger_entries) > 0 then
        insert into public.ledger_entries (
            tenant_id, entry_number, parent_id, student_id, account_id,
            entry_type, amount, category, description, entry_date,
            source_type, source_id, method, receipt_number, payment_status,
            reverses_id, actor_id, actor_name, at, metadata
        )
        select
            v_tenant,
            r.entry_number,
            v_student.parent_id,
            v_student.id,
            'parent:' || v_student.parent_id || ':category:' || r.category ||
              ':student:' || v_student.id,
            r.entry_type,
            r.amount,
            r.category,
            r.description,
            coalesce(nullif(btrim(coalesce(r.entry_date, '')), '')::timestamptz, now()),
            r.source_type,
            r.source_id,
            r.method,
            r.receipt_number,
            r.payment_status,
            r.reverses_id,
            r.actor_id,
            r.actor_name,
            nullif(btrim(coalesce(r.at, '')), '')::timestamptz,
            r.metadata
          from jsonb_to_recordset(p_ledger_entries) as r(
                entry_number    text,
                entry_type      text,
                amount          numeric,
                category        text,
                description     text,
                entry_date      text,
                source_type     text,
                source_id       text,
                method          text,
                receipt_number  text,
                payment_status  text,
                reverses_id     text,
                actor_id        text,
                actor_name      text,
                at              text,
                metadata        jsonb
              )
          on conflict do nothing;

        get diagnostics v_ledger_written = row_count;
    end if;

    -- -----------------------------------------------------------------
    -- 3. The installment tranches (INV-25c: academic_year_id = TARGET —
    --    the charge-belonging year, frozen at write per INV-18b).
    -- -----------------------------------------------------------------
    if p_installments is not null and jsonb_array_length(p_installments) > 0 then
        insert into public.installments (
            tenant_id, parent_id, student_id, category, tranche_number,
            label, amount_due, amount_paid, amount_pending, due_date,
            paid_date, status, academic_cycle, payment_plan,
            is_custom_schedule, custom_schedule_note, source_type, source_id,
            academic_year_id, updated_at
        )
        select
            v_tenant,
            v_student.parent_id,
            v_student.id,
            r.category,
            r.tranche_number,
            r.label,
            r.amount_due,
            coalesce(r.amount_paid, 0),
            coalesce(r.amount_pending, 0),
            nullif(btrim(coalesce(r.due_date, '')), '')::date,
            nullif(btrim(coalesce(r.paid_date, '')), '')::date,
            coalesce(nullif(btrim(coalesce(r.status, '')), ''), 'unpaid'),
            nullif(btrim(coalesce(r.academic_cycle, '')), ''),
            coalesce(nullif(btrim(coalesce(r.payment_plan, '')), ''), 'tranches'),
            coalesce(r.is_custom_schedule, false),
            r.custom_schedule_note,
            r.source_type,
            r.source_id,
            v_target.id,
            now()
          from jsonb_to_recordset(p_installments) as r(
                category             text,
                tranche_number       integer,
                label                text,
                amount_due           numeric,
                amount_paid          numeric,
                amount_pending       numeric,
                due_date             text,
                paid_date            text,
                status               text,
                academic_cycle       text,
                payment_plan         text,
                is_custom_schedule   boolean,
                custom_schedule_note text,
                source_type          text,
                source_id            text
              )
          on conflict do nothing;

        get diagnostics v_inst_written = row_count;
    end if;

    -- -----------------------------------------------------------------
    -- 4. The status flip (INV-23a: re_enrolled is terminal pre-freeze).
    -- -----------------------------------------------------------------
    update public.re_enrollments re
       set status = 're_enrolled',
           target_class_id = p_class_id,
           decided_at = now(),
           decided_by_profile_id = p_actor_profile_id,
           decided_by_name = coalesce(p_actor_name, '—'),
           re_enrolled_at = now(),
           installments_written = v_inst_written,
           notes = coalesce(p_notes, re.notes),
           updated_at = now()
     where re.id = v_row.id;

    -- -----------------------------------------------------------------
    -- 5. ONE audit entry (the 0014 canonical entry point).
    -- -----------------------------------------------------------------
    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'student.re_enrolled',
        p_entity_type := 'student',
        p_entity_id   := v_student.id,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_before_json := jsonb_build_object(
                             'status', v_row.status,
                             'grade_level_code', v_student.grade_level_code,
                             'class_id', v_student.class_id
                         ),
        p_after_json  := jsonb_build_object(
                             'target_academic_year', v_target.code,
                             'grade_level_code', coalesce(nullif(btrim(p_grade_level_code), ''), v_student.grade_level_code),
                             'class_id', p_class_id,
                             'installments_written', v_inst_written,
                             'ledger_written', v_ledger_written
                         ),
        p_note        := format('Réinscription %s : %s %s réinscrit pour %s (%s tranche(s) écrite(s)).',
                                v_target.code, v_student.first_name, v_student.last_name, v_target.code, v_inst_written)
    );

    return jsonb_build_object(
        'ok', true,
        're_enrollment_id', v_row.id,
        'student_id', v_student.id,
        'student_code', v_student.student_code,
        'target_academic_year', v_target.code,
        'installments_written', v_inst_written,
        'ledger_written', v_ledger_written
    );
end;
$function$
;
comment on function fn_re_enroll_student(uuid,text,uuid,text,text,jsonb,jsonb,text,uuid,text,uuid) is 'T-437 (INV-25): the ONE composite re-enrollment transaction — the target-year placement update on the EXISTING student row (identity/parent/history untouched, INV-21a/21c), the client-derived billing legs (the register_family_batch wire shapes) stamped academic_year_id = target (INV-25c), the status flip, ONE audit. Money stays client-derived (§15.39b); previous-year financial rows are never touched (INV-26a).';

create or replace function public.fn_reopen_promotion_cycle_class(p_cycle_id uuid, p_class_id uuid, p_reason text DEFAULT NULL::text, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
    v_tenant uuid := public.fn_resolve_cycle_tenant(p_tenant_id);
    v_cycle public.promotion_cycles;
    v_class_row public.promotion_cycle_classes;
    v_awaiting integer;
begin
    select * into v_cycle
      from public.promotion_cycles pc
     where pc.id = p_cycle_id and pc.tenant_id = v_tenant
     for update;
    if v_cycle.id is null then
        raise exception 'fn_reopen_promotion_cycle_class: cycle % not found in tenant', p_cycle_id
          using errcode = '23503';
    end if;
    if v_cycle.status in ('completed', 'cancelled') then
        raise exception 'fn_reopen_promotion_cycle_class: the cycle for % is % — its classes can no longer be reopened', v_cycle.source_academic_year, v_cycle.status
          using errcode = '55006';
    end if;

    select * into v_class_row
      from public.promotion_cycle_classes pcc
     where pcc.cycle_id = p_cycle_id and pcc.class_id = p_class_id and pcc.tenant_id = v_tenant
     for update;
    if v_class_row.id is null then
        raise exception 'fn_reopen_promotion_cycle_class: class % is not part of cycle %', p_class_id, p_cycle_id
          using errcode = '23503';
    end if;
    if v_class_row.status not in ('processed', 'exception', 'skipped') then
        raise exception 'fn_reopen_promotion_cycle_class: the class % is % — nothing to reopen', v_class_row.class_name, v_class_row.status
          using errcode = '55006';
    end if;

    -- The live awaiting count for a reopened review.
    select count(*) into v_awaiting
      from public.students s
     where s.class_id = p_class_id
       and s.tenant_id = v_tenant
       and s.deleted_at is null
       and s.is_active;

    update public.promotion_cycle_classes pcc
       set status = 'in_review',
           students_awaiting = v_awaiting,
           exception_note = null,
           updated_at = now()
     where pcc.id = v_class_row.id;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'promotion.cycle_class_reopen',
        p_entity_type := 'promotion_cycle',
        p_entity_id   := p_cycle_id,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json   := jsonb_build_object('class', v_class_row.class_name, 'reason', p_reason),
        p_note         := format('Classe %s rouverte dans le cycle %s → %s.', v_class_row.class_name, v_cycle.source_academic_year, v_cycle.target_academic_year)
    );

    return jsonb_build_object('ok', true, 'class_name', v_class_row.class_name, 'status', 'in_review');
end;
$function$
;

create or replace function public.fn_resolve_cycle_tenant(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
    v_tenant uuid;
    v_caller_is_service_role boolean := coalesce(auth.jwt() ->> 'role', '') = 'service_role';
begin
    v_tenant := public.current_tenant_id();
    if p_tenant_id is not null and (v_tenant is null or p_tenant_id <> v_tenant) then
        if not v_caller_is_service_role and not public.is_global_admin() then
            raise exception 'promotion cycle: caller tenant mismatch (p_tenant_id=%)', p_tenant_id
              using errcode = '42501';
        end if;
        v_tenant := p_tenant_id;
    end if;
    if v_tenant is null then
        raise exception 'promotion cycle: caller tenant unresolvable'
          using errcode = '42501';
    end if;
    return v_tenant;
end;
$function$
;

create or replace function public.fn_resolve_reenrollment_tenant(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
    v_tenant uuid;
    v_caller_is_service_role boolean := coalesce(auth.jwt() ->> 'role', '') = 'service_role';
begin
    v_tenant := public.current_tenant_id();
    if p_tenant_id is not null and (v_tenant is null or p_tenant_id <> v_tenant) then
        if not v_caller_is_service_role and not public.is_global_admin() then
            raise exception 're-enrollment: caller tenant mismatch (p_tenant_id=%)', p_tenant_id
              using errcode = '42501';
        end if;
        v_tenant := p_tenant_id;
    end if;
    if v_tenant is null then
        raise exception 're-enrollment: caller tenant unresolvable'
          using errcode = '42501';
    end if;
    return v_tenant;
end;
$function$
;

create or replace function public.fn_set_re_enrollment_decision(p_re_enrollment_id uuid, p_decision text, p_notes text DEFAULT NULL::text, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
    v_tenant uuid := public.fn_resolve_reenrollment_tenant(p_tenant_id);
    v_row public.re_enrollments;
begin
    if p_decision not in ('waiting', 'started', 'not_continuing') then
        raise exception 'fn_set_re_enrollment_decision: décision « % » invalide (waiting | started | not_continuing ; re_enrolled passe par fn_re_enroll_student)', p_decision
          using errcode = '22023';
    end if;

    select * into v_row
      from public.re_enrollments re
     where re.id = p_re_enrollment_id
       and re.tenant_id = v_tenant
     for update;
    if v_row.id is null then
        raise exception 'fn_set_re_enrollment_decision: candidat introuvable dans le tenant'
          using errcode = '42501';
    end if;

    if v_row.frozen_at is not null then
        raise exception 'fn_set_re_enrollment_decision: la liste est FIGÉE depuis % — aucune modification possible', v_row.frozen_at
          using errcode = '55006';
    end if;

    if v_row.status = 're_enrolled' then
        raise exception 'fn_set_re_enrollment_decision: l''élève est déjà réinscrit (%) — décision terminale', v_row.status
          using errcode = '55006';
    end if;

    update public.re_enrollments re
       set status = p_decision,
           decided_at = case when p_decision in ('started', 'not_continuing') then now() else null end,
           decided_by_profile_id = case when p_decision in ('started', 'not_continuing') then p_actor_profile_id else null end,
           decided_by_name = case when p_decision in ('started', 'not_continuing') then coalesce(p_actor_name, '—') else null end,
           notes = coalesce(p_notes, re.notes),
           updated_at = now()
     where re.id = v_row.id;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 're_enrollment.decision',
        p_entity_type := 're_enrollment',
        p_entity_id   := v_row.id,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_before_json := jsonb_build_object('status', v_row.status),
        p_after_json  := jsonb_build_object('status', p_decision),
        p_note        := format('Décision de réinscription : %s → %s.', v_row.status, p_decision)
    );

    return jsonb_build_object('ok', true, 're_enrollment_id', v_row.id, 'status', p_decision);
end;
$function$
;

create or replace function public.fn_stable_hash(s text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
    select upper(substring(lpad(to_hex(public.fn_fnv1a(s)), 8, '0'), 1, 6));
$function$
;
comment on function fn_stable_hash(text) is 'Upper 6 hex chars of the FNV-1a 32-bit hash (fn_fnv1a). Mirrors stableHash() on desktop (src/core/format/id.ts) and Android (core/IdentityCodes.kt).';

create or replace function public.fn_timetable_publish(p_version_id uuid, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant       uuid;
    v_version      public.timetable_versions%ROWTYPE;
    v_archived_id  uuid;
begin
    -- Caller verification (the 0055/0096 hardening pattern): fail closed.
    v_tenant := public.current_tenant_id();
    if v_tenant is null then
        return jsonb_build_object('ok', false, 'reason', 'no_tenant',
                                  'message', 'Aucun tenant résolu pour l''appelant.');
    end if;
    if not public.has_any_role(ARRAY['super_admin','support_staff']) then
        return jsonb_build_object('ok', false, 'reason', 'forbidden',
                                  'message', 'Seuls les administrateurs peuvent publier un emploi du temps.');
    end if;

    select * into v_version
    from public.timetable_versions
    where id = p_version_id and tenant_id = v_tenant
    for update;
    if not found then
        return jsonb_build_object('ok', false, 'reason', 'not_found',
                                  'message', 'Version d''emploi du temps introuvable.');
    end if;
    if v_version.status <> 'approved' then
        return jsonb_build_object('ok', false, 'reason', 'invalid_status',
                                  'message', 'Seule une version approuvée peut être publiée (statut actuel : '
                                             || v_version.status || ').');
    end if;

    -- Archive the currently published version (atomic swap; the partial
    -- unique index timetable_versions_one_published is the backstop).
    update public.timetable_versions
    set status = 'archived', updated_at = now()
    where tenant_id = v_tenant
      and academic_year_id = v_version.academic_year_id
      and status = 'published'
    returning id into v_archived_id;

    update public.timetable_versions
    set status = 'published',
        published_by = p_actor_profile_id,
        published_at = now(),
        updated_at = now()
    where id = p_version_id;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'timetable.version_publish',
        p_entity_type := 'timetable_version',
        p_entity_id   := p_version_id,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json  := jsonb_build_object(
                             'versionNumber', v_version.version_number,
                             'archivedVersionId', v_archived_id
                         ),
        p_note        := format('Emploi du temps version %s publié pour l''année %s.',
                                v_version.version_number, v_version.academic_year_id)
    );

    return jsonb_build_object(
        'ok', true,
        'publishedVersionId', p_version_id,
        'archivedVersionId', v_archived_id
    );
end;
$function$
;

create or replace function public.fn_track_compatible(p_student_filiere text, p_student_specialite text, p_class_filiere text, p_class_specialite text, p_class_grade text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
    v_tenant uuid;
    v_student_filiere text := lower(coalesce(nullif(btrim(p_student_filiere), ''), 'general'));
    v_class_filiere   text := lower(coalesce(nullif(btrim(p_class_filiere), ''), 'general'));
    v_student_spec    text := lower(nullif(btrim(p_student_specialite), ''));
    v_class_spec      text := lower(nullif(btrim(p_class_specialite), ''));
    v_applies         boolean;
begin
    -- Untagged class: always compatible (legacy pre-0107 behavior).
    if p_class_filiere is null or v_class_filiere = 'general' then
        return true;
    end if;

    -- Spécialité integrity: a class tagged with a spécialité requires an
    -- equal student spécialité (an untagged student spécialité passes —
    -- the assignment tags them).
    if v_class_spec is not null and v_student_spec is not null and v_student_spec <> v_class_spec then
        return false;
    end if;

    -- Untagged student: compatible with any tagged class (the assignment
    -- tags the student with the class's stream).
    if p_student_filiere is null or v_student_filiere = 'general' then
        return true;
    end if;

    -- Same stream: compatible.
    if v_student_filiere = v_class_filiere then
        return true;
    end if;

    -- Different stream: compatible only when the student's stream is NOT
    -- applicable at the class's grade — that is a re-streaming promotion
    -- (1AS tronc commun → 2AS filière), the whole point of year-end
    -- class formation. A stream that DOES apply at this grade and differs
    -- (2AS maths student into a 2AS lettres class) is a real conflict.
    v_tenant := coalesce(p_tenant_id, public.current_tenant_id());
    select exists (
        select 1
          from public.filieres f
         where f.tenant_id = v_tenant
           and f.code = v_student_filiere
           and p_class_grade = any (f.applicable_grades)
    ) into v_applies;

    return v_applies is not true;
end;
$function$
;
comment on function fn_track_compatible(text,text,text,text,text,uuid) is 'T-401: the canonical student→class classification-compatibility predicate (class formation guard). Untagged class/student always pass; a differing stream that applies at the target grade is a conflict.';

create or replace function public.generate_activation_code(p_tenant_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
    v_code text;
    v_attempts integer := 0;
begin
    loop
        v_code := lpad((floor(random() * 9000000 + 1000000))::text, 7, '0');
        v_attempts := v_attempts + 1;
        if not exists (
            select 1 from public.activation_codes
             where tenant_id = p_tenant_id
               and code = v_code
               and bound_to_auth_user_id is null
        ) then
            return v_code;
        end if;
        exit when v_attempts > 100;
    end loop;
    raise exception 'Could not generate unique activation code after 100 attempts';
end;
$function$
;
comment on function generate_activation_code(uuid) is 'BACKEND FALLBACK ONLY. Uses random() for activation code — non-deterministic. The canonical rule (spec §7.1) mandates a deterministic FNV-1a hash via the application layer. Both apps now use deterministicActivationCode(parentCode, tenantId). New code paths must NOT call this RPC.';

create or replace function public.generate_receipt_numbers(p_tenant_id uuid, p_count integer)
 RETURNS TABLE(receipt_number text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year INT := EXTRACT(YEAR FROM NOW());
  v_seq INT;
  v_i INT;
BEGIN
  IF p_count IS NULL OR p_count <= 0 THEN
    RETURN;
  END IF;

  -- SEC-111 pattern: the function is SECURITY DEFINER (it must read the
  -- tenant's payments regardless of the caller's RLS). Verify the caller.
  IF coalesce(auth.jwt() ->> 'role', '') <> 'service_role'
     AND NOT public.is_global_admin()
     AND p_tenant_id IS DISTINCT FROM public.current_tenant_id() THEN
      RAISE EXCEPTION 'generate_receipt_numbers: p_tenant_id does not match the authenticated caller''s tenant (SEC-111 pattern, T-015)';
  END IF;

  -- Serialize concurrent batch allocations for the same tenant so two
  -- importers never compute overlapping ranges. Transaction-scoped: released
  -- automatically at commit/rollback.
  PERFORM pg_advisory_xact_lock(hashtext('el-imtiyaz:receipt_numbers:' || p_tenant_id::text));

  SELECT COALESCE(MAX(CAST(SUBSTRING(pay.receipt_number FROM '\d{6}$') AS INT)), 0) INTO v_seq
  FROM payments pay
  WHERE pay.tenant_id = p_tenant_id AND pay.receipt_number LIKE 'REC-' || v_year || '-%';

  FOR v_i IN 1 .. p_count LOOP
    receipt_number := 'REC-' || v_year || '-' || LPAD((v_seq + v_i)::TEXT, 6, '0');
    RETURN NEXT;
  END LOOP;
END;
$function$
;
comment on function generate_receipt_numbers(uuid,integer) is 'T-015/DRIFT-011: allocate the next N canonical receipt numbers for a bulk import (advisory-xact-locked against concurrent allocations; see migration header for the documented residual window vs interactive collect).';

