create or replace function public.get_signed_url(p_bucket_id text, p_object_path text, p_expires_seconds integer DEFAULT 300)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
    v_url text;
    v_tenant_id uuid := public.current_tenant_id();
begin
    -- Validate tenant isolation: object path must start with tenant_id
    if not p_object_path like v_tenant_id::text || '/%' then
        raise exception 'Access denied: object does not belong to caller''s tenant';
    end if;

    -- Use Supabase storage function to generate signed URL
    -- (This is a placeholder — actual signed URL generation happens via
    -- the Supabase JS client or Edge Function; this SQL function is for
    -- server-side use cases where a function needs to return a URL.)
    select 'signed-url-placeholder' into v_url;

    return v_url;
end;
$function$
;
comment on function get_signed_url(text,text,integer) is 'Server-side signed URL generator. Validates tenant isolation. Client-side signed URLs should be generated via the Supabase JS client createSignedUrl() method.';

create or replace function public.handle_new_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
    v_is_admin_invited boolean;
    v_tenant_id uuid;
    v_user_profile_id uuid;
    v_requested_role text;
    v_full_name text;
    v_phone text;
begin
    -- ── Path detection ───────────────────────────────────────────────
    -- The create-user-account EF (server-side) sets app_metadata.created_by_admin=true
    -- before calling auth.admin.createUser. This is the ONLY trusted signal
    -- that the auth.users row came from an admin (not from self-signup).
    -- Self-signup (Google OAuth or email/password from the website) does
    -- NOT set this flag — Supabase's auth.users rows created via the public
    -- signUp endpoint have raw_app_meta_data = NULL or '{}' (the user
    -- cannot set app_metadata via the public API; only via admin API).
    v_is_admin_invited := coalesce(
        (new.raw_app_meta_data ->> 'created_by_admin') = 'true',
        false
    );

    -- ── Tenant resolution ────────────────────────────────────────────
    if v_is_admin_invited then
        -- Admin-invite path: the EF set app_metadata.tenant_id server-side
        -- (line 211 of create-user-account/index.ts). This is trusted.
        v_tenant_id := (new.raw_app_meta_data ->> 'tenant_id')::uuid;
        -- Fallback if the EF didn't set it (shouldn't happen — defensive).
        if v_tenant_id is null then
            select id into v_tenant_id from public.tenants
            where is_active = true
            order by created_at limit 1;
        end if;
    else
        -- Self-signup path: IGNORE client-supplied app_metadata.tenant_id
        -- (an attacker can set raw_user_meta_data freely; raw_app_meta_data
        -- is supposed to be admin-only but Supabase's OAuth flows may
        -- allow client-set app_metadata in some configurations — defense
        -- in depth). Use the canonical default tenant (0023_seed.sql).
        select id into v_tenant_id from public.tenants
        where is_active = true
        order by created_at limit 1;
    end if;

    -- ── Requested role resolution ───────────────────────────────────
    if v_is_admin_invited then
        -- Admin-invite path: the EF set user_metadata.requested_role via
        -- `toRequestedRole(body.role)` (line 78-82 of create-user-account/
        -- index.ts). This maps the 11-role wire code to 'parent' |
        -- 'student' | 'staff' (anything else becomes 'staff'). The actual
        -- role assignment happens in admin_create_user_account RPC (0044),
        -- NOT the trigger — the trigger just records what bucket the
        -- approval request will land in.
        v_requested_role := coalesce(
            new.raw_user_meta_data ->> 'requested_role',
            'parent'
        );
        -- Validate against the CHECK constraint ('parent' | 'student' | 'staff').
        -- If the EF supplied an invalid value, fall back to 'parent' (least-privilege).
        if v_requested_role not in ('parent', 'student', 'staff') then
            v_requested_role := 'parent';
        end if;
    else
        -- Self-signup path: HARDCODE 'parent'. Never trust the client-
        -- supplied raw_user_meta_data.requested_role. The only self-service
        -- role per plan §02.08 is 'parent' (the website is read-mostly
        -- for parents; staff accounts are admin-provisioned only).
        v_requested_role := 'parent';
    end if;

    -- ── Profile display fields ───────────────────────────────────────
    -- For admin-invite: use the EF-supplied full_name + phone (server-side).
    -- For self-signup: prefer the OAuth provider's user_metadata.full_name
    -- (Google returns it server-side via the OAuth flow — NOT client-
    -- controlled); fall back to email if absent. The client CANNOT inject
    -- a fake full_name via the Google OAuth flow (Google sets it server-side
    -- from the Google account profile). Phone is nullable; don't trust
    -- client-supplied phone (the bind_activation_code RPC will collect it
    -- later from the parent record).
    if v_is_admin_invited then
        v_full_name := new.raw_user_meta_data ->> 'full_name';
        v_phone := new.raw_user_meta_data ->> 'phone';
    else
        v_full_name := coalesce(
            new.raw_user_meta_data ->> 'full_name',
            new.raw_user_meta_data ->> 'name',
            new.email
        );
        v_phone := null;  -- collected later via the parent record
    end if;

    -- ── Insert user_profiles row ─────────────────────────────────────
    insert into public.user_profiles (
        auth_user_id, tenant_id, email, display_name, avatar_url,
        phone, status, created_at, updated_at
    ) values (
        new.id, v_tenant_id, new.email,
        v_full_name,
        new.raw_user_meta_data ->> 'avatar_url',
        v_phone,
        'pending',
        now(), now()
    )
    returning id into v_user_profile_id;

    -- ── Insert account_approval_requests row ─────────────────────────
    -- For self-signup: only the email + the hardcoded 'parent' role are
    -- captured. The other fields (activation_code, national_id, phone,
    -- full_name, notes_from_user) are NULL — they're collected later
    -- (activation_code via the bind-activation-code EF; national_id /
    -- phone / full_name via the parent record; notes via the admin
    -- approval UI).
    -- For admin-invite: the EF already supplied the values server-side;
    -- the approval request is auto-resolved by admin_create_user_account
    -- RPC (0044).
    insert into public.account_approval_requests (
        tenant_id, auth_user_id, email, requested_role,
        activation_code, national_id, phone, full_name,
        notes_from_user, status, requested_at
    ) values (
        v_tenant_id, new.id, new.email,
        v_requested_role,
        -- Only trust these fields for admin-invite path (server-side EF).
        case when v_is_admin_invited then new.raw_user_meta_data ->> 'activation_code' else null end,
        case when v_is_admin_invited then new.raw_user_meta_data ->> 'national_id' else null end,
        case when v_is_admin_invited then v_phone else null end,
        case when v_is_admin_invited then v_full_name else null end,
        case when v_is_admin_invited then new.raw_user_meta_data ->> 'notes' else null end,
        'pending',
        now()
    );

    return new;
end;
$function$
;
comment on function handle_new_auth_user() is 'Triggered when a new auth.users row is created. Inserts a matching user_profiles row (status=pending) and an account_approval_requests row so the admin can review the registration.';

create or replace function public.has_any_role(r_codes text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select exists (
        select 1 from unnest(r_codes) as code
        where code = any(public.current_user_roles())
    );
$function$
;
comment on function has_any_role(text[]) is 'Convenience predicate: has_any_role(array[''super_admin'',''financial_officer'']). SECURITY DEFINER so RLS policies can evaluate roles without exposing role_assignments rows.';

create or replace function public.has_permission(p_code text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select p_code = any(public.current_user_permissions());
$function$
;
comment on function has_permission(text) is 'Convenience predicate for inline RLS policies: has_permission(''view_roster''). SECURITY DEFINER so RLS policies can evaluate permissions without exposing the role tables.';

create or replace function public.has_role(r_code text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select r_code = any(public.current_user_roles());
$function$
;
comment on function has_role(text) is 'Convenience predicate: has_role(''super_admin''). SECURITY DEFINER so RLS policies can evaluate roles without exposing role_assignments rows.';

create or replace function public.is_global_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
    select exists (
        select 1 from public.user_profiles
        where auth_user_id = auth.uid()
          and tenant_id is null
    );
$function$
;

create or replace function public.is_own_parent_via_student(p_parent_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select exists (
        select 1
          from public.students s
         where s.auth_user_id = auth.uid()
           and s.deleted_at is null
           and s.parent_id = p_parent_id
    );
$function$
;
comment on function is_own_parent_via_student(uuid) is 'T-413 / STUDENT-103: TRUE when the caller is the bound student of the given parent (the parents_student_sees_own RLS path). SECURITY DEFINER so the parents policy does not recurse into the students policies (the 0067 profile_has_staff_role pattern).';

create or replace function public.mark_payment_bounced(p_tenant_id uuid, p_payment_id uuid, p_reason text, p_actor_id uuid, p_actor_name text DEFAULT 'System'::text, p_as_of timestamp with time zone DEFAULT now())
 RETURNS TABLE(payment_id uuid, payment_status text, reverted_installments integer, total_reverted numeric)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_payment RECORD;
  v_original_ledger RECORD;
  v_remaining NUMERIC;
  v_revert_count INT := 0;
  v_total_reverted NUMERIC := 0;
  v_ins RECORD;
  v_new_paid NUMERIC;
  v_new_pending NUMERIC;
  v_new_status TEXT;
BEGIN
  IF p_reason IS NULL OR BTRIM(p_reason) = '' THEN
    RAISE EXCEPTION 'A bounce reason is mandatory (vault §07.02)';
  END IF;

  SELECT * INTO v_payment
  FROM payments
  WHERE id = p_payment_id AND tenant_id = p_tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payment % not found', p_payment_id;
  END IF;
  IF v_payment.status <> 'pending' THEN
    RAISE EXCEPTION 'Only pending payments can bounce (current status: %)', v_payment.status;
  END IF;

  UPDATE payments
    SET status = 'unpaid',
        notes = CONCAT_WS(' | ', notes, 'Rejet: ' || BTRIM(p_reason)),
        updated_at = p_as_of
    WHERE id = p_payment_id;

  SELECT * INTO v_original_ledger
  FROM ledger_entries
  WHERE source_type = 'payment' AND source_id = p_payment_id::TEXT AND entry_type = 'payment'
  ORDER BY created_at DESC
  LIMIT 1;

  IF FOUND THEN
    INSERT INTO ledger_entries (
      entry_number, tenant_id, account_id, parent_id, student_id, category, amount,
      entry_type, source_type, source_id, method, receipt_number, payment_status,
      reverses_id, description, actor_id, actor_name, at, metadata
    ) VALUES (
      'led-' || EXTRACT(EPOCH FROM NOW()) || '-' || SUBSTRING(gen_random_uuid()::TEXT, 1, 8),
      p_tenant_id,
      v_original_ledger.account_id,
      v_original_ledger.parent_id,
      v_original_ledger.student_id,
      v_original_ledger.category,
      -v_original_ledger.amount,
      'reversal', 'payment', p_payment_id::TEXT,
      v_original_ledger.method, v_original_ledger.receipt_number, 'unpaid',
      v_original_ledger.entry_number,
      'Échec d''encaissement ' || v_payment.receipt_number || ' — chèque/virement rejeté',
      p_actor_id::TEXT, p_actor_name, p_as_of,
      JSONB_BUILD_OBJECT('bounceReason', BTRIM(p_reason), 'originalPaymentId', p_payment_id::TEXT)
    );

    v_remaining := v_payment.amount;
    FOR v_ins IN
      SELECT id, amount_due, amount_paid, amount_pending, category, status, paid_date, due_date
      FROM installments
      WHERE parent_id = v_payment.parent_id
        AND amount_pending > 0
        AND (v_payment.category IS NULL OR category = v_payment.category)
      ORDER BY due_date DESC, id DESC
      FOR UPDATE
    LOOP
      EXIT WHEN v_remaining <= 0;
      DECLARE
        v_revert NUMERIC := LEAST(v_remaining, v_ins.amount_pending);
      BEGIN
        v_new_paid := v_ins.amount_paid;
        v_new_pending := GREATEST(0, v_ins.amount_pending - v_revert);
        IF v_new_paid >= v_ins.amount_due AND v_ins.amount_due > 0 THEN
          v_new_status := 'paid';
        ELSIF v_new_paid > 0 THEN
          v_new_status := 'partial';
        ELSE
          -- Canonical reevaluateInstallmentStatus at the op clock
          -- (equivalence finding A-0042-LADDER).
          IF v_ins.due_date < p_as_of THEN
            v_new_status := 'overdue';
          ELSE
            v_new_status := 'pending';
          END IF;
        END IF;
        UPDATE installments
          SET amount_paid = v_new_paid,
              amount_pending = v_new_pending,
              status = v_new_status,
              paid_date = CASE WHEN v_new_status = 'paid' THEN v_ins.paid_date ELSE NULL END,
              updated_at = p_as_of
        WHERE id = v_ins.id;
        INSERT INTO audit_logs (
          id, tenant_id, action, entity_type, entity_id, actor_id, actor_name,
          diff, note, created_at
        ) VALUES (
          gen_random_uuid(), p_tenant_id, 'installment.revert_allocation', 'installment', v_ins.id,
          p_actor_id, p_actor_name,
          JSONB_BUILD_OBJECT(
            'before', JSONB_BUILD_OBJECT('amountPaid', v_ins.amount_paid, 'amountPending', v_ins.amount_pending, 'status', v_ins.status),
            'after', JSONB_BUILD_OBJECT('amountPaid', v_new_paid, 'amountPending', v_new_pending, 'status', v_new_status, 'reverted', v_revert)
          ),
          'Rejet bancaire — paiement ' || p_payment_id::TEXT || ' échoué.',
          p_as_of
        );
        v_revert_count := v_revert_count + 1;
        v_total_reverted := v_total_reverted + v_revert;
        v_remaining := v_remaining - v_revert;
      END;
    END LOOP;
  END IF;

  INSERT INTO audit_logs (
    id, tenant_id, action, entity_type, entity_id, actor_id, actor_name,
    diff, note, created_at
  ) VALUES (
    gen_random_uuid(), p_tenant_id, 'payment.mark_bounced', 'payment', p_payment_id,
    p_actor_id, p_actor_name,
    JSONB_BUILD_OBJECT(
      'before', JSONB_BUILD_OBJECT('status', 'pending', 'amount', v_payment.amount),
      'after', JSONB_BUILD_OBJECT('status', 'unpaid', 'reason', BTRIM(p_reason), 'revertedInstallments', v_revert_count, 'totalReverted', v_total_reverted)
    ),
    'Rejet bancaire ' || v_payment.receipt_number || ' — motif : ' || BTRIM(p_reason),
    p_as_of
  );

  RETURN QUERY
    SELECT p_payment_id, 'unpaid'::TEXT, v_revert_count, v_total_reverted;
END;
$function$
;

create or replace function public.mark_payment_cleared(p_tenant_id uuid, p_payment_id uuid, p_actor_id uuid, p_actor_name text DEFAULT 'System'::text, p_as_of timestamp with time zone DEFAULT now())
 RETURNS TABLE(payment_id uuid, payment_status text, cleared_installments integer, total_cleared numeric, overflow_credit numeric)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_payment RECORD;
  v_remaining NUMERIC;
  v_cleared_count INT := 0;
  v_total_cleared NUMERIC := 0;
  v_overflow NUMERIC := 0;
  v_ins RECORD;
  v_new_paid NUMERIC;
  v_new_pending NUMERIC;
  v_new_status TEXT;
  v_capacity NUMERIC;
  v_moved NUMERIC;
BEGIN
  SELECT * INTO v_payment
  FROM payments
  WHERE id = p_payment_id AND tenant_id = p_tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payment % not found', p_payment_id;
  END IF;
  IF v_payment.status <> 'pending' THEN
    RAISE EXCEPTION 'Only pending payments can be cleared (current status: %)', v_payment.status;
  END IF;

  UPDATE payments
    SET status = 'paid', updated_at = p_as_of
    WHERE id = p_payment_id;

  v_remaining := v_payment.amount;
  FOR v_ins IN
    SELECT id, amount_due, amount_paid, amount_pending, category, status, paid_date
    FROM installments
    WHERE parent_id = v_payment.parent_id
      AND amount_pending > 0
      AND (v_payment.category IS NULL OR category = v_payment.category)
    ORDER BY due_date ASC, id ASC
    FOR UPDATE
  LOOP
    EXIT WHEN v_remaining <= 0;
    -- BUSINESS-107 (INV-4): the pending→paid move is capped at the
    -- tranche's REMAINING CAPACITY (due − paid), never at the raw pending
    -- amount. Pre-0115 data could carry paid + pending > due (the
    -- cleared-branch bug); the cap stops the clearance from pushing
    -- amount_paid beyond amount_due.
    v_capacity := GREATEST(0, v_ins.amount_due - v_ins.amount_paid);
    v_moved := LEAST(v_remaining, v_ins.amount_pending, v_capacity);
    IF v_moved <= 0 THEN CONTINUE; END IF;
    v_new_paid := v_ins.amount_paid + v_moved;
    v_new_pending := GREATEST(0, v_ins.amount_pending - v_moved);
    IF v_new_paid >= v_ins.amount_due THEN
      v_new_status := 'paid';
    ELSIF v_new_paid > 0 THEN
      v_new_status := 'partial';
    ELSE
      -- Canonical reevaluateInstallmentStatus (clearance.ts) at the op clock.
      IF v_ins.due_date < p_as_of THEN
        v_new_status := 'overdue';
      ELSE
        v_new_status := 'pending';
      END IF;
    END IF;
    UPDATE installments
      SET amount_paid = v_new_paid,
          amount_pending = v_new_pending,
          status = v_new_status,
          paid_date = CASE WHEN v_new_status = 'paid' THEN COALESCE(v_ins.paid_date, p_as_of) ELSE v_ins.paid_date END,
          updated_at = p_as_of
        WHERE id = v_ins.id;
    INSERT INTO audit_logs (
      id, tenant_id, action, entity_type, entity_id, actor_id, actor_name,
      diff, note, created_at
    ) VALUES (
      gen_random_uuid(), p_tenant_id, 'installment.clear_funds', 'installment', v_ins.id,
      p_actor_id, p_actor_name,
      JSONB_BUILD_OBJECT(
        'before', JSONB_BUILD_OBJECT('amountPaid', v_ins.amount_paid, 'amountPending', v_ins.amount_pending, 'status', v_ins.status),
        'after', JSONB_BUILD_OBJECT('amountPaid', v_new_paid, 'amountPending', v_new_pending, 'status', v_new_status, 'cleared', v_moved)
      ),
      'Compensation bancaire — paiement ' || p_payment_id::TEXT || ' confirmé.',
      p_as_of
    );
    v_cleared_count := v_cleared_count + 1;
    v_total_cleared := v_total_cleared + v_moved;
    v_remaining := v_remaining - v_moved;
  END LOOP;

  -- BUSINESS-107: any cleared funds that could NOT move (every tranche at
  -- capacity) become parent_credit — previously they silently vanished
  -- from every read surface.
  v_overflow := GREATEST(0, v_remaining);
  IF v_overflow > 0 THEN
    INSERT INTO ledger_entries (
      entry_number, tenant_id, account_id, parent_id, student_id, category, amount,
      entry_type, source_type, source_id, method, receipt_number, payment_status,
      reverses_id, description, actor_id, actor_name, at, metadata
    ) VALUES (
      'led-' || EXTRACT(EPOCH FROM NOW()) || '-' || SUBSTRING(gen_random_uuid()::TEXT, 1, 8),
      p_tenant_id, 'parent:' || v_payment.parent_id || ':category:parent_credit',
      v_payment.parent_id, NULL, 'parent_credit', -v_overflow,
      'adjustment', 'adjustment', 'credit-' || p_payment_id::TEXT,
      NULL, NULL, NULL, NULL,
      'Crédit parent (excédent de compensation — paiement ' || v_payment.receipt_number || ')',
      p_actor_id::TEXT, p_actor_name, p_as_of,
      JSONB_BUILD_OBJECT('sourcePaymentId', p_payment_id, 'overflowCredit', v_overflow)
    );
  END IF;

  INSERT INTO audit_logs (
    id, tenant_id, action, entity_type, entity_id, actor_id, actor_name,
    diff, note, created_at
  ) VALUES (
    gen_random_uuid(), p_tenant_id, 'payment.mark_cleared', 'payment', p_payment_id,
    p_actor_id, p_actor_name,
    JSONB_BUILD_OBJECT(
      'before', JSONB_BUILD_OBJECT('status', 'pending', 'amount', v_payment.amount),
      'after', JSONB_BUILD_OBJECT('status', 'paid', 'clearedInstallments', v_cleared_count,
                                  'totalCleared', v_total_cleared, 'overflowCredit', v_overflow)
    ),
    'Compensation bancaire confirmée pour ' || v_payment.receipt_number,
    p_as_of
  );

  RETURN QUERY
    SELECT p_payment_id, 'paid'::TEXT, v_cleared_count, v_total_cleared, v_overflow;
END;
$function$
;

create or replace function public.mark_sync_queue_processed(p_id text, p_status text, p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    IF p_status NOT IN ('synced','failed','skipped_mock') THEN
        RAISE EXCEPTION 'Invalid status: %', p_status;
    END IF;
    UPDATE public.sync_queue
       SET status          = p_status,
           last_error      = p_error,
           last_attempt_at = now(),
           pushed_at       = CASE WHEN p_status = 'synced' THEN now() ELSE pushed_at END
     WHERE id = p_id;
END;
$function$
;

create or replace function public.next_receipt_number(p_tenant_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year INT := EXTRACT(YEAR FROM NOW());
  v_seq INT;
BEGIN
  SELECT COALESCE(MAX(CAST(SUBSTRING(pay.receipt_number FROM '\d{6}$') AS INT)), 0) + 1 INTO v_seq
  FROM payments pay
  WHERE pay.tenant_id = p_tenant_id AND pay.receipt_number LIKE 'REC-' || v_year || '-%';
  RETURN 'REC-' || v_year || '-' || LPAD(v_seq::TEXT, 6, '0');
END;
$function$
;
comment on function next_receipt_number(uuid) is 'T-015/DRIFT-011: canonical receipt number (ADR-004) — algorithm verbatim from collect_and_allocate_payment (migration 0040). Read-only; allocation happens in the caller''s transaction.';

create or replace function public.notify_chat_members_on_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_channel_name text;
    v_sender_label text;
    v_member_ids uuid[];
    v_member_id uuid;
begin
    -- Soft-deleted rows are never INSERTed (deleted_at is UPDATE-only) —
    -- no guard needed here; the touch trigger (0061) has the same shape.

    select name, member_ids
      into v_channel_name, v_member_ids
      from public.chat_channels
     where id = new.channel_id;

    if v_member_ids is null then
        -- Channel vanished (should not happen — FK) — nothing to fan out.
        return new;
    end if;

    -- Sender label for the title (display_name falls back to email).
    select coalesce(display_name, email)
      into v_sender_label
      from public.user_profiles
     where id = new.author_id;

    foreach v_member_id in array v_member_ids
    loop
        if v_member_id is distinct from new.author_id then
            insert into public.notifications (
                tenant_id,
                kind,
                title,
                body,
                priority,
                source,
                source_label,
                target_user_id,
                link_entity_type,
                link_entity_id,
                created_by,
                triggered_at
            ) values (
                new.tenant_id,
                'info',
                'Nouveau message' ||
                    case
                        when v_channel_name is not null and v_sender_label is not null
                            then ' de ' || v_sender_label || ' — ' || v_channel_name
                        when v_sender_label is not null
                            then ' de ' || v_sender_label
                        when v_channel_name is not null
                            then ' — ' || v_channel_name
                        else ''
                    end,
                left(coalesce(new.body, ''), 160),
                'medium',
                'system',
                'Messagerie',
                v_member_id,
                'chat_channel',
                new.channel_id,
                new.author_id,
                coalesce(new.sent_at, new.created_at)
            );
        end if;
    end loop;

    return new;
end;
$function$
;
comment on function notify_chat_members_on_message() is 'MSG-200: fan out one notification per channel member (except the author) on every chat message insert. SECURITY DEFINER per the 0061 touch-trigger convention — parents can author messages while notifications_insert is staff-or-self-gated; the body only targets explicit channel members.';

create or replace function public.notify_parent_user(p_parent_id uuid, p_title text, p_kind text DEFAULT 'alert'::text, p_body text DEFAULT NULL::text, p_priority text DEFAULT 'medium'::text, p_source_label text DEFAULT NULL::text, p_link_entity_type text DEFAULT 'parent'::text, p_link_entity_id uuid DEFAULT NULL::uuid, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant      uuid := public.current_tenant_id();
    v_profile_id  uuid;
    v_status      text;
    v_notif_id    uuid;
begin
    -- Caller verification (the hardened pattern — see header).
    if v_tenant is null then
        raise exception 'notify_parent_user: caller has no tenant context'
            using errcode = '42501';
    end if;
    if not public.has_any_role(array['super_admin', 'manager', 'support_staff', 'financial_officer', 'teacher']) then
        raise exception 'notify_parent_user: only staff may send parent notifications'
            using errcode = '42501';
    end if;

    -- The parent must exist in the caller's tenant.
    if not exists (
        select 1 from public.parents p
         where p.id = p_parent_id
           and p.tenant_id = v_tenant
           and p.deleted_at is null
    ) then
        raise exception 'notify_parent_user: parent % not found in the caller''s tenant', p_parent_id
            using errcode = '22023';
    end if;

    -- Resolve the parent's portal account (parents.auth_user_id →
    -- user_profiles.id). NULL when the parent never activated.
    select up.id, up.status
      into v_profile_id, v_status
      from public.parents p
      join public.user_profiles up on up.auth_user_id = p.auth_user_id
     where p.id = p_parent_id
       and p.tenant_id = v_tenant
     limit 1;

    if v_profile_id is null or v_status is distinct from 'active' then
        -- Undeliverable in-app: the parent has no active portal account.
        -- Return NULL so the caller can count/report it honestly.
        return null;
    end if;

    insert into public.notifications (
        tenant_id, kind, title, body, priority,
        source, source_label,
        target_user_id,
        link_entity_type, link_entity_id,
        created_by, triggered_at
    ) values (
        v_tenant,
        case
            when p_kind in ('alert', 'info', 'warning', 'success', 'error', 'system') then p_kind
            else 'alert'
        end,
        p_title,
        p_body,
        case
            when p_priority in ('low', 'medium', 'high', 'urgent') then p_priority
            else 'medium'
        end,
        'system',
        coalesce(p_source_label, 'Module Finances'),
        v_profile_id,
        coalesce(p_link_entity_type, 'parent'),
        coalesce(p_link_entity_id, p_parent_id),
        p_actor_id,
        now()
    )
    returning id into v_notif_id;

    return v_notif_id;
end;
$function$
;
comment on function notify_parent_user(uuid,text,text,text,text,text,text,uuid,uuid) is 'MSG-101: canonical parent notification writer. SECURITY DEFINER (hardened pattern): staff-gated, tenant-scoped, resolves parents.auth_user_id → user_profiles.id server-side (financial officers cannot read other profiles under RLS). Returns the notification id, or NULL when the parent has no ACTIVE portal account (undeliverable in-app).';

create or replace function public.notify_parents_on_homework()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    insert into public.notifications (
        tenant_id, kind, title, body, priority,
        source, source_label,
        target_user_id,
        link_entity_type, link_entity_id,
        created_by, triggered_at
    )
    select distinct
        new.tenant_id,
        'info',
        'Nouveau devoir — ' || coalesce(new.subject_name, 'Matière'),
        left(
            new.title ||
            case when btrim(coalesce(new.description, '')) <> ''
                     then ' — ' || left(btrim(new.description), 120)
                 else ''
            end ||
            case when new.due_date is not null
                     then ' (à rendre le ' || to_char(new.due_date, 'DD/MM/YYYY') || ')'
                 else ''
            end,
            200
        ),
        'medium',
        'system',
        'Devoirs',
        up.id,
        'homework',
        new.id,
        new.teacher_id,
        now()
      from public.students s
      join public.parents p on p.id = s.parent_id and p.tenant_id = new.tenant_id
      join public.user_profiles up on up.auth_user_id = p.auth_user_id and up.status = 'active'
     where s.class_id = new.class_id
       and s.tenant_id = new.tenant_id
       and s.is_active = true
       and s.deleted_at is null
       and s.enrollment_status = 'active'
       and p.deleted_at is null
       and p.auth_user_id is not null;

    return new;
end;
$function$
;
comment on function notify_parents_on_homework() is 'MSG-201: fan out one notification per distinct parent (with an ACTIVE portal account) of the class roster on every homework INSERT. SECURITY DEFINER per the 0061/0075 convention — only roster-derived targets, no client-injectable destination.';

create or replace function public.open_parent_admin_channel(p_name text DEFAULT NULL::text)
 RETURNS chat_channels
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_me     uuid := public.current_user_profile_id();
    v_tenant uuid := public.current_tenant_id();
    v_admin  uuid;
    v_a      uuid;
    v_b      uuid;
    v_code   text;
    v_ch     public.chat_channels;
begin
    if v_me is null then
        raise exception 'open_parent_admin_channel: no user profile for the caller (auth.uid() has no user_profiles row)'
            using errcode = '42501';
    end if;
    if v_tenant is null then
        raise exception 'open_parent_admin_channel: caller has no tenant'
            using errcode = '42501';
    end if;

    -- T-413 / STUDENT-104: the user side of the messenger is for PARENT and
    -- STUDENT accounts (an approved student is a system user who may reach
    -- the Administration — ADR-012's user↔admin scope). Staff keep using
    -- create_direct_channel (0061).
    if not exists (
        select 1
          from public.role_assignments ra
          join public.roles r on r.id = ra.role_id
         where ra.user_profile_id = v_me
           and (ra.tenant_id = v_tenant or ra.tenant_id is null)
           and ra.revoked_at is null
           and r.code in ('parent', 'student')
    ) then
        raise exception 'open_parent_admin_channel: only parent or student accounts may open the administration channel'
            using errcode = '42501';
    end if;
    if public.has_any_role(array['super_admin', 'manager', 'support_staff', 'financial_officer', 'teacher']) then
        raise exception 'open_parent_admin_channel: staff members must use create_direct_channel (0061)'
            using errcode = '42501';
    end if;

    -- Resolve the Administrator: the tenant's oldest ACTIVE super_admin,
    -- falling back to the oldest ACTIVE support_staff.
    select up.id into v_admin
      from public.user_profiles up
      join public.role_assignments ra on ra.user_profile_id = up.id and ra.revoked_at is null
      join public.roles r on r.id = ra.role_id
     where r.code = 'super_admin'
       and (ra.tenant_id = v_tenant or ra.tenant_id is null)
       and up.status = 'active'
     order by up.created_at
     limit 1;

    if v_admin is null then
        select up.id into v_admin
          from public.user_profiles up
          join public.role_assignments ra on ra.user_profile_id = up.id and ra.revoked_at is null
          join public.roles r on r.id = ra.role_id
         where r.code = 'support_staff'
           and (ra.tenant_id = v_tenant or ra.tenant_id is null)
           and up.status = 'active'
         order by up.created_at
         limit 1;
    end if;

    if v_admin is null then
        raise exception 'open_parent_admin_channel: no active administrator account found for this tenant (create the super_admin account first)'
            using errcode = '02000';
    end if;
    if v_admin = v_me then
        raise exception 'open_parent_admin_channel: the administrator cannot open a channel with themselves'
            using errcode = '22023';
    end if;

    -- Deterministic idempotent DM code — the SAME pair algorithm as 0061's
    -- create_direct_channel, so the channel a user opens here is the very
    -- channel the staff side's openParentChannel/create_direct_channel
    -- would resolve to for the same pair (one conversation per pair).
    v_a := least(v_me, v_admin);
    v_b := greatest(v_me, v_admin);
    v_code := 'DM-' || v_a || '-' || v_b;

    insert into public.chat_channels (
        tenant_id, code, name, channel_type, member_ids, created_by, description
    ) values (
        v_tenant, v_code,
        coalesce(nullif(btrim(p_name), ''), 'Administration'),
        'direct', array[v_a, v_b], v_me,
        'User (parent/student) to administration channel (0067, ADR-012; student eligibility added by 0116, T-413)'
    )
    on conflict (tenant_id, code) do nothing
    returning * into v_ch;

    if v_ch is null then
        -- Already exists (idempotent re-open by either member of the pair).
        select * into v_ch
          from public.chat_channels
         where tenant_id = v_tenant and code = v_code;
    end if;

    if v_ch is null then
        raise exception 'open_parent_admin_channel: channel vanished after upsert'
            using errcode = '22023';
    end if;

    -- Audit the creation (0014 convention; mirrors 0061's chat.channel_create).
    if v_ch.created_by = v_me then
        insert into public.audit_logs (
            tenant_id, action, entity_type, entity_id, actor_id, after_json, note
        ) values (
            v_tenant, 'chat.parent_admin_channel_open', 'chat_channel', v_ch.id, v_me,
            to_jsonb(v_ch), 'open_parent_admin_channel (idempotent RPC, migration 0067 / ADR-012; student eligibility: 0116, T-413)'
        );
    end if;

    return v_ch;
end;
$function$
;
comment on function open_parent_admin_channel(text) is 'CHAT-200a (0067 / ADR-012; student eligibility added by 0116 / T-413): the USER side of the messenger — idempotently opens (or returns) the 1:1 direct channel between the calling parent-or-student and the tenant Administrator (super_admin, fallback support_staff). Deterministic DM code from the sorted member pair — the same channel create_direct_channel resolves for the pair. SECURITY DEFINER with full caller verification (parent/student-role gate, staff excluded).';

create or replace function public.prevent_self_releve_entry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_personnel_user_id uuid;
begin
    -- T-482 / ADR-034: auto rows are recorded by the canonical
    -- record_auto_releve_entry RPC — the system side effect of the caller's
    -- OWN classroom operation (§09.06), where recorded_by == the teacher's
    -- user id BY DESIGN. The §09.05 ban below governs manual rows only.
    if new.entry_source = 'auto' then
        return new;
    end if;

    select user_id into v_personnel_user_id from public.personnel where id = new.personnel_id;

    if v_personnel_user_id is not null and v_personnel_user_id = new.recorded_by then
        raise exception 'Plan §09.05 violation: a teacher cannot record their own Releve entry. Use a separate administrator.';
    end if;

    return new;
end;
$function$
;

create or replace function public.profile_has_staff_role(p_profile_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select exists (
        select 1
          from public.role_assignments ra
          join public.roles r on r.id = ra.role_id
         where ra.user_profile_id = p_profile_id
           and ra.revoked_at is null
           and (ra.tenant_id = public.current_tenant_id() or ra.tenant_id is null)
           -- T-463 (0135): the FULL employee set — the same 9-role list
           -- 0105 gave create_direct_channel (the 0023 census minus
           -- parent/student). The 0067 5-role list predated the workforce
           -- parity mandate and made worker group-channel raw inserts
           -- RLS-impossible (CHAT-300's permissions half).
           and r.code = any(array[
               'super_admin', 'manager', 'support_staff', 'financial_officer', 'teacher',
               'worker', 'buyer', 'driver', 'warehouse_worker'
           ])
    );
$function$
;
comment on function profile_has_staff_role(uuid) is 'CHAT-300 (0135): does this profile hold an ACTIVE employee role (the 0105 9-role set — office + workforce) in the CURRENT tenant? Caller-scoped (current_tenant_id) — for RLS policies. Use profile_has_staff_role_in_tenant for row-tenant derivations (the 0135 trigger/backfill).';

create or replace function public.profile_has_staff_role_in_tenant(p_profile_id uuid, p_tenant_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select exists (
        select 1
          from public.role_assignments ra
          join public.roles r on r.id = ra.role_id
         where ra.user_profile_id = p_profile_id
           and ra.revoked_at is null
           and (ra.tenant_id = p_tenant_id or ra.tenant_id is null)
           and r.code = any(array[
               'super_admin', 'manager', 'support_staff', 'financial_officer', 'teacher',
               'worker', 'buyer', 'driver', 'warehouse_worker'
           ])
    );
$function$
;
comment on function profile_has_staff_role_in_tenant(uuid,uuid) is 'CHAT-300 (0135): the row-tenant variant of profile_has_staff_role — does this profile hold an ACTIVE employee role in the GIVEN tenant? The scope-derivation trigger and the 0135 backfill use this (current_tenant_id() is caller-scoped and NULL in caller-less migration contexts).';

create or replace function public.pull_device_tokens_for_sync(p_tenant_id uuid, p_since timestamp with time zone DEFAULT '1970-01-01 00:00:00+00'::timestamp with time zone, p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
      FROM (
        SELECT id, tenant_id, user_id, token, platform, app_version,
               is_active, last_seen_at, created_at, updated_at
          FROM public.device_tokens
         WHERE tenant_id = p_tenant_id
           AND updated_at >= p_since
           AND is_active = true
         ORDER BY updated_at ASC
         LIMIT p_limit
      ) t;
$function$
;

create or replace function public.pull_ledger_entries_for_sync(p_tenant_id uuid, p_since timestamp with time zone DEFAULT '1970-01-01 00:00:00+00'::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 2000)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
      FROM (
        SELECT le.id, le.tenant_id, le.entry_number, le.parent_id, le.student_id, le.account_id,
               le.entry_type, le.amount, le.category, le.description, le.entry_date, le.created_at,
               le.source_type, le.source_id, le.method, le.receipt_number, le.payment_status,
               -- 0037 (preserved): resolve the reversal pointer into the server UUID space
               CASE WHEN le.reverses_id IS NULL THEN NULL
                    ELSE COALESCE(
                        (SELECT ref.id::text
                           FROM public.ledger_entries ref
                          WHERE ref.tenant_id = le.tenant_id
                            AND (ref.entry_number = le.reverses_id
                                 OR (ref.source_type = 'payment' AND ref.source_id = le.reverses_id)
                                 OR ref.id::text = le.reverses_id)
                          LIMIT 1),
                        le.reverses_id)
               END AS reverses_id,
               le.actor_id, le.actor_name, le.at, le.metadata,
               -- 0143 (SYNC-304): the change-time cursor column — the Android
               -- drain advances on it (previously never returned: the client
               -- cursor was NULL on every row).
               le.updated_at
          FROM public.ledger_entries le
         WHERE le.tenant_id = p_tenant_id
           AND (
             le.updated_at > p_since
             OR (le.updated_at = p_since AND (p_after_id IS NULL OR le.id > p_after_id))
           )
         ORDER BY le.updated_at ASC, le.id ASC
         LIMIT p_limit
      ) t;
$function$
;

create or replace function public.pull_parents_for_sync(p_tenant_id uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 500)
 RETURNS TABLE(id uuid, tenant_id uuid, parent_code text, first_name text, last_name text, display_name text, primary_phone text, secondary_phone text, email text, occupation text, address text, relationship text, is_active boolean, transport_destination text, city_tier text, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    p.id, p.tenant_id, p.parent_code, p.first_name, p.last_name, p.display_name,
    p.primary_phone, p.secondary_phone, p.email, p.occupation, p.address,
    p.relationship, p.is_active,
    p.transport_destination, p.city_tier,
    p.created_at, p.updated_at
  FROM public.parents p
  WHERE p.tenant_id = p_tenant_id
    AND p.deleted_at IS NULL
    AND (
      p_since IS NULL
      OR p.updated_at > p_since
      OR (p_after_id IS NOT NULL AND p.updated_at = p_since AND p.id > p_after_id)
    )
  ORDER BY p.updated_at ASC, p.id ASC
  LIMIT p_limit;
END;
$function$
;

create or replace function public.pull_payments_for_sync(p_tenant_id uuid, p_since timestamp with time zone DEFAULT '1970-01-01 00:00:00+00'::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 1000)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb)
      FROM (
        SELECT id, tenant_id, payment_number, receipt_number, parent_id, student_id,
               invoice_id, installment_id, amount, method, category, status,
               check_number, check_bank_name, check_issue_date, check_clearance_date,
               transfer_reference, transfer_source_bank, proof_path,
               collected_at, collected_by, notes, reversal_of_payment_id,
               created_at, updated_at
          FROM public.payments
         WHERE tenant_id = p_tenant_id
           AND (
             updated_at > p_since
             OR (updated_at = p_since AND (p_after_id IS NULL OR id > p_after_id))
           )
         ORDER BY updated_at ASC, id ASC
         LIMIT p_limit
      ) t;
$function$
;

create or replace function public.pull_students_for_sync(p_tenant_id uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 500)
 RETURNS TABLE(id uuid, tenant_id uuid, student_code text, parent_id uuid, first_name text, middle_name text, last_name text, display_name text, date_of_birth date, gender text, grade_level_id uuid, class_id uuid, enrollment_date date, enrollment_status text, medical_notes text, is_active boolean, grade_level_code text, transport_tier text, payment_plan text, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    s.id, s.tenant_id, s.student_code, s.parent_id,
    s.first_name, s.middle_name, s.last_name, s.display_name,
    s.date_of_birth, s.gender, s.grade_level_id, s.class_id,
    s.enrollment_date, s.enrollment_status, s.medical_notes, s.is_active,
    s.grade_level_code, s.transport_tier, s.payment_plan,
    s.created_at, s.updated_at
  FROM public.students s
  WHERE s.tenant_id = p_tenant_id
    AND s.deleted_at IS NULL
    AND (
      p_since IS NULL
      OR s.updated_at > p_since
      OR (p_after_id IS NOT NULL AND s.updated_at = p_since AND s.id > p_after_id)
    )
  ORDER BY s.updated_at ASC, s.id ASC
  LIMIT p_limit;
END;
$function$
;

create or replace function public.purge_expired_backups(p_tenant_id uuid)
 RETURNS TABLE(archive_id uuid, file_name text, purged_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_archive record;
begin
    -- BKUP-507: the alias `ba` + fully-qualified references resolve the
    -- OUT-parameter/column ambiguity (42702). The OUT parameter names stay
    -- identical — the returned row-key contract is unchanged.
    for v_archive in
        select ba.id, ba.file_name
          from public.backup_archives ba
         where ba.tenant_id = p_tenant_id
           and ba.retention_expires_at < now()
           and ba.status <> 'purged'
    loop
        update public.backup_archives
           set status = 'purged',
               purge_at = now(),
               updated_at = now()
         where id = v_archive.id;

        perform public.write_audit_log(
            p_tenant_id := p_tenant_id,
            p_action := 'backup.purge',
            p_entity_type := 'backup_archive',
            p_entity_id := v_archive.id,
            p_after_json := jsonb_build_object('file_name', v_archive.file_name, 'purged_at', now())
        );

        return query select v_archive.id, v_archive.file_name, now();
    end loop;
end;
$function$
;
comment on function purge_expired_backups(uuid) is 'Marks expired backup archives as purged in metadata. Actual ciphertext deletion happens in Electron IndexedDB (plan §13.03). T-415/BKUP-507: the body now alias-qualifies every column reference (the 0022 unqualified file_name collided with the RETURNS TABLE OUT parameter — 42702 on every call).';

create or replace function public.purge_student_parent_domain(p_confirm_phrase text, p_dry_run boolean DEFAULT true, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant         uuid;
    v_counts         jsonb := '{}'::jsonb;
    v_total          bigint := 0;
    v_n              bigint;
    v_parent_ids     uuid[];
    v_student_ids    uuid[];
    v_auth_ids       uuid[];
    v_profile_ids    uuid[];
    v_channel_ids    uuid[];
    v_audit_id       uuid;
    v_other_queue    bigint;
begin
    -- Gate 1 — super_admin OR a DB-superuser console session (ADR-027).
    if not (
        public.has_role('super_admin')
        or exists (select 1 from pg_roles where rolname = session_user and rolsuper)
    ) then
        return jsonb_build_object('ok', false, 'code', 'forbidden');
    end if;

    -- Gate 2 — tenant resolution (explicit param → caller context → fail
    -- closed; NEVER a null-tenant match-everything).
    v_tenant := coalesce(p_tenant_id, public.current_tenant_id());
    if v_tenant is null then
        return jsonb_build_object('ok', false, 'code', 'tenant_unresolved');
    end if;
    if not exists (select 1 from public.tenants where id = v_tenant) then
        return jsonb_build_object('ok', false, 'code', 'invalid_tenant');
    end if;

    -- Gate 3 — the typed phrase, execute mode only (dry-run deletes nothing).
    if not p_dry_run and coalesce(btrim(p_confirm_phrase), '') <> 'PURGER' then
        return jsonb_build_object('ok', false, 'code', 'confirmation_required');
    end if;

    -- ------------------------------------------------------------------
    -- Target collection — EVERY set is resolved BEFORE any delete so the
    -- dry-run preview and the execution see the SAME blast radius.
    -- ------------------------------------------------------------------
    select coalesce(array_agg(p.id), '{}') into v_parent_ids
      from public.parents p where p.tenant_id = v_tenant;

    select coalesce(array_agg(s.id), '{}') into v_student_ids
      from public.students s where s.tenant_id = v_tenant;

    -- The portal accounts of the domain — parents' + students' auth users,
    -- EXCLUDING any account that holds a staff role (the staff guard).
    select coalesce(array_agg(distinct au), '{}') into v_auth_ids
      from (
            select p.auth_user_id as au from public.parents p
             where p.tenant_id = v_tenant and p.auth_user_id is not null
            union
            select s.auth_user_id from public.students s
             where s.tenant_id = v_tenant and s.auth_user_id is not null
           ) ids(au)
     where not exists (
            select 1
              from public.user_profiles up
              join public.role_assignments ra on ra.user_profile_id = up.id
                                              and ra.revoked_at is null
              join public.roles r on r.id = ra.role_id and r.is_staff_role
             where up.auth_user_id = ids.au
           );

    select coalesce(array_agg(up.id), '{}') into v_profile_ids
      from public.user_profiles up
     where up.auth_user_id = any(v_auth_ids);

    -- Parent-member chat channels (ADR-012 parent↔admin direct channels;
    -- member_ids is a NATIVE uuid[] of user_profiles.id (0010) → the
    -- array-overlap operator &&, NOT a jsonb operator).
    select coalesce(array_agg(c.id), '{}') into v_channel_ids
      from public.chat_channels c
     where c.tenant_id = v_tenant
       and c.member_ids && v_profile_ids;

    -- The per-family helper: same predicate for the count (dry-run) and
    -- the delete (execute) — the preview can never drift from the blast.
    -- ------------------------------------------------------------------
    -- A. The financial closure (children before parents, RESTRICT-safe)
    -- ------------------------------------------------------------------
    if p_dry_run then
        select count(*) into v_n from public.payment_allocations t
         where t.tenant_id = v_tenant;
    else
        delete from public.payment_allocations t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('payment_allocations', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.payments t where t.tenant_id = v_tenant;
    else
        delete from public.payments t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('payments', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.installments t where t.tenant_id = v_tenant;
    else
        delete from public.installments t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('installments', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.invoices t where t.tenant_id = v_tenant;
    else
        delete from public.invoices t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('invoices', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.ledger_entries t where t.tenant_id = v_tenant;
    else
        delete from public.ledger_entries t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('ledger_entries', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.account_adjustments t where t.tenant_id = v_tenant;
    else
        delete from public.account_adjustments t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('account_adjustments', v_n); v_total := v_total + v_n;

    -- receipts: in the file chain (0007) but ABSENT live (§57c) — the
    -- existence guard keeps the branch dead where the table does not exist
    -- (PL/pgSQL compiles lazily; the dead branch never parses).
    if exists (select 1 from information_schema.tables
                where table_schema = 'public' and table_name = 'receipts') then
        if p_dry_run then
            select count(*) into v_n from public.receipts t where t.tenant_id = v_tenant;
        else
            delete from public.receipts t where t.tenant_id = v_tenant;
            get diagnostics v_n = row_count;
        end if;
        v_counts := v_counts || jsonb_build_object('receipts', v_n); v_total := v_total + v_n;
    end if;

    if p_dry_run then
        select count(*) into v_n from public.discount_applications t where t.tenant_id = v_tenant;
    else
        delete from public.discount_applications t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('discount_applications', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.service_enrollments t where t.tenant_id = v_tenant;
    else
        delete from public.service_enrollments t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('service_enrollments', v_n); v_total := v_total + v_n;

    -- ------------------------------------------------------------------
    -- B. The academic student data (incl. the 0004 no-FK soft references)
    -- ------------------------------------------------------------------
    if p_dry_run then
        select count(*) into v_n from public.grades t where t.tenant_id = v_tenant;
    else
        delete from public.grades t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('grades', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.attendance_records t where t.tenant_id = v_tenant;
    else
        delete from public.attendance_records t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('attendance_records', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.academic_history t where t.tenant_id = v_tenant;
    else
        delete from public.academic_history t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('academic_history', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.student_academic_histories t where t.tenant_id = v_tenant;
    else
        delete from public.student_academic_histories t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('student_academic_histories', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.student_documents t where t.tenant_id = v_tenant;
    else
        delete from public.student_documents t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('student_documents', v_n); v_total := v_total + v_n;

    -- ------------------------------------------------------------------
    -- C. The CRM core (links before principals; parents LAST)
    -- ------------------------------------------------------------------
    if p_dry_run then
        select count(*) into v_n from public.activation_codes t where t.tenant_id = v_tenant;
    else
        delete from public.activation_codes t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('activation_codes', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.parent_student_links t where t.tenant_id = v_tenant;
    else
        delete from public.parent_student_links t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('parent_student_links', v_n); v_total := v_total + v_n;

    -- approval requests LINKED to purged rows, PLUS any request keyed to
    -- an auth account the purge is deleting (PURGE-502: the GoTrue trigger
    -- creates requests keyed by auth_user_id with target_parent_id NULL,
    -- and 0044 resolves them without ever linking a target — after the
    -- bind, the parents row claims the same auth_user_id; leaving the
    -- request behind would orphan it against the deleted account). A
    -- pending signup whose account is NOT claimed by any parent/student
    -- row keeps BOTH its account and its request (ADR-027's pre-parent
    -- boundary preserved — v_auth_ids only contains claimed accounts).
    if p_dry_run then
        select count(*) into v_n from public.account_approval_requests t
         where t.tenant_id = v_tenant
           and (t.target_parent_id = any(v_parent_ids)
                or t.target_student_id = any(v_student_ids)
                or t.auth_user_id = any(v_auth_ids));
    else
        delete from public.account_approval_requests t
         where t.tenant_id = v_tenant
           and (t.target_parent_id = any(v_parent_ids)
                or t.target_student_id = any(v_student_ids)
                or t.auth_user_id = any(v_auth_ids));
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('account_approval_requests', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.students t where t.tenant_id = v_tenant;
    else
        delete from public.students t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('students', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.parents t where t.tenant_id = v_tenant;
    else
        delete from public.parents t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('parents', v_n); v_total := v_total + v_n;

    -- ------------------------------------------------------------------
    -- D. The portal/auth closure (messages before channels; auth.users
    --    LAST; the staff guard already excluded staff accounts above)
    -- ------------------------------------------------------------------
    if p_dry_run then
        select count(*) into v_n from public.chat_messages t
         where t.tenant_id = v_tenant and t.channel_id = any(v_channel_ids);
    else
        delete from public.chat_messages t
         where t.tenant_id = v_tenant and t.channel_id = any(v_channel_ids);
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('chat_messages', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.chat_channels t
         where t.tenant_id = v_tenant and t.id = any(v_channel_ids);
    else
        delete from public.chat_channels t
         where t.tenant_id = v_tenant and t.id = any(v_channel_ids);
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('chat_channels', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.notifications t
         where t.tenant_id = v_tenant
           and (t.target_user_id = any(v_auth_ids)
                or (t.link_entity_type = 'parent' and t.link_entity_id = any(v_parent_ids))
                or (t.link_entity_type = 'student' and t.link_entity_id = any(v_student_ids)));
    else
        delete from public.notifications t
         where t.tenant_id = v_tenant
           and (t.target_user_id = any(v_auth_ids)
                or (t.link_entity_type = 'parent' and t.link_entity_id = any(v_parent_ids))
                or (t.link_entity_type = 'student' and t.link_entity_id = any(v_student_ids)));
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('notifications', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.calendar_events t
         where t.tenant_id = v_tenant
           and t.target_entity_type in ('parent', 'student')
           and (t.target_entity_id = any(v_parent_ids)
                or t.target_entity_id = any(v_student_ids));
    else
        delete from public.calendar_events t
         where t.tenant_id = v_tenant
           and t.target_entity_type in ('parent', 'student')
           and (t.target_entity_id = any(v_parent_ids)
                or t.target_entity_id = any(v_student_ids));
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('calendar_events', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.notification_preferences t
         where t.tenant_id = v_tenant and t.user_profile_id = any(v_profile_ids);
    else
        delete from public.notification_preferences t
         where t.tenant_id = v_tenant and t.user_profile_id = any(v_profile_ids);
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('notification_preferences', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.device_tokens t
         where t.user_id = any(v_auth_ids);
    else
        delete from public.device_tokens t where t.user_id = any(v_auth_ids);
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('device_tokens', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.sessions t
         where t.user_profile_id = any(v_profile_ids);
    else
        delete from public.sessions t where t.user_profile_id = any(v_profile_ids);
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('sessions', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.role_assignments t
         where t.user_profile_id = any(v_profile_ids);
    else
        delete from public.role_assignments t where t.user_profile_id = any(v_profile_ids);
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('role_assignments', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.user_profiles t
         where t.id = any(v_profile_ids);
    else
        delete from public.user_profiles t where t.id = any(v_profile_ids);
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('user_profiles', v_n); v_total := v_total + v_n;

    -- auth.users LAST (the GoTrue accounts; SECURITY DEFINER runs as the
    -- owner — postgres — which the live sandbox proves has the grant).
    if p_dry_run then
        select count(*) into v_n from auth.users t where t.id = any(v_auth_ids);
    else
        delete from auth.users t where t.id = any(v_auth_ids);
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('auth_users', v_n); v_total := v_total + v_n;

    -- ------------------------------------------------------------------
    -- E. The sync staging — ONLY this tenant's five domain entities
    --    (PURGE-501: the queue's idempotent upserts would resurrect every
    --    purged row on the next drain). Everything else in the queue, and
    --    the sync RPCs themselves, are untouched.
    -- ------------------------------------------------------------------
    if p_dry_run then
        select count(*) into v_n from public.sync_queue t
         where t.tenant_id = v_tenant
           and t.entity in ('parent', 'student', 'payment', 'installment', 'ledger_entry');
    else
        delete from public.sync_queue t
         where t.tenant_id = v_tenant
           and t.entity in ('parent', 'student', 'payment', 'installment', 'ledger_entry');
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('sync_queue_domain', v_n); v_total := v_total + v_n;

    -- The non-interference evidence, returned with every call: what the
    -- purge left alone in the queue.
    select count(*) into v_other_queue from public.sync_queue t
     where t.tenant_id = v_tenant
       and t.entity not in ('parent', 'student', 'payment', 'installment', 'ledger_entry');

    -- ------------------------------------------------------------------
    -- The audit entry (append-only journal — execute mode only; dry-run
    -- changed nothing and writes nothing). counts ride p_after_json.
    -- ------------------------------------------------------------------
    if not p_dry_run then
        v_audit_id := public.write_audit_log(
            p_tenant_id   => v_tenant,
            p_action      => 'system.purge_student_parent_domain',
            p_entity_type => 'system',
            p_entity_id   => null,
            p_actor_id    => null,
            p_actor_name  => coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'email', session_user),
            p_after_json  => v_counts || jsonb_build_object('total', v_total),
            p_note        => 'T-416 (issue #12): the student/parent domain reset — '
                             || v_total || ' rows across ' || (select count(*) from jsonb_object_keys(v_counts)) || ' families; '
                             || 'backup/sync-infrastructure/audit-journal/academic-catalog untouched per ADR-027.'
        );
    end if;

    return jsonb_build_object(
        'ok', true,
        'mode', case when p_dry_run then 'dry_run' else 'executed' end,
        'tenant_id', v_tenant,
        'counts', v_counts,
        'total', v_total,
        'preserved', jsonb_build_object(
            'backup_archives', 'untouched',
            'sync_queue_other', v_other_queue,
            'audit_logs', 'append_only',
            'academic_catalog', 'untouched',
            'workforce_operations', 'untouched'
        ),
        'audit_entry_id', v_audit_id
    );
end;
$function$
;
comment on function purge_student_parent_domain(text,boolean,uuid) is 'T-416 / issue #12 — the canonical student/parent domain reset (ADR-027). Destructive, tenant-wide, execute-gated by the typed phrase ''PURGER''; p_dry_run=true (the default) counts without deleting. The backup family, the sync infrastructure (non-domain queue rows + RPCs), the audit journal, the academic catalog, and the workforce/operations domains are NEVER touched. 0121 (PURGE-502): requests keyed to a purged auth account die with the account.';

create or replace function public.read_debt_aging_thresholds()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant uuid;
    v_grace integer;
    v_yellow integer;
    v_red integer;
    v_active integer;
    v_amount_yellow numeric;
    v_amount_red numeric;
    v_severe numeric;
    v_msg_green text;
    v_msg_yellow text;
    v_msg_orange text;
    v_msg_red text;
begin
    -- The SAME staff gate as the aging surface itself (0111/0125/0133/0138) —
    -- the thresholds are the aging audience's operational config, and the
    -- system_settings RLS (0024) stays untouched.
    if not public.has_any_role(array['super_admin', 'financial_officer', 'support_staff']) then
        raise exception 'forbidden: debt thresholds are a staff surface';
    end if;

    v_tenant := public.current_tenant_id();
    if v_tenant is null then
        raise exception 'forbidden: no tenant context';
    end if;

    select t.grace_period_days, t.yellow_days, t.red_days, t.active_payer_grace_days
      into v_grace, v_yellow, v_red, v_active
      from public.debt_aging_thresholds(v_tenant) t;

    -- T-469 (DEBT-103): the AMOUNT dimension + the level messages — read
    -- directly from system_settings (documented defaults when missing).
    -- T-502 (DEBT-104): + the SEVERE-DEBT edge (the console's quick query).
    select
        coalesce(min(case when s.key = 'debt.amount_threshold_yellow_dzd'
                          then (s.value #>> '{}')::numeric end), 20000),
        coalesce(min(case when s.key = 'debt.amount_threshold_red_dzd'
                          then (s.value #>> '{}')::numeric end), 60000),
        coalesce(min(case when s.key = 'debt.severe_debt_dzd'
                          then (s.value #>> '{}')::numeric end), 40000)
      into v_amount_yellow, v_amount_red, v_severe
      from public.system_settings s
     where s.tenant_id = v_tenant
       and s.category = 'debt'
       and s.key in ('debt.amount_threshold_yellow_dzd', 'debt.amount_threshold_red_dzd',
                     'debt.severe_debt_dzd');

    select
        coalesce(max(case when s.key = 'debt.level_message_green'    then s.value #>> '{}' end), ''),
        coalesce(max(case when s.key = 'debt.level_message_yellow'   then s.value #>> '{}' end), ''),
        coalesce(max(case when s.key = 'debt.level_message_orange'   then s.value #>> '{}' end), ''),
        coalesce(max(case when s.key = 'debt.level_message_red'      then s.value #>> '{}' end), '')
      into v_msg_green, v_msg_yellow, v_msg_orange, v_msg_red
      from public.system_settings s
     where s.tenant_id = v_tenant
       and s.category = 'debt'
       and s.key in ('debt.level_message_green', 'debt.level_message_yellow',
                     'debt.level_message_orange', 'debt.level_message_red');

    return jsonb_build_object(
        'gracePeriodDays', coalesce(v_grace, 5),
        'yellowDays', coalesce(v_yellow, 15),
        'redDays', coalesce(v_red, 60),
        'activePayerGraceDays', coalesce(v_active, 15),
        -- T-469 (DEBT-103): the amount edges (0 = the classification is
        -- disabled — every amount is amount-green) + the per-level messages
        -- (empty = the canonical engine text stands).
        'amountYellowDzd', coalesce(v_amount_yellow, 20000),
        'amountRedDzd', coalesce(v_amount_red, 60000),
        -- T-502 (DEBT-104): the console's severe-debt quick-query edge
        -- (default 40 000 — the previously hardcoded value).
        'severeDebtDzd', coalesce(v_severe, 40000),
        'levelMessages', jsonb_build_object(
            'green', coalesce(v_msg_green, ''),
            'yellow', coalesce(v_msg_yellow, ''),
            'orange', coalesce(v_msg_orange, ''),
            'red', coalesce(v_msg_red, '')
        )
    );
end;
$function$
;
comment on function read_debt_aging_thresholds() is 'T-443 (DEBT-101) + T-469 (DEBT-103) + T-502 (DEBT-104): the staff-gated light reader for the configurable debt risk configuration — the 4 day-thresholds (0125), the 2 amount-thresholds and the 4 level-message templates (0138), and the severe-debt edge of the Investigation Console''s quick query (0150). Consumed by the desktop dashboard triage + the Finances legend + the amount classification + the operational console.';

create or replace function public.read_debt_summary_collection()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
declare
    v_tenant uuid;
    v_result jsonb;
begin
    if not public.has_any_role(array['super_admin', 'financial_officer', 'support_staff']) then
        raise exception 'forbidden: financial collections are a staff surface';
    end if;
    v_tenant := public.current_tenant_id();
    if v_tenant is null then
        raise exception 'forbidden: no tenant context';
    end if;

    -- The TS formula it mirrors (SupabaseDebtRepository.readSummaries):
    --   remaining = greatest(0, due − paid − pending) over status <> 'paid';
    --   skip rows with remaining <= 0; per parent: Σremaining, days from the
    --   OLDEST remaining row (the TS takes the max days-over-due — the same
    --   value); student_count = the per-parent count of students rows
    --   (tenant-scoped, deliberately NO deleted_at filter — bit-parity with
    --   the current display). RAW display fields returned; the client maps.
    with unpaid as (
        select i.parent_id,
               i.id,
               greatest(0, i.amount_due - i.amount_paid - i.amount_pending) as remaining,
               i.due_date
          from public.installments i
         where i.tenant_id = v_tenant
           and i.status <> 'paid'
    ),
    filtered as (
        select * from unpaid where remaining > 0
    ),
    per_parent as (
        select parent_id,
               sum(remaining) as outstanding_amount,
               min(due_date) as oldest_due_date
          from filtered
         group by parent_id
    )
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'parent_id', pp.parent_id,
                'display_name', p.display_name,
                'first_name', p.first_name,
                'last_name', p.last_name,
                'primary_phone', p.primary_phone,
                'outstanding_amount', pp.outstanding_amount,
                'oldest_due_date', to_char(pp.oldest_due_date, 'YYYY-MM-DD'),
                'student_count', (
                    select count(*)
                      from public.students s
                     where s.tenant_id = v_tenant
                       and s.parent_id = pp.parent_id
                )
            )
            order by pp.outstanding_amount desc, pp.parent_id
        ),
        '[]'::jsonb
    )
      into v_result
      from per_parent pp
      join public.parents p
        on p.id = pp.parent_id
       and p.tenant_id = v_tenant;

    return v_result;
end;
$function$
;
comment on function read_debt_summary_collection() is 'T-423 (PERF-505 + DATA-038/DATA-040): the per-parent debtor aggregates (the §15 installment basis — INV-4 remaining over unpaid installments) in one jsonb array. Replaces the client-side three-read computation that PostgREST capped at 1,000 rows per read. Raw display fields; the client keeps every display decision.';

create or replace function public.read_installments_collection()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
declare
    v_tenant uuid;
    v_result jsonb;
begin
    if not public.has_any_role(array['super_admin', 'financial_officer', 'support_staff']) then
        raise exception 'forbidden: financial collections are a staff surface';
    end if;
    v_tenant := public.current_tenant_id();
    if v_tenant is null then
        raise exception 'forbidden: no tenant context';
    end if;

    select coalesce(
        jsonb_agg(to_jsonb(i) order by i.id),
        '[]'::jsonb
    )
      into v_result
      from public.installments i
     where i.tenant_id = v_tenant;

    return v_result;
end;
$function$
;
comment on function read_installments_collection() is 'T-423 (PERF-505): the staff read RPC for the installments collection — one jsonb array, PK order (the client sorts due_date asc in-memory). The whole 5,963-row schedule in one round trip (the Tranches tab T1+T2+T3 fix).';

