create or replace function public.read_payments_collection()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
declare
    v_tenant uuid;
    v_result jsonb;
begin
    if not public.has_any_role(array['super_admin', 'financial_officer', 'support_staff']) then
        raise exception 'forbidden: financial collections are a staff surface';
    end if;
    v_tenant := public.current_tenant_id();
    if v_tenant is null then
        raise exception 'forbidden: no tenant context';
    end if;

    select coalesce(
        -- T-423: NO server-side sort by unindexed columns (the live
        -- EXPLAIN attribution — the due_date/collected_at sorts cost the
        -- same top-N sort that made the direct reads slow; the CLIENT
        -- restores the display order in-memory, which is free at these
        -- sizes). Primary-key order keeps the payload deterministic.
        jsonb_agg(to_jsonb(p) order by p.id),
        '[]'::jsonb
    )
      into v_result
      from public.payments p
     where p.tenant_id = v_tenant;

    return v_result;
end;
$function$
;
comment on function read_payments_collection() is 'T-423 (PERF-505): the staff read RPC for the payments collection — one jsonb array (immune to the 1000-row cap), PK order (the client restores the display order; no server-side sort by unindexed columns — the live EXPLAIN attribution). SECURITY DEFINER: bypasses the per-row RLS policy chain that makes the direct reads 6.5-19.9s at 80-90% (live-measured, issue #23).';

create or replace function public.record_auto_releve_entry(p_kind text, p_class_id uuid DEFAULT NULL::uuid, p_class_subject_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant_id uuid;
    v_user_id uuid;
    v_personnel_id uuid;
    v_entry_id uuid;
begin
    -- The caller must be an authenticated member of a tenant.
    v_user_id := auth.uid();
    if v_user_id is null then
        raise exception 'record_auto_releve_entry: an authenticated caller is required';
    end if;
    v_tenant_id := public.current_tenant_id();
    if v_tenant_id is null then
        raise exception 'record_auto_releve_entry: no tenant context for the caller';
    end if;

    -- The kind whitelist (the §09.06 vocabulary).
    if p_kind not in ('grade_entry', 'homework_push', 'roll_call') then
        raise exception 'record_auto_releve_entry: unknown auto kind ''%''', p_kind;
    end if;

    -- §09.06 is the per-TEACHER ledger: resolve the CALLER's own personnel
    -- row in this tenant. A caller with no personnel binding (an admin
    -- entering grades, a support account) returns NULL — nothing to
    -- auto-record.
    select p.id into v_personnel_id
      from public.personnel p
     where p.tenant_id = v_tenant_id
       and p.user_id = v_user_id
       and p.deleted_at is null
     order by p.created_at
     limit 1;
    if v_personnel_id is null then
        return null;
    end if;

    -- The activity vocabulary (the desktop mock's §09.06 mapping, verbatim):
    --   grade_entry → correction · homework_push → task · roll_call →
    --   supervision (the 0140-widened clients' wire code).
    insert into public.releve_entries (
        tenant_id,
        personnel_id,
        activity_type,
        class_id,
        class_subject_id,
        description,
        clock_in_at,
        clock_out_at,
        recorded_by,
        entry_source,
        auto_kind
    ) values (
        v_tenant_id,
        v_personnel_id,
        case p_kind
            when 'grade_entry'  then 'correction'
            when 'homework_push' then 'task'
            when 'roll_call'    then 'supervision'
        end,
        p_class_id,
        p_class_subject_id,
        p_note,
        now(),
        null,
        v_user_id,
        'auto',
        p_kind
    )
    returning id into v_entry_id;

    return v_entry_id;
end;
$function$
;

create or replace function public.record_expense_state_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
    if (tg_op = 'UPDATE') and (old.status is distinct from new.status) then
        insert into public.expense_state_transitions (tenant_id, ticket_id, from_status, to_status, actor_id, actor_note, transitioned_at)
        values (
            new.tenant_id, new.id, old.status, new.status,
            coalesce(new.approved_by, new.settled_by, new.submitted_by),
            coalesce(new.approval_note, new.rejected_reason),
            now()
        );
    end if;
    return new;
end;
$function$
;

create or replace function public.record_salary_disbursement(p_personnel_id uuid, p_period text, p_method text, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_actor_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_personnel record;
    v_actor_id uuid := public.current_user_profile_id();
    v_actor_name text;
    v_tenant_id uuid;
    v_bonuses numeric := 0;
    v_deductions numeric := 0;
    v_net numeric := 0;
    v_result public.salary_payments;
    v_caller_is_service_role boolean := coalesce(auth.jwt() ->> 'role', '') = 'service_role';
begin
    -- ── Caller verification (0055 pattern) ─────────────────────────────
    if not v_caller_is_service_role then
        if auth.uid() is null then
            raise exception 'record_salary_disbursement: an authenticated caller is required';
        end if;
        if not public.has_any_role(array['super_admin', 'financial_officer']) then
            raise exception 'record_salary_disbursement: only super_admin / financial_officer may record payroll disbursements';
        end if;
    end if;

    if p_method not in ('cash', 'bank_transfer', 'check', 'mobile_money') then
        raise exception 'record_salary_disbursement: invalid payment method %', p_method;
    end if;
    if p_period !~ '^\d{4}-\d{2}$' then
        raise exception 'record_salary_disbursement: period must be YYYY-MM (got %)', p_period;
    end if;

    select * into v_personnel
      from public.personnel
     where id = p_personnel_id;

    if not found then
        raise exception 'record_salary_disbursement: personnel record % not found', p_personnel_id;
    end if;

    v_tenant_id := v_personnel.tenant_id;

    if not v_caller_is_service_role
       and public.current_tenant_id() is not null
       and public.current_tenant_id() <> v_tenant_id then
        raise exception 'record_salary_disbursement: cross-tenant disbursement refused';
    end if;

    select coalesce(display_name, '') into v_actor_name
      from public.user_profiles
     where id = v_actor_id
       and v_actor_id is not null;
    v_actor_name := coalesce(nullif(trim(p_actor_name), ''), nullif(v_actor_name, ''), 'Admin');

    -- The period's one-off bonuses/deductions (effective within the month).
    select
        coalesce(sum(case when type = 'bonus' then delta end), 0),
        coalesce(sum(case when type = 'deduction' then -delta end), 0)
      into v_bonuses, v_deductions
      from public.salary_adjustments
     where personnel_id = p_personnel_id
       and effective_date >= (p_period || '-01')::date
       and effective_date < ((p_period || '-01')::date + interval '1 month');

    v_net := greatest(0, coalesce(v_personnel.base_salary, 0) + v_bonuses - v_deductions);

    -- Idempotent upsert (re-recording the same month updates, never doubles).
    insert into public.salary_payments (
        tenant_id, personnel_id, period, base_salary, bonuses_total,
        deductions_total, net_paid, status, payment_date, method,
        reference_number, notes, paid_by, paid_by_name
    ) values (
        v_tenant_id, p_personnel_id, p_period, coalesce(v_personnel.base_salary, 0), v_bonuses,
        v_deductions, v_net, 'paid', current_date, p_method,
        nullif(trim(coalesce(p_reference_number, '')), ''), nullif(trim(coalesce(p_notes, '')), ''), v_actor_id, v_actor_name
    )
    on conflict (tenant_id, personnel_id, period)
    do update set
        base_salary      = excluded.base_salary,
        bonuses_total    = excluded.bonuses_total,
        deductions_total = excluded.deductions_total,
        net_paid         = excluded.net_paid,
        status           = 'paid',
        payment_date     = current_date,
        method           = excluded.method,
        reference_number = excluded.reference_number,
        notes            = excluded.notes,
        paid_by          = excluded.paid_by,
        paid_by_name     = excluded.paid_by_name,
        updated_at       = now()
    returning * into v_result;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant_id,
        p_action      := 'personnel.salary_disbursed',
        p_entity_type := 'personnel',
        p_entity_id   := p_personnel_id,
        p_actor_id    := v_actor_id,
        p_actor_name  := v_actor_name,
        p_before_json := null,
        p_after_json  := jsonb_build_object('period', p_period, 'net_paid', v_net, 'method', p_method),
        p_note        := format('Payroll disbursed for %s (%s DZD via %s)', p_period, v_net, p_method)
    );

    return to_jsonb(v_result);
end;
$function$
;

create or replace function public.refresh_all_materialized_views()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    refresh materialized view concurrently public.mv_dashboard_kpis;
    refresh materialized view concurrently public.mv_debt_aging;
    refresh materialized view concurrently public.mv_top_debtors;
    refresh materialized view concurrently public.mv_revenue_by_month;
    refresh materialized view concurrently public.mv_grade_summary;
end;
$function$
;
comment on function refresh_all_materialized_views() is 'Refreshes all materialized views concurrently (requires UNIQUE indexes).';

create or replace function public.refresh_materialized_view(p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
    -- Refresh a single materialized view by name. Returns TRUE on success.
    -- The view name must be one of the canonical views defined in 0021 +
    -- 0034 (mv_dashboard_kpis, mv_debt_aging, mv_top_debtors, mv_revenue_by_month).
    -- Other names raise an exception to prevent arbitrary view refreshes.
    IF p_name NOT IN ('mv_dashboard_kpis', 'mv_debt_aging', 'mv_top_debtors', 'mv_revenue_by_month') THEN
        RAISE EXCEPTION 'Cannot refresh unknown materialized view: %', p_name;
    END IF;
    EXECUTE format('REFRESH MATERIALIZED VIEW CONCURRENTLY public.%I', p_name);
    RETURN TRUE;
END;
$function$
;
comment on function refresh_materialized_view(text) is 'Refresh a single canonical materialized view by name. Allowed names: mv_dashboard_kpis, mv_debt_aging, mv_top_debtors, mv_revenue_by_month. Used by the refresh-materialized-views Edge Function per-view fallback.';

create or replace function public.register_family_batch(p_tenant_id uuid, p_parent jsonb, p_students jsonb, p_ledger_entries jsonb DEFAULT '[]'::jsonb, p_installments jsonb DEFAULT '[]'::jsonb)
 RETURNS TABLE(out_parent jsonb, out_students jsonb, out_ledger_written integer, out_installments_written integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_parent_id        uuid;
  v_parent_code      text;
  v_parent_inserted  boolean;
  v_student_ids      uuid[] := '{}';
  v_sid              uuid;
  v_s                record;
  v_e                record;
  v_i                record;
  v_student_count    integer;
  v_ledger_written   integer := 0;
  v_inst_written     integer := 0;
  v_parent_json      jsonb;
  v_students_json    jsonb;
  v_ref              integer;
BEGIN
  -- ------------------------------------------------------------------
  -- 0. Payload guards (fail fast, before any mutation).
  -- ------------------------------------------------------------------
  IF p_tenant_id IS NULL THEN
    RAISE EXCEPTION 'register_family_batch: p_tenant_id requis'
      USING HINT = 'The client resolves the tenant from the session fixture.';
  END IF;
  IF p_parent IS NULL
     OR NULLIF(TRIM(COALESCE(p_parent->>'parent_code', '')), '') IS NULL THEN
    RAISE EXCEPTION 'register_family_batch: p_parent.parent_code requis'
      USING HINT = 'batchRegister computes the deterministic parent code before the call (re-runs must converge, never duplicate).';
  END IF;
  IF p_students IS NULL THEN
    p_students := '[]'::jsonb;
  END IF;
  v_student_count := jsonb_array_length(p_students);
  IF v_student_count = 0 THEN
    RAISE EXCEPTION 'register_family_batch: au moins un élève requis'
      USING HINT = 'The wizard validates this client-side; this is the server-side mirror.';
  END IF;

  -- ------------------------------------------------------------------
  -- 1. The parent — the CANONICAL idempotent upsert (0031/0037 body,
  --    identity chain + activation code), CALLED, not reimplemented.
  -- ------------------------------------------------------------------
  SELECT u.out_parent_id, u.out_parent_code, u.out_was_inserted
    INTO v_parent_id, v_parent_code, v_parent_inserted
    FROM public.upsert_parent_from_import(
           p_tenant_id,
           p_parent->>'parent_code',
           p_parent->>'first_name',
           p_parent->>'last_name',
           p_parent->>'display_name',
           p_parent->>'primary_phone',
           p_parent->>'secondary_phone',
           p_parent->>'email',
           p_parent->>'occupation',
           p_parent->>'address',
           p_parent->>'relationship',
           p_parent->>'preferred_language',
           COALESCE((p_parent->>'is_active')::boolean, true),
           p_parent->>'transport_destination',
           p_parent->>'city_tier',
           p_parent->>'activation_code'
         ) u;

  IF v_parent_id IS NULL THEN
    RAISE EXCEPTION 'register_family_batch: upsert_parent_from_import n''a retourné aucun id (%)', v_parent_code;
  END IF;

  -- ------------------------------------------------------------------
  -- 2. The students — the CANONICAL idempotent upsert per student, in
  --    payload order (the 0-based student_ref contract the billing rows
  --    rely on). §15.37: every date/uuid field blank→null at the seam.
  --    0112: the classification (filiere/specialite) is threaded through
  --    to the upsert's trailing 0107 params. 0128: the origin (T-437) is
  --    threaded the same way through the trailing 0128 params.
  -- ------------------------------------------------------------------
  FOR v_s IN
    SELECT *
      FROM jsonb_to_recordset(p_students) AS s(
            student_code       text,
            first_name         text,
            last_name          text,
            display_name       text,
            middle_name        text,
            date_of_birth      text,
            gender             text,
            grade_level_id     uuid,
            class_id           uuid,
            enrollment_date    text,
            enrollment_status  text,
            medical_notes      text,
            is_active          boolean,
            grade_level_code   text,
            transport_tier     text,
            payment_plan       text,
            filiere_code       text,
            specialite_code    text,
            origin_type        text,
            previous_school_name    text,
            previous_school_level   text,
            previous_academic_year  text,
            origin_notes       text
          )
  LOOP
    SELECT u.out_student_id
      INTO v_sid
      FROM public.upsert_student_from_import(
             p_tenant_id,
             v_s.student_code,
             v_parent_id::text,   -- 0037 ref-tolerant param: a server UUID text resolves directly
             v_s.first_name,
             v_s.last_name,
             v_s.display_name,
             v_s.middle_name,
             NULLIF(TRIM(COALESCE(v_s.date_of_birth, '')), '')::date,
             v_s.gender,
             v_s.grade_level_id,
             v_s.class_id,
             NULLIF(TRIM(COALESCE(v_s.enrollment_date, '')), '')::date,
             v_s.enrollment_status,
             v_s.medical_notes,
             COALESCE(v_s.is_active, true),
             v_s.grade_level_code,
             v_s.transport_tier,
             v_s.payment_plan,
             -- 0112 (T-407): the classification the wizard's step 2
             -- collected — previously dropped at this seam.
             NULLIF(TRIM(COALESCE(v_s.filiere_code, '')), ''),
             NULLIF(TRIM(COALESCE(v_s.specialite_code, '')), ''),
             -- 0128 (T-437): the origin the wizard's step 2 collects —
             -- the same threading discipline (INV-24a).
             NULLIF(TRIM(COALESCE(v_s.origin_type, '')), ''),
             NULLIF(TRIM(COALESCE(v_s.previous_school_name, '')), ''),
             NULLIF(TRIM(COALESCE(v_s.previous_school_level, '')), ''),
             NULLIF(TRIM(COALESCE(v_s.previous_academic_year, '')), ''),
             v_s.origin_notes
           ) u;

    IF v_sid IS NULL THEN
      RAISE EXCEPTION 'register_family_batch: upsert_student_from_import n''a retourné aucun id pour « % % » (%)',
        v_s.first_name, v_s.last_name, v_s.student_code;
    END IF;
    v_student_ids := array_append(v_student_ids, v_sid);
  END LOOP;

  -- ------------------------------------------------------------------
  -- 3. The ledger charges — the IMPORT-107 wire semantics: ONE plain
  --    INSERT ... ON CONFLICT DO NOTHING (no arbiter: honors BOTH the
  --    (tenant, entry_number) key and the PARTIAL source_uidx). The
  --    account_id is derived HERE with the exact deriveAccountId format
  --    (domain/calc/ledger/account-id.ts) because the client cannot know
  --    the uuids before this call.
  -- ------------------------------------------------------------------
  IF p_ledger_entries IS NOT NULL AND jsonb_array_length(p_ledger_entries) > 0 THEN
    -- Ref guard FIRST: a dangling student_ref is a client bug — fail loudly.
    FOR v_ref IN
      SELECT (e->>'student_ref')::integer
        FROM jsonb_array_elements(p_ledger_entries) e
       WHERE e->>'student_ref' IS NOT NULL
    LOOP
      IF v_ref IS NULL OR v_ref < 0 OR v_ref >= v_student_count THEN
        RAISE EXCEPTION 'register_family_batch: student_ref % hors limites (0..%) dans p_ledger_entries', v_ref, v_student_count - 1;
      END IF;
    END LOOP;

    INSERT INTO public.ledger_entries (
      tenant_id, entry_number, parent_id, student_id, account_id,
      entry_type, amount, category, description, entry_date,
      source_type, source_id, method, receipt_number, payment_status,
      reverses_id, actor_id, actor_name, at, metadata
    )
    SELECT
      p_tenant_id,
      r.entry_number,
      v_parent_id,
      CASE WHEN r.student_ref IS NULL THEN NULL
           ELSE v_student_ids[r.student_ref + 1] END,
      -- deriveAccountId (account-id.ts) — the EXACT string format:
      'parent:' || v_parent_id || ':category:' || r.category ||
        CASE WHEN r.student_ref IS NULL THEN ''
             ELSE ':student:' || v_student_ids[r.student_ref + 1] END,
      r.entry_type,
      r.amount,
      r.category,
      r.description,
      COALESCE(NULLIF(TRIM(COALESCE(r.entry_date, '')), '')::timestamptz, now()),
      r.source_type,
      r.source_id,
      r.method,
      r.receipt_number,
      r.payment_status,
      r.reverses_id,
      r.actor_id,
      r.actor_name,
      NULLIF(TRIM(COALESCE(r.at, '')), '')::timestamptz,
      r.metadata
      FROM jsonb_to_recordset(p_ledger_entries) AS r(
            student_ref     integer,
            entry_number    text,
            entry_type      text,
            amount          numeric,
            category        text,
            description     text,
            entry_date      text,
            source_type     text,
            source_id       text,
            method          text,
            receipt_number  text,
            payment_status  text,
            reverses_id     text,
            actor_id        text,
            actor_name      text,
            at              text,
            metadata        jsonb
          )
      ON CONFLICT DO NOTHING;

    GET DIAGNOSTICS v_ledger_written = ROW_COUNT;
  END IF;

  -- ------------------------------------------------------------------
  -- 4. The installment tranches — the IMPORT-110 wire semantics: ONE
  --    plain INSERT ... ON CONFLICT DO NOTHING (no arbiter: honors the
  --    PARTIAL 0032 identity index). installments.student_id is NOT NULL
  --    — every tranche row MUST carry a valid student_ref.
  -- ------------------------------------------------------------------
  IF p_installments IS NOT NULL AND jsonb_array_length(p_installments) > 0 THEN
    FOR v_ref IN
      SELECT (i->>'student_ref')::integer
        FROM jsonb_array_elements(p_installments) i
    LOOP
      IF v_ref IS NULL OR v_ref < 0 OR v_ref >= v_student_count THEN
        RAISE EXCEPTION 'register_family_batch: student_ref % hors limites (0..%) dans p_installments', v_ref, v_student_count - 1;
      END IF;
    END LOOP;

    INSERT INTO public.installments (
      tenant_id, parent_id, student_id, category, tranche_number,
      label, amount_due, amount_paid, amount_pending, due_date,
      paid_date, status, academic_cycle, payment_plan,
      is_custom_schedule, custom_schedule_note, source_type, source_id,
      updated_at
    )
    SELECT
      p_tenant_id,
      v_parent_id,
      v_student_ids[r.student_ref + 1],
      r.category,
      r.tranche_number,
      r.label,
      r.amount_due,
      COALESCE(r.amount_paid, 0),
      COALESCE(r.amount_pending, 0),
      NULLIF(TRIM(COALESCE(r.due_date, '')), '')::date,
      NULLIF(TRIM(COALESCE(r.paid_date, '')), '')::date,
      COALESCE(NULLIF(TRIM(COALESCE(r.status, '')), ''), 'unpaid'),
      NULLIF(TRIM(COALESCE(r.academic_cycle, '')), ''),
      COALESCE(NULLIF(TRIM(COALESCE(r.payment_plan, '')), ''), 'tranches'),
      COALESCE(r.is_custom_schedule, false),
      r.custom_schedule_note,
      r.source_type,
      r.source_id,
      now()
      FROM jsonb_to_recordset(p_installments) AS r(
            student_ref          integer,
            category             text,
            tranche_number       integer,
            label                text,
            amount_due           numeric,
            amount_paid          numeric,
            amount_pending       numeric,
            due_date             text,
            paid_date            text,
            status               text,
            academic_cycle       text,
            payment_plan         text,
            is_custom_schedule   boolean,
            custom_schedule_note text,
            source_type          text,
            source_id            text
          )
      ON CONFLICT DO NOTHING;

    GET DIAGNOSTICS v_inst_written = ROW_COUNT;
  END IF;

  -- ------------------------------------------------------------------
  -- 5. The response — the FULL rows (the client's two full-row fetches
  --    of the T-397 shape are gone). Students in PAYLOAD order so the
  --    client can zip them with its inputs for the gradeLevel patches.
  -- ------------------------------------------------------------------
  SELECT to_jsonb(p)
    INTO v_parent_json
    FROM public.parents p
   WHERE p.id = v_parent_id;

  SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY u.ord), '[]'::jsonb)
    INTO v_students_json
    FROM unnest(v_student_ids) WITH ORDINALITY AS u(sid, ord)
    JOIN public.students s ON s.id = u.sid;

  RETURN QUERY SELECT v_parent_json, v_students_json, v_ledger_written, v_inst_written;
END;
$function$
;
comment on function register_family_batch(uuid,jsonb,jsonb,jsonb,jsonb) is 'T-398/PERF-502: the ONE-round-trip family registration. Reuses the canonical idempotent upserts (upsert_parent_from_import + upsert_student_from_import) inside ONE transaction; billing rows arrive client-derived (the canonical TS calc engine) with 0-based student_ref indexes the RPC resolves to uuids; ledger/installments written ON CONFLICT DO NOTHING (IMPORT-107/IMPORT-110 wire semantics); returns the full parent + student rows; fully idempotent (deterministic codes + ON CONFLICT) — safe under rpcWithIdempotentRetry. 0112 (T-407): the student classification (filiere_code/specialite_code) is threaded through to the canonical upsert (previously dropped at this seam). 0128 (T-437): the student origin (origin_type/previous_school_*) is threaded through the same way (INV-24a) — and an EXISTING parent is bound by passing its ACTUAL parent_code in p_parent (the primary identity match reuses the record — the direct add-student flow, ADR-031 §7).';

create or replace function public.register_fcm_token(p_user_id uuid, p_token text, p_platform text DEFAULT 'android'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_token_id uuid;
    v_tenant_id uuid;
    v_caller_profile uuid;
    v_is_service_role boolean;
    v_conflict_user uuid;
    v_conflict_active boolean;
    v_id uuid;
BEGIN
    IF p_token IS NULL OR trim(p_token) = '' THEN
        RAISE EXCEPTION 'p_token is required';
    END IF;

    -- SEC-106 (0050): verify the caller owns the profile they register for.
    v_is_service_role := (auth.role() = 'service_role');
    IF NOT v_is_service_role THEN
        SELECT up.id INTO v_caller_profile
          FROM public.user_profiles up
         WHERE up.auth_user_id = auth.uid()
         LIMIT 1;
        IF v_caller_profile IS NULL OR v_caller_profile <> p_user_id THEN
            RAISE EXCEPTION 'register_fcm_token: caller does not own user profile %', p_user_id
              USING ERRCODE = '42501';
        END IF;
    END IF;

    -- Resolve tenant from the user's profile.
    SELECT tenant_id INTO v_tenant_id
      FROM public.user_profiles
     WHERE id = p_user_id
     LIMIT 1;

    IF v_tenant_id IS NULL THEN
        -- Default tenant — matches the seed in 0023.
        v_tenant_id := '00000000-0000-0000-0000-000000000001'::uuid;
    END IF;

    -- T-030: inspect the conflicting row BEFORE the upsert so the silent
    -- re-point can be distinguished from a legitimate reactivation.
    SELECT dt.user_id, dt.is_active
      INTO v_conflict_user, v_conflict_active
      FROM public.device_tokens dt
     WHERE dt.tenant_id = v_tenant_id
       AND dt.token = p_token
     LIMIT 1;

    IF v_conflict_user IS NOT NULL AND v_conflict_user <> p_user_id THEN
        IF v_conflict_active THEN
            -- PUSH-102: the token belongs to an ACTIVE session of another
            -- user — a silent transfer would hijack their notifications.
            -- The canonical sign-out (deactivate_fcm_tokens) is the
            -- legitimate way to release the device first.
            RAISE EXCEPTION 'register_fcm_token: token is registered to an ACTIVE device of user % — transfer requires that user to sign out first', v_conflict_user
              USING ERRCODE = '42501';
        END IF;
        -- Inactive conflict = the previous owner signed out: explicit
        -- transfer, AUDITED (PUSH-102 "audit + explicit transfer").
        INSERT INTO public.device_tokens (tenant_id, user_id, token, platform, is_active, last_seen_at)
        VALUES (v_tenant_id, p_user_id, p_token, p_platform, true, now())
        ON CONFLICT (tenant_id, token) DO UPDATE
           SET user_id       = EXCLUDED.user_id,
               platform      = EXCLUDED.platform,
               is_active     = true,
               last_seen_at  = now()
        RETURNING id INTO v_token_id;

        PERFORM public.write_audit_log(
            p_tenant_id   := v_tenant_id,
            p_action      := 'device_token.transfer',
            p_entity_type := 'device_token',
            p_entity_id   := v_token_id,
            p_actor_id    := p_user_id,
            p_before_json := jsonb_build_object('user_id', v_conflict_user, 'is_active', false),
            p_after_json  := jsonb_build_object('user_id', p_user_id, 'is_active', true),
            p_note        := 'Transfert de jeton FCM (appareil partagé, ancien propriétaire déconnecté)'
        );
        RETURN v_token_id;
    END IF;

    -- Same user (or brand-new row): plain reactivation/registration.
    INSERT INTO public.device_tokens (tenant_id, user_id, token, platform, is_active, last_seen_at)
    VALUES (v_tenant_id, p_user_id, p_token, p_platform, true, now())
    ON CONFLICT (tenant_id, token) DO UPDATE
       SET user_id       = EXCLUDED.user_id,
           platform      = EXCLUDED.platform,
           is_active     = true,
           last_seen_at  = now()
    RETURNING id INTO v_token_id;

    PERFORM public.write_audit_log(
        p_tenant_id   := v_tenant_id,
        p_action      := 'device_token.register',
        p_entity_type := 'device_token',
        p_entity_id   := v_token_id,
        p_actor_id    := p_user_id,
        p_after_json  := jsonb_build_object('platform', p_platform, 'active', true),
        p_note        := 'Enregistrement (ré)activé de jeton FCM'
    );

    RETURN v_token_id;
END;
$function$
;
comment on function register_fcm_token(uuid,text,text) is 'Canonical FCM registration entry point shared by the Android app (FcmTokenRegistrar) and the web portal (fcm-registration.ts). Upserts device_tokens by (tenant_id, token). SEC-106 (0050): client callers may only register against their own profile. PUSH-102/T-030 (0060): a token held by an ACTIVE session of ANOTHER user is rejected (42501) — transfer only after that user signs out (deactivate), and every transfer is audited.';

create or replace function public.reject_account_request(p_request_id uuid, p_reviewer_profile_id uuid, p_decision_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
    if p_decision_note is null or trim(p_decision_note) = '' then
        raise exception 'A rejection reason is required';
    end if;

    update public.account_approval_requests
       set status = 'rejected',
           reviewed_by = p_reviewer_profile_id,
           reviewed_at = now(),
           decision_note = p_decision_note
     where id = p_request_id
       and status = 'pending';

    -- Suspend the user profile so they cannot sign in
    update public.user_profiles
       set status = 'suspended'
     where auth_user_id = (
         select auth_user_id from public.account_approval_requests where id = p_request_id
     );
end;
$function$
;
comment on function reject_account_request(uuid,uuid,text) is 'Rejects a web registration request with a mandatory reason. Suspends the user profile so they cannot sign in.';

create or replace function public.resolve_academic_year_id_for_date(p_date date, p_tenant_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select (
        select ay.id
          from public.academic_years ay
         where ay.tenant_id = p_tenant_id
           and p_date between ay.start_date and ay.end_date
         order by ay.start_date desc
         limit 1
    );
$function$
;
comment on function resolve_academic_year_id_for_date(date,uuid) is 'T-436: the id-valued INV-14 window resolver — the tenant academic_years row containing the date (NULL when no window matches; the Jul1–Jun30 convention is a CODE, not a row, and is resolved by the read-side precedence instead).';

create or replace function public.resolve_installment_ref(p_tenant_id uuid, p_installment_ref text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uuid uuid;
    v_id   uuid;
BEGIN
    IF p_installment_ref IS NULL OR TRIM(p_installment_ref) = '' THEN
        RETURN NULL;
    END IF;

    BEGIN
        v_uuid := p_installment_ref::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
        v_uuid := NULL;
    END;
    IF v_uuid IS NOT NULL THEN
        RETURN v_uuid;
    END IF;

    -- Mobile local ref → android_sync provenance row.
    SELECT id INTO v_id FROM public.installments
     WHERE tenant_id = p_tenant_id
       AND source_type = 'android_sync'
       AND source_id = p_installment_ref
     LIMIT 1;
    RETURN v_id;
END;
$function$
;
comment on function resolve_installment_ref(uuid,text) is 'Resolve an installment reference (server UUID or mobile local ref registered via upsert_installment_from_import) to installments.id. NULL when unresolvable.';

create or replace function public.resolve_parent_ref(p_tenant_id uuid, p_parent_ref text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uuid uuid;
    v_id   uuid;
BEGIN
    IF p_parent_ref IS NULL OR TRIM(p_parent_ref) = '' THEN
        RETURN NULL;
    END IF;

    -- 1a. Already a server UUID (desktop push / pull round-trip).
    BEGIN
        v_uuid := p_parent_ref::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
        v_uuid := NULL;
    END;
    IF v_uuid IS NOT NULL THEN
        SELECT id INTO v_id FROM public.parents
         WHERE id = v_uuid AND tenant_id = p_tenant_id AND deleted_at IS NULL;
        RETURN COALESCE(v_id, v_uuid);  -- trust valid UUIDs even if not yet present
    END IF;

    -- 1b. Android local ref → canonical parent_code ("PAR-YYYY-XXXXXX").
    SELECT id INTO v_id FROM public.parents
     WHERE tenant_id = p_tenant_id AND parent_code = p_parent_ref AND deleted_at IS NULL
     LIMIT 1;
    RETURN v_id;
END;
$function$
;
comment on function resolve_parent_ref(uuid,text) is 'Resolve a parent reference (server UUID, or canonical parent_code such as PAR-2026-1A2B3C) to the parents.id UUID within a tenant. Returns NULL when unresolvable. Used by the ref-tolerant upsert_*_from_import RPCs so mobile clients can push their local string IDs.';

create or replace function public.resolve_student_ref(p_tenant_id uuid, p_student_ref text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uuid uuid;
    v_id   uuid;
BEGIN
    IF p_student_ref IS NULL OR TRIM(p_student_ref) = '' THEN
        RETURN NULL;
    END IF;

    BEGIN
        v_uuid := p_student_ref::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
        v_uuid := NULL;
    END;
    IF v_uuid IS NOT NULL THEN
        SELECT id INTO v_id FROM public.students
         WHERE id = v_uuid AND tenant_id = p_tenant_id AND deleted_at IS NULL;
        RETURN COALESCE(v_id, v_uuid);
    END IF;

    SELECT id INTO v_id FROM public.students
     WHERE tenant_id = p_tenant_id AND student_code = p_student_ref AND deleted_at IS NULL
     LIMIT 1;
    RETURN v_id;
END;
$function$
;
comment on function resolve_student_ref(uuid,text) is 'Resolve a student reference (server UUID, or canonical student_code such as ELV-2026-1A2B3C) to the students.id UUID within a tenant. NULL when unresolvable.';

create or replace function public.respond_leave_clarification(p_request_id uuid, p_response text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_profile_id uuid;
  v_tenant_id uuid;
  v_status text;
begin
  v_profile_id := public.current_user_profile_id();
  v_tenant_id := public.current_tenant_id();

  if v_profile_id is null or v_tenant_id is null then
    raise exception 'Authentication context is required';
  end if;

  if btrim(coalesce(p_response, '')) = '' then
    raise exception 'A clarification response is required';
  end if;

  select lr.status
    into v_status
  from public.leave_requests lr
  join public.personnel p
    on p.id = lr.personnel_id
   and p.tenant_id = lr.tenant_id
  where lr.id = p_request_id
    and lr.tenant_id = v_tenant_id
    and p.user_id = v_profile_id
    and p.deleted_at is null
  for update;

  if not found then
    raise exception 'Leave request not found or not owned by the current user';
  end if;

  if v_status <> 'clarification_requested' then
    raise exception 'Leave request is not awaiting clarification response';
  end if;

  update public.leave_requests
  set
    status = 'pending',
    clarification_response = btrim(p_response),
    updated_at = now()
  where id = p_request_id
    and tenant_id = v_tenant_id;

  return p_request_id;
end;
$function$
;

create or replace function public.revert_payment_allocation(p_tenant_id uuid, p_payment_id uuid, p_actor_id uuid, p_actor_name text, p_reason text, p_as_of timestamp with time zone DEFAULT now())
 RETURNS TABLE(payment_id uuid, new_status text, reversal_entry_id text, reverts_count integer, total_reverted numeric)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_payment RECORD;
  v_original_ledger RECORD;
  v_reversal_id TEXT;
  v_reverts JSONB := '[]'::JSONB;
  v_count INT := 0;
  v_total_reverted NUMERIC := 0;
  v_remaining NUMERIC;
  v_ins RECORD;
  v_revert NUMERIC;
  v_new_paid NUMERIC;
  v_new_pending NUMERIC;
  v_new_status TEXT;
  v_original_was_pending BOOLEAN;
  -- T-310: resolved actor (see collect_and_allocate_payment).
  v_actor_name TEXT; v_actor_role TEXT;
BEGIN
  -- T-310 (AUDIT-502): resolve the actor ONCE (same rules as collect).
  IF p_actor_name IS NOT NULL AND p_actor_name <> '' AND p_actor_name <> p_actor_id::TEXT THEN
    v_actor_name := p_actor_name;
  ELSE
    SELECT coalesce(up.display_name, up.email) INTO v_actor_name
      FROM public.user_profiles up
     WHERE up.id = p_actor_id OR up.auth_user_id = p_actor_id
     ORDER BY (up.id = p_actor_id) DESC
     LIMIT 1;
    v_actor_name := coalesce(v_actor_name, 'System');
  END IF;
  SELECT r.code INTO v_actor_role
    FROM public.role_assignments ra
    JOIN public.roles r ON r.id = ra.role_id
   WHERE ra.user_profile_id = (
         SELECT up.id FROM public.user_profiles up
          WHERE up.id = p_actor_id OR up.auth_user_id = p_actor_id
          ORDER BY (up.id = p_actor_id) DESC LIMIT 1)
     AND ra.revoked_at IS NULL
   ORDER BY r.code
   LIMIT 1;

  -- 1. Lock payment row.
  -- SEC-112: the lookup is now tenant-scoped — a payment from another
  -- tenant is indistinguishable from a nonexistent one ("not found"),
  -- so cross-tenant refunds are impossible even for service_role
  -- callers (which bypass RLS). INVOKER callers were already protected
  -- by the payments RLS SELECT policy; this closes the DEFINER/svc gap.
  SELECT * INTO v_payment FROM payments WHERE id = p_payment_id AND tenant_id = p_tenant_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payment % not found', p_payment_id;
  END IF;
  IF v_payment.status NOT IN ('paid', 'pending') THEN
    RAISE EXCEPTION 'Payment % is already % (cannot revert)', p_payment_id, v_payment.status;
  END IF;

  -- 2. Update payment status.
  UPDATE payments SET status = 'refunded', updated_at = p_as_of WHERE id = p_payment_id;

  -- 3. Find original ledger entry + insert reversal.
  SELECT * INTO v_original_ledger
    FROM ledger_entries
    WHERE source_type = 'payment' AND source_id = p_payment_id::TEXT AND entry_type = 'payment'
    LIMIT 1;

  IF FOUND THEN
    -- Determine originalWasPending: true if the original payment's status
    -- was 'pending' (uncleared funds). This is the CRITICAL branch.
    v_original_was_pending := (v_original_ledger.payment_status = 'pending');

    -- FRESH-DB FIX: same triple bug (type column, text id into uuid PK,
    -- missing NOT NULL entry_number).
    v_reversal_id := 'led-' || EXTRACT(EPOCH FROM NOW()) || '-' || SUBSTRING(gen_random_uuid()::TEXT, 1, 8);
    INSERT INTO ledger_entries (
      entry_number, tenant_id, account_id, parent_id, student_id, category, amount,
      entry_type, source_type, source_id, method, receipt_number, payment_status,
      reverses_id, description, actor_id, actor_name, at, metadata
    ) VALUES (
      v_reversal_id, v_payment.tenant_id, v_original_ledger.account_id,
      v_original_ledger.parent_id, v_original_ledger.student_id,
      v_original_ledger.category, -v_original_ledger.amount,
      'reversal', 'payment', p_payment_id::TEXT,
      -- Canonical: refund/reversal entries have method=null, paymentStatus=null.
      NULL, v_original_ledger.receipt_number, NULL,
      v_original_ledger.id::TEXT,
      'Remboursement ' || v_payment.receipt_number || ' — inversion de l''écriture de paiement',
      p_actor_id::TEXT, v_actor_name, p_as_of,
      JSONB_BUILD_OBJECT('refundReason', p_reason, 'originalPaymentId', p_payment_id, 'originalWasPending', v_original_was_pending)
    );

    -- 4. LIFO reverse-waterfall.
    v_remaining := v_payment.amount;

    IF v_original_was_pending THEN
      -- Pending branch: subtract from amount_pending. NEVER touch amount_paid.
      FOR v_ins IN
        SELECT id, amount_due, amount_paid, amount_pending, due_date, status
        FROM installments
        WHERE parent_id = v_payment.parent_id
          AND amount_pending > 0
          AND (v_payment.category IS NULL OR category = v_payment.category)
        ORDER BY due_date DESC, id DESC
        FOR UPDATE
      LOOP
        EXIT WHEN v_remaining <= 0;
        v_revert := LEAST(v_remaining, v_ins.amount_pending);
        v_new_pending := v_ins.amount_pending - v_revert;
        v_new_paid := v_ins.amount_paid;  -- UNCHANGED for pending reversals
        -- Status re-evaluation: pending reversal doesn't change paid amount,
        -- so if there were no cleared funds, tranche reverts to its prior
        -- non-pending status based on amount_paid vs amount_due.
        IF v_new_paid >= v_ins.amount_due AND v_ins.amount_due > 0 THEN
          v_new_status := 'paid';
        ELSIF v_new_paid > 0 THEN
          v_new_status := 'partial';
        ELSIF v_ins.due_date < p_as_of THEN
          v_new_status := 'overdue';
        ELSE
          -- Canonical reevaluateInstallmentStatus: fully unpaid + future due
          -- date reverts to 'pending' (equivalence finding A-0042-LADDER).
          v_new_status := 'pending';
        END IF;
        -- If amount_pending is now 0, status reverts to the above. If > 0,
        -- keep pending_clearance (still has uncleared funds).
        IF v_new_pending > 0 THEN
          v_new_status := 'pending_clearance';
        END IF;
        UPDATE installments
          SET amount_paid = v_new_paid, amount_pending = v_new_pending,
              status = v_new_status,
              paid_date = CASE WHEN v_new_status = 'paid' THEN paid_date ELSE NULL END
          WHERE id = v_ins.id;
        v_reverts := v_reverts || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
          'installmentId', v_ins.id, 'revertedAmount', v_revert,
          'newAmountPaid', v_new_paid, 'newAmountPending', v_new_pending,
          'newStatus', v_new_status, 'bucket', 'pending'
        ));
        v_count := v_count + 1;
        v_total_reverted := v_total_reverted + v_revert;
        v_remaining := v_remaining - v_revert;
      END LOOP;
    ELSE
      -- Cleared branch: subtract from amount_paid.
      FOR v_ins IN
        SELECT id, amount_due, amount_paid, amount_pending, due_date, status
        FROM installments
        WHERE parent_id = v_payment.parent_id
          AND amount_paid > 0
          AND (v_payment.category IS NULL OR category = v_payment.category)
        ORDER BY due_date DESC, id DESC
        FOR UPDATE
      LOOP
        EXIT WHEN v_remaining <= 0;
        v_revert := LEAST(v_remaining, v_ins.amount_paid);
        v_new_paid := v_ins.amount_paid - v_revert;
        v_new_pending := v_ins.amount_pending;  -- unchanged for cleared reversals
        IF v_new_paid >= v_ins.amount_due AND v_ins.amount_due > 0 THEN
          v_new_status := 'paid';
        ELSIF v_new_paid > 0 THEN
          v_new_status := 'partial';
        ELSIF v_ins.due_date < p_as_of THEN
          v_new_status := 'overdue';
        ELSE
          -- Canonical reevaluateInstallmentStatus: fully unpaid + future due
          -- date reverts to 'pending' (equivalence finding A-0042-LADDER).
          v_new_status := 'pending';
        END IF;
        UPDATE installments
          SET amount_paid = v_new_paid, amount_pending = v_new_pending,
              status = v_new_status,
              paid_date = CASE WHEN v_new_status = 'paid' THEN paid_date ELSE NULL END
          WHERE id = v_ins.id;
        v_reverts := v_reverts || JSONB_BUILD_ARRAY(JSONB_BUILD_OBJECT(
          'installmentId', v_ins.id, 'revertedAmount', v_revert,
          'newAmountPaid', v_new_paid, 'newAmountPending', v_new_pending,
          'newStatus', v_new_status, 'bucket', 'paid'
        ));
        v_count := v_count + 1;
        v_total_reverted := v_total_reverted + v_revert;
        v_remaining := v_remaining - v_revert;
      END LOOP;
    END IF;
  END IF;

  -- 5. Audit log.
  -- SEC-112: stamped with the PAYMENT's actual tenant (v_payment.tenant_id),
  -- no longer the caller-supplied p_tenant_id.
  -- T-310 (AUDIT-502): the wrapped {before, after} payload now ALSO lands in
  -- the canonical columns (unwrapped) + actor_role; the legacy `diff` column
  -- keeps the wrapped shape for backward compat.
  INSERT INTO audit_logs (
    id, tenant_id, action, entity_type, entity_id, actor_id, actor_name, actor_role,
    before_json, after_json, diff, note, created_at
  ) VALUES (
    gen_random_uuid(), v_payment.tenant_id, 'payment.refund', 'payment', p_payment_id,
    p_actor_id, v_actor_name, v_actor_role,
    JSONB_BUILD_OBJECT('status', v_payment.status),
    JSONB_BUILD_OBJECT(
      'status', 'refunded', 'reversalEntryId', v_reversal_id,
      'revertsCount', v_count, 'totalReverted', v_total_reverted,
      'originalWasPending', v_original_was_pending
    ),
    JSONB_BUILD_OBJECT(
      'before', JSONB_BUILD_OBJECT('status', v_payment.status),
      'after', JSONB_BUILD_OBJECT(
        'status', 'refunded', 'reversalEntryId', v_reversal_id,
        'revertsCount', v_count, 'totalReverted', v_total_reverted,
        'originalWasPending', v_original_was_pending
      )
    ),
    'Inversion LIFO via RPC revert_payment_allocation (canonical 0034) — ' || COALESCE(p_reason, 'N/A'),
    p_as_of
  );

  RETURN QUERY
    SELECT p_payment_id, 'refunded'::TEXT, v_reversal_id, v_count, v_total_reverted;
END;
$function$
;
comment on function revert_payment_allocation(uuid,uuid,uuid,text,text,timestamp with time zone) is 'T-310 (0087): the LIFO reversal — unchanged business logic (0034); the audit row now carries the unwrapped before_json/after_json + actor_role, and a NULL p_actor_name resolves server-side.';

create or replace function public.save_dashboard_layout(p_view_key text, p_layout jsonb)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
    v_profile uuid;
    v_tenant  uuid;
    v_saved_at timestamptz;
begin
    -- Identity resolved SERVER-SIDE from the JWT: the caller cannot target
    -- another user's row (the client never sends tenant/profile columns).
    v_profile := public.current_user_profile_id();
    v_tenant  := public.current_tenant_id();
    if v_profile is null or v_tenant is null then
        raise exception 'save_dashboard_layout: no profile/tenant context'
          using errcode = '42501';
    end if;

    if p_view_key is null or btrim(p_view_key) = '' then
        raise exception 'save_dashboard_layout: p_view_key is required'
          using errcode = '23514';
    end if;
    if p_layout is null or jsonb_typeof(p_layout) <> 'object' then
        raise exception 'save_dashboard_layout: p_layout must be a JSON object'
          using errcode = '23514';
    end if;

    insert into public.dashboard_layouts (tenant_id, user_profile_id, view_key, layout)
    values (v_tenant, v_profile, btrim(p_view_key), p_layout)
    on conflict (tenant_id, user_profile_id, view_key)
    do update set layout = excluded.layout
    returning updated_at into v_saved_at;

    return v_saved_at;
end;
$function$
;
comment on function save_dashboard_layout(text,jsonb) is 'T-448 (UI-326): the ONLY write path for dashboard layouts — the EXPLICIT save. Caller profile + tenant resolved server-side (JWT); upserts the caller''s own row on (tenant, profile, view key). SECURITY INVOKER: the table''s own RLS stays the guard. Returns the saved-at timestamp.';

create or replace function public.search_entities(p_tenant_id uuid, p_query text, p_limit integer DEFAULT 20)
 RETURNS TABLE(entity_type text, entity_id uuid, label text, sublabel text, score real)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
    -- Parents
    select 'parent'::text, p.id,
           p.last_name || ' ' || p.first_name,
           p.primary_phone,
           similarity(p.last_name || ' ' || p.first_name, p_query)
      from public.parents p
     where p.tenant_id = p_tenant_id
       and p.deleted_at is null
       and (p.last_name || ' ' || p.first_name) % p_query
    union all
    -- Students
    select 'student'::text, s.id,
           s.last_name || ' ' || s.first_name,
           s.student_code,
           similarity(s.last_name || ' ' || s.first_name, p_query)
      from public.students s
     where s.tenant_id = p_tenant_id
       and s.deleted_at is null
       and (s.last_name || ' ' || s.first_name) % p_query
    union all
    -- Personnel
    select 'personnel'::text, per.id,
           per.last_name || ' ' || per.first_name,
           per.personnel_code,
           similarity(per.last_name || ' ' || per.first_name, p_query)
      from public.personnel per
     where per.tenant_id = p_tenant_id
       and per.deleted_at is null
       and (per.last_name || ' ' || per.first_name) % p_query
    order by 5 desc  -- positional: UNION output columns are not aliased, so `score` is unresolvable
    limit p_limit;
$function$
;
comment on function search_entities(uuid,text,integer) is 'Cross-entity trigram search across parents, students, personnel.';

create or replace function public.set_active_pricing_config(p_config_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant uuid;
    v_target public.pricing_configs%rowtype;
begin
    -- Gate 1 — staff roles (mirrors the 0019 pricing_configs_admin policy:
    -- pricing writes are super_admin / financial_officer).
    if not public.has_any_role(array['super_admin', 'financial_officer']) then
        raise exception 'forbidden: pricing activation is a staff surface'
            using errcode = '42501';
    end if;

    -- Gate 2 — tenant scope (SECURITY DEFINER bypasses the RLS that would
    -- normally scope writes; current_tenant_id() is the canonical resolver).
    v_tenant := public.current_tenant_id();
    if v_tenant is null then
        raise exception 'forbidden: no tenant context'
            using errcode = '42501';
    end if;

    select * into v_target
      from public.pricing_configs
     where id = p_config_id;

    if v_target.id is null then
        raise exception 'pricing config not found: %', p_config_id
            using errcode = '22023';
    end if;

    if v_target.tenant_id <> v_tenant then
        raise exception 'forbidden: pricing config belongs to another tenant'
            using errcode = '42501';
    end if;

    if v_target.is_active then
        -- Idempotent no-op: activating the already-active config.
        return v_target.id;
    end if;

    -- The switch, atomically: deactivate siblings, activate the target.
    update public.pricing_configs
       set is_active = false,
           updated_at = now()
     where tenant_id = v_tenant
       and is_active
       and id <> p_config_id;

    update public.pricing_configs
       set is_active = true,
           updated_at = now()
     where id = p_config_id
    returning * into v_target;

    -- 0086 pricing mutation triggers already audit both UPDATEs (before/after
    -- snapshots with actor attribution) — no manual audit row here.
    return v_target.id;
end;
$function$
;
comment on function set_active_pricing_config(uuid) is 'T-414 / PRICING-500 / ADR-025: atomically switches the tenant''s ACTIVE pricing config (deactivates siblings, activates the target). Idempotent for the already-active config. Gates: super_admin/financial_officer + current tenant. The previously active config is left UNCHANGED except is_active=false — historical pricing is preserved (INV-1: financial records replay stored amounts, never re-priced).';

create or replace function public.set_assessments_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.tenant_id IS NULL THEN
        IF NEW.student_id IS NOT NULL THEN
            SELECT s.tenant_id INTO NEW.tenant_id
              FROM public.students s WHERE s.id = NEW.student_id;
        END IF;
    END IF;
    -- T-025 (TENANT-105): the previous fallback stamped orphan rows with
    -- the DEMO tenant ('00000000-…-0001') because fn_current_tenant_id()
    -- always returned NULL. An assessment that cannot be tenant-resolved is
    -- a caller bug — fail loudly instead of writing cross-tenant data.
    IF NEW.tenant_id IS NULL THEN
        RAISE EXCEPTION 'assessment tenant_id unresolvable: no tenant_id and no valid student_id (student_id=%)', NEW.student_id
            USING ERRCODE = '23502';
    END IF;
    RETURN NEW;
END;
$function$
;

create or replace function public.set_current_academic_year(p_academic_year_id uuid, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS academic_years
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_year public.academic_years;
    v_tenant uuid;
    v_caller_is_service_role boolean;
    v_prev_year public.academic_years;
BEGIN
    v_caller_is_service_role := coalesce(auth.jwt() ->> 'role', '') = 'service_role';

    -- Tenant resolution (0055 pattern): explicit tenant allowed for
    -- service_role + global admins only; everyone else must BE of the tenant.
    v_tenant := public.current_tenant_id();
    IF p_tenant_id IS NOT NULL AND (v_tenant IS NULL OR p_tenant_id <> v_tenant) THEN
        IF NOT v_caller_is_service_role AND NOT public.is_global_admin() THEN
            RAISE EXCEPTION 'set_current_academic_year: caller tenant mismatch (p_tenant_id=%)', p_tenant_id
              USING ERRCODE = '42501';
        END IF;
        v_tenant := p_tenant_id;
    END IF;

    IF v_tenant IS NULL THEN
        RAISE EXCEPTION 'set_current_academic_year: caller tenant unresolvable'
          USING ERRCODE = '42501';
    END IF;

    -- Remember the tenant's previous current year for the audit diff.
    SELECT * INTO v_prev_year
      FROM public.academic_years ay
     WHERE ay.tenant_id = v_tenant AND ay.is_current
     LIMIT 1;

    -- ACAD-101: ONE statement — there is no zero-current-year window.
    UPDATE public.academic_years ay
       SET is_current = (ay.id = p_academic_year_id),
           updated_at = now()
     WHERE ay.tenant_id = v_tenant
     RETURNING ay.* INTO v_year;

    IF v_year.id IS NULL OR v_year.id <> p_academic_year_id THEN
        -- Either the target does not exist, is in another tenant (RLS hid
        -- it), or the caller lacks the academic_years_admin policy — the
        -- UPDATE matched zero rows or could not set the target. Roll back.
        RAISE EXCEPTION 'set_current_academic_year: academic year % not applicable for this caller', p_academic_year_id
          USING ERRCODE = '23503';
    END IF;

    PERFORM public.write_audit_log(
        p_tenant_id      := v_tenant,
        p_action         := 'academic_year.set_current',
        p_entity_type    := 'academic_year',
        p_entity_id      := p_academic_year_id,
        p_actor_id       := p_actor_profile_id,
        p_actor_name     := p_actor_name,
        p_before_json    := CASE WHEN v_prev_year.id IS NULL THEN NULL
                                 ELSE jsonb_build_object('id', v_prev_year.id, 'label', v_prev_year.label) END,
        p_after_json     := jsonb_build_object('id', v_year.id, 'label', v_year.label),
        p_note           := 'Année courante basculée (atomique, RPC 0059)'
    );

    RETURN v_year;
END;
$function$
;
comment on function set_current_academic_year(uuid,uuid,text,uuid) is 'T-041 (ACAD-101): atomically flips is_current for every academic year of the tenant in ONE statement (no zero-current-year window). Caller-verified; runs under caller RLS (academic_years_admin: super_admin + support_staff).';

create or replace function public.set_notification_preference_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.tenant_id is null then
    select tenant_id into new.tenant_id from public.user_profiles where id = new.user_profile_id;
  end if;
  return new;
end;
$function$
;

create or replace function public.settle_expense(p_tenant_id uuid, p_ticket_id uuid, p_final_amount numeric, p_receipt_path text, p_actor_profile_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_ticket record;
    v_audit_id uuid;
    v_caller_is_service_role boolean := coalesce(auth.jwt() ->> 'role', '') = 'service_role';
begin
    -- ── Caller verification + actor binding (SEC-118, the 0055 pattern) ──
    if not v_caller_is_service_role then
        if auth.uid() is null then
            raise exception 'settle_expense: an authenticated caller is required';
        end if;
        if not public.has_any_role(array['super_admin', 'financial_officer', 'manager']) then
            raise exception 'settle_expense: only super_admin / financial_officer / manager may settle expenses';
        end if;
        if p_actor_profile_id is distinct from public.current_user_profile_id() then
            raise exception 'settle_expense: p_actor_profile_id must be the caller''s own profile (SEC-118 actor binding)';
        end if;
    end if;

    select * into v_ticket from public.expense_tickets where id = p_ticket_id and tenant_id = p_tenant_id;
    if not found then raise exception 'Expense ticket not found'; end if;

    if v_ticket.status not in ('approved_funds_released', 'disbursed') then
        raise exception 'Ticket must be approved_funds_released or disbursed to settle (current: %)', v_ticket.status;
    end if;

    if p_receipt_path is null or trim(p_receipt_path) = '' then
        raise exception 'Receipt upload is mandatory before settlement (plan §08)';
    end if;

    update public.expense_tickets
       set status = 'settled_and_closed',
           final_spent_amount = p_final_amount,
           receipt_path = p_receipt_path,
           receipt_uploaded_at = now(),
           receipt_uploaded_by = p_actor_profile_id,
           settled_by = p_actor_profile_id,
           settled_at = now(),
           updated_at = now()
     where id = p_ticket_id;

    v_audit_id := public.write_audit_log(
        p_tenant_id := p_tenant_id,
        p_action := 'expense.settle',
        p_entity_type := 'expense_ticket',
        p_entity_id := p_ticket_id,
        p_actor_id := p_actor_profile_id,
        p_after_json := jsonb_build_object('final_amount', p_final_amount, 'receipt_path', p_receipt_path)
    );

    return v_audit_id;
end;
$function$
;
comment on function settle_expense(uuid,uuid,numeric,text,uuid) is 'Atomic expense settlement. Requires receipt_path (plan §08) + SEC-118 (0155): 0055 caller verification and actor binding (p_actor_profile_id = the caller''s own profile for non-service callers).';

create or replace function public.soft_delete_parent(p_parent_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_row        public.parents%rowtype;
    v_active_kids integer;
begin
    -- Gate 1 — super_admin (the parents_delete RLS mirror).
    if not public.has_role('super_admin') then
        return jsonb_build_object('ok', false, 'code', 'forbidden');
    end if;

    -- Resolve + Gate 2 — tenant scope (404 semantics for unknown/cross-tenant).
    select p.* into v_row
      from public.parents p
     where p.id = p_parent_id
       and p.deleted_at is null
       and p.tenant_id = public.current_tenant_id();
    if not found then
        return jsonb_build_object('ok', false, 'code', 'not_found');
    end if;

    -- Gate 3 — the active-students guard (PARENT-500's core rule, canonical).
    select count(*) into v_active_kids
      from public.students s
     where s.parent_id = p_parent_id
       and s.tenant_id = v_row.tenant_id
       and s.deleted_at is null;
    if v_active_kids > 0 then
        return jsonb_build_object('ok', false, 'code', 'active_students_exist',
                                   'count', v_active_kids);
    end if;

    -- Gate 4 — the soft-delete itself, re-checking deleted_at (race-safe).
    update public.parents
       set deleted_at = now(),
           is_active  = false
     where id = p_parent_id
       and deleted_at is null;
    if not found then
        return jsonb_build_object('ok', false, 'code', 'not_found');
    end if;

    -- The intent record (the 0086 trigger adds the mechanism entry).
    perform public.write_audit_log(
        p_tenant_id   := v_row.tenant_id,
        p_action      := 'parent.delete',
        p_entity_type := 'parent',
        p_entity_id   := v_row.id,
        p_actor_id    := public.current_user_profile_id(),
        p_before_json := to_jsonb(v_row) - 'updated_at',
        p_after_json  := null,
        p_note        := 'Suppression logique (T-384 / soft_delete_parent) — l''historique financier est conservé'
    );

    return jsonb_build_object('ok', true, 'deleted_at', now());
end;
$function$
;
comment on function soft_delete_parent(uuid) is 'T-384 / RLS-500: canonical parent soft-delete (deleted_at + is_active=false) — super_admin-gated, tenant-scoped, active-students-guarded, audited. A plain PostgREST UPDATE on deleted_at is RLS-impossible (the SELECT policies fold deleted_at IS NULL into the UPDATE check).';

create or replace function public.soft_delete_student(p_student_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_row public.students%rowtype;
begin
    -- Gate 1 — super_admin (the students_delete RLS mirror).
    if not public.has_role('super_admin') then
        return jsonb_build_object('ok', false, 'code', 'forbidden');
    end if;

    -- Resolve + Gate 2 — tenant scope.
    select s.* into v_row
      from public.students s
     where s.id = p_student_id
       and s.deleted_at is null
       and s.tenant_id = public.current_tenant_id();
    if not found then
        return jsonb_build_object('ok', false, 'code', 'not_found');
    end if;

    -- The soft-delete (students carry no children — no guard needed).
    update public.students
       set deleted_at = now(),
           is_active  = false
     where id = p_student_id
       and deleted_at is null;
    if not found then
        return jsonb_build_object('ok', false, 'code', 'not_found');
    end if;

    -- The intent record (the 0086 trigger adds the mechanism entry).
    perform public.write_audit_log(
        p_tenant_id   := v_row.tenant_id,
        p_action      := 'student.delete',
        p_entity_type := 'student',
        p_entity_id   := v_row.id,
        p_actor_id    := public.current_user_profile_id(),
        p_before_json := to_jsonb(v_row) - 'updated_at',
        p_after_json  := null,
        p_note        := 'Suppression logique (T-381/T-384 / soft_delete_student) — l''historique financier et les archives sont conservés'
    );

    return jsonb_build_object('ok', true, 'deleted_at', now());
end;
$function$
;
comment on function soft_delete_student(uuid) is 'T-381/T-384 / RLS-500: canonical student soft-delete — super_admin-gated, tenant-scoped, audited. Fixes the RLS-impossible plain UPDATE path the deleteStudent repository call used.';

create or replace function public.sync_ledger_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.entry_date IS NOT NULL AND (NEW.at IS NULL OR NEW.at <> NEW.entry_date) THEN
        NEW.at := NEW.entry_date;
    ELSIF NEW.at IS NOT NULL AND (NEW.entry_date IS NULL OR NEW.entry_date <> NEW.at) THEN
        NEW.entry_date := NEW.at;
    END IF;
    RETURN NEW;
END;
$function$
;

create or replace function public.sync_payments_receipt_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  -- Only sync when receipt_number is NULL — preserve caller's explicit value.
  -- The canonical app always sets receipt_number explicitly; this trigger
  -- only fires as a safety net for legacy callers that set payment_number
  -- but not receipt_number.
  IF NEW.receipt_number IS NULL AND NEW.payment_number IS NOT NULL THEN
    NEW.receipt_number := NEW.payment_number;
  END IF;
  RETURN NEW;
END;
$function$
;

create or replace function public.timetable_entries_guard_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_status text;
begin
    if TG_OP = 'DELETE' then
        select status into v_status from public.timetable_versions where id = old.version_id;
        if v_status in ('published','archived') then
            raise exception 'timetable_entries is immutable for published/archived version % (T-404). Duplicate the version to a draft to make changes.', old.version_id
                using errcode = 'P0001';
        end if;
        return old;
    end if;

    select status into v_status from public.timetable_versions where id = new.version_id;
    if v_status in ('published','archived') then
        raise exception 'timetable_entries is immutable for published/archived version % (T-404). Duplicate the version to a draft to make changes.', new.version_id
            using errcode = 'P0001';
    end if;
    return new;
end;
$function$
;

create or replace function public.touch_chat_channel_on_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    update public.chat_channels
       set last_message_at      = coalesce(new.sent_at, new.created_at),
           last_message_preview = left(new.body, 120),
           updated_at           = now()
     where id = new.channel_id;
    return new;
end;
$function$
;
comment on function touch_chat_channel_on_message() is 'CHAT-104: keep chat_channels.last_message_at/preview fresh so channel lists order by last activity. SECURITY DEFINER because the UPDATE must run for ANY author (parents included) while chat_channels_update is staff/creator-gated; only denormalized preview columns are touched.';

create or replace function public.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$function$
;
comment on function touch_updated_at() is 'Universal BEFORE UPDATE trigger that bumps updated_at. Attach to every table that has an updated_at column.';

create or replace function public.unregister_fcm_token(p_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_row public.device_tokens%ROWTYPE;
    v_caller_profile uuid;
    v_is_service_role boolean;
BEGIN
    IF p_token IS NULL OR trim(p_token) = '' THEN
        RAISE EXCEPTION 'unregister_fcm_token: p_token is required';
    END IF;

    v_is_service_role := (auth.role() = 'service_role');

    SELECT * INTO v_row
      FROM public.device_tokens dt
     WHERE dt.token = p_token
     ORDER BY dt.is_active DESC, dt.last_seen_at DESC
     LIMIT 1;

    IF v_row.id IS NULL THEN
        RETURN NULL; -- nothing to retire (idempotent no-op)
    END IF;

    IF NOT v_is_service_role THEN
        SELECT up.id INTO v_caller_profile
          FROM public.user_profiles up
         WHERE up.auth_user_id = auth.uid()
         LIMIT 1;
        IF v_caller_profile IS NULL OR v_caller_profile <> v_row.user_id THEN
            RAISE EXCEPTION 'unregister_fcm_token: caller does not own the device token row %', v_row.id
              USING ERRCODE = '42501';
        END IF;
    END IF;

    UPDATE public.device_tokens
       SET is_active = false,
           last_seen_at = now()
     WHERE id = v_row.id
     RETURNING id INTO v_row.id;

    PERFORM public.write_audit_log(
        p_tenant_id   := v_row.tenant_id,
        p_action      := 'device_token.unregister',
        p_entity_type := 'device_token',
        p_entity_id   := v_row.id,
        p_actor_id    := v_row.user_id,
        p_after_json  := jsonb_build_object('is_active', false),
        p_note        := 'Retrait du jeton FCM (rotation / désactivation)'
    );

    RETURN v_row.id;
END;
$function$
;
comment on function unregister_fcm_token(text) is 'T-030 (PUSH-102/SYNC-104): retire ONE FCM token row by token string — used by the portal service-worker FCM_TOKEN_REFRESH flow to retire the stale token immediately. Caller-verified (row owner or service_role). Idempotent: returns NULL when no row matches.';

create or replace function public.upsert_assessment_from_import(p_tenant_id uuid, p_student_id uuid, p_subject_id uuid, p_term integer, p_academic_year text, p_class_id uuid DEFAULT NULL::uuid, p_devoir1 numeric DEFAULT NULL::numeric, p_devoir2 numeric DEFAULT NULL::numeric, p_examen numeric DEFAULT NULL::numeric, p_cc numeric DEFAULT NULL::numeric, p_coefficient numeric DEFAULT 1.00, p_coefficient_devoir1 numeric DEFAULT 1.00, p_coefficient_devoir2 numeric DEFAULT 1.00, p_coefficient_examen numeric DEFAULT 2.00, p_coefficient_cc numeric DEFAULT 0.00, p_entered_by uuid DEFAULT NULL::uuid, p_entered_at timestamp with time zone DEFAULT now())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_id UUID;
BEGIN
    INSERT INTO public.assessments (
        tenant_id, student_id, subject_id, class_id, term, academic_year,
        devoir1, devoir2, examen, cc, coefficient,
        coefficient_devoir1, coefficient_devoir2, coefficient_examen, coefficient_cc,
        entered_by, entered_at, created_at, updated_at
    ) VALUES (
        p_tenant_id, p_student_id, p_subject_id, p_class_id,
        GREATEST(1, LEAST(3, p_term)), p_academic_year,
        p_devoir1, p_devoir2, p_examen, p_cc, p_coefficient,
        p_coefficient_devoir1, p_coefficient_devoir2, p_coefficient_examen, p_coefficient_cc,
        p_entered_by, p_entered_at, NOW(), NOW()
    )
    ON CONFLICT (student_id, subject_id, term, academic_year) DO UPDATE SET
        devoir1 = EXCLUDED.devoir1,
        devoir2 = EXCLUDED.devoir2,
        examen  = EXCLUDED.examen,
        cc      = EXCLUDED.cc,
        coefficient = EXCLUDED.coefficient,
        coefficient_devoir1 = EXCLUDED.coefficient_devoir1,
        coefficient_devoir2 = EXCLUDED.coefficient_devoir2,
        coefficient_examen  = EXCLUDED.coefficient_examen,
        coefficient_cc      = EXCLUDED.coefficient_cc,
        class_id  = COALESCE(EXCLUDED.class_id, public.assessments.class_id),
        entered_by = EXCLUDED.entered_by,
        entered_at = EXCLUDED.entered_at,
        updated_at = NOW()
    RETURNING id INTO v_id;
    RETURN v_id;
END;
$function$
;
comment on function upsert_assessment_from_import(uuid,uuid,uuid,integer,text,uuid,numeric,numeric,numeric,numeric,numeric,numeric,numeric,numeric,numeric,uuid,timestamp with time zone) is 'Idempotent canonical assessment upsert (conflict key: student, subject, term, academic year). subject_average is recomputed by the assessments_compute_subject_average trigger — the canonical recipe rule Σ(mark×weight)/Σ(weight) over positive-weight components (devoir1, devoir2, examen, cc — ADR-018).';

create or replace function public.upsert_attendance_from_import(p_tenant_id uuid, p_student_id uuid, p_record_date date, p_status text, p_class_id uuid DEFAULT NULL::uuid, p_session text DEFAULT 'morning'::text, p_arrival_time text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_recorded_by uuid DEFAULT NULL::uuid, p_recorded_at timestamp with time zone DEFAULT now())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_id UUID;
    v_session TEXT := COALESCE(NULLIF(p_session, ''), 'morning');
    v_status  TEXT := COALESCE(NULLIF(p_status, ''), 'present');
BEGIN
    IF v_session NOT IN ('morning', 'afternoon', 'both') THEN
        RAISE EXCEPTION 'Invalid session: %', v_session;
    END IF;
    IF v_status NOT IN ('present', 'absent_excused', 'absent_unexcused', 'late') THEN
        RAISE EXCEPTION 'Invalid attendance status: %', v_status;
    END IF;

    INSERT INTO public.attendance_records (
        tenant_id, student_id, class_id, record_date, session, status,
        arrival_time, note, recorded_by, recorded_at, synced_at,
        created_at, updated_at
    ) VALUES (
        p_tenant_id, p_student_id, p_class_id, p_record_date, v_session, v_status,
        p_arrival_time, p_note, p_recorded_by, p_recorded_at, NOW(),
        NOW(), NOW()
    )
    ON CONFLICT (tenant_id, student_id, record_date, session) DO UPDATE SET
        status       = EXCLUDED.status,
        arrival_time = EXCLUDED.arrival_time,
        note         = EXCLUDED.note,
        class_id     = COALESCE(EXCLUDED.class_id, public.attendance_records.class_id),
        recorded_by  = EXCLUDED.recorded_by,
        recorded_at  = EXCLUDED.recorded_at,
        synced_at    = NOW(),
        updated_at   = NOW()
    RETURNING id INTO v_id;
    RETURN v_id;
END;
$function$
;
comment on function upsert_attendance_from_import(uuid,uuid,date,text,uuid,text,text,text,uuid,timestamp with time zone) is 'Idempotent roll-call upsert (conflict key: tenant, student, record_date, session). Used by the Android sync dispatcher (vault §06.03) so mobile roll calls reach the shared backend and the portal''s Absence Justification feature.';

create or replace function public.upsert_installment_from_import(p_tenant_id uuid, p_parent_id text, p_installment_ref text DEFAULT NULL::text, p_student_id text DEFAULT NULL::text, p_category text DEFAULT 'tuition'::text, p_label text DEFAULT NULL::text, p_amount_due numeric DEFAULT NULL::numeric, p_amount_paid numeric DEFAULT NULL::numeric, p_amount_pending numeric DEFAULT NULL::numeric, p_due_date date DEFAULT NULL::date, p_paid_date date DEFAULT NULL::date, p_status text DEFAULT 'unpaid'::text, p_academic_cycle text DEFAULT NULL::text, p_academic_year text DEFAULT NULL::text)
 RETURNS TABLE(installment_id uuid, was_inserted boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_id uuid;
    v_inserted boolean := false;
    v_existing uuid;
    v_parent uuid := public.resolve_parent_ref(p_tenant_id, p_parent_id);
    v_student uuid := public.resolve_student_ref(p_tenant_id, p_student_id);
    v_tranche int;
    v_label text := NULLIF(TRIM(COALESCE(p_label, '')), '');
    -- T-436 (DATA-052): the year id the parameter resolves to — an explicit
    -- code/label match against the tenant's academic_years first, then the
    -- INV-14 window on due_date; NULL when unresolvable (the read-side
    -- precedence fallback applies).
    v_year_id uuid := NULL;
BEGIN
    IF v_parent IS NULL THEN
        RAISE EXCEPTION 'upsert_installment_from_import: unresolvable parent ref %', p_parent_id;
    END IF;

    -- T-436: resolve p_academic_year (code or label match, tenant-scoped).
    IF p_academic_year IS NOT NULL AND NULLIF(TRIM(p_academic_year), '') IS NOT NULL THEN
        SELECT ay.id INTO v_year_id
          FROM public.academic_years ay
         WHERE ay.tenant_id = p_tenant_id
           AND (ay.code = p_academic_year OR ay.label = p_academic_year)
         ORDER BY ay.start_date DESC
         LIMIT 1;
    END IF;
    -- INV-14 window fallback on the due date when no explicit match.
    IF v_year_id IS NULL AND p_due_date IS NOT NULL THEN
        v_year_id := public.resolve_academic_year_id_for_date(p_due_date, p_tenant_id);
    END IF;

    -- Derive tranche_number from the label ("Tranche 2" -> 2) for identity matching.
    v_tranche := COALESCE(
        (SELECT NULLIF(regexp_replace(v_label, '\D', '', 'g'), '')::int WHERE v_label ~ 'Tranche\s*\d+'),
        NULL
    );

    -- Identity 1: mobile source provenance (source_type='android_sync', source_id=local ref)
    IF p_installment_ref IS NOT NULL AND TRIM(p_installment_ref) <> '' THEN
        SELECT id INTO v_existing
          FROM public.installments
         WHERE tenant_id = p_tenant_id
           AND source_type = 'android_sync'
           AND source_id = p_installment_ref
         LIMIT 1;
    END IF;

    -- Identity 2: canonical tranche identity (0032 bulk-import index columns)
    -- — T-437 (DATA-054): YEAR-AWARE. When the call resolves a year, the
    -- lookup prefers the EXACT-year row, then a NULL-year (claimable legacy)
    -- row; a DIFFERENT-year row is a different obligation — never matched
    -- (previously the year-blind match would UPDATE the previous year's
    -- tranche instead of inserting the new year's).
    IF v_existing IS NULL AND v_student IS NOT NULL AND v_tranche IS NOT NULL THEN
        SELECT id INTO v_existing
          FROM public.installments
         WHERE tenant_id = p_tenant_id
           AND parent_id = v_parent
           AND student_id = v_student
           AND category = COALESCE(NULLIF(p_category, ''), 'tuition')
           AND tranche_number = v_tranche
           AND (v_year_id IS NULL OR academic_year_id IS NULL OR academic_year_id = v_year_id)
         ORDER BY (academic_year_id = v_year_id) DESC NULLS LAST
         LIMIT 1;
    END IF;

    IF v_existing IS NOT NULL THEN
        UPDATE public.installments
           SET parent_id       = COALESCE(v_parent, parent_id),
               student_id      = COALESCE(v_student, student_id),
               category        = COALESCE(NULLIF(p_category, ''), category),
               label           = COALESCE(v_label, label),
               amount_due      = COALESCE(p_amount_due, amount_due),
               amount_paid     = COALESCE(p_amount_paid, amount_paid),
               amount_pending  = COALESCE(p_amount_pending, amount_pending),
               due_date        = COALESCE(p_due_date, due_date),
               paid_date       = COALESCE(p_paid_date, paid_date),
               status          = COALESCE(NULLIF(p_status, ''), status),
               academic_cycle  = COALESCE(p_academic_cycle, academic_cycle),
               academic_year_id = COALESCE(v_year_id, academic_year_id),
               source_type     = COALESCE(source_type, 'android_sync'),
               source_id       = COALESCE(source_id, p_installment_ref),
               updated_at      = now()
         WHERE id = v_existing;
        v_id := v_existing;
    ELSE
        v_id := public.gen_uuid();
        v_inserted := true;
        INSERT INTO public.installments (
            id, tenant_id, parent_id, student_id, category, label,
            tranche_number, amount_due, amount_paid, amount_pending,
            due_date, paid_date, status, academic_cycle,
            academic_year_id,
            source_type, source_id,
            created_at, updated_at
        ) VALUES (
            v_id, p_tenant_id, v_parent, v_student,
            COALESCE(NULLIF(p_category, ''), 'tuition'), v_label,
            v_tranche, p_amount_due,
            COALESCE(p_amount_paid, 0), COALESCE(p_amount_pending, 0),
            p_due_date, p_paid_date,
            COALESCE(NULLIF(p_status, ''), 'unpaid'),
            p_academic_cycle,
            v_year_id,
            CASE WHEN p_installment_ref IS NOT NULL THEN 'android_sync' END,
            p_installment_ref,
            now(), now()
        );
    END IF;

    RETURN QUERY SELECT v_id, v_inserted;
END;
$function$
;
comment on function upsert_installment_from_import(uuid,text,text,text,text,text,numeric,numeric,numeric,date,date,text,text,text) is 'Idempotent upsert for installments. Identity: (1) android_sync source provenance, (2) the canonical tranche identity (tenant, parent, student, category, tranche_number) — YEAR-AWARE since 0129 (T-437/DATA-054): with a resolved year, an exact-year row is preferred, then a NULL-year claimable row; a different-year row is a different obligation. p_academic_year wired since 0127 (DATA-052).';

create or replace function public.upsert_ledger_entry_from_import(p_tenant_id uuid, p_entry_number text DEFAULT NULL::text, p_parent_id text DEFAULT NULL::text, p_student_id text DEFAULT NULL::text, p_account_id text DEFAULT NULL::text, p_entry_type text DEFAULT 'charge'::text, p_amount numeric DEFAULT NULL::numeric, p_category text DEFAULT 'other'::text, p_description text DEFAULT NULL::text, p_source_type text DEFAULT 'bulk_import'::text, p_source_id text DEFAULT NULL::text, p_method text DEFAULT NULL::text, p_receipt_number text DEFAULT NULL::text, p_payment_status text DEFAULT NULL::text, p_reverses_id text DEFAULT NULL::text, p_actor_id text DEFAULT NULL::text, p_actor_name text DEFAULT NULL::text, p_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_metadata jsonb DEFAULT NULL::jsonb)
 RETURNS TABLE(entry_id uuid, was_inserted boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_id uuid;
    v_entry_number text := NULLIF(TRIM(COALESCE(p_entry_number, '')), '');
    v_inserted boolean := false;
    v_existing uuid;
    v_account_id text := NULLIF(TRIM(COALESCE(p_account_id, '')), '');
    v_parent uuid := public.resolve_parent_ref(p_tenant_id, p_parent_id);
    v_student uuid := public.resolve_student_ref(p_tenant_id, p_student_id);
    v_reverses uuid;
BEGIN
    IF v_parent IS NULL THEN
        RAISE EXCEPTION 'upsert_ledger_entry_from_import: unresolvable parent ref %', p_parent_id;
    END IF;

    -- ledger_entries.entry_number is NOT NULL — generate a stable fallback
    -- when the caller (older mobile builds) omits it.
    IF v_entry_number IS NULL THEN
        v_entry_number := 'led-' || EXTRACT(EPOCH FROM NOW())::bigint || '-' ||
                          SUBSTRING(public.gen_uuid()::text, 1, 8);
    END IF;

    -- Canonical account id (re)derivation — matches the clients'' deriveAccountId.
    IF v_account_id IS NULL THEN
        v_account_id := 'parent:' || v_parent || ':category:' || p_category ||
                        CASE WHEN v_student IS NOT NULL THEN ':student:' || v_student ELSE '' END;
    END IF;

    -- Idempotency — identity resolution order:
    --   1. entry_number (UNIQUE per entry — both clients push their local id
    --      here, so this is the per-entry identity).
    --   2. (source_type, source_id) — importer idempotency for re-imports.
    --      NEVER applied to `reversal` entries: a reversal shares the
    --      original entry's source identity BY DESIGN (desktop
    --      createReversalEntry copies the original's sourceType/sourceId), so
    --      matching on it would silently UPDATE the original entry instead of
    --      INSERTING the reversal row — corrupting balances.
    IF v_entry_number IS NOT NULL THEN
        SELECT id INTO v_existing
          FROM public.ledger_entries
         WHERE tenant_id = p_tenant_id
           AND entry_number = v_entry_number
         LIMIT 1;
    END IF;

    IF v_existing IS NULL
       AND p_source_type IS NOT NULL AND p_source_id IS NOT NULL
       AND COALESCE(NULLIF(p_entry_type, ''), 'charge') <> 'reversal' THEN
        SELECT id INTO v_existing
          FROM public.ledger_entries
         WHERE tenant_id = p_tenant_id
           AND source_type = p_source_type
           AND source_id = p_source_id
         LIMIT 1;
    END IF;

    -- Resolve reversal pointer against the server UUID space.
    IF p_reverses_id IS NOT NULL AND TRIM(p_reverses_id) <> '' THEN
        SELECT id INTO v_reverses
          FROM public.ledger_entries
         WHERE tenant_id = p_tenant_id
           AND (entry_number = p_reverses_id
             OR source_type = 'payment' AND source_id = p_reverses_id)
         LIMIT 1;
    END IF;

    IF v_existing IS NOT NULL THEN
        UPDATE public.ledger_entries
           SET parent_id      = COALESCE(v_parent, parent_id),
               student_id     = COALESCE(v_student, student_id),
               account_id     = v_account_id,
               entry_type     = COALESCE(NULLIF(p_entry_type, ''), entry_type),
               amount         = COALESCE(p_amount, amount),
               category       = COALESCE(NULLIF(p_category, ''), category),
               description    = COALESCE(p_description, description),
               method         = COALESCE(p_method, method),
               receipt_number = COALESCE(p_receipt_number, receipt_number),
               payment_status = COALESCE(p_payment_status, payment_status),
               reverses_id    = COALESCE(v_reverses::text, reverses_id),
               metadata       = COALESCE(p_metadata, metadata)
         WHERE id = v_existing;
        v_id := v_existing;
    ELSE
        -- NOTE: ledger_entries has created_at only (immutable ledger — no
        -- updated_at column).
        INSERT INTO public.ledger_entries (
            tenant_id, entry_number, parent_id, student_id, account_id,
            entry_type, amount, category, description, source_type, source_id,
            method, receipt_number, payment_status, reverses_id,
            actor_id, actor_name, at, metadata,
            created_at
        ) VALUES (
            p_tenant_id, v_entry_number, v_parent, v_student, v_account_id,
            COALESCE(NULLIF(p_entry_type, ''), 'charge'),
            COALESCE(p_amount, 0),
            COALESCE(NULLIF(p_category, ''), 'other'),
            p_description,
            COALESCE(NULLIF(p_source_type, ''), 'bulk_import'),
            p_source_id,
            p_method, p_receipt_number, p_payment_status, v_reverses::text,
            p_actor_id, p_actor_name,
            COALESCE(p_at, now()),
            COALESCE(p_metadata, '{}'::jsonb),
            now()
        )
        RETURNING id INTO v_id;
        v_inserted := true;
    END IF;

    RETURN QUERY SELECT v_id, v_inserted;
END;
$function$
;
comment on function upsert_ledger_entry_from_import(uuid,text,text,text,text,text,numeric,text,text,text,text,text,text,text,text,text,text,timestamp with time zone,jsonb) is 'Idempotent ledger-entry upsert. Identity: entry_number first, then (source_type, source_id) — but NEVER for reversal entries (they share the original''s source identity by design). 0037: refs resolved to server UUIDs; p_reverses_id resolved against the server entry space.';

create or replace function public.upsert_parent_from_import(p_tenant_id uuid, p_parent_code text, p_first_name text, p_last_name text, p_display_name text DEFAULT NULL::text, p_primary_phone text DEFAULT NULL::text, p_secondary_phone text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_occupation text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_relationship text DEFAULT NULL::text, p_preferred_language text DEFAULT 'fr'::text, p_is_active boolean DEFAULT true, p_transport_destination text DEFAULT NULL::text, p_city_tier text DEFAULT NULL::text, p_activation_code text DEFAULT NULL::text)
 RETURNS TABLE(out_parent_id uuid, out_parent_code text, out_was_inserted boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id             uuid;
  v_code           text := COALESCE(NULLIF(TRIM(p_parent_code), ''),
                                   'PAR-' || EXTRACT(YEAR FROM now())::int || '-' || UPPER(SUBSTRING(MD5(RANDOM()::text), 1, 6)));
  v_existing       uuid;
  v_inserted       boolean := false;
  v_first          text := COALESCE(NULLIF(TRIM(p_first_name), ''), '');
  v_last           text := COALESCE(NULLIF(TRIM(p_last_name), ''), '');
  v_disp           text := COALESCE(NULLIF(TRIM(p_display_name), ''), NULLIF(TRIM(v_first || ' ' || v_last), ''));
  v_phone          text := COALESCE(NULLIF(TRIM(p_primary_phone), ''), '(inconnu)');
  v_act_code       text := NULLIF(TRIM(COALESCE(p_activation_code, '')), '');
BEGIN
  SELECT p.id INTO v_existing
  FROM public.parents p
  WHERE p.tenant_id = p_tenant_id
    AND p.parent_code = v_code
    AND p.deleted_at IS NULL
  LIMIT 1;

  IF v_existing IS NULL AND v_phone <> '(inconnu)' THEN
    SELECT p.id INTO v_existing
    FROM public.parents p
    WHERE p.tenant_id = p_tenant_id
      AND p.primary_phone = v_phone
      AND p.deleted_at IS NULL
    LIMIT 1;
  END IF;

  IF v_existing IS NULL AND v_disp IS NOT NULL THEN
    SELECT p.id INTO v_existing
    FROM public.parents p
    WHERE p.tenant_id = p_tenant_id
      AND p.display_name = v_disp
      AND p.deleted_at IS NULL
    LIMIT 1;
  END IF;

  IF v_existing IS NULL AND p_email IS NOT NULL AND TRIM(p_email) <> '' THEN
    SELECT p.id INTO v_existing
    FROM public.parents p
    WHERE p.tenant_id = p_tenant_id
      AND p.email = TRIM(p_email)
      AND p.deleted_at IS NULL
    LIMIT 1;
  END IF;

  IF v_existing IS NOT NULL THEN
    UPDATE public.parents p SET
      first_name            = COALESCE(NULLIF(TRIM(p_first_name), ''), p.first_name),
      last_name             = COALESCE(NULLIF(TRIM(p_last_name), ''), p.last_name),
      display_name          = COALESCE(v_disp, p.display_name),
      primary_phone         = CASE WHEN p_primary_phone IS NOT NULL AND TRIM(p_primary_phone) <> '' THEN p_primary_phone ELSE p.primary_phone END,
      secondary_phone       = COALESCE(p_secondary_phone, p.secondary_phone),
      email                 = COALESCE(NULLIF(TRIM(p_email), ''), p.email),
      occupation            = COALESCE(NULLIF(TRIM(p_occupation), ''), p.occupation),
      address               = COALESCE(NULLIF(TRIM(p_address), ''), p.address),
      relationship          = COALESCE(p_relationship, p.relationship),
      is_active             = p_is_active,
      transport_destination = COALESCE(NULLIF(TRIM(p_transport_destination), ''), p.transport_destination),
      city_tier             = COALESCE(NULLIF(TRIM(p_city_tier), ''), p.city_tier),
      updated_at            = now()
    WHERE p.id = v_existing;
    v_id := v_existing;
  ELSE
    -- NOTE: the parents table has no preferred_language column — the
    -- parameter is accepted for API compatibility but not persisted
    -- (matches the 0031 original).
    INSERT INTO public.parents (
      tenant_id, parent_code, first_name, last_name, display_name,
      primary_phone, secondary_phone, email, occupation, address,
      relationship, is_active, transport_destination, city_tier
    ) VALUES (
      p_tenant_id, v_code, v_first, v_last, v_disp,
      v_phone, p_secondary_phone, p_email, p_occupation, p_address,
      p_relationship, p_is_active,
      NULLIF(TRIM(COALESCE(p_transport_destination, '')), ''),
      NULLIF(TRIM(COALESCE(p_city_tier, '')), '')
    )
    RETURNING id INTO v_id;
    v_inserted := true;
  END IF;

  -- 0037: populate activation_codes so the parent can bind their web account.
  -- Idempotent on (tenant_id, code). Skips when the code is already bound to
  -- another parent (never hijack an existing binding).
  IF v_act_code IS NOT NULL THEN
    INSERT INTO public.activation_codes (tenant_id, code, parent_id, issued_at, expires_at)
    VALUES (p_tenant_id, v_act_code, v_id, now(), now() + interval '365 days')
    ON CONFLICT (tenant_id, code) DO UPDATE
      SET parent_id = EXCLUDED.parent_id
    WHERE public.activation_codes.bound_to_auth_user_id IS NULL;
  END IF;

  RETURN QUERY SELECT v_id, v_code, v_inserted;
END;
$function$
;
comment on function upsert_parent_from_import(uuid,text,text,text,text,text,text,text,text,text,text,text,boolean,text,text,text) is 'Idempotent parent upsert. Identity: parent_code, then phone, then display_name, then email. 0037: also populates activation_codes when p_activation_code is provided (canonical deterministicActivationCode output) so web-portal activation works for imported / cross-platform-created parents.';

create or replace function public.upsert_payment_from_import(p_tenant_id uuid, p_payment_number text, p_parent_id text, p_student_id text, p_invoice_id uuid DEFAULT NULL::uuid, p_installment_id text DEFAULT NULL::text, p_amount numeric DEFAULT NULL::numeric, p_method text DEFAULT 'cash'::text, p_category text DEFAULT 'other'::text, p_status text DEFAULT 'paid'::text, p_check_number text DEFAULT NULL::text, p_check_bank_name text DEFAULT NULL::text, p_check_issue_date date DEFAULT NULL::date, p_check_clearance_date date DEFAULT NULL::date, p_transfer_reference text DEFAULT NULL::text, p_transfer_source_bank text DEFAULT NULL::text, p_proof_path text DEFAULT NULL::text, p_collected_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_collected_by uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_reversal_of_payment_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(payment_id uuid, payment_number text, was_inserted boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_id uuid;
    v_num text := p_payment_number;
    v_inserted boolean := false;
    v_existing RECORD;
    v_final_status text;
    v_parent uuid := public.resolve_parent_ref(p_tenant_id, p_parent_id);
    v_student uuid := public.resolve_student_ref(p_tenant_id, p_student_id);
    v_installment uuid := public.resolve_installment_ref(p_tenant_id, p_installment_id);
BEGIN
    -- ── SEC-111: caller-tenant verification ──────────────────────────
    -- The SECURITY DEFINER flag bypasses RLS, so without this check any
    -- authenticated caller could write payments into ANY tenant by
    -- passing a foreign p_tenant_id. Trusted exemptions:
    --   - service_role: server-side code (Edge Functions, import jobs);
    --   - global admins (0053): no resolvable current_tenant_id()
    --     (user_profiles.tenant_id IS NULL); the desktop TENANT-103
    --     fallback legitimately targets the demo tenant.
    IF coalesce(auth.jwt() ->> 'role', '') <> 'service_role'
       AND NOT public.is_global_admin()
       AND p_tenant_id IS DISTINCT FROM public.current_tenant_id() THEN
        RAISE EXCEPTION 'upsert_payment_from_import: p_tenant_id does not match the authenticated caller''s tenant (SEC-111)';
    END IF;

    -- ── T-015 / DRIFT-011: server-side canonical number when none supplied.
    -- The desktop sync queue now pushes payments WITHOUT a number when the
    -- queued row carries none (previously a client-side random PAY- number —
    -- collision-prone, wrong format). Dedup by number is meaningless for a
    -- NULL number (the lookup below cannot match), so this path always
    -- INSERTs — correct: nothing identifiable to update.
    IF v_num IS NULL OR btrim(v_num) = '' THEN
        v_num := public.next_receipt_number(p_tenant_id);
    END IF;

    IF v_parent IS NULL THEN
        RAISE EXCEPTION 'upsert_payment_from_import: unresolvable parent ref %', p_parent_id;
    END IF;

    -- NOTE: qualify — `payment_number` is also an output column of the
    -- RETURNS TABLE (unqualified refs are ambiguous).
    SELECT pay.id, pay.payment_number INTO v_existing
      FROM public.payments pay
     WHERE pay.tenant_id = p_tenant_id
       AND pay.payment_number = v_num
     LIMIT 1;

    -- Determine the auto-status for cash vs non-cash (mirrors enforce_payment_proof trigger).
    v_final_status := COALESCE(p_status, CASE WHEN p_method = 'cash' THEN 'paid' ELSE 'pending' END);

    IF FOUND THEN
        v_id := v_existing.id;
        UPDATE public.payments
           SET parent_id        = COALESCE(v_parent, parent_id),
               student_id       = COALESCE(v_student, student_id),
               invoice_id       = COALESCE(p_invoice_id, invoice_id),
               installment_id   = COALESCE(v_installment, installment_id),
               amount           = COALESCE(p_amount, amount),
               method           = COALESCE(NULLIF(p_method, ''), method),
               category         = COALESCE(NULLIF(p_category, ''), category),
               status           = v_final_status,
               check_number     = COALESCE(p_check_number, check_number),
               check_bank_name  = COALESCE(p_check_bank_name, check_bank_name),
               check_issue_date = COALESCE(p_check_issue_date, check_issue_date),
               check_clearance_date = COALESCE(p_check_clearance_date, check_clearance_date),
               transfer_reference = COALESCE(p_transfer_reference, transfer_reference),
               transfer_source_bank = COALESCE(p_transfer_source_bank, transfer_source_bank),
               proof_path       = COALESCE(p_proof_path, proof_path),
               collected_at     = COALESCE(p_collected_at, collected_at),
               collected_by     = COALESCE(p_collected_by, collected_by),
               notes            = COALESCE(p_notes, notes),
               reversal_of_payment_id = COALESCE(p_reversal_of_payment_id, reversal_of_payment_id),
               updated_at       = now()
         WHERE id = v_id;
    ELSE
        v_id := public.gen_uuid();
        v_inserted := true;
        INSERT INTO public.payments (
            id, tenant_id, payment_number, parent_id, student_id, invoice_id, installment_id,
            amount, method, category, status,
            check_number, check_bank_name, check_issue_date, check_clearance_date,
            transfer_reference, transfer_source_bank, proof_path,
            collected_at, collected_by, notes, reversal_of_payment_id,
            created_at, updated_at
        ) VALUES (
            v_id, p_tenant_id, v_num, v_parent, v_student, p_invoice_id, v_installment,
            COALESCE(p_amount, 0), COALESCE(NULLIF(p_method, ''), 'cash'),
            COALESCE(NULLIF(p_category, ''), 'other'), v_final_status,
            p_check_number, p_check_bank_name, p_check_issue_date, p_check_clearance_date,
            p_transfer_reference, p_transfer_source_bank, p_proof_path,
            COALESCE(p_collected_at, now()), p_collected_by, p_notes, p_reversal_of_payment_id,
            now(), now()
        );
    END IF;

    RETURN QUERY SELECT v_id, v_num, v_inserted;
END;
$function$
;
comment on function upsert_payment_from_import(uuid,text,text,text,uuid,text,numeric,text,text,text,text,text,date,date,text,text,text,timestamp with time zone,uuid,text,uuid) is 'Idempotent upsert for payments. Identity: (tenant, payment_number). 0037: p_parent_id / p_student_id / p_installment_id accept server UUIDs, canonical codes or mobile local refs (resolved via resolve_*_ref).';

create or replace function public.upsert_secret_setting(p_tenant_id uuid, p_category text, p_key text, p_label_fr text, p_value_encrypted text, p_actor_profile_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid;
begin
    insert into public.system_settings (
        tenant_id, category, key, label_fr, value_encrypted, value_type,
        is_sensitive, updated_by, updated_at, created_at
    ) values (
        p_tenant_id, p_category, p_key, p_label_fr, p_value_encrypted, 'secret',
        true, p_actor_profile_id, now(), now()
    )
    on conflict (tenant_id, category, key) do update
    set value_encrypted = excluded.value_encrypted,
        is_sensitive = true,
        value_type = 'secret',
        updated_by = excluded.updated_by,
        updated_at = now()
    returning id into v_id;

    -- Audit log (does NOT include the value for security)
    perform public.write_audit_log(
        p_tenant_id := p_tenant_id,
        p_action := 'system_secret.update',
        p_entity_type := 'system_setting',
        p_entity_id := v_id,
        p_actor_id := p_actor_profile_id,
        p_after_json := jsonb_build_object('key', p_key, 'category', p_category, 'masked', true)
    );

    return v_id;
end;
$function$
;
comment on function upsert_secret_setting(uuid,text,text,text,text,uuid) is 'Insert or update a SECRET setting. The value_encrypted parameter is AES-256-GCM ciphertext (encrypted by the Electron app). Audit-logged (value NOT included in audit).';

create or replace function public.upsert_setting(p_tenant_id uuid, p_category text, p_key text, p_label_fr text, p_value jsonb, p_value_type text DEFAULT 'string'::text, p_is_sensitive boolean DEFAULT false, p_actor_profile_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid;
begin
    insert into public.system_settings (
        tenant_id, category, key, label_fr, value, value_type, is_sensitive,
        updated_by, updated_at, created_at
    ) values (
        p_tenant_id, p_category, p_key, p_label_fr, p_value, p_value_type, p_is_sensitive,
        p_actor_profile_id, now(), now()
    )
    on conflict (tenant_id, category, key) do update
    set value = excluded.value,
        value_type = excluded.value_type,
        is_sensitive = excluded.is_sensitive,
        updated_by = excluded.updated_by,
        updated_at = now()
    returning id into v_id;

    -- Audit log
    perform public.write_audit_log(
        p_tenant_id := p_tenant_id,
        p_action := 'system_setting.update',
        p_entity_type := 'system_setting',
        p_entity_id := v_id,
        p_actor_id := p_actor_profile_id,
        p_after_json := jsonb_build_object('key', p_key, 'category', p_category, 'value_type', p_value_type)
    );

    return v_id;
end;
$function$
;
comment on function upsert_setting(uuid,text,text,text,jsonb,text,boolean,uuid) is 'Insert or update a setting. Audit-logged. For sensitive values, use upsert_secret_setting instead.';

create or replace function public.upsert_student_from_import(p_tenant_id uuid, p_student_code text, p_parent_id text, p_first_name text, p_last_name text, p_display_name text DEFAULT NULL::text, p_middle_name text DEFAULT NULL::text, p_date_of_birth date DEFAULT NULL::date, p_gender text DEFAULT NULL::text, p_grade_level_id uuid DEFAULT NULL::uuid, p_class_id uuid DEFAULT NULL::uuid, p_enrollment_date date DEFAULT NULL::date, p_enrollment_status text DEFAULT 'active'::text, p_medical_notes text DEFAULT NULL::text, p_is_active boolean DEFAULT true, p_grade_level_code text DEFAULT NULL::text, p_transport_tier text DEFAULT NULL::text, p_payment_plan text DEFAULT 'tranches'::text, p_filiere_code text DEFAULT NULL::text, p_specialite_code text DEFAULT NULL::text, p_origin_type text DEFAULT NULL::text, p_previous_school_name text DEFAULT NULL::text, p_previous_school_level text DEFAULT NULL::text, p_previous_academic_year text DEFAULT NULL::text, p_origin_notes text DEFAULT NULL::text)
 RETURNS TABLE(out_student_id uuid, out_student_code text, out_was_inserted boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id        uuid;
  v_code      text := COALESCE(NULLIF(TRIM(p_student_code), ''),
                               'ELV-' || EXTRACT(YEAR FROM now())::int || '-' || UPPER(SUBSTRING(MD5(RANDOM()::text), 1, 6)));
  v_existing  uuid;
  v_inserted  boolean := false;
  v_first     text := COALESCE(NULLIF(TRIM(p_first_name), ''), '');
  v_last      text := COALESCE(NULLIF(TRIM(p_last_name), ''), '');
  v_disp      text := COALESCE(NULLIF(TRIM(p_display_name), ''),
                               NULLIF(TRIM(v_first || ' ' || v_last), ''));
  v_plan      text := CASE WHEN p_payment_plan IN ('tranches', 'full_annual') THEN p_payment_plan ELSE 'tranches' END;
  -- 0037: Android pushes 'M'/'F' gender codes while the students.gender CHECK
  -- requires male/female/other — normalize at the RPC boundary.
  v_gender    text := CASE lower(COALESCE(p_gender, ''))
                     WHEN 'm' THEN 'male'
                     WHEN 'f' THEN 'female'
                     WHEN 'male' THEN 'male'
                     WHEN 'female' THEN 'female'
                     WHEN 'other' THEN 'other'
                     ELSE NULL END;
  v_parent    uuid := public.resolve_parent_ref(p_tenant_id, p_parent_id);
  -- 0107: normalized classification ('general' → NULL storage, the
  -- untagged pre-0107 state; COALESCE preserves existing values).
  v_filiere   text := lower(NULLIF(btrim(COALESCE(p_filiere_code, '')), ''));
  v_specialite text := lower(NULLIF(btrim(COALESCE(p_specialite_code, '')), ''));
  -- 0128: normalized origin (the CHECK constraint is the authority; this
  -- maps blank/unknown to NULL = unknown, preserving stored values).
  v_origin    text := lower(NULLIF(btrim(COALESCE(p_origin_type, '')), ''));
BEGIN
  IF v_parent IS NULL THEN
      RAISE EXCEPTION 'upsert_student_from_import: unresolvable parent ref %', p_parent_id
        USING HINT = 'Push the parent (upsert_parent_from_import) before its students.';
  END IF;

  IF v_filiere = 'general' THEN
      v_filiere := NULL;
  END IF;
  IF v_origin NOT IN ('new_admission', 'transfer', 'continuation', 'other') THEN
      v_origin := NULL;
  END IF;

  -- Identity resolution (column refs qualified — see 0031):
  --   1. (tenant_id, student_code)
  --   2. (parent_id, first_name, last_name) when all three are non-empty
  SELECT s.id INTO v_existing
  FROM public.students s
  WHERE s.tenant_id = p_tenant_id
    AND s.student_code = v_code
    AND s.deleted_at IS NULL
  LIMIT 1;

  IF v_existing IS NULL AND v_first <> '' AND v_last <> '' THEN
    SELECT s.id INTO v_existing
    FROM public.students s
    WHERE s.tenant_id = p_tenant_id
      AND s.parent_id = v_parent
      AND s.first_name = v_first
      AND s.last_name = v_last
      AND s.deleted_at IS NULL
    LIMIT 1;
  END IF;

  IF v_existing IS NOT NULL THEN
    UPDATE public.students s SET
      parent_id           = v_parent,
      first_name          = COALESCE(NULLIF(TRIM(p_first_name), ''), s.first_name),
      last_name           = COALESCE(NULLIF(TRIM(p_last_name), ''), s.last_name),
      display_name        = COALESCE(v_disp, s.display_name),
      middle_name         = COALESCE(p_middle_name, s.middle_name),
      date_of_birth       = COALESCE(p_date_of_birth, s.date_of_birth),
      gender              = COALESCE(v_gender, s.gender),
      grade_level_id      = COALESCE(p_grade_level_id, s.grade_level_id),
      class_id            = COALESCE(p_class_id, s.class_id),
      enrollment_date     = COALESCE(p_enrollment_date, s.enrollment_date),
      enrollment_status   = COALESCE(NULLIF(TRIM(p_enrollment_status), ''), s.enrollment_status),
      medical_notes       = COALESCE(p_medical_notes, s.medical_notes),
      is_active           = p_is_active,
      grade_level_code    = COALESCE(NULLIF(TRIM(p_grade_level_code), ''), s.grade_level_code),
      transport_tier      = COALESCE(NULLIF(TRIM(p_transport_tier), ''), s.transport_tier),
      payment_plan        = v_plan,
      -- 0107: classification — provided value wins, else preserved.
      filiere_code        = COALESCE(v_filiere, s.filiere_code),
      specialite_code     = COALESCE(v_specialite, s.specialite_code),
      -- 0128 (T-437): origin — provided value wins, else preserved (imports
      -- never erase a captured origin; NULL = unknown).
      origin_type         = COALESCE(v_origin, s.origin_type),
      previous_school_name    = COALESCE(NULLIF(TRIM(COALESCE(p_previous_school_name, '')), ''), s.previous_school_name),
      previous_school_level   = COALESCE(NULLIF(TRIM(COALESCE(p_previous_school_level, '')), ''), s.previous_school_level),
      previous_academic_year  = COALESCE(NULLIF(TRIM(COALESCE(p_previous_academic_year, '')), ''), s.previous_academic_year),
      origin_notes        = COALESCE(p_origin_notes, s.origin_notes),
      updated_at          = now()
    WHERE s.id = v_existing;
    v_id := v_existing;
  ELSE
    INSERT INTO public.students (
      tenant_id, student_code, parent_id, first_name, middle_name, last_name,
      display_name, date_of_birth, gender, grade_level_id, class_id,
      enrollment_date, enrollment_status, medical_notes, is_active,
      grade_level_code, transport_tier, payment_plan,
      filiere_code, specialite_code,
      origin_type, previous_school_name, previous_school_level,
      previous_academic_year, origin_notes
    ) VALUES (
      p_tenant_id, v_code, v_parent, v_first, p_middle_name, v_last,
      v_disp, COALESCE(p_date_of_birth, '2000-01-01'::date), v_gender, p_grade_level_id, p_class_id,
      COALESCE(p_enrollment_date, current_date), COALESCE(NULLIF(TRIM(p_enrollment_status), ''), 'active'),
      p_medical_notes, p_is_active,
      p_grade_level_code, p_transport_tier, v_plan,
      v_filiere, v_specialite,
      v_origin, NULLIF(TRIM(COALESCE(p_previous_school_name, '')), ''),
      NULLIF(TRIM(COALESCE(p_previous_school_level, '')), ''),
      NULLIF(TRIM(COALESCE(p_previous_academic_year, '')), ''),
      p_origin_notes
    )
    RETURNING id INTO v_id;
    v_inserted := true;
  END IF;

  RETURN QUERY SELECT v_id, v_code, v_inserted;
END;
$function$
;
comment on function upsert_student_from_import(uuid,text,text,text,text,text,text,date,text,uuid,uuid,date,text,text,boolean,text,text,text,text,text,text,text,text,text,text) is 'Idempotent upsert for students. Identity: (tenant, student_code) with fallback to (parent_id, first_name, last_name). 0037: p_parent_id accepts a server UUID, a canonical parent_code (PAR-YYYY-XXXXXX) or a mobile local ref; preserves the 0028 params (grade_level_code / transport_tier / payment_plan). 0107 (T-401): p_filiere_code / p_specialite_code set the academic classification (NULL or the literal general = untagged; COALESCE preserves the stored classification on partial syncs — imports never erase classification). 0128 (T-437): the five origin params set the pre-admission origin (origin_type/previous_school_name/previous_school_level/previous_academic_year/origin_notes — INV-24a; COALESCE preserves a captured origin on partial syncs).';

create or replace function public.validate_workflow_dag(p_definition jsonb, p_strict boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
    v_nodes        jsonb;
    v_edges        jsonb;
    v_errors       text[] := '{}';
    v_warnings     text[] := '{}';
    v_node_ids     text[] := '{}';
    v_edge_ids     text[] := '{}';
    v_seen_pairs   text[] := '{}';
    v_subtype_map  jsonb := '{
        "trigger":   ["payment_overdue","student_enrolled","payment_recorded","schedule","absence_limit_exceeded","manual_run","grade_below_threshold","payment_cleared_or_bounced","document_expiration","calendar_cron_event","stock_level_critical"],
        "condition": ["debt_over_threshold","payment_method_match","student_status_match","time_window","route_switch","has_medical_justification"],
        "action":    ["send_email","apply_discount","create_invoice","push_notification","log_audit","send_whatsapp","restrict_account","dispatch_task","generate_document","account_adjustment"],
        "delay":     ["wait_duration"],
        "transform": ["database_query","extract_field"]
    }'::jsonb;
    v_node         jsonb;
    v_edge         jsonb;
    v_cfg          jsonb;
    v_id           text;
    v_type         text;
    v_subtype      text;
    v_source       text;
    v_target       text;
    v_pair         text;
    v_i            int;
    v_j            int;
    v_k            int;
    v_n            int;
    v_m            int;
    v_src_idx      int;
    v_tgt_idx      int;
    -- Kahn state: flat parallel arrays (deduped edge list) + 1-D in-degree.
    v_edge_src     int[] := '{}';
    v_edge_tgt     int[] := '{}';
    v_in_degree    int[];
    v_queue        int[];
    v_current      int;
    v_processed    int := 0;
    v_cycle_nodes  text[] := '{}';
    v_trigger_seen boolean := false;
    v_cond         jsonb;
    v_cond_text    jsonb;
    v_route        jsonb;
    v_duration     numeric;
begin
    -- ---------- structural: the definition object itself ----------
    if p_definition is null or jsonb_typeof(p_definition) <> 'object' then
        return jsonb_build_object('valid', false, 'errors',
            jsonb_build_array('definition must be a JSON object with nodes[] and edges[]'),
            'warnings', '[]'::jsonb, 'node_count', 0, 'edge_count', 0);
    end if;
    if not p_definition ? 'nodes' or jsonb_typeof(p_definition -> 'nodes') <> 'array' then
        return jsonb_build_object('valid', false, 'errors',
            jsonb_build_array('definition.nodes must be an array'),
            'warnings', '[]'::jsonb, 'node_count', 0, 'edge_count', 0);
    end if;
    if not p_definition ? 'edges' or jsonb_typeof(p_definition -> 'edges') <> 'array' then
        return jsonb_build_object('valid', false, 'errors',
            jsonb_build_array('definition.edges must be an array'),
            'warnings', '[]'::jsonb, 'node_count', 0, 'edge_count', 0);
    end if;

    v_nodes := p_definition -> 'nodes';
    v_edges := coalesce(p_definition -> 'edges', '[]'::jsonb);
    v_n := jsonb_array_length(v_nodes);
    v_m := jsonb_array_length(v_edges);

    if v_n = 0 then
        v_errors := array_append(v_errors, 'workflow has no nodes');
    end if;

    -- ---------- nodes: id, type, subtype ----------
    v_i := 0;
    for v_node in select jsonb_array_elements(v_nodes)
    loop
        v_i := v_i + 1;
        if jsonb_typeof(v_node) <> 'object' then
            v_errors := array_append(v_errors, format('node[%s] is not an object', v_i - 1));
            v_node_ids := array_append(v_node_ids, '§invalid' || v_i::text || '§');
            continue;
        end if;
        v_id := v_node ->> 'id';
        if v_id is null or v_id = '' then
            v_errors := array_append(v_errors, format('node[%s] has an empty/missing id', v_i - 1));
            v_id := '§invalid' || v_i::text || '§';
        elsif v_id = any(v_node_ids) then
            v_errors := array_append(v_errors, format('duplicate node id "%s"', v_id));
        end if;
        v_node_ids := array_append(v_node_ids, v_id);

        v_type := v_node ->> 'type';
        if v_type is null or not (v_type = any(array['trigger','condition','action','delay','transform'])) then
            v_errors := array_append(v_errors, format('node "%s" has invalid type "%s"', v_id, coalesce(v_type, '§null§')));
        else
            v_subtype := v_node ->> 'subtype';
            if v_subtype is null or v_subtype = '' then
                v_errors := array_append(v_errors, format('node "%s" (type %s) is missing its subtype', v_id, v_type));
            elsif not (v_subtype = any(array(select jsonb_array_elements_text(coalesce(v_subtype_map -> v_type, '[]'::jsonb))))) then
                v_errors := array_append(v_errors, format('node "%s": subtype "%s" is not registered for type %s', v_id, v_subtype, v_type));
            end if;
        end if;

        if v_type = 'trigger' then
            v_trigger_seen := true;
        end if;
    end loop;

    -- ---------- edges: id, refs, self, duplicate pairs ----------
    v_i := 0;
    for v_edge in select jsonb_array_elements(v_edges)
    loop
        v_i := v_i + 1;
        if jsonb_typeof(v_edge) <> 'object' then
            v_errors := array_append(v_errors, format('edge[%s] is not an object', v_i - 1));
            continue;
        end if;
        v_id := v_edge ->> 'id';
        if v_id is null or v_id = '' then
            v_warnings := array_append(v_warnings, format('edge[%s] has no id (tolerated — key is (source,target))', v_i - 1));
        elsif v_id = any(v_edge_ids) then
            v_errors := array_append(v_errors, format('duplicate edge id "%s"', v_id));
        end if;
        v_edge_ids := array_append(v_edge_ids, v_id);

        v_source := v_edge ->> 'source';
        v_target := v_edge ->> 'target';
        if v_source is null or v_source = '' or not (v_source = any(v_node_ids)) then
            v_errors := array_append(v_errors, format('edge "%s" references unknown source node "%s"', coalesce(v_id, format('edge[%s]', v_i - 1)), coalesce(v_source, '§null§')));
        end if;
        if v_target is null or v_target = '' or not (v_target = any(v_node_ids)) then
            v_errors := array_append(v_errors, format('edge "%s" references unknown target node "%s"', coalesce(v_id, format('edge[%s]', v_i - 1)), coalesce(v_target, '§null§')));
        end if;
        if v_source is not null and v_source = v_target then
            v_errors := array_append(v_errors, format('edge "%s" is a self-reference on node "%s"', coalesce(v_id, format('edge[%s]', v_i - 1)), v_source));
        end if;
        if v_source is not null and v_target is not null and v_source <> v_target
           and (v_source = any(v_node_ids)) and (v_target = any(v_node_ids)) then
            v_pair := v_source || '->' || v_target;
            if v_pair = any(v_seen_pairs) then
                v_errors := array_append(v_errors, format('duplicate edge between "%s" and "%s"', v_source, v_target));
            else
                -- Deduped edge list for the Kahn walk (first pair wins).
                v_edge_src := array_append(v_edge_src, array_position(v_node_ids, v_source));
                v_edge_tgt := array_append(v_edge_tgt, array_position(v_node_ids, v_target));
            end if;
            v_seen_pairs := array_append(v_seen_pairs, v_pair);
        end if;
    end loop;

    -- ---------- Kahn cycle detection (in-degree walk, flat edge arrays) ----------
    if v_n > 0 and coalesce(array_length(v_node_ids, 1), 0) = v_n then
        for v_i in 1..v_n loop
            v_in_degree[v_i] := 0;
        end loop;
        for v_k in 1..coalesce(array_length(v_edge_src, 1), 0) loop
            v_in_degree[v_edge_tgt[v_k]] := coalesce(v_in_degree[v_edge_tgt[v_k]], 0) + 1;
        end loop;

        for v_i in 1..v_n loop
            if coalesce(v_in_degree[v_i], 0) = 0 then
                v_queue := array_append(v_queue, v_i);
            end if;
        end loop;

        while coalesce(array_length(v_queue, 1), 0) > 0
        loop
            v_current := v_queue[1];
            v_queue := v_queue[2:coalesce(array_length(v_queue, 1), 1)];
            v_processed := v_processed + 1;
            for v_k in 1..coalesce(array_length(v_edge_src, 1), 0) loop
                if v_edge_src[v_k] = v_current then
                    v_j := v_edge_tgt[v_k];
                    v_in_degree[v_j] := v_in_degree[v_j] - 1;
                    if v_in_degree[v_j] = 0 then
                        v_queue := array_append(v_queue, v_j);
                    end if;
                end if;
            end loop;
        end loop;

        if v_processed < v_n then
            for v_i in 1..v_n loop
                if coalesce(v_in_degree[v_i], 0) > 0 then
                    v_cycle_nodes := array_append(v_cycle_nodes, v_node_ids[v_i]);
                end if;
            end loop;
            v_errors := array_append(v_errors,
                format('cycle detected — %s node(s) involved: %s (Kahn)',
                       coalesce(array_length(v_cycle_nodes, 1), 0), array_to_string(v_cycle_nodes, ', ')));
        end if;

        -- Trigger in-degree rule (a trigger fed by another node is malformed).
        -- Computed from the deduped edge list (the walk above MUTATES
        -- v_in_degree, so it cannot be reused here).
        for v_node in select jsonb_array_elements(v_nodes)
        loop
            if (v_node ->> 'type') = 'trigger' then
                v_src_idx := array_position(v_node_ids, v_node ->> 'id');
                if v_src_idx is not null then
                    v_tgt_idx := 0;
                    for v_k in 1..coalesce(array_length(v_edge_tgt, 1), 0) loop
                        if v_edge_tgt[v_k] = v_src_idx then
                            v_tgt_idx := v_tgt_idx + 1;
                        end if;
                    end loop;
                    if v_tgt_idx > 0 then
                        v_errors := array_append(v_errors,
                            format('trigger node "%s" has incoming edges — triggers must be roots', v_node ->> 'id'));
                    end if;
                end if;
            end if;
        end loop;
    end if;

    -- ---------- strict-mode rules (publish gate) ----------
    if p_strict then
        if not v_trigger_seen and v_n > 0 then
            v_errors := array_append(v_errors, 'workflow has no trigger node (required for publishing)');
        end if;

        for v_node in select jsonb_array_elements(v_nodes)
        loop
            v_id := v_node ->> 'id';
            v_subtype := v_node ->> 'subtype';
            v_type := v_node ->> 'type';
            v_cfg := coalesce(v_node -> 'config', '{}'::jsonb);

            if v_type = 'condition' and v_subtype in ('debt_over_threshold','payment_method_match','student_status_match','has_medical_justification') then
                v_cond := coalesce(v_cfg -> 'condition', v_cfg -> '_condition');
                if v_cond is null then
                    -- legacy scalar configs tolerated with a warning
                    if v_cfg ? 'threshold' or v_cfg ? 'method' or v_cfg ? 'status' then
                        v_warnings := array_append(v_warnings,
                            format('node "%s": legacy scalar condition config (no canonical condition tree)', v_id));
                    else
                        v_errors := array_append(v_errors,
                            format('node "%s": condition node has no condition configured', v_id));
                    end if;
                elsif jsonb_typeof(v_cond) = 'string' then
                    begin
                        v_cond_text := (v_cond #>> '{}')::jsonb;
                        if not public.workflow_condition_valid(v_cond_text) then
                            v_errors := array_append(v_errors, format('node "%s": malformed condition tree', v_id));
                        end if;
                    exception when others then
                        v_errors := array_append(v_errors, format('node "%s": condition is a string but not valid JSON', v_id));
                    end;
                elsif not public.workflow_condition_valid(v_cond) then
                    v_errors := array_append(v_errors, format('node "%s": malformed condition tree', v_id));
                end if;
            end if;

            if v_type = 'condition' and v_subtype = 'route_switch' then
                if not (v_cfg ? 'routes') or jsonb_typeof(v_cfg -> 'routes') <> 'array' then
                    v_errors := array_append(v_errors, format('node "%s": route_switch has no routes configured', v_id));
                else
                    for v_route in select jsonb_array_elements(v_cfg -> 'routes')
                    loop
                        if jsonb_typeof(v_route) <> 'object' or not (v_route ? 'condition') then
                            v_errors := array_append(v_errors, format('node "%s": a route is missing its condition', v_id));
                        elsif not public.workflow_condition_valid(v_route -> 'condition') then
                            v_errors := array_append(v_errors, format('node "%s": a route condition is malformed', v_id));
                        end if;
                    end loop;
                end if;
            end if;

            if v_type = 'delay' and v_subtype = 'wait_duration' then
                if v_cfg ? 'duration_ms' then
                    begin
                        v_duration := (v_cfg ->> 'duration_ms')::numeric;
                        if v_duration is null or v_duration <= 0 then
                            v_errors := array_append(v_errors, format('node "%s": wait_duration must be a positive duration_ms', v_id));
                        end if;
                    exception when others then
                        v_errors := array_append(v_errors, format('node "%s": duration_ms is not a number', v_id));
                    end;
                else
                    v_errors := array_append(v_errors, format('node "%s": wait_duration has no duration_ms', v_id));
                end if;
            end if;
        end loop;
    end if;

    return jsonb_build_object(
        'valid', (coalesce(array_length(v_errors, 1), 0) = 0),
        'errors', to_jsonb(v_errors),
        'warnings', to_jsonb(v_warnings),
        'node_count', v_n,
        'edge_count', v_m
    );
end;
$function$
;

create or replace function public.workflow_condition_valid(p_node jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
    v_kind       text;
    v_combinator text;
    v_child      jsonb;
begin
    if p_node is null or jsonb_typeof(p_node) <> 'object' then
        return false;
    end if;
    v_kind := p_node ->> 'kind';
    if v_kind = 'comparison' then
        return p_node ? 'field'
           and jsonb_typeof(p_node -> 'field') = 'string'
           and (p_node ->> 'field') <> ''
           and p_node ? 'op'
           and (p_node ->> 'op') in ('>', '<', '>=', '<=', '==', '!=');
    elsif v_kind = 'logic' then
        v_combinator := p_node ->> 'combinator';
        if v_combinator not in ('and', 'or', 'not') then
            return false;
        end if;
        if not p_node ? 'children' or jsonb_typeof(p_node -> 'children') <> 'array' then
            return false;
        end if;
        if v_combinator = 'not' and jsonb_array_length(p_node -> 'children') <> 1 then
            return false;
        end if;
        for v_child in select jsonb_array_elements(p_node -> 'children')
        loop
            if not public.workflow_condition_valid(v_child) then
                return false;
            end if;
        end loop;
        return true;
    end if;
    return false;
end;
$function$
;

create or replace function public.workflows_publish_gate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
    v_result jsonb;
    v_errors text[];
begin
    if new.status = 'published'
       and (old.status is distinct from 'published'
            or new.dag_definition is distinct from old.dag_definition) then
        v_result := public.validate_workflow_dag(new.dag_definition, true);
        if not (v_result ->> 'valid')::boolean then
            v_errors := array(select jsonb_array_elements_text(v_result -> 'errors'));
            raise exception 'workflow publish rejected: %',
                    array_to_string(v_errors, ' | ')
                using errcode = '23514';
        end if;
    end if;
    return new;
end;
$function$
;

create or replace function public.workflows_publish_gate_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
    v_result jsonb;
    v_errors text[];
begin
    if new.status = 'published' then
        v_result := public.validate_workflow_dag(new.dag_definition, true);
        if not (v_result ->> 'valid')::boolean then
            v_errors := array(select jsonb_array_elements_text(v_result -> 'errors'));
            raise exception 'workflow publish rejected: %',
                    array_to_string(v_errors, ' | ')
                using errcode = '23514';
        end if;
        -- Direct-insert publish: the publish counter starts at 1.
        if coalesce(new.version, 0) < 1 then
            new.version := 1;
        end if;
    end if;
    return new;
end;
$function$
;

create or replace function public.workflows_version_on_publish()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    -- Bump the publish version on every transition INTO 'published'
    -- (draft→published, disabled→published). The column default is 0
    -- (= never published), so the first publish lands at 1.
    -- Unpublishing/editing does NOT touch it.
    if new.status = 'published' and old.status is distinct from 'published' then
        new.version := coalesce(old.version, 0) + 1;
    end if;
    return new;
end;
$function$
;

create or replace function public.write_audit_log(p_tenant_id uuid, p_action text, p_entity_type text, p_entity_id uuid DEFAULT NULL::uuid, p_actor_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_actor_role text DEFAULT NULL::text, p_session_id uuid DEFAULT NULL::uuid, p_before_json jsonb DEFAULT NULL::jsonb, p_after_json jsonb DEFAULT NULL::jsonb, p_note text DEFAULT NULL::text, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
    v_audit_id uuid;
begin
    insert into public.audit_logs (
        tenant_id, action, entity_type, entity_id,
        actor_id, actor_name, actor_role, session_id,
        before_json, after_json, note,
        ip_address, user_agent, request_id,
        occurred_at, created_at
    ) values (
        p_tenant_id, p_action, p_entity_type, p_entity_id,
        p_actor_id, p_actor_name, p_actor_role, p_session_id,
        p_before_json, p_after_json, p_note,
        p_ip_address, p_user_agent, p_request_id,
        now(), now()
    )
    returning id into v_audit_id;

    return v_audit_id;
end;
$function$
;
comment on function write_audit_log(uuid,text,text,uuid,uuid,text,text,uuid,jsonb,jsonb,text,inet,text,text) is 'Canonical entry point for writing to the audit log. Called by every repository mutation AND by triggers on tables that lack their own audit triggers.';

