-- ############################################################################
-- §7. VIEWS (14)
-- ############################################################################

create or replace view public.active_pricing_config as
 SELECT pc.id,
    pc.tenant_id,
    pc.academic_year_id,
    pc.label,
    pc.registration_fee,
    pc.late_penalty_per_day,
    pc.second_apron_fee,
    pc.early_payment_bonus_pct,
    pc.early_payment_deadline,
    pc.is_active,
    pc.created_at,
    pc.updated_at,
    ay.label AS academic_year_label
   FROM pricing_configs pc
     JOIN academic_years ay ON ay.id = pc.academic_year_id
  WHERE pc.is_active = true AND ay.is_current = true
  ORDER BY pc.updated_at DESC;
;
comment on view public.active_pricing_config is 'Convenience view: active pricing config joined with current academic year.';

create or replace view public.audit_log_by_entity as
 SELECT entity_type,
    entity_id,
    count(*) AS event_count,
    max(occurred_at) AS last_event_at,
    min(occurred_at) AS first_event_at,
    array_agg(DISTINCT action) AS actions
   FROM audit_logs
  GROUP BY entity_type, entity_id;
;
comment on view public.audit_log_by_entity is 'Pivot view for entity-centric audit queries (e.g. "show me everything that happened to parent X").';

create or replace view public.audit_log_with_actor as
 SELECT al.id,
    al.tenant_id,
    al.action,
    al.entity_type,
    al.entity_id,
    al.actor_id,
    al.actor_name,
    al.actor_role,
    al.session_id,
    al.before_json,
    al.after_json,
    al.note,
    al.ip_address,
    al.user_agent,
    al.request_id,
    al.supersedes_id,
    al.occurred_at,
    al.created_at,
    up.email AS actor_email,
    up.display_name AS actor_display_name,
    r.label_fr AS actor_role_label
   FROM audit_logs al
     LEFT JOIN user_profiles up ON up.id = al.actor_id
     LEFT JOIN roles r ON r.code = al.actor_role;
;
comment on view public.audit_log_with_actor is 'Denormalized audit log view for fast UI listing without joins.';

create or replace view public.v_timetable_published as
 SELECT e.id,
    e.tenant_id,
    e.academic_year_id,
    e.version_id,
    e.class_id,
    c.code AS class_code,
    c.name AS class_name,
    e.subject_id,
    s.name_fr AS subject_name_fr,
    s.name_ar AS subject_name_ar,
    e.teacher_id,
    (p.first_name || ' '::text) || p.last_name AS teacher_name,
    e.room_id,
    r.name AS room_label,
    e.day,
    e.period_index,
    e.start_minutes,
    e.end_minutes,
    e.lesson_group,
    e.notes
   FROM timetable_entries e
     JOIN timetable_versions v ON v.id = e.version_id AND v.status = 'published'::text
     JOIN classes c ON c.id = e.class_id
     JOIN subjects s ON s.id = e.subject_id
     LEFT JOIN personnel p ON p.id = e.teacher_id
     LEFT JOIN rooms r ON r.id = e.room_id
  WHERE e.tenant_id = current_tenant_id();
;
comment on view public.v_timetable_published is 'T-408 (SCHED-106): parent-portal projection of the ONE canonical published timetable (0109/0110). SECURITY DEFINER semantics expose ONLY published-entry name projections — parents cannot SELECT personnel/rooms directly under RLS; the view never exposes staff-only rows, drafts or trials.';

create or replace view public.vw_attendance_summary as
 SELECT tenant_id,
    student_id,
    count(*) FILTER (WHERE status = 'present'::text) AS present_count,
    count(*) FILTER (WHERE status = 'absent_excused'::text) AS absent_excused_count,
    count(*) FILTER (WHERE status = 'absent_unexcused'::text) AS absent_unexcused_count,
    count(*) FILTER (WHERE status = 'late'::text) AS late_count,
    count(*) AS total_records,
        CASE
            WHEN count(*) = 0 THEN 0::numeric
            ELSE (count(*) FILTER (WHERE status = 'present'::text)::numeric / count(*)::numeric * 100::numeric)::numeric(5,2)
        END AS attendance_rate_pct
   FROM attendance_records
  GROUP BY tenant_id, student_id;
;
comment on view public.vw_attendance_summary is 'Per-student attendance counts and rate.';

create or replace view public.vw_audit_log_by_day as
 SELECT tenant_id,
    occurred_at::date AS day,
    action,
    count(*) AS event_count
   FROM audit_logs
  GROUP BY tenant_id, (occurred_at::date), action
  ORDER BY tenant_id, (occurred_at::date) DESC, action;
;
comment on view public.vw_audit_log_by_day is 'Daily audit event counts per action code. Used for trend analysis.';

create or replace view public.vw_calendar_events_derived as
 SELECT calendar_events.tenant_id,
    calendar_events.kind,
    calendar_events.title,
    calendar_events.description,
    calendar_events.start_at,
    calendar_events.end_at,
    calendar_events.all_day,
    calendar_events.location,
    calendar_events.target_entity_type,
    calendar_events.target_entity_id,
    calendar_events.target_name,
    calendar_events.target_phone,
    'manual'::text AS derivation_source,
    calendar_events.created_by,
    calendar_events.created_at
   FROM calendar_events
  WHERE calendar_events.is_deleted = false
UNION ALL
 SELECT pay.tenant_id,
    'payment_received'::text AS kind,
    'Paiement '::text || pay.payment_number AS title,
    pay.notes AS description,
    pay.collected_at AS start_at,
    pay.collected_at + '00:01:00'::interval AS end_at,
    false AS all_day,
    NULL::text AS location,
    'payment'::text AS target_entity_type,
    pay.id AS target_entity_id,
    (p.last_name || ' '::text) || p.first_name AS target_name,
    p.primary_phone AS target_phone,
    'system'::text AS derivation_source,
    NULL::uuid AS created_by,
    pay.created_at
   FROM payments pay
     JOIN parents p ON p.id = pay.parent_id
  WHERE pay.status = 'paid'::text
UNION ALL
 SELECT et.tenant_id,
    'expense_event'::text AS kind,
    'Dépense: '::text || et.title AS title,
    et.description,
    COALESCE(et.disbursed_at, et.approved_at, et.submitted_at) AS start_at,
    COALESCE(et.disbursed_at, et.approved_at, et.submitted_at) + '00:01:00'::interval AS end_at,
    false AS all_day,
    NULL::text AS location,
    'expense_ticket'::text AS target_entity_type,
    et.id AS target_entity_id,
    NULL::text AS target_name,
    NULL::text AS target_phone,
    'system'::text AS derivation_source,
    NULL::uuid AS created_by,
    et.created_at
   FROM expense_tickets et
  WHERE et.status = ANY (ARRAY['approved_funds_released'::text, 'disbursed'::text, 'settled_and_closed'::text])
UNION ALL
 SELECT al.tenant_id,
    'audit_log'::text AS kind,
    al.action AS title,
    al.note AS description,
    al.occurred_at AS start_at,
    al.occurred_at + '00:01:00'::interval AS end_at,
    false AS all_day,
    NULL::text AS location,
    al.entity_type AS target_entity_type,
    al.entity_id AS target_entity_id,
    al.actor_name AS target_name,
    NULL::text AS target_phone,
    'system'::text AS derivation_source,
    al.actor_id AS created_by,
    al.created_at
   FROM audit_logs al
  WHERE al.action = ANY (ARRAY['expense.approve'::text, 'expense.reject'::text, 'payment.refund'::text, 'workflow.deploy'::text, 'backup.run'::text]);
;
comment on view public.vw_calendar_events_derived is 'Unified calendar view: manual events + auto-derived events from payments, expenses, audit log.';

create or replace view public.vw_inventory_low_stock as
 SELECT tenant_id,
    sku,
    name,
    category,
    quantity_on_hand,
    reorder_level,
    reorder_quantity,
    unit_cost,
    location,
    reorder_level - quantity_on_hand AS shortfall
   FROM inventory_items
  WHERE quantity_on_hand <= reorder_level AND is_active = true AND deleted_at IS NULL;
;
comment on view public.vw_inventory_low_stock is 'Items at or below reorder level. Drives restock alerts.';

create or replace view public.vw_pending_approvals as
 SELECT id AS tenant_id,
    ( SELECT count(*) AS count
           FROM account_approval_requests ar
          WHERE ar.tenant_id = t.id AND ar.status = 'pending'::text) AS pending_account_approvals,
    ( SELECT count(*) AS count
           FROM expense_tickets et
          WHERE et.tenant_id = t.id AND et.status = 'pending_approval'::text) AS pending_expense_approvals,
    ( SELECT count(*) AS count
           FROM leave_requests lr
          WHERE lr.tenant_id = t.id AND lr.status = 'pending'::text) AS pending_leave_requests,
    ( SELECT count(*) AS count
           FROM purchase_requests pr
          WHERE pr.tenant_id = t.id AND pr.status = 'submitted'::text) AS pending_purchase_requests
   FROM tenants t
  WHERE deleted_at IS NULL;
;
comment on view public.vw_pending_approvals is 'Counts of pending items per tenant. Displayed on admin dashboard.';

create or replace view public.vw_personnel_directory as
 SELECT per.tenant_id,
    per.personnel_code,
    (per.last_name || ' '::text) || per.first_name AS full_name,
    per.staff_category,
    r.label_fr AS role_label,
    d.name_fr AS department_name,
    per."position",
    per.primary_phone,
    per.email,
    per.hire_date,
    per.is_active
   FROM personnel per
     LEFT JOIN roles r ON r.id = per.role_id
     LEFT JOIN departments d ON d.id = per.department_id
  WHERE per.deleted_at IS NULL;
;
comment on view public.vw_personnel_directory is 'Personnel directory WITHOUT salary fields. Safe for general staff viewing.';

create or replace view public.vw_personnel_directory_restricted as
 SELECT per.tenant_id,
    per.personnel_code,
    (per.last_name || ' '::text) || per.first_name AS full_name,
    per.staff_category,
    r.label_fr AS role_label,
    d.name_fr AS department_name,
    per."position",
    per.primary_phone,
    per.email,
    per.hire_date,
    per.is_active,
    per.base_salary,
    per.payment_method,
    per.bank_account,
    per.bonuses_json
   FROM personnel per
     LEFT JOIN roles r ON r.id = per.role_id
     LEFT JOIN departments d ON d.id = per.department_id
  WHERE per.deleted_at IS NULL;
;
comment on view public.vw_personnel_directory_restricted is 'Personnel directory WITH salary fields. RLS restricts to SuperAdmin + FinancialOfficer (plan §09.04).';

create or replace view public.vw_pricing_full as
 SELECT pc.tenant_id,
    pc.id AS pricing_config_id,
    pc.label,
    ay.label AS academic_year,
    pc.registration_fee,
    pc.late_penalty_per_day,
    pc.second_apron_fee,
    pc.early_payment_bonus_pct,
    pc.early_payment_deadline,
    pc.is_active,
    ( SELECT jsonb_agg(jsonb_build_object('level_id', glt.academic_level_id, 'level_code', al.grade_code, 'level_label', al.year_label, 'annual_amount', glt.annual_amount, 'tranches', jsonb_build_array(jsonb_build_object('number', 1, 'amount', glt.tranche_1_amount, 'month', glt.tranche_1_month), jsonb_build_object('number', 2, 'amount', glt.tranche_2_amount, 'month', glt.tranche_2_month), jsonb_build_object('number', 3, 'amount', glt.tranche_3_amount, 'month', glt.tranche_3_month)))) AS jsonb_agg
           FROM grade_level_tuition glt
             JOIN academic_levels al ON al.id = glt.academic_level_id
          WHERE glt.pricing_config_id = pc.id) AS tuition_by_level,
    ( SELECT jsonb_agg(jsonb_build_object('destination_id', td.id, 'code', td.code, 'label_fr', td.label_fr, 'annual_amount', td.annual_amount, 'tranches', jsonb_build_array(jsonb_build_object('number', 1, 'amount', td.tranche_1_amount, 'month', td.tranche_1_month), jsonb_build_object('number', 2, 'amount', td.tranche_2_amount, 'month', td.tranche_2_month), jsonb_build_object('number', 3, 'amount', td.tranche_3_amount, 'month', td.tranche_3_month)))) AS jsonb_agg
           FROM transport_destinations td
          WHERE td.pricing_config_id = pc.id) AS transport_by_destination,
    ( SELECT jsonb_agg(jsonb_build_object('service_id', cs.id, 'code', cs.code, 'label_fr', cs.label_fr, 'semester_amount', cs.semester_amount, 'annual_amount', cs.annual_amount, 'billing_model', cs.billing_model)) AS jsonb_agg
           FROM complementary_services cs
          WHERE cs.pricing_config_id = pc.id AND cs.is_active = true) AS complementary_services,
    ( SELECT jsonb_agg(jsonb_build_object('service_id', ads.id, 'code', ads.code, 'label_fr', ads.label_fr, 'amount', ads.amount, 'billing_model', ads.billing_model)) AS jsonb_agg
           FROM additional_services ads
          WHERE ads.pricing_config_id = pc.id AND ads.is_active = true) AS additional_services,
    ( SELECT jsonb_agg(jsonb_build_object('discount_id', d.id, 'code', d.code, 'label_fr', d.label_fr, 'discount_type', d.discount_type, 'amount', d.amount, 'applies_to', d.applies_to)) AS jsonb_agg
           FROM discounts d
          WHERE d.pricing_config_id = pc.id AND d.is_active = true) AS discounts
   FROM pricing_configs pc
     JOIN academic_years ay ON ay.id = pc.academic_year_id;
;
comment on view public.vw_pricing_full is 'Fully joined pricing config (tuition + transport + services + discounts) for client hydration.';

create or replace view public.vw_revenue_by_category as
 SELECT tenant_id,
    COALESCE(category, 'other'::text) AS category,
    date_trunc('month'::text, collected_at) AS month,
    COALESCE(sum(amount) FILTER (WHERE status = 'paid'::text), 0::numeric) AS gross_revenue,
    COALESCE(sum(amount) FILTER (WHERE status = 'paid'::text), 0::numeric) - COALESCE(( SELECT sum(abs(le.amount)) AS sum
           FROM ledger_entries le
          WHERE le.entry_type = 'refund'::text AND le.reverses_id IS NULL AND le.parent_id = pay.parent_id AND le.category = COALESCE(pay.category, 'other'::text)), 0::numeric) AS net_revenue,
    count(*) FILTER (WHERE status = 'paid'::text) AS payment_count
   FROM payments pay
  GROUP BY tenant_id, category, (date_trunc('month'::text, collected_at)), parent_id;
;

create or replace view public.vw_student_roster as
 SELECT s.tenant_id,
    s.student_code,
    (s.last_name || ' '::text) || s.first_name AS student_name,
    s.date_of_birth,
    s.gender,
    s.enrollment_status,
    s.grade_level_id,
    al.cycle AS academic_cycle,
    al.year_label AS academic_level,
    c.code AS class_code,
    c.name AS class_name,
    p.parent_code,
    (p.last_name || ' '::text) || p.first_name AS parent_name,
    p.primary_phone,
    p.email AS parent_email,
    p.relationship,
    p.address,
    p.city
   FROM students s
     LEFT JOIN parents p ON p.id = s.parent_id
     LEFT JOIN classes c ON c.id = s.class_id
     LEFT JOIN academic_levels al ON al.id = s.grade_level_id
  WHERE s.deleted_at IS NULL;
;
comment on view public.vw_student_roster is 'Joined student+parent+class view for roster exports.';

-- ############################################################################
-- §8. MATERIALIZED VIEWS (5) + the 0049 unique indexes
--     (REFRESH CONCURRENTLY preconditions)
-- ############################################################################

create materialized view public.mv_dashboard_kpis as
 SELECT id AS tenant_id,
    ( SELECT count(*) AS count
           FROM parents p
          WHERE p.tenant_id = t.id AND p.deleted_at IS NULL) AS total_parents,
    ( SELECT count(*) AS count
           FROM students s
          WHERE s.tenant_id = t.id AND s.deleted_at IS NULL AND s.enrollment_status = 'active'::text) AS total_students,
    ( SELECT COALESCE(sum(pay.amount), 0::numeric) AS "coalesce"
           FROM payments pay
          WHERE pay.tenant_id = t.id AND pay.status = 'paid'::text AND pay.collected_at >= date_trunc('month'::text, now()) AND pay.collected_at < date_trunc('month'::text, now() + '1 mon'::interval)) AS monthly_revenue,
    ( SELECT COALESCE(sum(pay.amount), 0::numeric) AS "coalesce"
           FROM payments pay
          WHERE pay.tenant_id = t.id AND pay.status = 'paid'::text AND pay.collected_at >= date_trunc('day'::text, now()) AND pay.collected_at < date_trunc('day'::text, now() + '1 day'::interval)) AS today_revenue,
    ( SELECT COALESCE(sum(summary.total_outstanding), 0::numeric) AS "coalesce"
           FROM parents p2
             CROSS JOIN LATERAL compute_parent_summary(p2.id) summary(parent_id, total_outstanding, total_overdue, total_charged, total_paid, total_adjusted, total_refunded, total_cleared, total_pending, total_unallocated_credit, account_count, accounts)
          WHERE p2.tenant_id = t.id AND p2.deleted_at IS NULL) AS outstanding_debt,
    ( SELECT COALESCE(sum(summary.total_overdue), 0::numeric) AS "coalesce"
           FROM parents p2
             CROSS JOIN LATERAL compute_parent_summary(p2.id) summary(parent_id, total_outstanding, total_overdue, total_charged, total_paid, total_adjusted, total_refunded, total_cleared, total_pending, total_unallocated_credit, account_count, accounts)
          WHERE p2.tenant_id = t.id AND p2.deleted_at IS NULL) AS overdue_debt,
    ( SELECT count(DISTINCT p2.id) AS count
           FROM parents p2
             CROSS JOIN LATERAL compute_parent_summary(p2.id) summary(parent_id, total_outstanding, total_overdue, total_charged, total_paid, total_adjusted, total_refunded, total_cleared, total_pending, total_unallocated_credit, account_count, accounts)
          WHERE p2.tenant_id = t.id AND p2.deleted_at IS NULL AND summary.total_overdue > 0::numeric) AS overdue_families_count,
    ( SELECT count(*) AS count
           FROM payments pay
          WHERE pay.tenant_id = t.id AND pay.method = 'check'::text AND pay.status = 'pending'::text) AS pending_checks_count,
    ( SELECT COALESCE(sum(pay.amount), 0::numeric) AS "coalesce"
           FROM payments pay
          WHERE pay.tenant_id = t.id AND pay.method = 'check'::text AND pay.status = 'pending'::text) AS pending_checks_amount
   FROM tenants t
 with no data;
comment on materialized view public.mv_dashboard_kpis is 'One row per tenant. BUG-NEW-002: the 0034/0041/0042 versions SUMmed payments over a tenants×parents×students×payments join — every payment multiplied by the tenant student count (live: 54.96M reported as 21.38B). This version uses scalar subqueries: each aggregate reads its base table exactly once.';

create materialized view public.mv_debt_aging as
 SELECT p.id AS parent_id,
    p.tenant_id,
    p.display_name,
    (COALESCE(p.first_name, ''::text) || ' '::text) || COALESCE(p.last_name, ''::text) AS parent_name,
    summary.total_outstanding,
    summary.total_overdue,
        CASE
            WHEN summary.total_overdue > 0::numeric AND (EXTRACT(epoch FROM now() - (( SELECT max(ins.due_date) AS max
               FROM installments ins
              WHERE ins.parent_id = p.id AND ins.due_date < now() AND ins.amount_due > ins.amount_paid))::timestamp with time zone) / 86400::numeric) > 180::numeric THEN '180_plus'::text
            WHEN summary.total_overdue > 0::numeric AND (EXTRACT(epoch FROM now() - (( SELECT max(ins.due_date) AS max
               FROM installments ins
              WHERE ins.parent_id = p.id AND ins.due_date < now() AND ins.amount_due > ins.amount_paid))::timestamp with time zone) / 86400::numeric) > 90::numeric THEN '91_180'::text
            WHEN summary.total_overdue > 0::numeric AND (EXTRACT(epoch FROM now() - (( SELECT max(ins.due_date) AS max
               FROM installments ins
              WHERE ins.parent_id = p.id AND ins.due_date < now() AND ins.amount_due > ins.amount_paid))::timestamp with time zone) / 86400::numeric) > 60::numeric THEN '61_90'::text
            WHEN summary.total_overdue > 0::numeric AND (EXTRACT(epoch FROM now() - (( SELECT max(ins.due_date) AS max
               FROM installments ins
              WHERE ins.parent_id = p.id AND ins.due_date < now() AND ins.amount_due > ins.amount_paid))::timestamp with time zone) / 86400::numeric) > 30::numeric THEN '31_60'::text
            WHEN summary.total_overdue > 0::numeric THEN '0_30'::text
            ELSE NULL::text
        END AS aging_bucket,
    aging.outstanding_amount AS installment_outstanding,
    aging.debt_age_days,
    aging.origin_academic_year,
    aging.last_payment_at,
    aging.inactivity_days,
    aging.subsequent_year_payment_count,
    aging.subsequent_year_payment_total,
    aging.status_level,
    aging.reason_code
   FROM parents p
     CROSS JOIN LATERAL compute_parent_summary(p.id) summary(parent_id, total_outstanding, total_overdue, total_charged, total_paid, total_adjusted, total_refunded, total_cleared, total_pending, total_unallocated_credit, account_count, accounts)
     LEFT JOIN compute_debt_aging_rows(NULL::uuid, now()) aging(tenant_id, parent_id, parent_name, parent_phone, student_ids, outstanding_amount, oldest_due_date, debt_age_days, origin_academic_year, last_payment_at, days_since_last_payment, inactivity_days, subsequent_year_payment_count, subsequent_year_payment_total, has_subsequent_year_payments, obligations, status_level, reason_code, computed_at) ON aging.parent_id = p.id
  WHERE p.deleted_at IS NULL AND summary.total_outstanding > 0::numeric
 with no data;
comment on materialized view public.mv_debt_aging is 'Per-parent debt aging: aging_bucket = ledger-overdue age band (0042 basis); T-405 columns = cross-year payment-behavior status on the installment basis (financial-rules §15 — installment_outstanding is the Créances-tab number, total_outstanding stays the ledger replay).';

create materialized view public.mv_grade_summary as
 SELECT g.tenant_id,
    g.student_id,
    g.class_subject_id,
    cs.subject_id,
    cs.coefficient,
    max(g.subject_average) AS subject_average,
    max(g.subject_average) * cs.coefficient AS weighted_score
   FROM grades g
     JOIN class_subjects cs ON cs.id = g.class_subject_id
  GROUP BY g.tenant_id, g.student_id, g.class_subject_id, cs.subject_id, cs.coefficient
 with no data;

create materialized view public.mv_revenue_by_month as
 SELECT tenant_id,
    date_trunc('month'::text, collected_at) AS month,
    COALESCE(sum(amount) FILTER (WHERE status = 'paid'::text), 0::numeric) AS revenue,
    count(*) FILTER (WHERE status = 'paid'::text) AS payment_count
   FROM payments
  GROUP BY tenant_id, (date_trunc('month'::text, collected_at))
 with no data;

create materialized view public.mv_top_debtors as
 SELECT parent_id,
    tenant_id,
    parent_name,
    total_outstanding,
    total_overdue,
    aging_bucket,
    row_number() OVER (PARTITION BY tenant_id ORDER BY total_outstanding DESC) AS rank
   FROM mv_debt_aging
  WHERE total_outstanding > 0::numeric
  ORDER BY total_outstanding DESC
 with no data;
create UNIQUE INDEX uq_mv_dashboard_kpis_tenant ON public.mv_dashboard_kpis USING btree (tenant_id);
create UNIQUE INDEX uq_mv_debt_aging_tenant_parent ON public.mv_debt_aging USING btree (tenant_id, parent_id);
create UNIQUE INDEX uq_mv_revenue_by_month_tenant_month ON public.mv_revenue_by_month USING btree (tenant_id, month);
create UNIQUE INDEX uq_mv_top_debtors_tenant_parent ON public.mv_top_debtors USING btree (tenant_id, parent_id);

