create policy assessments_admin on public.assessments
  for all
  to authenticated
  using (((tenant_id = current_tenant_id()) AND has_any_role(ARRAY['super_admin'::text, 'support_staff'::text, 'teacher'::text])))
  with check (((tenant_id = current_tenant_id()) AND has_any_role(ARRAY['super_admin'::text, 'support_staff'::text, 'teacher'::text])))
;
create policy assessments_select on public.assessments
  for select
  to authenticated
  using (((tenant_id = current_tenant_id()) AND (has_any_role(ARRAY['super_admin'::text, 'support_staff'::text, 'financial_officer'::text, 'manager'::text]) OR (has_role('parent'::text) AND (student_id IN ( SELECT s.id
   FROM (students s
     JOIN parents p ON ((p.id = s.parent_id)))
  WHERE ((p.auth_user_id = auth.uid()) AND (p.deleted_at IS NULL))))) OR (has_role('student'::text) AND (student_id IN ( SELECT s.id
   FROM students s
  WHERE ((s.auth_user_id = auth.uid()) AND (s.deleted_at IS NULL))))) OR (has_role('teacher'::text) AND (student_id IN ( SELECT s.id
   FROM students s
  WHERE ((s.deleted_at IS NULL) AND ((EXISTS ( SELECT 1
           FROM classes c
          WHERE ((c.id = s.class_id) AND (c.homeroom_teacher_id IN ( SELECT p.id
                   FROM personnel p
                  WHERE ((p.user_id = current_user_profile_id()) AND (p.deleted_at IS NULL))))))) OR (EXISTS ( SELECT 1
           FROM class_subjects cs
          WHERE ((cs.class_id = s.class_id) AND (cs.teacher_id IN ( SELECT p.id
                   FROM personnel p
                  WHERE ((p.user_id = current_user_profile_id()) AND (p.deleted_at IS NULL)))))))))))))))
;
