create policy calendar_events_admin on public.calendar_events
  for all
  to authenticated
  using (((tenant_id = ( SELECT current_tenant_id() AS current_tenant_id)) AND ( SELECT has_any_role(ARRAY['super_admin'::text, 'financial_officer'::text, 'support_staff'::text, 'manager'::text, 'teacher'::text, 'buyer'::text, 'driver'::text, 'warehouse_worker'::text, 'worker'::text]) AS has_any_role)))
  with check (((tenant_id = ( SELECT current_tenant_id() AS current_tenant_id)) AND ( SELECT has_any_role(ARRAY['super_admin'::text, 'financial_officer'::text, 'support_staff'::text, 'manager'::text, 'teacher'::text, 'buyer'::text, 'driver'::text, 'warehouse_worker'::text, 'worker'::text]) AS has_any_role)))
;
create policy calendar_events_select on public.calendar_events
  for select
  to authenticated
  using (((tenant_id = ( SELECT current_tenant_id() AS current_tenant_id)) AND (is_deleted = false) AND (( SELECT has_any_role(ARRAY['super_admin'::text, 'financial_officer'::text, 'support_staff'::text, 'manager'::text, 'teacher'::text, 'buyer'::text, 'driver'::text, 'warehouse_worker'::text, 'worker'::text]) AS has_any_role) OR (( SELECT has_role('parent'::text) AS has_role) AND (target_entity_type = 'exam'::text) AND (target_entity_id IN ( SELECT s.class_id
   FROM (students s
     JOIN parents p ON ((p.id = s.parent_id)))
  WHERE ((p.auth_user_id = auth.uid()) AND (p.deleted_at IS NULL) AND (s.deleted_at IS NULL) AND (s.class_id IS NOT NULL))))))))
;
create policy chat_channels_insert on public.chat_channels
  for insert
  to authenticated
  with check (((tenant_id = current_tenant_id()) AND (member_ids @> ARRAY[current_user_profile_id()]) AND ((channel_type IS DISTINCT FROM 'announcement'::text) OR has_any_role(ARRAY['super_admin'::text, 'manager'::text, 'support_staff'::text])) AND (has_any_role(ARRAY['super_admin'::text, 'manager'::text, 'support_staff'::text, 'financial_officer'::text, 'teacher'::text]) OR ( SELECT bool_and(profile_has_staff_role(m.m)) AS bool_and
   FROM unnest(chat_channels.member_ids) m(m)
  WHERE (m.m IS DISTINCT FROM current_user_profile_id())))))
;
create policy chat_channels_select on public.chat_channels
  for select
  to authenticated
  using (((tenant_id = current_tenant_id()) AND (has_role('super_admin'::text) OR (member_ids @> ARRAY[current_user_profile_id()]))))
;
create policy chat_channels_update on public.chat_channels
  for update
  to authenticated
  using (((tenant_id = current_tenant_id()) AND (has_any_role(ARRAY['super_admin'::text, 'manager'::text, 'support_staff'::text]) OR (created_by = current_user_profile_id()))))
  with check (((tenant_id = current_tenant_id()) AND (has_any_role(ARRAY['super_admin'::text, 'manager'::text, 'support_staff'::text]) OR (created_by = current_user_profile_id()))))
;
create policy chat_messages_insert on public.chat_messages
  for insert
  to authenticated
  with check (((tenant_id = current_tenant_id()) AND (author_id = current_user_profile_id()) AND (EXISTS ( SELECT 1
   FROM chat_channels c
  WHERE ((c.id = chat_messages.channel_id) AND (c.tenant_id = chat_messages.tenant_id) AND (c.member_ids @> ARRAY[current_user_profile_id()])))) AND (has_any_role(ARRAY['super_admin'::text, 'manager'::text, 'support_staff'::text, 'financial_officer'::text, 'teacher'::text, 'worker'::text, 'buyer'::text, 'driver'::text, 'warehouse_worker'::text]) OR (EXISTS ( SELECT 1
   FROM (chat_channels c
     JOIN LATERAL ( SELECT m.m
           FROM unnest(c.member_ids) m(m)
          WHERE (m.m IS DISTINCT FROM current_user_profile_id())) members ON (true))
  WHERE ((c.id = chat_messages.channel_id) AND (c.tenant_id = chat_messages.tenant_id) AND (c.channel_type = 'direct'::text) AND profile_has_staff_role(members.m)))))))
;
create policy chat_messages_select on public.chat_messages
  for select
  to authenticated
  using (((tenant_id = current_tenant_id()) AND (deleted_at IS NULL) AND (has_role('super_admin'::text) OR (EXISTS ( SELECT 1
   FROM chat_channels c
  WHERE ((c.id = chat_messages.channel_id) AND (c.member_ids @> ARRAY[current_user_profile_id()])))))))
;
create policy chat_messages_update_own on public.chat_messages
  for update
  to authenticated
  using (((tenant_id = current_tenant_id()) AND (author_id = current_user_profile_id())))
  with check (((tenant_id = current_tenant_id()) AND (author_id = current_user_profile_id())))
;
create policy chat_messages_update_read_by on public.chat_messages
  for update
  to authenticated
  using (((tenant_id = current_tenant_id()) AND (EXISTS ( SELECT 1
   FROM chat_channels c
  WHERE ((c.id = chat_messages.channel_id) AND (c.tenant_id = chat_messages.tenant_id) AND (c.member_ids @> ARRAY[current_user_profile_id()]))))))
  with check (((tenant_id = current_tenant_id()) AND (EXISTS ( SELECT 1
   FROM chat_channels c
  WHERE ((c.id = chat_messages.channel_id) AND (c.tenant_id = chat_messages.tenant_id) AND (c.member_ids @> ARRAY[current_user_profile_id()]))))))
;
