-- ############################################################################
-- §12. REALTIME PUBLICATION MEMBERSHIPS (the 0085/0095/0106 final set)
-- ############################################################################
do $$
begin
  if not exists (select from pg_publication where pubname = 'supabase_realtime') then
    create publication supabase_realtime;
  end if;
  if not exists (select from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='audit_logs') then
    alter publication supabase_realtime add table public.audit_logs;
  end if;
  if not exists (select from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='chat_channels') then
    alter publication supabase_realtime add table public.chat_channels;
  end if;
  if not exists (select from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='chat_messages') then
    alter publication supabase_realtime add table public.chat_messages;
  end if;
  if not exists (select from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='leave_requests') then
    alter publication supabase_realtime add table public.leave_requests;
  end if;
  if not exists (select from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='salary_payments') then
    alter publication supabase_realtime add table public.salary_payments;
  end if;
  if not exists (select from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='staff_absences') then
    alter publication supabase_realtime add table public.staff_absences;
  end if;
end;
$$;

