  with check (((bucket_id = 'task-attachments'::text) AND ((storage.foldername(name))[1] = (current_tenant_id())::text) AND has_any_role(ARRAY['super_admin'::text, 'financial_officer'::text, 'support_staff'::text, 'teacher'::text, 'manager'::text, 'buyer'::text, 'driver'::text, 'warehouse_worker'::text, 'worker'::text])))
;
create policy tenant_assets_read on storage.objects
  for select
  to authenticated
  using (((bucket_id = 'tenant-assets'::text) AND ((storage.foldername(name))[1] = (current_tenant_id())::text) AND has_any_role(ARRAY['super_admin'::text, 'financial_officer'::text])))
;
create policy tenant_assets_write on storage.objects
  for insert
  to authenticated
  with check (((bucket_id = 'tenant-assets'::text) AND ((storage.foldername(name))[1] = (current_tenant_id())::text) AND has_role('super_admin'::text)))
;

